-- Cəmi: 6145 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 44-ე თვეში! ბავშვი უკვე ღრმად განიცდის განცდას — „მე დიდი ვარ“. ამ პერიოდში დააკისრეთ მცირე პასუხისმგებლობები, მაგალითად, მიეცით საშუალება, თავად აირჩიოს ტანსაცმელი ან სუფრის გაწყობაში დაგეხმაროთ. ეს მის დამოუკიდებლობის სურვილს დადებითი მიმართულებით წარმართავს და თავდაჯერებას უმაღლებს.') WHERE id = 'aad2ad75-5a11-4a2d-9c7c-2bc5d48aa312';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „სწრაფი და მოქნილი მანევრირება“. ბავშვს უკვე შეუძლია, მთელი სისწრაფით სირბილისას წინ დაბრკოლება დაინახოს და წაქცევის გარეშე გვერდი აუაროს. ეს ტვინში „მოძრაობის დაგეგმვის“ უნარის განვითარების უმაღლესი ეტაპია. პარკში მოუწყვეთ პატარა დაბრკოლებების ზოლი. ეს გააუმჯობესებს როგორც სხეულის კონტროლს, ისე მოქნილობას.') WHERE id = '5ff72db7-e0be-4353-a758-f27d398fc0b7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია საგნების ერთდროულად დაჯგუფება როგორც ფერის, ისე მასალის მიხედვით: „ეს ლურჯიცაა და რბილიც“. ეს კოგნიტიური მოქნილობის მნიშვნელოვანი მაჩვენებელია. შესთავაზეთ თამაშები სხვადასხვა ტექსტურის მქონე საგნებით (ხე, ქსოვილი, პლასტმასი).') WHERE id = 'b98d1c0b-fdd1-4aeb-a1f1-d636c58ba6b7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „დინამიკური ხტომა“. ბავშვს უკვე შეუძლია სირბილისას წინ შემხვედრ პატარა დაბრკოლებას სიჩქარის შეუნელებლად გადაახტეს. ეს მიუთითებს, რომ ტვინში მოძრაობის წინასწარ დაგეგმვის (motor planning) უნარი ვითარდება. პარკში შეგიძლიათ პატარა დაბრკოლებები მოუწყოთ.') WHERE id = '60d3fdb2-caa2-4bc5-bc84-452616921b80';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „დროის რიტუალები“. მიუხედავად იმისა, რომ ბავშვს ჯერ სრულად არ აქვს გააზრებული ცნებები „გუშინ“, „დღეს“ და „ხვალ“, მან კარგად იცის ყოველდღიური რიტუალები: „ჭამის შემდეგ — პარკი“ ან „ძილის წინ — ზღაპარი“. ასეთი თანმიმდევრობები მის გონებაში დროის ხაზს აყალიბებს.') WHERE id = '95122e91-e077-4e38-a3b4-27a4e9e756f1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „სიმეტრიის მცდელობები“. ბავშვი ცდილობს ქაღალდის დაკეცვას ან ნახატზე დეტალების (მაგალითად, ადამიანის ორი თვალისა და ორი ხელის) უფრო სიმეტრიულად განლაგებას. ეს აჩვენებს, რამდენად ვითარდება მისი ვიზუალურ-სივრცითი აღქმა.') WHERE id = '27b05f17-57a4-4b79-9091-f702b81309dd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პოლიტიკური“ მოლაპარაკებები. ბავშვი უკვე ცდილობს თქვენთან „ვაჭრობას“: „თუ ბოსტნეულს შევჭამ, შემდეგ პარკში უფრო დიდხანს დავრჩებით?“ ეს აჩვენებს, რომ ის სოციალური ზემოქმედების მექანიზმებს სწავლობს. ამ „მოლაპარაკებებისას“ იყავით გულწრფელი და თანმიმდევრული — ასე სწავლობს ბავშვი საზღვრებს.') WHERE id = '0875811d-7343-4ba3-a29e-c235cba78b04';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „წარმოსახვითი სცენარები“. ახლა თამაშები უფრო რთული ხდება: „მე გამყიდველი ვარ, თქვენ მოდით და ჩემგან პური იყიდეთ“. ამ თამაშებში ბავშვი საზოგადოებაში არსებულ როლებს ცდის. მიჰყევით მის სცენარებს და ხელი შეუწყვეთ ამ შემოქმედებით პროცესს.') WHERE id = 'c35d44af-1b5b-4a3a-b44c-143278463e37';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„საკუთარი თავის აღწერა“. ბავშვს უკვე შეუძლია საკუთარი თავის დახასიათება: „მე ქერა ვარ“, „მე სწრაფად დავრბივარ“. ეს ინდივიდუალური იდენტობის განმტკიცებაზე მიუთითებს. დაუსვით კითხვები, მაგალითად: „კიდევ რა მოგწონს?“ და ამით საკუთარი თავის შეცნობაში დაეხმარეთ. საკუთარი თავის მიმართ დადებითი დამოკიდებულება მისი მომავალი თავდაჯერებულობის საფუძველია.') WHERE id = '9ca9132e-1f05-4086-b977-373ac1739718';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „დიპლომატია და მოლაპარაკება“. სასურველის მისაღებად ბავშვი უკვე ისეთ შეთავაზებებს აკეთებს, როგორიცაა: „თუ შენ ამას მომცემ, მეც ამას მოგცემ“. ეს სოციალური ინტელექტისა და პრობლემების გადაჭრის უნარის მაღალ დონეზე მიუთითებს. მხარი დაუჭირეთ მის სამართლიან „ვაჭრობის“ მცდელობებს და დადებითად შეხვდით მათ.') WHERE id = '68e14866-1913-4e48-a5b0-15a89d136783';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „დროის რიტუალიზაცია“. ბავშვი ისეთი ფრაზებით, როგორიცაა „დილით, როცა ვიღვიძებ“ და „საღამოს, როცა ვიძინებ“, უკვე განასხვავებს დღის მონაკვეთებს. მასთან ერთად განიხილეთ მომდევნო დღის გეგმები ფორმატით: „ჯერ, შემდეგ, ბოლოს“. ეს მას უსაფრთხოებისა და მოწესრიგებულობის განცდას უქმნის.') WHERE id = 'fc45f60c-b22c-4712-b519-43e1ec159d0a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ფეხით მართვა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, ფეხით ოდნავ წინ წასწიოს და ასე გადაადგილოს (დრიბლინგი). ამას დინამიკური წონასწორობა და ყურადღება სჭირდება. პარკში პატარა „საფეხბურთო ბილიკი“ მოუწყეთ და სთხოვეთ, ბურთი მიზნისკენ წაიყვანოს.') WHERE id = '27b3b770-0010-4e27-a15b-7e39df48e572';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „თავაზიანობა და სოციალური ეტიკეტი“. ბავშვი უკვე სიტუაციის შესაბამისად იყენებს ისეთ ფრაზებს, როგორიცაა „ბოდიში“ და „შეიძლება?“. სხვებთან თქვენი საუბარი მისთვის მთავარი მაგალითია. როდესაც თავაზიანად იქცევა, დაანახვეთ, რა სასიამოვნო შთაბეჭდილებას ახდენს ეს სხვებზე: „რადგან ასეთი თავაზიანი ხარ, ყველა გიღიმის“.') WHERE id = 'eddeff81-68cf-4451-8b49-9db4335c7821';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „წარუმატებლობის მიღება“. როცა ბავშვს რაიმე არ გამოსდის (მაგალითად, ფაზლს ვერ აწყობს), ის უკვე მაშინვე აღარ ბრაზდება — ხელახლა ცდილობს ან დახმარებას ითხოვს. შეაქეთ არა შედეგისთვის, არამედ ძალისხმევისთვის: „ძალიან ეცადე და არ დანებდი, ყოჩაღ!“.') WHERE id = '3c009bb9-dfc9-4682-a20a-9afa3ba74f26';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „საგნების ფუნქცია“. ბავშვი საგნებს უკვე არა მხოლოდ გარეგნობის, არამედ მათი დანიშნულების მიხედვითაც აჯგუფებს. „ესენი საჭრელი ხელსაწყოებია“, „ესენი კი საწერი საშუალებებია“. ეს მიუთითებს, რომ მის გონებაში არსებული ინფორმაციის ბაზა უფრო სისტემური და ფუნქციური ხდება.') WHERE id = '52b43fec-3fc9-4135-bc89-1ca56d2c89c9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ კოორდინაციაში — „ზუსტი მანევრები“. ბავშვს უკვე შეუძლია სითხით სავსე ჭიქა თითქმის დაუღვრელად წაიღოს ან ვიწრო ბილიკზე გაიაროს. ეს აჩვენებს, რამდენად დაიხვეწა მისი მხედველობით-მოტორული კოორდინაცია. სახლში „პატარა დამხმარის“ როლების მიცემით შეგიძლიათ მისი ყურადღება კიდევ უფრო განამტკიცოთ.') WHERE id = 'b2a95188-79e5-4c80-963a-2302704140ca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ემოციების ლექსიკა“. ბავშვი უკვე მხოლოდ „ცუდად ვარ“ ან „კარგად ვარ“ აღარ ამბობს. ის სათანადო დროს იყენებს ისეთ სიტყვებს, როგორებიცაა: „გავბრაზდი“, „მომენატრა“, „მიხარია“. აღიარეთ და დაადასტურეთ მისი გრძნობები: „ნორმალურია, რომ ტირი, რადგან მოგენატრა“. ეს მისი ემოციური ჯანმრთელობის ერთ-ერთი ყველაზე მყარი საფუძველია.') WHERE id = '8d118e2f-9e48-4f84-bdd9-4688744f285c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1330-ე დღის მწვერვალი! ბავშვი უკვე ოფიციალურად „ადრეული ბავშვობის“ ყველაზე აქტიურ და ცნობიერ ეტაპზეა. ახლა ის როგორც ფიზიკურად, ისე ემოციურად სრულფასოვანი ინდივიდია. თქვენ ეს გზა ცოდნითა და სიყვარულით გამოიარეთ. „Anacan“ ყოველთვის თქვენ გვერდითაა!') WHERE id = 'ee7d4f4f-acca-4792-810c-9ebdc339da81';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 45-ე თვეში! ბავშვი უკვე იწყებს მის გარშემო არსებულ წარწერებში ნაცნობი ასოების ძებნას. განსაკუთრებით ხშირად მას საკუთარი სახელის პირველი ასოს ამოცნობა ყველგან შეუძლია. ეს კითხვის უნარის განვითარების საწყისი ეტაპია. ნუ აიძულებთ ასოების სწავლას — უბრალოდ თამაშის დროს უთხარით იმ ასოების სახელები და ბგერები, რომლებსაც ხედავს.') WHERE id = 'c1854d46-26a3-452c-9eb7-697ec5a92d6c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „სამთვლიანი ველოსიპედის სრულყოფილი მართვა“. ბავშვს უკვე შეუძლია პედლების გაუჩერებლად ტრიალი, საჭის მოხვევა და ვიწრო მოსახვევების გავლა. ეს როგორც სხეულის ქვედა ნაწილის სიძლიერის, ისე მხედველობით-სივრცითი კოორდინაციის განვითარების უმაღლესი დონეა.') WHERE id = 'ee3c0b22-95f2-4059-93bc-287ff0eb00cf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აბსტრაქტული ცნებები: მარჯვენა და მარცხენა“. ბავშვი ინტერესდება ისეთი ცნებების შესწავლით, როგორიცაა „მარჯვენა ხელი“ და „მარცხენა ფეხი“. ჯერჯერობით შეიძლება აერიოს და ეს ნორმალურია. როცა წინდებს აცმევთ, უთხარით: „ახლა მარჯვენა ფეხი გამომიწოდე“ — ასე ეს ცნებები ყოველდღიურ ცხოვრებაში შეიტანეთ.') WHERE id = 'dcd74d19-3308-4446-89b6-05aecfc53aed';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „თვითრეგულაცია (Self-regulation)“. როცა ბავშვს რაიმე არ გამოსდის, ის უკვე მაშინვე აღარ ბრაზდება, გიყურებთ და შეუძლია გკითხოთ: „კიდევ ვცადო?“. ეს ემოციური სიმწიფის ერთ-ერთი უმნიშვნელოვანესი საფეხურია. შეაქეთ არა შედეგისთვის, არამედ გამოვლენილი მოთმინებისა და ძალისხმევისთვის. თქვენ შესანიშნავი დედა ხართ!') WHERE id = 'b36ad394-fd9c-40bc-963f-954848c1c743';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე რთული აქტივობების დროსაც იყენებს თანმიმდევრობას — „ჯერ, ახლა, შემდეგ“: „ჯერ სათამაშოებს ავალაგებ, შემდეგ ხელებს დავიბან და საჭმელს შევჭამ“. ეს თავის ტვინში სტრატეგიული დაგეგმვის უნარის (აღმასრულებელი ფუნქციის) განვითარებაზე მიუთითებს. მიეცით ბავშვს აქტიური როლი დღის დაგეგმვაში — ეს მის შინაგან დისციპლინას განამტკიცებს.') WHERE id = 'a41e3209-8dbf-44ce-98bb-5a5b64b4268c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „სტატიკური და დინამიკური წონასწორობა“. ბავშვს უკვე შეუძლია ცალ ფეხზე 5-10 წამით დგომა ან ვიწრო ბორდიურზე წონასწორობის დაუკარგავად გავლა. ეს ვესტიბულური სისტემის სრულად მომწიფებაზე მიუთითებს. სწორედ ახლაა საუკეთესო დრო, მასთან ერთად თამაში „ბაგირზე მოსიარულე“ ითამაშოთ.') WHERE id = '696cb686-c625-440d-93fe-4e04eee0ca77';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „მიზეზ-შედეგობრივი ჯაჭვი“. ბავშვი უკვე ცდილობს, თქვენს აკრძალვებს ლოგიკური ახსნა მოუძებნოს: „რატომ არ შეიძლება ახლა ტკბილეული?“. პასუხისას „იმიტომ, რომ მე ასე ვამბობ“-ის ნაცვლად აუხსენით: „რადგან ახლა ტკბილეულს თუ შეჭამ, მუცელი გაგეძღება და სასარგებლო სადილს ვეღარ შეჭამ“. ეს მის ლოგიკურ აზროვნებას ავითარებს.') WHERE id = '1bdc4f44-d5e0-42ee-9d67-dc1beca39c22';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „დეტალები ადამიანის გამოსახულებაში“. როცა ბავშვი ადამიანს ხატავს, უკვე ამატებს ისეთ წვრილ დეტალებს, როგორიცაა თითები, წამწამები, ღილები ან ქუდი. ეს ნახატები იმის შედეგია, თუ რამდენად ყურადღებით აკვირდება ის გარე სამყაროს, და ასევე ხელისა და თვალის კოორდინაციის განვითარებას ასახავს.') WHERE id = 'dd86234a-f54a-432f-bcb2-f0fc25c1a9f2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„წარმოსახვითი შიშები და გამბედაობა“. ამ ასაკში წარმოსახვა იმდენად ძლიერია, რომ ბავშვმა სიბნელეში შეიძლება „ურჩხულები“ დაინახოს. ნუ უარყოფთ მის შიშს; ერთად შექმენით „შიშის გამფანტავი“ რიტუალები (მაგალითად, ჯადოსნური ბალიში ან ფანარი). ეს მას ემოციური უსაფრთხოების განცდას უმტკიცებს.') WHERE id = '30d373fa-79f5-41e2-b2ee-ce7f265298c1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ლიდერობა და თანამშრომლობა“. ბავშვი უკვე თავად იგონებს თამაშის სიუჟეტს და მეგობრებს როლებს უნაწილებს: „შენ კატა იყავი, მე კი შენი პატრონი ვიქნები“. ეს იმაზე მეტყველებს, რომ ის სოციალურ იერარქიასა და როლებს იაზრებს. ზოგჯერ აჰყევით მის სცენარს და ამგვარად მხარი დაუჭირეთ შემოქმედებითი ლიდერობის მცდელობას.') WHERE id = 'ec5ff997-3ed4-4645-be9c-2d361314cc2f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „რაოდენობა და რიცხვის სიმბოლო“. ბავშვს უკვე სრულად ესმის, რომ ციფრი „4“ ოთხ ვაშლს აღნიშნავს, ხოლო ციფრი „1“ — ერთ საგანს. მიეცით ისეთი დავალებები, როგორიცაა „მომეცი 5 ფანქარი“, რათა განუმტკიცოთ კავშირი აბსტრაქტულ რიცხვებსა და რეალურ რაოდენობას შორის.') WHERE id = 'c8eb9b80-1c81-4e02-86f3-e8fdf448ffb9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ორი ხელით დაჭერა“. ბავშვი უკვე იწყებს მისკენ ნელა ნასროლი ბურთის დაჭერას — ხელებს იდაყვებში ხრის და მკერდთან აერთიანებს (ზოგჯერ კი ბურთს პირდაპირ ხელებით იჭერს). ეს რეაქციის სისწრაფისა და თვალით მიყოლის უნარის განვითარებაზე მიუთითებს. ახლო მანძილიდან რბილი ბურთით ერთად ივარჯიშეთ.') WHERE id = 'e3704303-d02a-47ea-9a47-f1164a3046e0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „დროის რიტუალები“. ბავშვი ცნებებს „გუშინ“, „დღეს“ და „ხვალ“ უკვე უფრო სწორად იყენებს. როცა ამბობს: „ხვალ ბებიასთან წავალ“, ის გონებაში დროის მიმდინარეობას წარმოიდგენს. დღის ბოლოს ხვალინდელი გეგმები „ზღაპარივით“ მოუყევით და ასე დაიძინეთ. ეს მას მომავალი დროის აღქმის ჩამოყალიბებაშიც ეხმარება.') WHERE id = '58a4bd7b-b429-45cf-92c2-f503f4e7d474';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'განვითარების 1350 მნიშვნელოვანი დღე! ბავშვმა უკვე ოფიციალურად დატოვა „ჩვილობის“ ნაპირი და „ადრეული ბავშვობის“ ოკეანეში თავისუფლად დაცურავს. მისი ინდივიდუალურობა, იუმორის გრძნობა და ხასიათი ახლა თქვენთვის ყველაზე დიდი ინტერესის წყაროა. ამ 1350 დღის განმავლობაში თქვენ მისი სამყაროს ყველაზე საიმედო ნავსადგური იყავით. ყოჩაღ, დედა!') WHERE id = '647eb338-5057-4cf4-a29d-e4970189abc1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი სოციალურ თამაშებში უკვე იყენებს განსხვავებას „მე“-სა და „ჩვენ“-ს შორის. თუ ის ასე ანაწილებს საქმეს: „მოდი, ერთად ავაშენოთ სახლი: შენ აგურები მოიტანე, მე კი დავაწყობ“, ეს თანამშრომლობითი აზროვნების უმაღლესი გამოვლინებაა. მიეცით შესაძლებლობა, ჯგუფურ საქმიანობაში მოსინჯოს თავი როგორც ლიდერის, ისე დამხმარის როლში. ეს მომავალში გუნდური მუშაობისთვის საჭირო უნარებს ჩამოუყალიბებს.') WHERE id = '56b16411-749d-48ab-a1c9-aec6ee4d3f2b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „სწრაფი სირბილი და მკვეთრი მოხვევა“. ბავშვს უკვე შეუძლია სირბილისას წონასწორობის დაკარგვის გარეშე მკვეთრად მოუხვიოს. ეს აჩვენებს, რამდენად დაიხვეწა მისი სხეულის შეგრძნება (პროპრიოცეფცია) და კუნთების კონტროლი. პარკში „ზიგზაგით სირბილი“ მისთვის შესანიშნავი ვარჯიშია.') WHERE id = '3acf9991-6e18-469c-8243-5255e3b47e73';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „რატომ?“ კითხვების ლოგიკური ჯაჭვი. ბავშვი უკვე აღარ კმაყოფილდება თქვენი პასუხით და ჯაჭვურად გისვამთ კითხვებს: „მაშინ ის რატომ არის ასეთი?“ პასუხის გაცემისას თავადაც წაახალისეთ დაფიქრებისკენ: „შენი აზრით, სად მიდის მზე?“ ეს მის წარმოსახვას მეცნიერულ ცნობისმოყვარეობასთან აერთიანებს. მცირე ენციკლოპედიებით გაუფართოეთ ინტერესების სფერო.') WHERE id = '09e33fb1-46b4-4ad6-a2f6-bb3ee2d41636';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ქაღალდის დაკეცვა (ორიგამის საფუძვლები)“. ბავშვი უკვე ცდილობს, ქაღალდი ზუსტად შუაზე გადაკეცოს და კუთხეები ერთმანეთს დაამთხვიოს. ეს მოქმედება ხელის კუნთებსაც აძლიერებს და გეომეტრიული სიმეტრიის ცნებასაც ამყარებს მის გონებაში. ასწავლეთ ფერადი ქაღალდებით მარტივი ფორმების გაკეთება.') WHERE id = 'b9689a6f-2bcb-421e-acea-f03b1095905f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითკონტროლი და ემოციების გამოხატვა“. გაბრაზებისას ბავშვი მხოლოდ კი აღარ ყვირის, არამედ შეუძლია საკუთარი ემოცია სიტყვებით გამოხატოს: „ახლა ძალიან გაბრაზებული ვარ!“ აღიარეთ და დაადასტურეთ მისი გრძნობები: „მესმის შენი, გაბრაზება ნორმალურია“. ეს მის ემოციურ სიმწიფეს უწყობს ხელს.') WHERE id = '7a0c1e64-9ecb-47f6-83f4-aa32390210cd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „დიპლომატიური მოლაპარაკება“. სასურველის მისაღებად ბავშვმა შეიძლება ასეთი „გარიგება“ შემოგთავაზოთ: „თუ ამ მანქანას მომცემ, მეც მოგცემ შოკოლადს“. ეს სოციალური გავლენისა და დიპლომატიის უნარის ჩამოყალიბების დასაწყისია. თამაშის ფორმით გამოსცადეთ მასთან სამართლიანი „ვაჭრობის“ წესები.') WHERE id = '2dd70517-4599-4775-b1e7-2b11f39244da';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „რაოდენობის მუდმივობა (მოცულობა)“. ჩაატარეთ მასთან ექსპერიმენტი სამზარეულოში: ერთნაირი რაოდენობის წყალი ჩაასხით ერთ განიერ და ერთ მაღალ, ვიწრო ჭურჭელში. მან შესაძლოა ჯერ კიდევ თქვას, რომ მაღალ ჭურჭელში მეტი წყალია. ასეთი ექსპერიმენტები მას ვიზუალურ აღქმასა და ლოგიკურ აზროვნებას შორის წინააღმდეგობის გააზრებაში ეხმარება.') WHERE id = 'eb9fac33-252a-4cde-bb98-95be1aaf831f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ფეხით მართვა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, ფეხით ოდნავ წინ წაწიოს და ასე გადაადგილდეს (დრიბლინგი). ეს დინამიკურ წონასწორობასა და ყურადღებას მოითხოვს. პარკში მასთან ერთად მოაწყვეთ პატარა „საფეხბურთო ბილიკი“ და სთხოვეთ, ბურთი მიზნისკენ წაიყვანოს.') WHERE id = 'f40621db-c962-42bd-85b1-429800b2b4ef';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „თავაზიანობა და სოციალური ნორმები“. ბავშვი გამოთქმებს, როგორიცაა „ბოდიში“ და „შეიძლება?“, უკვე უბრალოდ დაზეპირებულად კი არ ამბობს, არამედ სიტუაციის შესაბამისად და გააზრებულად იყენებს. სხვებთან თქვენი საუბარი მისთვის მთავარი მაგალითია. როდესაც ის თავაზიანად იქცევა, აუცილებლად აგრძნობინეთ, რა სასიამოვნო შთაბეჭდილებას ახდენს მისი საქციელი გარშემომყოფებზე.') WHERE id = '3804d992-5f37-4fb4-bfb6-18ad143039e9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1360-დღიანი დიდი მოგზაურობა! ბავშვს უკვე 45 თვე შეუსრულდა. ახლა ის სრულფასოვანი პიროვნებაა — პატარა ადამიანი საკუთარი აზრებით, ხუმრობებითა და ოცნებებით. ამ 1360 დღის განმავლობაში თქვენ მისი სამყაროს არქიტექტორი იყავით. მის თავდაჯერებულ მზერაში თქვენი სიყვარულის კვალი ჩანს. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '333176ec-4bc6-4177-b76d-921996ec28d4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი საგნებს უკვე არა მხოლოდ გარეგნობის, არამედ მასალის მიხედვითაც განასხვავებს: „ეს პლასტმასაა, ეს კი რკინაა“. მიეცით მას სხვადასხვა ტექსტურის მქონე საგნები და ჰკითხეთ, რით განსხვავდება ისინი. ეს ეხმარება, უფრო დეტალურად გააანალიზოს გარემო და ფიზიკური სამყაროს შესახებ ცოდნა სისტემაში მოიყვანოს.') WHERE id = '657efc38-ed5e-4e3a-9572-7dbdb9184154';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ განვითარებაში „სტატიკური წონასწორობის მწვერვალი“. ბავშვს უკვე შეუძლია, ცალ ფეხზე 5-10 წამი ისე იდგეს, რომ არაფერს შეეხოს. ეს მიუთითებს როგორც შიგნითა ყურში მდებარე წონასწორობის ცენტრის განვითარებაზე, ისე წელისა და ფეხის კუნთების გაძლიერებაზე. ეთამაშეთ მას თამაში „გავიყინეთ“ და ეს უნარი სახალისო აქტივობად აქციეთ.') WHERE id = '2f039b11-24db-4020-90d7-1c5f7a16c171';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „თავაზიანობა და ეტიკეტი“. ბავშვი სიტყვებს „ბოდიში“ და „გთხოვთ“ უკვე არა უბრალოდ დაზეპირებულად, არამედ გააზრებულად იყენებს. სხვებთან საუბრისას თქვენი ხმის ტონი მისთვის საუკეთესო სახელმძღვანელოა. როდესაც ის თავაზიანად იქცევა, აგრძნობინეთ, რა დადებით გავლენას ახდენს ასეთი ქცევა გარშემომყოფებზე.') WHERE id = '81b527f9-bc6c-4fa6-a384-bfac0dbe1b99';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1370-დღიანი საოცარი გზა! ბავშვმა ჩვილობის ჩვევები უკვე სრულად დატოვა უკან და სკოლამდელი ასაკის ყველაზე აქტიურ ეტაპზე გადადის. ის უკვე საკუთარ თავს „მედ“ აღიქვამს და მზადაა, სამყარო შეცვალოს. ამ 1370 დღის განმავლობაში თქვენ მისი ყველაზე სანდო მეგზური იყავით. მადლობა გადაუხადეთ საკუთარ თავს სიყვარულისა და მოთმინებისთვის!') WHERE id = '7f1e62d7-6f8c-466a-917b-3acd9000a197';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი გარშემო არსებულ წარწერებში უკვე ნაცნობი ასოების ძებნას იწყებს, განსაკუთრებით კი — საკუთარი სახელის პირველ ასოს. ეს „ვიზუალური კითხვის“ ეტაპია. ნუ აიძულებთ ასოების სწავლას; უბრალოდ საინტერესოდ აღმოაჩენინეთ, რომელ ბგერას აღნიშნავს მის მიერ ნანახი თითოეული სიმბოლო.') WHERE id = '395ee563-1ee4-4a29-8a28-f145933f9a6e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში — „დინამიკური მანევრირება“. ბავშვს სირბილისას უკვე ადვილად შეუძლია წინ არსებული დაბრკოლებისთვის გვერდის ავლა ან მიმართულების უეცრად შეცვლა. ეს ტვინში მოძრაობის დაგეგმვის უნარის გაუმჯობესებაზე მიუთითებს. პარკში მასთან ერთად „ზიგზაგის რბოლა“ ითამაშეთ და მოქნილობის განვითარებაში დაეხმარეთ.') WHERE id = 'cad61f20-8263-4b3a-bfc8-ed14fb447f18';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ვარაუდი და ლოგიკა“. ზღაპრის კითხვისას ჰკითხეთ: „როგორ ფიქრობ, შემდეგ რა მოხდება?“ ბავშვს უკვე შეუძლია მოვლენების განვითარების შესაბამისად ლოგიკური ვარაუდების გამოთქმა. ეს ავითარებს როგორც მის წარმოსახვას, ისე მიზეზშედეგობრივი კავშირების გაგების უნარს.') WHERE id = '9337ce82-dd36-4b6f-a92e-336053ee8590';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ფიგურის გადახატვა: კვადრატი“. წრისგან განსხვავებით, კვადრატის დახატვისას საჭიროა ფანქრის კუთხეებთან შეჩერება და მიმართულების შეცვლა. ეს წერის შესასწავლად მნიშვნელოვანი ფიზიკური მომზადებაა. აჩვენეთ, როგორ შეიძლება სხვადასხვა გეომეტრიული ფიგურის გაერთიანებით სახლის ან მანქანის დახატვა.') WHERE id = '90518b08-497d-4de6-998e-df3fea30a1f5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მიზეზ-შედეგობრივი ჯაჭვი“. ბავშვი უკვე ცდილობს, თქვენს აკრძალვებს ლოგიკური ახსნა მოუძებნოს: „რატომ არ შეიძლება ახლა ტკბილეული?“. პასუხისას, „იმიტომ, რომ მე ასე ვამბობ“ ფრაზის ნაცვლად, აუხსენით: „თუ ახლა ტკბილეულს შეჭამ, მუცელი გაგევსება და სასარგებლო სადილს ვეღარ შეჭამ“. ეს მის ლოგიკურ აზროვნებას ავითარებს.') WHERE id = 'c914eb21-6b42-48f0-8ec0-5b93a47ae392';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „ადამიანის გამოსახულების დეტალები“. ბავშვი ადამიანის ხატვისას უკვე ამატებს ისეთ წვრილ დეტალებს, როგორიცაა თითები, წამწამები, ღილები ან ქუდი. ეს ნახატები იმის შედეგია, თუ რამდენად ყურადღებით აკვირდება ის გარემოს, და ასევე მისი თვალისა და ხელის კოორდინაციის განვითარებას ასახავს.') WHERE id = 'fdd8b340-0697-4aeb-8d02-8988eb7da642';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„წარმოსახვითი შიშების მართვა“. ამ ასაკში ბავშვებს ზოგჯერ სიბნელის ან „ურჩხულების“ ეშინიათ. ნუ უარყოფთ მის შიშს; ამის ნაცვლად, მოიფიქრეთ ისეთი თამაშები, როგორიცაა „ჯადოსნური ფანარი, რომელიც ურჩხულს განდევნის“. თქვენი ემოციური მხარდაჭერა ბავშვს ასწავლის, რომ ეს შიშები დროებითია.') WHERE id = 'd0348641-27c7-4875-b24e-5d2722f25676';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „შედეგზე ორიენტირებული თანამშრომლობა“. ბავშვს უკვე შეუძლია, მეგობართან ერთად დიდი კოშკის ასაშენებლად „კუბიკები“ გაინაწილოს. ეს უკვე არა უბრალოდ გვერდიგვერდ, არამედ საერთო მიზნისთვის თამაშია (თანამშრომლობითი თამაში). შეაქეთ მისი ეს პატარა დიპლომატი და უთხარით: „რა შესანიშნავი გუნდი ხართ!“.') WHERE id = 'bd3e5f00-1925-4d9d-bea8-7fc43abbb171';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „რაოდენობის მუდმივობის ტესტი“. ბავშვმა შეიძლება ჯერ კიდევ იფიქროს, რომ გაბრტყელებული პლასტილინი გუნდად შეკრულ პლასტილინზე დიდია. ჩაატარეთ მასთან მსგავსი ცდები: პლასტილინის გუნდა გააბრტყელეთ, შემდეგ კი კვლავ გუნდად შეკარით. ეს ეხმარება ბავშვს, გაიაზროს ფიზიკური სამყაროს უცვლელი კანონები.') WHERE id = '34ed2954-3007-40b2-9228-8e5bbced6cd6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ფეხით მართვა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს, არამედ ცდილობს, ფეხით ოდნავ წინ გაგორებით (დრიბლინგით) გადაადგილოს. ეს დინამიკურ წონასწორობასა და ფეხისა და თვალის კოორდინაციას მოითხოვს. პარკში მოუწყეთ პატარა „საფეხბურთო ბილიკი“ და სთხოვეთ, ბურთი მიზნისკენ წაიყვანოს.') WHERE id = 'f67ac937-be10-4065-8ce0-71169b977a25';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"თვითკონტროლი და მოთმინება". ბავშვს უკვე ესმის, რომ რიგის ლოდინი ან სურვილის დაუყოვნებლივ შეუსრულებლობა "დასასრული" არ არის. თქვენს ნათქვამს — "5 წუთი მოიცადე" — უფრო მშვიდად იღებს. ლოდინის შემდეგ აუცილებლად უთხარით: "მადლობა, რომ მოთმინება გამოიჩინე" და ამით მისი დადებითი ქცევა განამტკიცეთ.') WHERE id = '24183c71-3661-48ff-a107-410bfbd38523';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — "წესებზე დაფუძნებული გუნდური თამაშები". ბავშვი უკვე ინტერესდება სხვა ბავშვებთან ერთად ისეთი თამაშებით, რომლებსაც წესები აქვს (მაგალითად, "დამალობანა"). ეს სოციალური ადაპტაციის მნიშვნელოვანი ეტაპია. როდესაც წესებს იცავს, შეაქეთ სიტყვებით: "ყოჩაღ, რომ პატიოსნად ითამაშე".') WHERE id = '04f3027e-9e30-43e8-bafb-f6c237c97831';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტურ განვითარებაში — "რაოდენობის მყისიერი ამოცნობა (Subitizing)". ბავშვს უკვე შეუძლია 4-5 საგანს უბრალოდ შეხედოს და დაუთვლელად მიხვდეს, რამდენია. აჩვენეთ ბარათები სხვადასხვა რაოდენობის წერტილებით და ჰკითხეთ: "რამდენია აქ?" ეს სამომავლოდ სწრაფი მათემატიკური გამოთვლების საფუძველია.') WHERE id = '494bf11b-00d7-4571-8a96-04e2a73dc57c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: "ერთ ფეხზე ხტომა". ბავშვი უკვე ცდილობს ერთ ფეხზე ზედიზედ რამდენჯერმე ახტეს. ამას ძალაც და კარგად განვითარებული წონასწორობაც სჭირდება. სახლში მასთან ერთად ითამაშეთ "ნაკვალევებზე ხტომა", რათა ფეხის კუნთები და წონასწორობის უნარი გაუძლიერდეს.') WHERE id = 'e519a6cc-28f9-4dbb-80e3-d4aaf6533df1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — "დროის ვიზუალიზაცია". ბავშვმა უკვე კარგად იცის დღის მონაკვეთები და მათი თანმიმდევრობა. "დილით, როცა ვიღვიძებთ, მზე ამოდის, საღამოს კი მთვარე ჩნდება". მასთან ხვალინდელი გეგმების "ჯერ, შემდეგ, ბოლოს" ფორმატით განხილვა უსაფრთხოების განცდასაც უყალიბებს.') WHERE id = '22058766-30d2-4299-8138-dbe3e33f7a99';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: "დიპლომატია და გამოსავლის პოვნა". კონფლიქტის დროს ბავშვი უკვე მხოლოდ ტირილით აღარ რეაგირებს და ისეთ წინადადებებს გამოთქვამს, როგორიცაა: "მოდი, სათამაშო გავიყოთ" ან "ეს მე მომეცი და მეც ამას მოგცემ". ეს სოციალური ინტელექტის უმაღლესი გამოვლინებაა. ყოველთვის მხარი დაუჭირეთ მის მშვიდობიან მიდგომას. თქვენ შესანიშნავ პიროვნებას ზრდით!') WHERE id = '29c7e41f-162a-440d-ad79-c662956e2e8e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია ნივთები ერთდროულად ფერისა და ზომის მიხედვით დააჯგუფოს: „ყველა პატარა და მწვანე კუბი აქ მოვაგროვოთ“. ეს კოგნიტიური მოქნილობის მნიშვნელოვანი მაჩვენებელია. ყურადღების გასავითარებლად შესთავაზეთ სხვადასხვა კრიტერიუმზე დაფუძნებული თამაში „მოძებნე და იპოვე“.') WHERE id = '428720ac-8db6-44a9-825f-ab25eee4d54f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ზუსტი სროლა“. ბავშვს უკვე შეუძლია ბურთი ან პატარა ტომარა უფრო ზუსტად ისროლოს კონკრეტული სამიზნისკენ (მაგალითად, კალათში). ეს სივრცეში მანძილის შეფასებისა (spatial estimation) და ძალის რეგულირების უნარების განვითარებაზე მიუთითებს. სახლში მასთან ერთად მოაწყვეთ შეჯიბრება „მოარტყი სამიზნეს“; ეს ასევე ხელს უწყობს თვალისა და ხელის კოორდინაციის გაუმჯობესებას.') WHERE id = '5a34a884-0d1a-4ecc-8aaf-0538071d5d58';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „რატომ“-დან „როგორ“-ზე გადასვლა. ახლა ბავშვი არა მხოლოდ მოვლენების მიზეზს, არამედ მათ მექანიზმსაც კითხულობს: „მანქანა როგორ მოძრაობს?“, „წვიმა როგორ მოდის?“. პასუხის გაცემისას მარტივი ფიზიკური კანონების ახსნით (მაგალითად, „ბორბლები ტრიალებს“) წაახალისეთ მისი სამეცნიერო ცნობისმოყვარეობა.') WHERE id = '43f973d1-c670-48fb-b082-c963d974b2cb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „კომპოზიციის შექმნა“. ხატვისას ბავშვი უკვე ერთ ფურცელზე რამდენიმე ერთმანეთთან დაკავშირებულ ობიექტს აერთიანებს: „ეს სახლია, ეს კი მის გვერდით მდგომი ხე“. ეს მიუთითებს, რომ ბავშვი ვიზუალური სამყაროს მთლიანად და სისტემურად აღქმას იწყებს.') WHERE id = '4fc62a39-6aec-4659-8e0d-de5a572b7f58';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითრეგულაცია (Self-regulation)“. გაბრაზებისას ბავშვი უკვე ცდილობს, ფიზიკური რეაქცია (მაგალითად, დარტყმა) სიტყვებით ჩაანაცვლოს და თქვას: „გავბრაზდი!“. ეს ემოციური ინტელექტის განვითარებაში ერთ-ერთი უდიდესი წინსვლაა. როდესაც ბავშვი თავის გრძნობას გამოხატავს, მოუსმინეთ და მხარი დაუჭირეთ სიტყვებით: „ვამაყობ შენით, რომ შენი გრძნობა სიტყვებით გამოხატე“.') WHERE id = '2e78bbc8-d3e0-46e9-b6f4-fd06f0ff0e92';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „დიალოგი როლურ თამაშებში“. ახლა ბავშვი თამაშისას ხანგრძლივ დიალოგებს აწყობს: „შენ მაღაზიაში მოხვედი და ჩემგან პურს ითხოვ...“. ამ თამაშების საშუალებით ის სოციალურ ნორმებსა და კომუნიკაციის ეტიკეტს სცდის. მიჰყევით მის სცენარს და ჩაერთეთ ამ შემოქმედებით პროცესში.') WHERE id = 'c878d5a6-c839-4863-9ea6-c1e45caf4ee6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებითი განვითარების ეტაპი — „საპირისპირო ცნებების კლასიფიცირება“. ბავშვი უკვე მკაფიოდ განასხვავებს ცნებებს: „ცხელი-ცივი“, „მაღალი-დაბალი“, „მძიმე-მსუბუქი“. ეთამაშეთ თამაში „იპოვე საპირისპირო“: თქვენ თქვით „დიდი“, მან კი — „პატარა“. ეს ხელს უწყობს როგორც მისი ლექსიკური მარაგის გამდიდრებას, ისე აბსტრაქტული შედარებითი აზროვნების განვითარებას.') WHERE id = '96a1b8b4-4a53-4821-8a70-36e9af7db4b1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „კიბეზე მანევრირება“. ბავშვი უკვე თავდაჯერებით ადის და ჩამოდის კიბეზე და ზოგჯერ წონასწორობის შენარჩუნებას მაშინაც ახერხებს, როცა ხელში სათამაშო უჭირავს. ეს დინამიკური წონასწორობის მაღალი დონის მაჩვენებელია. ყოველთვის ახლოს იყავით, თუმცა აგრძნობინეთ, რომ ენდობით და დამოუკიდებლად მოძრაობა შეუძლია.') WHERE id = 'e31518b3-755f-43f6-a042-c5c881774776';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველება: „წარმოსახვა და ამბის მოყოლა“. ბავშვმა შეიძლება თავისივე გამოგონილი პატარა ზღაპრები მოგიყვეთ. ამ ზღაპრებში რეალობა და ფანტაზია ერთმანეთშია შერწყმული. წაახალისეთ მისი მონათხრობი ისეთი დაინტერესებული შეკითხვებით, როგორიცაა „მართლა?“ ან „შემდეგ რა მოხდა?“. ეს მომავალში მისი მეტყველების გამართულობასა და გამომსახველობას შეუწყობს ხელს.') WHERE id = '1285abea-7296-4d22-a83f-6877ea839c11';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მედეგობა: „გამარჯვება და დამარცხება“. ბავშვი თამაშში წაგებას უკვე უფრო მშვიდად იღებს, თუმცა არა ყოველთვის. სიტყვებით „მოდი, კიდევ ერთხელ ვითამაშოთ“ ხელახლა ცდა მისი ნებისყოფის მაჩვენებელია. ყოველთვის გაუსვით ხაზი ამ მნიშვნელოვან ცხოვრებისეულ უნარს და უთხარით: „მთავარი თამაშია“.') WHERE id = 'ab47da7b-7dd4-423e-bf69-3500dd83cc2f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე რთულ სოციალურ სიტუაციებშიც იყენებს ლოგიკას „თუ... მაშინ...“: „თუ მე მას ჩემს სათამაშოს მივცემ, ისიც მომცემს თავისას“. ეს ურთიერთგაგებისა და ორმხრივი ურთიერთობების საფუძველია. ეთამაშეთ თამაში „რა შედეგი მოჰყვება?“ (მაგალითად, „რა მოხდება, თუ ყვავილს არ მოვრწყავთ?“). ეს ბავშვს მოვლენების წინასწარ განჭვრეტის უნარს უვითარებს.') WHERE id = 'd6bf3a90-b7f5-4d81-9101-4bd23f1bc25d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური აქტივობა: „სიმაღლიდან ხტომა“. ბავშვს უკვე შეუძლია გარკვეული სიმაღლიდან (მაგალითად, დაბალი საფეხურიდან) ორივე ფეხზე ისე ჩამოხტეს, რომ წონასწორობა არ დაკარგოს. ეს მუხლისა და კოჭ-წვივის სახსრების გაძლიერების მაჩვენებელია. ასწავლეთ „რბილად დაშვება“ — მუხლების ოდნავ მოხრით.') WHERE id = '2795a26f-4a85-42cd-9860-03afd8411f60';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „წინასწარმეტყველების უნარი“. ზღაპრის კითხვისას ბავშვი უკვე ლოგიკურად პასუხობს კითხვას: „როგორ ფიქრობ, შემდეგ რა მოხდება?“ ეს იმაზე მიუთითებს, რომ ის მოვლენებს შორის ფარული კავშირების გააზრებას იწყებს. წაახალისეთ მისი წარმოსახვა კითხვით: „შენ მის ადგილას რას გააკეთებდი?“') WHERE id = '8651dfdb-b093-4f7c-b25e-9846200e12c4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „დროის აბსტრაქტული ცნებები“. ბავშვს უკვე ესმის დროის უფრო ფართო მონაკვეთები, როგორიცაა „შაბათ-კვირას“, „დღესასწაულზე“, „დაბადების დღეზე“. როდესაც მასთან ახლო მომავალში დაგეგმილ მნიშვნელოვან მოვლენაზე (მაგალითად, გასეირნებაზე) საუბრობთ, გამოიყენეთ ისეთი გამოთქმები, როგორიცაა „3 დღის შემდეგ“, რათა დროის აღქმა კიდევ უფრო გაუღრმაოთ.') WHERE id = '4dbdf376-fb0e-469f-bb2e-b3be32d8d1c8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ასოების გადაწერა“. ბავშვი უკვე ცდილობს, ზოგიერთი მარტივი ასო (მაგალითად, A, O, T) ზუსტად ისე გადაწეროს, როგორც ხედავს. ამ დროს სიმბოლოები ერთდროულად გადადის როგორც ვიზუალურ, ისე მოტორულ მეხსიერებაში. შესთავაზეთ, ასოები ქვიშით სავსე ლანგარზე ან თითის საღებავებით „დაწეროს“.') WHERE id = '83f43947-4f06-425b-801a-dd053a64d6b1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითრეგულაცია: სურვილის გადავადება“. ბავშვი უკვე ეგუება, რომ ჯილდოს მისაღებად ცოტა მეტხანს უნდა მოიცადოს (მაგალითად, „ტკბილეული ჭამის შემდეგ“). ეს ნებისყოფისა და თვითრეგულაციის (სიამოვნების გადავადების) განვითარებაზე მიუთითებს. აუცილებლად აღნიშნეთ და შეაქეთ მისი მოთმინება; ეს მომავალში წარმატებული აკადემიური ცხოვრების ერთ-ერთი გასაღებია.') WHERE id = '51891c5d-a6e3-40d4-8ba5-38112ce2f223';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ჯგუფური სოლიდარობა“. როდესაც მეგობარი ტირის, ბავშვი უკვე უბრალოდ კი არ უყურებს, არამედ ეკითხება: „რა მოხდა?“ ან თქვენ გაცნობებთ. ეს ემპათიის აქტიური ეტაპია. მხარი დაუჭირეთ მის მზრუნველ დამოკიდებულებას და უთხარით: „ძალიან კეთილი მეგობარი ხარ“.') WHERE id = '9932ed27-e891-4fec-aac9-e64c5a418a49';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში — „შეკრების საფუძვლები“. ბავშვი უკვე ხვდება, რომ თუ 2 სათამაშოს კიდევ 1 დაემატება, სულ 3 გამოვა — დათვლის გარეშე (ან სწრაფად დათვლით). ყოველდღიური საქმიანობისას შესთავაზეთ პატარა მათემატიკური ამოცანები, მაგალითად: „შენ 2 ვაშლი გქონდა, მე კიდევ 1 მოგეცი. ახლა რამდენი გაქვს?“') WHERE id = '5f9e5aa3-02e0-4bd3-85bf-ad954730aed0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ცალ ფეხზე ხტომა (ჰოპ-სტოპი)“. ბავშვს უკვე შეუძლია, ცალ ფეხზე ზედიზედ 2-3-ჯერ ახტეს. ამისთვის საჭიროა როგორც წონასწორობის კარგად დაცვა, ისე ფეხის კუნთების ძალა. სახლში მასთან ერთად ითამაშეთ „ნაკვალევი“, რათა კოორდინაცია კიდევ უფრო განუვითაროთ.') WHERE id = '5d319604-f8fa-4e75-83e3-e78cf306cb47';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკის უნარებში — „ქაღალდის გამოჭრა: ფორმის ამოჭრა“. ბავშვი უკვე ცდილობს, უსაფრთხო მაკრატლით მარტივი წრე ან კვადრატი კონტურის გასწვრივ ამოჭრას. ეს ხელის წვრილი კუნთების მაღალ დონეზე კონტროლს მოითხოვს.') WHERE id = '9727b126-febe-431d-a82a-db6a6416efff';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სამართლიანობისა და წესრიგის მცველი“. ბავშვი უკვე რეაგირებს არა მხოლოდ მაშინ, როცა თავად არღვევს წესს, არამედ მაშინაც, როცა ამას სხვები აკეთებენ: „მამა, შენ რიგი დაარღვიე!“ ეს შინაგანი სინდისისა და სოციალური სამართლიანობის განცდის ჩამოყალიბებაა. აუხსენით, რატომ არის წესები ყველასთვის ერთნაირი.') WHERE id = 'a0bdfa22-2c16-417c-bc41-62353716c069';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „დიპლომატიური გადაწყვეტილებები“. კონფლიქტის დროს ბავშვს უკვე შეუძლია ისეთი შეთავაზებების გაკეთება, როგორიცაა: „მოდი, რიგრიგობით ვითამაშოთ“. ეს სოციალური ინტელექტის ერთ-ერთი ყველაზე მკაფიო მაჩვენებელია. აუცილებლად შეაქეთ მისი მშვიდობიანი მიდგომა და უთხარით: „ძალიან კარგი გამოსავალი იპოვე“.') WHERE id = '1c1d5af4-d669-4eee-8938-97dcf06fd2d8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიური განვითარებისთვის ჩაატარეთ „რაოდენობის მუდმივობის ექსპერიმენტები“. ბავშვთან ერთად ითამაშეთ ქვიშით ან წყლით. ერთი და იგივე რაოდენობის წყალი სხვადასხვა ჭურჭელში ჩაასხით. მან შეიძლება ჯერ კიდევ იფიქროს, რომ მაღალ ჭურჭელში მეტი წყალია. ასეთი ექსპერიმენტები მის ტვინს ფიზიკური რეალობის აღქმისთვის ამზადებს.') WHERE id = '32e16fdb-1a45-43a1-8bb5-fea77db311d2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „აღწერითი ამბავი“. ბავშვი მის მიერ დახატულ სურათს ან ნანახ მოვლენას თანმიმდევრული წინადადებებით გადმოსცემს. „აქ ძაღლი იყო, გაიქცა, შემდეგ ხეზე ავიდა...“. ყურადღება მიაქციეთ მისი მონათხრობის თანმიმდევრულობას. ეს აჩვენებს, როგორ აწყობს ის გონებაში მოვლენებს ლოგიკური თანმიმდევრობით.') WHERE id = '5e32473e-0836-4d23-8816-7e98014c394b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1400 დღის დიდი გამარჯვება! თქვენმა ბავშვმა უკვე 46 თვე შეასრულა. ის უკვე პატარა „მეცნიერია“, რომელიც საკუთარ თავს აცნობიერებს, სხვების გრძნობებს თანაუგრძნობს და სამყაროს ლოგიკურად იკვლევს. ამ 1400 დღის განმავლობაში თქვენ თქვენი ბავშვისთვის ყველაზე საიმედო ნავსაყუდელი და საუკეთესო მასწავლებელი იყავით. თქვენ შესანიშნავი დედა ხართ!') WHERE id = 'af7c9867-8fc8-42cc-b62a-1044c801bdef';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება 47-ე თვეში! ბავშვს უკვე უკეთ ესმის „პასუხისმგებლობის“ მნიშვნელობა. მიეცით მას სახლში მცირე „დავალებები“ (მაგალითად, მცენარეების მორწყვა ან მაგიდაზე ხელსახოცების დადება). ეს დაეხმარება, თავი ოჯახის მნიშვნელოვან და სასარგებლო წევრად იგრძნოს. აუცილებლად აღნიშნეთ მისი ძალისხმევა და მადლობა გადაუხადეთ.') WHERE id = '13b68bb4-0e80-4802-bd12-f626258d3f54';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „მონაცვლეობითი ნაბიჯებით სირბილი“. ბავშვს უკვე შეუძლია სირბილისას კიბის საფეხურები ან დაბრკოლებები რიტმულად გადალახოს და ყოველ ნაბიჯზე თითო ფეხი დადგას. ეს აჩვენებს, რამდენად განვითარდა ქვედა კიდურების ძალა და ვიზუალურ-მოტორული დაგეგმვის უნარი.') WHERE id = '8fba68a9-4860-41c9-9d6a-0aabd4a4dc7d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ფონეტიკა და ასოები“. ბავშვი უკვე არჩევს, რომელი ბგერით იწყება სიტყვა: „ვაშლი ''ვ''-ზე იწყება“. ითამაშეთ მასთან „ბგერებზე ნადირობა“; სთხოვეთ, ოთახში იპოვოს საგნები, რომელთა სახელებიც კონკრეტული ბგერით იწყება. ეს მომავალში კითხვისა და წერის უნარების ჩამოყალიბებისთვის უმნიშვნელოვანესი საფუძველია.') WHERE id = '4c5fdac9-9874-4896-80d4-6960b6675b1b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ფანქრის სწორად დაჭერა (ტრიპოდული ჭერა)“. ბავშვი უკვე უფრო თავდაჯერებულად იჭერს ფანქარს ცერა, საჩვენებელი და შუა თითებით („სამფეხა“ ჭერით). ეს საშუალებას აძლევს, უფრო დეტალური ნახატები დახატოს და ასოები გადაიწეროს. მიეცით სხვადასხვა სისქის ფანქრები, რათა თითის კუნთები ავარჯიშოს.') WHERE id = '01cf8b7d-9668-4ab1-a360-d6968cb99749';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის მხარს ზემოდან გადაგდება“. ბავშვს უკვე შეუძლია ბურთი მიზნისკენ უფრო ძლიერად და ზუსტად ისროლოს. ეს ხელისა და მხრის კუნთების კოორდინირებული მუშაობის შედეგია. პარკში მასთან ერთად ითამაშეთ პატარა თამაში — „ბურთის კალათში ჩაგდება“. ეს არა მხოლოდ სახალისოა, არამედ სხეულის კონტროლსაც აუმჯობესებს.') WHERE id = '5eff2db7-b37a-4ebb-9335-292fea3a6331';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითმართვა: წესების ლოგიკა“. ბავშვი უკვე ცდილობს, წესები დაიცვას არა მხოლოდ იმიტომ, რომ თქვენ უთხარით, არამედ იმიტომაც, რომ მათი ლოგიკა ესმის. „გზაზე სიარულისას ხელს გკიდებ, რადგან მანქანები მოძრაობენ“. განაგრძეთ მისთვის იმის ახსნა, რომ წესები უსაფრთხოებისა და წესრიგისთვის აუცილებელია — ეს შინაგანი დისციპლინის საფუძველია.') WHERE id = 'd91c45ef-c67b-4312-9a1e-572e86ed0a0e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „სამართლიანად განაწილება“. ბავშვი უკვე ინტერესდება სათამაშოების ან ტკბილეულის მეგობრებს შორის თანაბრად განაწილებით: „ერთი შენ, ერთი მე“. ეს სოციალური ემპათიისა და საწყისი მათემატიკური წარმოდგენების (გაყოფის) შერწყმაა.') WHERE id = '2a9fd489-5479-4444-9ad0-d9ca9e6d37c8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „საგნების კლასიფიცირება“. ბავშვი უკვე აჯგუფებს საგნებს როგორც მათი სახეობის, ისე გამოყენების ადგილის მიხედვით: „ესენი სამზარეულოსთვისაა, ესენი კი — საძინებლისთვის“. ეს აჩვენებს, რამდენად სისტემურად და იერარქიულად არის ორგანიზებული ინფორმაცია მის გონებაში.') WHERE id = 'b49a3e45-1e44-429c-b3ab-7432f30a4a37';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის დაჭერა და სროლა (ინტეგრაცია)“. ბავშვს უკვე შეუძლია, ბურთის დაჭერისთანავე მიზანში ისროლოს. ეს თანმიმდევრული მოძრაობების ერთმანეთთან დაკავშირებაა. პარკში მასთან ერთად ითამაშეთ „ესროლე-დაიჭირე“, რათა რეაქციის სისწრაფე და მოქნილობა განუვითაროთ.') WHERE id = 'b2cee277-0949-412e-af09-df96b2fd9cfd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „რთული წინადადებების აგება“. ბავშვი უკვე იყენებს ისეთ კავშირებს, როგორებიცაა „თუ“, „რადგან“ და „თუმცა“, და გრძელ, ლოგიკურ წინადადებებს ადგენს. მოუსმინეთ ისე, რომ არ შეაწყვეტინოთ, და გაუფართოეთ აზრი სიტყვებით: „ანუ, შენ ასე ფიქრობ...“. ეს აუმჯობესებს საკუთარი აზრის გამოხატვის უნარს და აქტიურ ლექსიკურ მარაგს.') WHERE id = 'eaf98320-82a4-46ba-81fe-43fd023e6b82';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური სიმტკიცე: „საკუთარი თავის დამშვიდება“. მცირე წაქცევის ან წარუმატებლობის დროს ბავშვმა შეიძლება მაშინვე აღარ იტიროს, საკუთარ თავს უთხრას „არაფერი მომხდარა“ და წამოდგეს. ეს ემოციური გამძლეობის მნიშვნელოვანი მაჩვენებელია. ყოველთვის დაუჭირეთ მხარი მის სიმამაცეს სიტყვებით: „ძალიან ძლიერი ხარ!“.') WHERE id = 'c0cb0b02-4a51-4012-b51b-53868aad0bf0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე ინტერესდება „საათის“ ცნებით. შეიძლება გკითხოთ: „რომელი საათია?“ დრო წუთებით კი არა, მოვლენებით აუხსენით: „როცა დიდი ისარი აქ მოვა, სასეირნოდ წავალთ“. ეს დაეხმარება გააცნობიეროს, რომ დრო გაზომვადი ცნებაა.') WHERE id = '3a58737c-1dc5-47f3-86ee-31c959892712';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ჯვარედინი კოორდინაცია“. ბავშვს უკვე შეუძლია, ადგილზე ნაბიჯისას მარჯვენა ხელი მარცხენა მუხლს მიადოს და პირიქით. ეს მოძრაობა ტვინის ორივე ნახევარსფეროს ერთდროულ მუშაობას მოითხოვს და მომავალში კითხვისა და წერის პროცესს გაუადვილებს.') WHERE id = '86960e2f-7035-4c14-a9a6-baeb23c3ea3d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „წარსულის დეტალები“. ბავშვს უკვე შეუძლია, რამდენიმე დღის წინ მომხდარი ამბავი თანმიმდევრულად მოყვეს: „ბებიასთან რომ წავედით, იქ კატა ვნახეთ და ის ხეზე ავიდა“. მისი „ეპიზოდური მეხსიერების“ გასაძლიერებლად დღის ბოლოს ჰკითხეთ: „რა იყო დღეს ყველაზე საინტერესო?“') WHERE id = '6caf0def-6055-4b83-9a80-442193cfb9e1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ქაღალდის ჭრა: რთული ფორმები“. ბავშვი უკვე ცდილობს, მაკრატლით არა მხოლოდ სწორი ხაზის გასწვრივ გაჭრას, არამედ ტალღოვანი ხაზები ან დიდი წრეც გამოჭრას. ეს ხელისა და თვალის კოორდინაციის განვითარების ძალიან მაღალ დონეზე მიუთითებს.') WHERE id = '64c3b0ce-8c21-4147-b606-f32ae65475bf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მარჯვენისა და მარცხენის ცნება“. ბავშვს უკვე შეუძლია მარჯვენა და მარცხენა ხელის გარჩევა, თუმცა ჯერ ყოველთვის ზუსტად არა. სივრცეში ორიენტაციის გასაუმჯობესებლად უთხარით: „კოვზი მარჯვენა ხელით დაიჭირე“ ან „წინდა მარცხენა ფეხზე ჩაიცვი“. ეს უნარი მნიშვნელოვანია, რათა მომავალში ასოების მიმართულება არ აერიოს.') WHERE id = '51c70f08-e08e-4a17-97ca-6373b3c435eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ჯგუფში ლიდერობა“. თამაშის დროს ბავშვი უკვე ანაწილებს როლებს და სხვა ბავშვებს ეუბნება: „შენ აქ გადმოდი, შენ ეს გააკეთე“. ასე ის სოციალურ იერარქიასა და ორგანიზატორულ უნარებს ცდის. დააკვირდით ლიდერობის მის მცდელობებს და დაეხმარეთ, სამართლიანი იყოს.') WHERE id = 'ed221959-c928-4692-880d-29170d62352e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „საპირისპირო ცნებების კლასიფიკაცია“. ბავშვი უკვე სრულად არჩევს ერთმანეთისგან ცნებებს: „ცხელი-ცივი“, „მაღალი-დაბალი“, „მძიმე-მსუბუქი“. ეთამაშეთ თამაში „იპოვე საპირისპირო“: თქვენ თქვით „დიდი“, მან კი — „პატარა“. ეს ავითარებს როგორც მის ლექსიკურ მარაგს, ისე აბსტრაქტულ შედარებით აზროვნებას.') WHERE id = '00735398-0d89-4428-a943-f4a27fc19021';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში — „ფიგურის გადახატვა: სამკუთხედი და ჯვარი“. ბავშვს უკვე შეუძლია სწორი ხაზების გადაკვეთით ჯვრის (+) დახატვა და ცდილობს სამკუთხედის მსგავსი ფორმების შექმნას. ეს წერის უნარის საწყისი საფუძველია. მიეცით ფერადი ფანქრები და სუფთა ფურცლები, რათა ხელი შეუწყოთ მის ამ „გეომეტრიულ აღმოჩენებს“.') WHERE id = '1b117df4-43a4-4780-a2e3-365c2acc3518';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითკონტროლი: სურვილის დაკმაყოფილების გადავადება“. ბავშვი უკვე ეგუება, რომ ჯილდოს მისაღებად ცოტა მეტი ხანი უნდა მოიცადოს (მაგალითად, „ტკბილეული ჭამის შემდეგ“). ეს ნებისყოფისა და თვითკონტროლის (delayed gratification) განვითარებაზე მიუთითებს. აუცილებლად შეაქეთ მისი მოთმინება — მომავალში ეს წარმატებული აკადემიური ცხოვრების ერთ-ერთი მნიშვნელოვანი საფუძველია.') WHERE id = '93c7b1b4-9941-4328-bd03-c48ffc7f605f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „ჯგუფური თანადგომა“. როცა მეგობარი ტირის, ბავშვი უკვე მხოლოდ კი არ უყურებს, არამედ ეკითხება: „რა მოხდა?“ ან თქვენ გატყობინებთ. ეს ემპათიის აქტიური ეტაპია. მხარი დაუჭირეთ მის მზრუნველ ბუნებას და უთხარით: „ძალიან კეთილი მეგობარი ხარ“.') WHERE id = 'e9a7f349-2186-4929-ba3f-64f7d951af57';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში — „შეკრების საფუძვლები“. ბავშვს უკვე შეუძლია მიხვდეს, რომ თუ 2 სათამაშოს კიდევ 1-ს დაუმატებს, სულ 3 გამოვა — დათვლის გარეშე ან სწრაფად დათვლით. ყოველდღიურ საქმიანობაში მოუფიქრეთ პატარა მათემატიკური ამოცანები, მაგალითად: „2 ვაშლი გქონდა, მე კიდევ 1 მოგეცი. ახლა რამდენი გაქვს?“') WHERE id = '6d1eeaa2-0164-4cca-94b4-9c14e8d79d60';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „კიბეზე მანევრირება“. ბავშვი უკვე თავდაჯერებით ადის და ჩადის კიბეზე და ზოგჯერ მაშინაც კი ინარჩუნებს წონასწორობას, როცა ხელში სათამაშო უჭირავს. ეს დინამიკური წონასწორობის მაღალი დონეა. ყოველთვის ახლოს იყავით, თუმცა აგრძნობინეთ, რომ ენდობით და დამოუკიდებლად მოძრაობის საშუალება მიეცით.') WHERE id = '28cfd5f7-ecbc-4133-9e9d-cc5c82140054';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში — „რაოდენობის მუდმივობა: რიცხვი“. თუ ერთნაირი რაოდენობის ქვებს ერთ მხარეს მჭიდროდ დააწყობთ, მეორე მხარეს კი ფართოდ გაანაწილებთ, ბავშვი უკვე იწყებს იმის გაგებას, რომ ორივე მხარეს ქვების რაოდენობა თანაბარია. ეს არის ვიზუალური ილუზიიდან ლოგიკურ დასკვნაზე გადასვლის ეტაპი.') WHERE id = '55c3f5e4-d3a4-465e-b035-b83e41b450d4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ცალ ფეხზე ხტომა“. ბავშვს უკვე შეუძლია ცალ ფეხზე რამდენჯერმე წინ გადახტომა. ამას წონასწორობაც სჭირდება და ფეხის ძლიერი, სწრაფი ბიძგიც. შესანიშნავი დროა, რომ სახლში მასთან ერთად „კლასობანა“ ითამაშოთ.') WHERE id = 'ddfca79d-8eb7-4cbd-84fd-61e54d7153db';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „სიტყვების შიდა ბგერები“. ბავშვი უკვე სიტყვების ბოლოში არსებულ ბგერებსაც არჩევს (მაგალითად, შეუძლია თქვას, რომ სიტყვა „ალმა“ ''ა''-ზე მთავრდება). ეს ფონემატური სმენის განვითარების უმაღლესი ეტაპია. მასთან ერთად ითამაშეთ „მოიფიქრე სიტყვა ბოლო ასოზე“ (სიტყვების ჯაჭვი), რათა მისი ლექსიკური მარაგი და სმენითი ყურადღება გააუმჯობესოთ.') WHERE id = '3863c552-322d-4dc8-a917-02d61270f313';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური გამძლეობა: „წარუმატებლობა და სტრატეგია“. როცა ბავშვს რაიმე არ გამოსდის, ის მაშინვე აღარ ტირის და ფიქრობს: „სხვაგვარად ხომ არ ვცადო?“. ეს „განვითარებაზე ორიენტირებული აზროვნების“ (growth mindset) საფუძველია. აუცილებლად შეაქეთ არა მიღებული შედეგისთვის, არამედ ახალი გზის ძიებისთვის.') WHERE id = 'da0d4f8a-08c6-45ad-9022-933f9025eb01';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი საგნებს უკვე არა მხოლოდ გარეგნობის, არამედ მასალის მიხედვითაც განასხვავებს: „ეს პლასტმასისაა, ეს კი რკინის“. მიეცით მას სხვადასხვა ტექსტურის მქონე საგნები და ჰკითხეთ, რით განსხვავდებიან ისინი. ეს დაეხმარება, უფრო დეტალურად გააანალიზოს გარემომცველი სამყარო და ფიზიკური სამყაროს შესახებ ცოდნა სისტემაში მოიყვანოს.') WHERE id = 'ec9b72ac-4600-4d72-8d5e-3a0bc232d29c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ზუსტი ნახტომი“. ბავშვს უკვე შეუძლია კონკრეტული სამიზნისკენ გადახტომა (მაგალითად, იატაკზე დახაზული წრის შიგნით). ეს მიუთითებს როგორც წონასწორობის შენარჩუნების, ისე სივრცეში მანძილის განსაზღვრის უნარზე. პარკში თამაში „ქვიდან ქვაზე გადახტომა“ მისთვის შესანიშნავი ვარჯიშია.') WHERE id = 'f6611b06-b8bc-42ff-84b4-2e17ea2e10d6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითკონტროლი: ემოციური დიპლომატია“. როდესაც ბავშვი სასურველს ვერ იღებს, ყვირილის ნაცვლად უკვე შეუძლია თავისი მიზეზი აგიხსნათ: „მაგრამ მე ეს ძალიან მინდოდა, რადგან...“. დააფასეთ დიალოგის გამართვის მისი მცდელობა. აღიარეთ და დაადასტურეთ მისი გრძნობები, თუმცა მოთმინებით აუხსენით ისიც, თუ რატომ რჩება წესები უცვლელი.') WHERE id = 'd8f54a1a-d4b0-4c91-b361-1e6376bfa2db';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „წესების ერთგულება“. ბავშვი უკვე განსაკუთრებულ მნიშვნელობას ანიჭებს სამაგიდო თამაშების (მაგალითად, დომინოს ან მარტივი რიცხვითი თამაშების) წესების დარღვევის გარეშე თამაშს. ეს სოციალური ადაპტაციის მნიშვნელოვანი ეტაპია. როდესაც წესებს იცავს, წაახალისეთ სიტყვებით: „ძალიან სამართლიანად და მოთმინებით ითამაშე“.') WHERE id = '111e7db0-d36d-44a0-97d8-10b28cd566ca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „რაოდენობის მუდმივობა: მოცულობის ცდა“. თუ პლასტილინის ერთსა და იმავე რაოდენობას ჯერ გუნდად, შემდეგ კი გრძელ „გველად“ აქცევთ, ბავშვი უკვე იწყებს იმის გააზრებას, რომ რაოდენობა უცვლელი რჩება. ეს ვიზუალური ილუზიიდან ლოგიკურ დასკვნაზე გადასვლის ეტაპია. ასეთი ექსპერიმენტები ერთად ჩაატარეთ.') WHERE id = '0655a03a-60b9-48e1-b285-1d3c83082836';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ერთ ფეხზე ხტომა“. ბავშვს უკვე შეუძლია ერთ ფეხზე რამდენჯერმე წინ გადახტომა. ამისთვის საჭიროა როგორც წონასწორობა, ისე ფეხის ძლიერი ბიძგი. შესანიშნავი დროა, რომ სახლში მასთან ერთად „კლასობანა“ ითამაშოთ — ეს სივრცეში ორიენტაციასაც აუმჯობესებს.') WHERE id = 'c5a0358e-6841-4ba2-8c21-cb976413e324';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ფანტაზიისა და ლოგიკის სინთეზი“. ბავშვს შეუძლია მოგიყვეთ თავისივე გამოგონილი ზღაპრები, რომლებსაც ლოგიკური თანმიმდევრობა აქვს. „ერთხელ იყო ერთი რობოტი, რომელიც გაჩერდა, რადგან ელემენტი დაუჯდა...“. ხელი შეუწყვეთ მის თხრობას ისეთი კითხვებით, როგორიცაა: „მერე რა მოხდა?“. ეს მომავალში გამართული და გამომსახველი მეტყველების განვითარებაში დაეხმარება.') WHERE id = '5fe788e8-9a0a-4448-9455-65cf7a8679b1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური მდგრადობა: „წარუმატებლობასთან გამკლავების ახალი სტრატეგია“. როდესაც ბავშვს რაიმე არ გამოსდის (მაგალითად, ფაზლის აწყობა), მაშინვე კი არ ბრაზდება, არამედ ახალ გზებს ეძებს: „იქნებ ასე დავდო?“. ეს „განვითარებაზე ორიენტირებული აზროვნების“ (growth mindset) საფუძველია. აუცილებლად შეაქეთ არა შედეგისთვის, არამედ ახალი გზის პოვნის მცდელობისთვის.') WHERE id = '19cb7d19-f480-4e1f-805a-267dba1df2a8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „წარმოსახვა და ამბავი“. ბავშვს უკვე შეუძლია, თავისი მოფიქრებული პატარა ზღაპრები მოგიყვეთ. ამ ზღაპრებში რეალობა და ფანტაზია ერთმანეთშია გადახლართული. მხარი დაუჭირეთ მის მონათხრობს ისეთი დაინტერესებული კითხვებით, როგორებიცაა: „მართლა?“ ან „შემდეგ რა მოხდა?“. ეს მომავალში გამართული და გამომსახველი მეტყველების განვითარებაში დაეხმარება.') WHERE id = 'c414dc79-8944-48c3-a5d5-e50145e600bc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1430-დღიანი გამარჯვება! ბავშვს უკვე 47 თვე შეუსრულდა. ის უკვე პატარა „მეცნიერია“, რომელიც აცნობიერებს საკუთარ თავს, თანაუგრძნობს სხვებს და სამყაროს ლოგიკური აზროვნებით იკვლევს. ამ 1430 დღის განმავლობაში თქვენ თქვენი ბავშვისთვის ყველაზე საიმედო ნავსაყუდელი და საუკეთესო მასწავლებელი იყავით. თქვენ საოცარი დედა ხართ!') WHERE id = '8f2e9299-bb7b-4d28-9fbc-c07c7ba2a262';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '48-ე თვემდე (4 წლამდე) უკუთვლა დაიწყო! ბავშვი სოციალურ თამაშებში უკვე სრულად იყენებს განსხვავებას „მე“-სა და „ჩვენ“-ს შორის. თუ ის საქმეებს ასე ანაწილებს: „მოდი, ერთად ავაშენოთ გემი — შენ იალქანი დაიჭირე, მე კი საჭეს მოვკიდებ ხელს“, ეს თანამშრომლობის უნარის უმაღლესი გამოვლინებაა. შეაქეთ მისი გუნდური სულისკვეთება — ეს მომავალი სასკოლო ცხოვრებისთვის მნიშვნელოვანია.') WHERE id = 'b940be7d-ee82-4c09-8760-e2ce9294193f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — „ზუსტი მოხვევები“. ბავშვს უკვე შეუძლია, სრული სისწრაფით სირბილისას უეცრად გაჩერდეს ან წონასწორობის დაკარგვის გარეშე მკვეთრად მოუხვიოს. ეს ვესტიბულური სისტემისა და კუნთების კონტროლის სრულად კოორდინირებულ მუშაობაზე მიუთითებს. პარკში პატარა „დაბრკოლებების ზოლი“ მოუწყვეთ.') WHERE id = 'ce453995-5119-4943-ace6-1439bc5d5820';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ბგერების ანალიზი“. ბავშვი უკვე იწყებს არა მხოლოდ სიტყვის დასაწყისში, არამედ ბოლოშიც ბგერების გარჩევას: „მაგიდა „ა“-ზე მთავრდება“. ეს ფონემატური სმენის განვითარებაზე მიუთითებს. ეთამაშეთ თამაში „მოიფიქრე ახალი სიტყვა, რომელიც ბოლო ბგერით იწყება“ და ამით მისი ენობრივი ალღო გააუმჯობესეთ.') WHERE id = 'e258838d-b844-4e68-840e-2eb0ef520682';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ქაღალდის გამოჭრა: დეტალური ფიგურები“. ბავშვი უკვე ცდილობს, მაკრატლით კონტურის გასწვრივ გამოჭრას რთული ფორმები (მაგალითად, ვარსკვლავი ან პატარა ცხოველის სილუეტი). ეს აჩვენებს, რამდენად დაიხვეწა თვალისა და ხელის კოორდინაცია. მიეცით სხვადასხვა ფერის ქაღალდები.') WHERE id = '619d1623-d881-46f6-a718-4a537172efc7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში „შეკრების საფუძვლები“. ბავშვს უკვე შეუძლია გაიაზროს, რომ 2 სათამაშოს კიდევ 1 რომ დაუმატოს, სულ 3 გამოვა — დათვლის გარეშე (ან სწრაფად დათვლით). ყოველდღიურ საქმიანობაში მოუფიქრეთ მარტივი მათემატიკური ამოცანები, მაგალითად: „თქვენ 2 ვაშლი გქონდათ, მე კიდევ 1 მოგეცით. ახლა რამდენი გაქვთ?“') WHERE id = '321e201a-5cd6-485a-a700-1c1f11885a2b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „კიბეზე გადაადგილება“. ბავშვი უკვე თავდაჯერებით ადის და ჩამოდის კიბეზე და ზოგჯერ წონასწორობის შენარჩუნება მაშინაც შეუძლია, როცა ხელში სათამაშო უჭირავს. ეს დინამიკური წონასწორობის მაღალ დონეზე მიუთითებს. ყოველთვის ახლოს იყავით, თუმცა აგრძნობინეთ, რომ თავისუფლად გადაადგილება შეუძლია.') WHERE id = '26b9ae52-0022-4e15-934b-ad179ba90589';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „წარმოსახვა და ამბის მოყოლა“. ბავშვმა შეიძლება საკუთარი გამოგონილი პატარა ზღაპრები მოგიყვეთ. ამ ზღაპრებში რეალობა და ფანტაზია ერთმანეთშია შერწყმული. მისი მონათხრობი წაახალისეთ ისეთი დაინტერესებული კითხვებით, როგორიცაა „მართლა?“ ან „შემდეგ რა მოხდა?“. ეს მომავალში გამართულად და გამომსახველად მეტყველებაში დაეხმარება.') WHERE id = 'e96b1dc7-ba0c-47d3-b15a-cb6918e2bc9b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '4 წლის შესრულებამდე სულ 30 დღე დარჩა! ბავშვი უკვე სკოლამდელი ასაკის ყველაზე ნაყოფიერ ეტაპზეა. ახლა ის სრულფასოვანი პიროვნებაა — პატარა ადამიანი საკუთარი გემოვნებით, შიშებითა და უსასრულო კითხვებით. თქვენ ეს გზა ცოდნითა და სიყვარულით გამოიარეთ. „Anacan“ ყოველთვის თქვენს გვერდითაა!') WHERE id = '34fd4a41-2c8b-49b5-b2b0-6911f5bb04ab';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი საგნებს უკვე არა მხოლოდ გარეგნული ნიშნების, არამედ მათი კუთვნილების მიხედვითაც აჯგუფებს. „ესენი ზღვის ცხოველები არიან, ესენი კი — ტყის“. ეს მიუთითებს, რომ მის გონებაში ინფორმაცია უკვე სამეცნიერო კატეგორიებად იყოფა. ითამაშეთ მასთან თამაში „ვინ სად ცხოვრობს?“.') WHERE id = 'bacec645-5384-4fc1-94d1-94b2914a27a1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ მოძრაობაში „სწრაფი სირბილი და კოორდინირებული გაჩერება“. ბავშვს უკვე შეუძლია სრული სისწრაფით სირბილისას თქვენს ბრძანებაზე „გაჩერდი!“ მაშინვე შეჩერდეს ისე, რომ არ წაიქცეს და წინ არ წაბორძიკდეს. ეს როგორც კუნთების კონტროლის, ისე სმენით-მოტორული რეაქციის უმაღლესი დონეა. პარკში ეს თამაში რეგულარულად გაიმეორეთ.') WHERE id = 'ea737131-3977-4085-b4c4-94dd4ae125f1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი საგნებს უკვე არა მხოლოდ გარეგნობის, არამედ მასალის მიხედვითაც განასხვავებს: "ეს პლასტმასისაა, ეს კი რკინის". მიეცით მას სხვადასხვა ტექსტურის მქონე ნივთები და ჰკითხეთ, რით განსხვავდებიან ისინი. ეს ეხმარება, უფრო დეტალურად გააანალიზოს გარემომცველი სამყარო და ფიზიკური სამყაროს შესახებ ცოდნა სისტემაში მოიყვანოს.') WHERE id = '0ec14802-bab2-45c4-8cbf-788bdfa85e13';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკურ აქტივობაში — "ზუსტი ნახტომი". ბავშვს უკვე შეუძლია კონკრეტული სამიზნისკენ გადახტომა (მაგალითად, იატაკზე დახატული წრის შიგნით). ეს მიუთითებს როგორც წონასწორობის დაცვის, ისე სივრცეში მანძილის განსაზღვრის უნარზე. პარკში თამაში "ქვიდან ქვაზე გადახტომა" მისთვის შესანიშნავი ვარჯიშია.') WHERE id = '0ddedeb7-e832-48ca-923d-05838885cdc1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — "საპირისპირო ცნებების კლასიფიკაცია". ბავშვი უკვე სრულად განასხვავებს ცნებებს: "ცხელი-ცივი", "მაღალი-დაბალი", "მძიმე-მსუბუქი". ეთამაშეთ მას თამაში "იპოვე საპირისპირო": თქვენ თქვით "დიდი", მან კი — "პატარა". ეს ავითარებს როგორც მის ლექსიკურ მარაგს, ისე აბსტრაქტულ და შედარებით აზროვნებას.') WHERE id = '3810cfc8-49ab-40fa-b90d-2edf9dc84fae';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — "ფიგურების გადახატვა: სამკუთხედი და ჯვარი". ბავშვს უკვე შეუძლია სწორი ხაზების გადაკვეთით ჯვრის (+) დახატვა და ცდილობს სამკუთხედის მსგავსი ფორმების შექმნას. ეს წერის უნარის საწყისი საფუძველია. მიეცით ფერადი ფანქრები და სუფთა ფურცლები, რათა ხელი შეუწყოთ მის ამ "გეომეტრიულ აღმოჩენებს".') WHERE id = 'dfeb7b05-cea8-4a6f-b41b-005f3d3c488e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"თვითკონტროლი: სურვილის გადადება". ბავშვი უკვე ეგუება, რომ ჯილდოს მისაღებად ცოტა მეტხანს უნდა დაელოდოს (მაგალითად, "ტკბილეული ჭამის შემდეგ"). ეს ნებისყოფისა და თვითკონტროლის (delayed gratification) განვითარებაზე მიუთითებს. აუცილებლად შეაქეთ ასეთი მოთმინებისთვის; ეს მომავალში წარმატებული აკადემიური ცხოვრების ერთ-ერთი გასაღებია.') WHERE id = '988ae101-5f2f-4a86-a365-28a27e843965';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — "ჯგუფური სოლიდარობა". როცა მეგობარი ტირის, ბავშვი უკვე უბრალოდ კი არ უყურებს, არამედ ეკითხება: "რა მოხდა?" ან თქვენ გატყობინებთ. ეს ემპათიის აქტიური ეტაპია. მხარი დაუჭირეთ მის ამ მზრუნველ თვისებას და უთხარით: "ძალიან კეთილი მეგობარი ხარ".') WHERE id = 'ed4539aa-f1cf-4dd1-97f9-a5cf3f6b499d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „რთული ამბის აგება“. ბავშვი უკვე იგონებს ზღაპრებს და სიუჟეტის შესაქმნელად იყენებს ისეთ კავშირებს, როგორიცაა „რადგან“, „მაგრამ“, „ამიტომ“. ყურადღებით მოუსმინეთ მის ამბებს და ისეთი კითხვებით, როგორიცაა „როგორ ფიქრობ, რა გააკეთა შემდეგ მთავარმა გმირმა?“, ახალი დეტალების მოფიქრებაში დაეხმარეთ.') WHERE id = '24dad4d0-2c9d-4d1c-bb0a-41d9b402e0e7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '4 წლის შესრულებამდე სულ რაღაც 20 დღე დარჩა! ბავშვმა პატარაობის ჩვევები უკვე მთლიანად უკან მოიტოვა და საკუთარი, გამორჩეული ხასიათის მქონე პატარა პიროვნებად იქცა. ამ 1460 დღის განმავლობაში მის განვითარების გზაზე თქვენ ყველაზე კაშკაშა შუქი იყავით. მისი წარმატებები თქვენი სიყვარულის შედეგია. არაჩვეულებრივი ხართ!') WHERE id = 'd76fe554-fd7b-4db0-9296-a5ba3be690d0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში — „ზრდილობიანი მსჯელობა“. ბავშვი სასურველის მისაღებად უკვე არა მხოლოდ ამბობს: „გთხოვ, შეიძლება?“, არამედ მიზეზსაც ასახელებს: „იმიტომ, რომ ძალიან მიყვარს“. თქვენი თავაზიანი პასუხი მის სოციალურ-საკომუნიკაციო ენას აყალიბებს. დააფასეთ მისი ყოველი ზრდილობიანი თხოვნა და უთხარით: „რადგან ასე ლამაზად მითხარი, სიამოვნებით გიპასუხებ“.') WHERE id = '0bfff590-18d1-438c-bef2-c5dac59fc7e3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში — „ასოებისა და ციფრების ვიზუალური გადმოწერა“. ბავშვი უკვე ცდილობს, ქაღალდზე დაწეროს თავისი სახელის ასოები ან ისეთი ციფრები, როგორიცაა „1, 2, 3“. ეს მოძრაობისა და ვიზუალური მეხსიერების ერთობლივი მუშაობაა. მიეცით სხვადასხვა ფერის ფანქრები და მისი „ნაწერები“ სახლში თვალსაჩინო ადგილას დაკიდეთ.') WHERE id = '65fb665a-a079-4bde-be1e-8536275e5fd6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თვითრეგულაცია: ემოციური დამოუკიდებლობა“. მცირე პრობლემის დროს (მაგალითად, როცა სათამაშო დაეშლება) ბავშვი უკვე მაშინვე თქვენთან აღარ გამორბის და ჯერ თავად ცდილობს მის შეკეთებას. ეს „მე შემიძლია“ განცდის განმტკიცებაა. დააკვირდით მის დამოუკიდებელ მცდელობებს და მხოლოდ მაშინ ჩაერიეთ, როცა დახმარება დასჭირდება.') WHERE id = '5a2e55ce-3f97-41a9-965d-b857b33a020f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში — „წესების ახსნა“. ბავშვი უკვე უხსნის თამაშის წესებს უმცროს ბავშვებს ან თავის სათამაშოებს: „ჯერ მე, შემდეგ შენ“. ეს შინაგანი დისციპლინისა და ლიდერული უნარების მაჩვენებელია. მხარი დაუჭირეთ მის ამ „მასწავლებლურ“ მხარეს.') WHERE id = '1e4b1da3-fa3d-4b83-9554-7fdd901b9dfb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიურ განვითარებაში — „დროის კალენდარი“. ბავშვს უკვე ესმის ისეთი გამოთქმები, როგორიცაა „3 დღე დარჩა“ ან „შაბათ-კვირას წავალთ“. დაბადების დღის მოახლოებისას გააკეთეთ „უკუთვლის კალენდარი“. ყოველი გასული დღის მონიშვნა მას დროის სვლის უკეთ აღქმაში ეხმარება.') WHERE id = 'e9a169de-bc44-43dd-b6f0-9adaff7e3796';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: „ბურთის ფეხით მიზანში დარტყმა“. ბავშვი უკვე უბრალოდ კი არ ურტყამს ბურთს ფეხს, არამედ ცდილობს, ის კონკრეტულ მიზანში (მაგალითად, ორ ქვას შორის) მოათავსოს. ეს სივრცეში მანძილის განსაზღვრასა და ფეხის კუნთების ზუსტ მუშაობას მოითხოვს.') WHERE id = '1c5a132d-9357-46a5-b5fe-17d6baae9cac';

