UPDATE public.nutrition_tips SET title_ka = COALESCE(title_ka, 'კვერცხი'), content_ka = COALESCE(content_ka, 'მდიდარია მაღალი ხარისხის ცილებითა და ქოლინით, რომელიც მნიშვნელოვანია ტვინის განვითარებისთვის. ხელს უწყობს ბავშვის ნერვული სისტემის ჩამოყალიბებას.') WHERE id = 'a551c688-076a-470a-9862-b199c56afee1';
UPDATE public.nutrition_tips SET title_ka = COALESCE(title_ka, 'ფოლატით მდიდარი საკვები'), content_ka = COALESCE(content_ka, 'ორსულობის პირველ ტრიმესტრში ფოლატი ძალიან მნიშვნელოვანია. მუქი მწვანე ფოთლოვანი ბოსტნეული, ციტრუსები და პარკოსნები მისი კარგი წყაროა.') WHERE id = '3cd9d02f-2306-400b-bf13-48f59e00d6e0';
UPDATE public.nutrition_tips SET title_ka = COALESCE(title_ka, 'რკინის მიღება'), content_ka = COALESCE(content_ka, 'ორსულობის დროს რკინაზე მოთხოვნილება იზრდება. წითელი ხორცი, ისპანახი და ოსპი მისი კარგი წყაროა.') WHERE id = 'c72c92e6-079c-4154-b75a-f4bc2185c69d';
