UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'საპნის ბუშტებზე დაკვირვება'), description_ka = COALESCE(description_ka, 'საპნის ბუშტებზე დაკვირვება მზერით თვალის გასაყოლებლად'), instructions_ka = COALESCE(instructions_ka, '1. გაუშვით საპნის ბუშტები ბავშვთან ახლოს\n2. მიუთითეთ ბუშტებზე და აღუწერეთ ისინი\n3. ბუშტებს საშუალება მიეცით, ნაზად გასკდეს ბავშვის კანზე') WHERE id = '449a2aa8-5640-4e79-b7fa-0c92027bb12c';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'სხვადასხვა ფაქტურის შესწავლა'), description_ka = COALESCE(description_ka, 'სხვადასხვა ფაქტურის შეგრძნებით შესწავლა'), instructions_ka = COALESCE(instructions_ka, '1. მოაგროვეთ სხვადასხვა ფაქტურის მქონე ნივთები\n2. მიეცით ბავშვს საშუალება, თითოეულ ნივთს შეეხოს\n3. აღუწერეთ ფაქტურები: რბილი, ხორკლიანი, გლუვი') WHERE id = 'e257be70-2380-44c1-91be-9e079d4879b7';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'კონტეინერით თამაში'), description_ka = COALESCE(description_ka, 'საგნების კონტეინერში ჩადება და იქიდან ამოღება'), instructions_ka = COALESCE(instructions_ka, '1. გამოიყენეთ უსაფრთხო კონტეინერი და რბილი სათამაშოები\n2. აჩვენეთ ბავშვს, როგორ ჩადოს ნივთები კონტეინერში\n3. წაახალისეთ, რომ ნივთები ამოიღოს\n4. წარმატება ტაშით აღნიშნეთ') WHERE id = '4d841e68-97b6-4186-be6e-26bef3df65df';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ბურთის გაგორება'), description_ka = COALESCE(description_ka, 'ბურთის ერთმანეთისთვის გაგორება'), instructions_ka = COALESCE(instructions_ka, '1. დაჯექით ბავშვის პირისპირ\n2. რბილი ბურთი ბავშვისკენ გააგორეთ\n3. წაახალისეთ, რომ ბურთი უკან გამოაგოროს\n4. შეაქეთ, როცა თამაშში ჩაერთვება') WHERE id = '073a2084-da2c-4ef3-8a93-22136a2c77a5';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'სარკესთან მუცელზე თამაში'), description_ka = COALESCE(description_ka, 'სარკეში საკუთარი თავის დანახვა ბავშვის განვითარებას ასტიმულირებს'), instructions_ka = COALESCE(instructions_ka, 'დააწვინეთ ბავშვი მუცლით ბალიშზე. წინ დაუდეთ სარკე. აჩვენეთ მას საკუთარი თავი სარკეში.') WHERE id = '20e1c63e-791f-43a8-bb33-84ebfe166368';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'სამზარეულოს ორკესტრი'), description_ka = COALESCE(description_ka, 'ქვაბებითა და ტაფებით რიტმის გრძნობის განვითარება'), instructions_ka = COALESCE(instructions_ka, 'ბავშვს წინ დაუდეთ ხის კოვზი და ქვაბები. აჩვენეთ, როგორ დააკაკუნოს. ერთად შექმენით რიტმი.') WHERE id = '5a6d5c7d-3489-4b3d-8210-fbeed43d3536';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'გვირაბი ყუთისგან'), description_ka = COALESCE(description_ka, 'ცოცვისა და აღმოჩენის უნარების განვითარება'), instructions_ka = COALESCE(instructions_ka, 'დიდ მუყაოს ყუთს ორივე მხარე გაუხსენით. წაახალისეთ ბავშვი, რომ ერთი მხრიდან შეძვრეს. მეორე მხრიდან დაუძახეთ.') WHERE id = '8266c528-ae95-47fa-b7f4-28400410ebc2';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'წინდების თოჯინები'), description_ka = COALESCE(description_ka, 'კომუნიკაციისა და შემოქმედებითი უნარების განვითარება'), instructions_ka = COALESCE(instructions_ka, 'ძველი წინდისგან თოჯინა გააკეთეთ. ბავშვს მისი მეშვეობით „ესაუბრეთ“. გამოსცით სხვადასხვა ხმა.') WHERE id = 'fc6ee2c8-0599-4677-994a-dc1385d83024';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'სხვადასხვა ფაქტურის ბილიკი'), description_ka = COALESCE(description_ka, 'შეგრძნებების განვითარება სხვადასხვა ფაქტურის მეშვეობით'), instructions_ka = COALESCE(instructions_ka, 'იატაკზე დაალაგეთ სხვადასხვა ფაქტურის მასალები (საბანი, შარფი, ქაღალდი). მიეცით ბავშვს მათზე ცოცვის საშუალება.') WHERE id = '3b19cf38-0d12-4b49-81d4-69a60f7b3cc2';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'მაღალი კონტრასტის ბარათები'), description_ka = COALESCE(description_ka, 'შავ-თეთრი ორნამენტების ბარათები მხედველობის განვითარებისთვის'), instructions_ka = COALESCE(instructions_ka, '1. დაიჭირეთ ბარათი ბავშვის სახიდან 20-30cm-ის დაშორებით\n2. ნელა გადაადგილეთ მარცხნიდან მარჯვნივ\n3. დააკვირდით, როგორ აყოლებს ბავშვი ბარათს თვალს') WHERE id = '16373dad-486f-490c-bc14-144cfd354f5f';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ჭიტა ნაჭრით'), description_ka = COALESCE(description_ka, 'კლასიკური თამაში „ჭიტა“'), instructions_ka = COALESCE(instructions_ka, '1. სახე ნაჭრით დაიფარეთ\n2. თქვით: „სად ვარ?“\n3. ნაჭერი მოიშორეთ და თქვით: „ჭიტა!“\n4. ბავშვს სახე ნაზად დაუფარეთ და გაიმეორეთ') WHERE id = '58d3e4f3-7256-4eaa-901e-ce192a8aca44';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'შავ-თეთრი მობილი'), description_ka = COALESCE(description_ka, 'ბავშვის ზემოთ მაღალი კონტრასტის მქონე გამოსახულებები დაკიდეთ'), instructions_ka = COALESCE(instructions_ka, 'ქაღალდისგან მარტივი ფიგურები გამოჭერით და ბავშვის ზემოთ, 20-30cm სიმაღლეზე დაკიდეთ. მიეცით ბავშვს საშუალება, თვალი გააყოლოს მათ მოძრაობას.') WHERE id = '8c2f484b-326a-4dac-b7a4-7eb528aff395';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ჭიქების დაწყობა'), description_ka = COALESCE(description_ka, 'ჭიქებით კოშკების აშენება'), instructions_ka = COALESCE(instructions_ka, '1. აჩვენეთ ბავშვს, როგორ დააწყოს ჭიქები ერთმანეთზე\n2. მიეცით ბავშვს საშუალება, კოშკი დაანგრიოს\n3. ხელახლა ააშენეთ და გაიმეორეთ\n4. ჭიქების დაწყობისას ფერები დაასახელეთ') WHERE id = '6145784f-e184-4ae7-8691-ff33671cc7d0';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'დასურათებული წიგნის კითხვა'), description_ka = COALESCE(description_ka, 'დასურათებული წიგნების ინტერაქტიული კითხვა'), instructions_ka = COALESCE(instructions_ka, '1. შეარჩიეთ წიგნები მკვეთრი, ფერადი სურათებით\n2. სურათებზე მიუთითეთ და დაასახელეთ, რა არის გამოსახული\n3. მიეცით ბავშვს გვერდების გადაფურცვლის საშუალება\n4. ცხოველების ხმები გამოსცით') WHERE id = '68d82e2b-fe11-4b41-af57-aa141f8eb6cc';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ფიგურების ჩამხარისხებელი'), description_ka = COALESCE(description_ka, 'ფიგურების შესაბამის ღიობებში მოთავსება'), instructions_ka = COALESCE(instructions_ka, '1. აჩვენეთ, როგორ თავსდება ფიგურები შესაბამის ღიობებში\n2. თავდაპირველად ბავშვს ხელი მიაშველეთ\n3. წარმატება ერთად აღნიშნეთ\n4. თამაშისას ფიგურები დაასახელეთ') WHERE id = '60e5d3d1-5587-48f5-99df-4e806c62490a';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'საცეკვაო წვეულება'), description_ka = COALESCE(description_ka, 'მუსიკის ფონზე ერთად ცეკვა'), instructions_ka = COALESCE(instructions_ka, '1. ჩართეთ მხიარული მუსიკა\n2. ბავშვი ხელში აიყვანეთ და მასთან ერთად იცეკვეთ\n3. ბავშვი ძირს დასვით და ერთად იცეკვეთ\n4. ტაში დაუკარით და დატრიალდით') WHERE id = '52245d35-3235-4e80-b73d-af4fe323ed93';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'საგანძურის კალათა'), description_ka = COALESCE(description_ka, 'შეავსეთ კალათა უსაფრთხო საყოფაცხოვრებო ნივთებით'), instructions_ka = COALESCE(instructions_ka, 'შეაგროვეთ განსხვავებული ტექსტურისა და ფორმის 5-10 უსაფრთხო ნივთი. მიეცით ბავშვს მათი თავისუფლად შესწავლის საშუალება და თითოეული ნივთი დაუსახელეთ.') WHERE id = 'ebc79f1e-7d23-4c5a-b28e-dda90e096b3a';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ტაშის სიმღერა'), description_ka = COALESCE(description_ka, 'იმღერეთ და ტაში ერთად დაუკარით'), instructions_ka = COALESCE(instructions_ka, 'იმღერეთ მარტივი სიმღერები ტაშის თანხლებით. დაეხმარეთ ბავშვს, ხელისგულები ერთმანეთს შემოჰკრას. ეს შესანიშნავი აქტივობაა რიტმის შეგრძნებისა და კოორდინაციის გასავითარებლად.') WHERE id = 'a4aa194b-9d64-4f72-8ba4-90ae6e12f0c5';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'კოვზების ჩაყრის თამაში'), description_ka = COALESCE(description_ka, 'ჩაყარეთ კოვზები ქვაბში'), instructions_ka = COALESCE(instructions_ka, 'აჩვენეთ ბავშვს, როგორ ჩაყაროს ხის კოვზები ქვაბში. მოასმენინეთ გამოცემული ხმა და მიეცით საშუალება, მოქმედება გაიმეოროს.') WHERE id = 'b99f62da-0ba0-4a8c-a136-3eae65f486ee';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ბამბის ბურთულების გადატანა'), description_ka = COALESCE(description_ka, 'გადაიტანეთ ბამბის ბურთულები ერთი ჭურჭლიდან მეორეში'), instructions_ka = COALESCE(instructions_ka, 'მიეცით ბავშვს ორი ჯამი და ბამბის ბურთულები. აჩვენეთ, როგორ აიღოს და გადაიტანოს ისინი. ეს შესანიშნავი აქტივობაა ნატიფი მოტორული უნარების გასავითარებლად.') WHERE id = 'bf6bdf5d-9977-460c-978a-4df325af6d86';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ქაღალდის დახევა'), description_ka = COALESCE(description_ka, 'დახიეთ ქაღალდი ნაჭრებად'), instructions_ka = COALESCE(instructions_ka, 'მიეცით ბავშვს რბილი ქაღალდი დასახევად. მისი ხმა და შეგრძნება ხელს უწყობს სენსორული აღქმის განვითარებასა და ხელების გაძლიერებას.') WHERE id = 'c80230e8-6d2c-459b-9557-6ff0795bbec7';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'მუყაოს მილის გვირაბი'), description_ka = COALESCE(description_ka, 'გააგორეთ ბურთი მუყაოს მილში'), instructions_ka = COALESCE(instructions_ka, 'დაიჭირეთ მუყაოს მილი და აჩვენეთ ბავშვს, როგორ გააგოროს მასში პატარა ბურთი. შემდეგ ერთად გაეკიდეთ ბურთს.') WHERE id = '977ee460-5cf3-4eaa-878a-9d316320f9a5';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ღრუბლის გაწურვა'), description_ka = COALESCE(description_ka, 'გაწურეთ სველი ღრუბლები ჯამებში'), instructions_ka = COALESCE(instructions_ka, 'დაასველეთ ღრუბლები და აჩვენეთ ბავშვს, როგორ გაწუროს წყალი ჯამში. ეს ვარჯიში შესანიშნავია ხელების გასაძლიერებლად.') WHERE id = 'df24840d-33ce-4c49-b093-3e0206c89ed5';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ბუმბულის სულით გადაადგილება'), description_ka = COALESCE(description_ka, 'შეუბერეთ ბუმბულებს და უყურეთ, როგორ ლივლივებენ'), instructions_ka = COALESCE(instructions_ka, 'ბუმბულები ბრტყელ ზედაპირზე დააწყვეთ. მსუბუქად შეუბერეთ და ბავშვსაც მიეცით საშუალება, სცადოს მათი დაჭერა ან მათთვის სულის შებერვა.') WHERE id = 'efd51de1-efff-48a2-a2e9-f6a4a3d7a2ee';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ქვიშით თამაში'), description_ka = COALESCE(description_ka, 'თხარეთ და გადაყარეთ ქვიშა'), instructions_ka = COALESCE(instructions_ka, 'ლანგარი ქვიშით შეავსეთ. მიეცით ბავშვს ჭიქები და კოვზები. აცადეთ, თხაროს, გადაყაროს ქვიშა და შეიგრძნოს მისი ტექსტურა.') WHERE id = '53ef4599-988b-4a29-8f82-c3c78d48283b';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'პლასტილინის ზელა'), description_ka = COALESCE(description_ka, 'მოზილეთ, გააგორეთ და სხვადასხვა ფორმა მიეცით პლასტილინს'), instructions_ka = COALESCE(instructions_ka, 'მიეცით ბავშვს პლასტილინი. აჩვენეთ, როგორ მოზილოს, გააგოროს და თითით ჩაზნიქოს. ფორმების გამოსაჭრელად გამოიყენეთ ორცხობილის საჭრელები.') WHERE id = '9a13c43a-a835-47cf-99fe-bd97a0f1562c';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'კუბურების კოშკი'), description_ka = COALESCE(description_ka, 'დააწყვეთ კუბურები რაც შეიძლება მაღლა'), instructions_ka = COALESCE(instructions_ka, 'აჩვენეთ ბავშვს, როგორ დააწყოს კუბურები ერთმანეთზე. დაითვალეთ თითოეული კუბური. იხალისეთ, როცა კოშკი დაინგრევა! შემდეგ ერთად ააშენეთ თავიდან.') WHERE id = '5c63d4c6-a28a-488e-84cb-86ad690cd854';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'შარფების ამოღება'), description_ka = COALESCE(description_ka, 'ამოიღეთ შარფები კონტეინერიდან'), instructions_ka = COALESCE(instructions_ka, 'ჩადეთ შარფები ხვრელიან ყუთში. მიეცით ბავშვს საშუალება, სათითაოდ ამოიღოს ისინი. დაასახელეთ თითოეული ფერი.') WHERE id = '00ca6e21-d67f-4f0a-a874-ef5c64e2e91a';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ჩხარუნაზე თვალითა და სმენით მიყოლა'), description_ka = COALESCE(description_ka, 'ჩხარუნაზე თვალითა და სმენით მიყოლის ვარჯიში'), instructions_ka = COALESCE(instructions_ka, '1. შეანჯღრიეთ ჩხარუნა ბავშვის ყურადღების მისაქცევად\n2. ნელა ამოძრავეთ სხვადასხვა მიმართულებით\n3. მიეცით ბავშვს მისი ხელში აღების საშუალება') WHERE id = 'ea96ae3c-ed32-4118-b146-ecbb3a3bb763';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ვითომ სატელეფონო საუბარი'), description_ka = COALESCE(description_ka, 'ტელეფონით საუბრის იმიტაცია'), instructions_ka = COALESCE(instructions_ka, '1. მიეცით ბავშვს სათამაშო ტელეფონი\n2. მოაჩვენეთ, თითქოს ბავშვს ურეკავთ\n3. წაახალისეთ ბავშვი, რომ „ილაპარაკოს“\n4. ისაუბრეთ მორიგეობით') WHERE id = 'e08ba272-48b6-4a5f-b44b-0ba7da5cb808';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ნაზი სიმღერა'), description_ka = COALESCE(description_ka, 'უმღერეთ ბავშვს მშვიდად და ნაზად'), instructions_ka = COALESCE(instructions_ka, 'გულთან ახლოს დაიჭირეთ ბავშვი და ნაზად უმღერეთ იავნანა ან მარტივი სიმღერები. დააკვირდით, როგორ რეაგირებს ბავშვი თქვენს ხმაზე.') WHERE id = 'a3c29297-6e01-48c7-9b34-d7d9d3af361a';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'მუცელზე წოლა სათამაშოებით'), description_ka = COALESCE(description_ka, 'მუცელზე წოლისას ბავშვის წინ ფერადი სათამაშოები მოათავსეთ'), instructions_ka = COALESCE(instructions_ka, 'დააწვინეთ ბავშვი მუცელზე. ფერადი სათამაშოები ოდნავ მოშორებით დაუწყვეთ, რათა წაახალისოთ, მათკენ გაიწიოს და თავი ასწიოს.') WHERE id = 'e0e77763-f782-46a8-bcfe-1cf276ba2cce';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'წყალში შხეფების დრო'), description_ka = COALESCE(description_ka, 'მიეცით ბავშვს საშუალება, ხელებით წყალი აშხეფოს'), instructions_ka = COALESCE(instructions_ka, 'არაღრმა თასში თბილი წყალი ჩაასხით. მიეცით ბავშვს საშუალება, წყალს შეეხოს და აშხეფოს. ყოველთვის ყურადღებით მეთვალყურეობდეთ.') WHERE id = '5cea30c3-38d1-4326-b521-b5428eba62a1';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'მფრინავი ბავშვი'), description_ka = COALESCE(description_ka, 'ნაზად ასწიეთ ბავშვი ჰაერში'), instructions_ka = COALESCE(instructions_ka, 'დაწექით ზურგზე, ბავშვი უსაფრთხოდ დაიჭირეთ და ნაზად ასწიეთ მაღლა, თითქოს დაფრინავს. ეს შესანიშნავი აქტივობაა ემოციური კავშირის გასაძლიერებლად.') WHERE id = 'eb368346-4c28-48f4-acc2-82c3747e66bf';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'წყლის გადასხმა'), description_ka = COALESCE(description_ka, 'გადაასხით წყალი ერთი ჭიქიდან მეორეში'), instructions_ka = COALESCE(instructions_ka, 'მიეცით ბავშვს ორი ჭიქა და წყალი. აჩვენეთ, როგორ გადაასხას წყალი ერთი ჭიქიდან მეორეში. ეს შესანიშნავი აქტივობაა კოორდინაციის გასავითარებლად.') WHERE id = '94152e25-5d19-43e0-9c7f-26f0205d234e';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'დამალობანა სათამაშოთი'), description_ka = COALESCE(description_ka, 'დამალეთ სათამაშო ჭიქის ქვეშ და იპოვეთ'), instructions_ka = COALESCE(instructions_ka, 'დადგით 2-3 ჭიქა თავდაყირა. ერთ-ერთი მათგანის ქვეშ დამალეთ პატარა სათამაშო. სთხოვეთ ბავშვს, იპოვოს ის.') WHERE id = '18e16dc8-b896-4c03-8b0c-c7052e294b98';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ფერების მიხედვით დახარისხება'), description_ka = COALESCE(description_ka, 'დაახარისხეთ საგნები ფერების მიხედვით კონტეინერებში'), instructions_ka = COALESCE(instructions_ka, 'გამოიყენეთ სხვადასხვა ფერის საგნები (კუბიკები, ბურთები, თავსახურები). დადგით კონტეინერები და სთხოვეთ ბავშვს, საგნები ფერების მიხედვით დაახარისხოს.') WHERE id = 'a9054a6e-ef97-45fa-aea0-e0e0cc640bc3';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'სხეულის ნაწილების თამაში'), description_ka = COALESCE(description_ka, 'მიუთითეთ სხეულის ნაწილებზე და დაასახელეთ ისინი'), instructions_ka = COALESCE(instructions_ka, 'შეეხეთ თქვენს ცხვირს, ყურებსა და თვალებს და დაასახელეთ ისინი. სთხოვეთ ბავშვს, გაიმეოროს. იმღერეთ სიმღერა თავზე, მხრებზე, მუხლებსა და ფეხის თითებზე.') WHERE id = '07108cc6-ef41-4d92-ad52-d3d9ab5b5c1a';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'გამომყევი'), description_ka = COALESCE(description_ka, 'ერთად გაიმეორეთ მოძრაობები'), instructions_ka = COALESCE(instructions_ka, 'შეასრულეთ მარტივი მოქმედებები: ახტით, დაუკარით ტაში, დატრიალდით, დააბაკუნეთ ფეხები. სთხოვეთ ბავშვს, გაიმეოროს. შემდეგ კი მას მიეცით საშუალება, თავად იყოს წამყვანი.') WHERE id = '61ed8f13-2ee8-4bf5-b395-427c971b2b93';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ფაზლების დრო'), description_ka = COALESCE(description_ka, 'მარტივი ფორმების ფაზლები'), instructions_ka = COALESCE(instructions_ka, 'მიეცით ბავშვს მარტივი, 3-5-ნაწილიანი ფაზლი. დაეხმარეთ, ფორმები ერთმანეთს შეუსაბამოს. აღნიშნეთ სიხარულით თითოეული ნაწილის სწორად მოთავსება.') WHERE id = '407aee71-093f-47d5-be98-f518ebc93883';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'სენსორული ბოთლი'), description_ka = COALESCE(description_ka, 'ფერადი სითხით სავსე ბოთლი ბავშვის ყურადღებას იპყრობს'), instructions_ka = COALESCE(instructions_ka, 'პლასტმასის ბოთლში ჩაასხით ფერადი წყალი ან ჩაყარეთ ბრჭყვიალა მასალა. თავსახური მჭიდროდ დაახურეთ. აჩვენეთ ბავშვს და მიეცით გაგორების საშუალება.') WHERE id = '75be8860-ac3f-4a9e-87c7-5122de70d0a6';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ხელის მოკიდება და ჩაჭიდება'), description_ka = COALESCE(description_ka, 'მიეცით ბავშვს თქვენი თითების ჩაჭიდების საშუალება'), instructions_ka = COALESCE(instructions_ka, 'გაუწოდეთ ბავშვს თითები, რომ ჩაგეჭიდოთ. ფრთხილად მოქაჩეთ, რათა ხელი უფრო ძლიერად ჩაგჭიდოთ.') WHERE id = 'f5161cf6-25f1-4eda-b672-91e0dc7075f4';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ქსოვილების შეგრძნება'), description_ka = COALESCE(description_ka, 'მიეცით ბავშვს სხვადასხვა ქსოვილთან შეხების საშუალება'), instructions_ka = COALESCE(instructions_ka, 'შეაგროვეთ რბილი, უხეში, გლუვი და ფუმფულა ქსოვილები. მიეცით ბავშვს საშუალება, თითოეულს შეეხოს და შეიგრძნოს, თქვენ კი ამ დროს მათი ფაქტურა დაასახელეთ.') WHERE id = 'd62cf27d-4570-4976-85c1-ea88d0004a93';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ჩხრიალას ჟღარუნი'), description_ka = COALESCE(description_ka, 'ბავშვი ჩხრიალას აქნევს და ხმებს გამოსცემს'), instructions_ka = COALESCE(instructions_ka, 'მიეცით ბავშვს ჩხრიალა და აჩვენეთ, როგორ უნდა შეანჯღრიოს. შეაქეთ, როცა თქვენს მოძრაობას გაიმეორებს. სცადეთ სხვადასხვა რიტმი.') WHERE id = 'b0958c0b-1439-4e5e-8443-a1ae673d0845';
UPDATE public.play_activities SET title_ka = COALESCE(title_ka, 'ყინულის კუბებით ხატვა'), description_ka = COALESCE(description_ka, 'დახატეთ ქაღალდზე ფერადი ყინულის კუბებით'), instructions_ka = COALESCE(instructions_ka, 'გაყინეთ საკვები საღებავით შეღებილი წყალი. მიეცით ბავშვს საშუალება, ყინული ქაღალდზე გაასრიალოს და ფერადი ნახატები შექმნას.') WHERE id = '2fb728ab-9f62-4c72-8288-051a6eb7e14e';
