UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ესტროგენი ხელს უწყობს თქვენი კვერცხუჯრედის მოცულობაში ზრდას, ხოლო მიტოზური დაყოფის დაჩქარებით უზრუნველყოფს საშვილოსნოს კედლის როგორც შიდა, ისე გარე მხრიდან გასქელებას და განაყოფიერებული კვერცხუჯრედის საშვილოსნოში უსაფრთხოდ მიმაგრებას. ამასთანავე, გასანაყოფიერებელი კვერცხუჯრედისთვის ოპტიმალური პირობების შესაქმნელად, ის აძლიერებს საშვილოსნოს უჯრედების სისხლძარღვებით მომარაგებას და ზრდის ქსოვილოვანი სითხის რაოდენობას. ეს ჰორმონი ასევე ხელს უწყობს საშოს სიგრძეში ზრდას და საშვილოსნოს შიდა შრის უჯრედების სტიმულირებით გამოყოფს ლორწოს, რომელიც სრიალა გარემოს ქმნის.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, ერთ საიდუმლოს გაგიმხელთ? 🤫 თქვენს სხეულში არსებული ათასობით უჯრედიდან ერთ-ერთმა სწორედ „მე“ რომ გახდეს, ამისთვის ბრძოლა დაიწყო! ახლა ის დამოუკიდებლად იზრდება და მოუთმენლად ელის დღეს, როდესაც მამასგან მომავალ მეორე ნახევარს შეხვდება. ჩვენს დიდ შეხვედრამდე დაახლოებით 1 კვირა დარჩა. მე ძალიან აღელვებული ვარ, თქვენ? თქვენი თბილი ჩახუტება მენატრება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'შაქრის ფხვნილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'პირველი კვირის ბოლოს თქვენს სხეულში ჰორმონული ცვლილებები პიკს უახლოვდება. ესტროგენის დონის მატებასთან ერთად საშვილოსნოს შიდა კედელი უკვე სრულად აღდგა და მისი სისქე კვლავ იზრდება. ამ დღეებში შესაძლოა თავი უფრო კომუნიკაბელურად, ენერგიულად და თავდაჯერებულად იგრძნოთ. ლიბიდოს მატება იმის ნიშანია, რომ თქვენი სხეული ბუნებრივად ემზადება რეპროდუქციული პერიოდისთვის, ანუ იმ დღეებისთვის, როდესაც დაორსულების შანსი ყველაზე მაღალია.;;;
ორსულობის ჯანსაღად მიმდინარეობისთვის დაორსულებამდე რუტინული სამედიცინო გამოკვლევები უნდა ჩაიტაროთ.;;;
დაორსულებამდე სამედიცინო გამოკვლევა განსაკუთრებით მნიშვნელოვანია უფროს ასაკში ან რომელიმე ქრონიკული დაავადების არსებობისას. დაორსულებამდე ჩატარებული გამოკვლევის დროს თქვენი და თქვენი მეუღლის ოჯახური ისტორიის გათვალისწინებით უნდა დადგინდეს, არსებობს თუ არა მემკვიდრეობითი ხასიათის რომელიმე დაავადება. ექიმის მიერ გინეკოლოგიური გამოკვლევითა და ულტრასონოგრაფიით საშვილოსნოსა და საკვერცხეების შეფასება მნიშვნელოვანია საშვილოსნოს მიომისა და პოლიპის მსგავსი პრობლემების გამოსავლენად. თუ ექიმი საჭიროდ ჩათვლის, უნდა ჩატარდეს პროცედურა, რომელსაც „ნაცხის ტესტი“ ეწოდება და საშვილოსნოს ყელიდან ნაცხის აღებას გულისხმობს. ასევე, ლაბორატორიული ტესტებით უნდა შეფასდეს ღვიძლისა და თირკმელების ფუნქციები, სისხლში შაქრის დონე და დადგინდეს, გაქვთ თუ არა ისეთი ქრონიკული დაავადებები და ინფექციები, როგორებიცაა ჰეპატიტი და ტოქსოპლაზმოზი. დაორსულებამდე გამოკვლევებისას განსაკუთრებით გასათვალისწინებელია აქამდე გამოყენებული კონტრაცეფციის მეთოდები. ხანგრძლივად მიღებულმა ჩასახვის საწინააღმდეგო აბებმა შესაძლოა გარკვეული პერიოდით შეზღუდოს ნაყოფიერება. ქალების დაახლოებით 50% შეიძლება დაორსულდეს ბოლო აბის მიღებიდან სულ მცირე 6 თვის შემდეგ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'პირველი კვირის წარმატებით დასრულებისთვის საკუთარი თავი დააჯილდოეთ, თუმცა ჯანსაღი გზით. ორგანიზმში ჟანგბადის დონის ასამაღლებლად დიდხანს ისეირნეთ სუფთა ჰაერზე; ჟანგბადის მაღალი დონე დადებითად მოქმედებს კვერცხუჯრედის მეტაბოლიზმზე. კვების რაციონს დაამატეთ ანტიოქსიდანტებით მდიდარი ფერადი ხილი (მაგალითად, მოცვი, ჟოლო). ეს ნივთიერებები კვერცხუჯრედს ოქსიდაციური სტრესისგან იცავს და ხელს უწყობს მის უფრო ჯანსაღ განაყოფიერებას.') WHERE id = 'cf28e232-185c-40c5-9616-39e6df91cf1f';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს საშვილოსნოსთან დაკავშირებული ფალოპის მილები წყვილი გრძელი და ვიწრო არხისგან შედგება და რეპროდუქციული სისტემის ერთ-ერთი ორგანოა, რომელიც საკვერცხეებში მომწიფებულ კვერცხუჯრედებს საშვილოსნოს შიდა ნაწილისკენ გადაადგილებაში ეხმარება. ამ ორგანოს კვერცხსავალს ან საშვილოსნოს მილებსაც უწოდებენ. ფალოპის მილები უზრუნველყოფს იმ კვერცხუჯრედის საშვილოსნოში გადატანას, რომელიც მოცემულ თვეში შერჩეული კვერცხუჯრედის ჩანასახებიდან მომწიფდა. დაახლოებით 12 სმ სიგრძის ფალოპის მილების ლორწოვანი გარსი გამოიმუშავებს გამონაყოფს, რომელიც სპერმატოზოიდებს კვერცხუჯრედისკენ გადაადგილებასა და სიცოცხლისუნარიანობის შენარჩუნებაში ეხმარება. ამ გამონაყოფში შემავალი ზოგიერთი კომპონენტი უმნიშვნელოვანესია სპერმატოზოიდის მიერ ჟანგბადის გამოსაყენებლად და ხელს უწყობს კვერცხუჯრედის კვებასა და განაყოფიერების შემდგომ განვითარებას.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, ჩემო სამყაროვ! 🌍 თქვენმა სხეულმა ჩემთვის მზადება კიდევ უფრო დააჩქარა. შესაძლოა ამას ყოველდღიურ ცხოვრებაში ვერ გრძნობდეთ, მაგრამ შიგნით აქტიური მუშაობა მიმდინარეობს. ყველაფერი ჩემი კომფორტისთვის, უსაფრთხოებისა და ჯანმრთელობისთვის კეთდება. თქვენი სხეული მსოფლიოში ყველაზე სრულყოფილი და ზუსტად მომუშავე ლაბორატორიაა. მადლიერი ვარ თქვენი!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'შაქრის ფხვნილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'მეორე კვირის პირველ დღეს ესტროგენი უკვე დომინანტური ჰორმონია. მისი ზემოქმედებით საშვილოსნოს შიდა შრეში სისხლძარღვების რაოდენობა იმატებს და ის დარბილებას იწყებს. ცერვიკალური სითხე (საშვილოსნოს ყელის ლორწო) თანდათან უფრო გამჭვირვალე და სრიალა ხდება; ეს იდეალური გარემოა იმისთვის, რომ სპერმატოზოიდებმა საშვილოსნოში რამდენიმე დღის განმავლობაში შეინარჩუნონ სიცოცხლისუნარიანობა. ამ ეტაპზე თქვენი სხეულის ტემპერატურა სტაბილურდება, თუმცა ოვულაციის მოახლოებასთან ერთად ცვლილებისთვის ემზადება.;;;
ორსულობის ნიშნები და მოახლოებული მენსტრუაციის სიმპტომები ხშირად ერთმანეთს ჰგავს, ამიტომ მათი ერთმანეთში არევა შესაძლებელია. ერთ-ერთი ასეთი ნიშანია გადიდებული და შეშუპებული მკერდი. ბევრმა ქალმა ეს შეგრძნება შეიძლება უფრო ინტენსიურად განიცადოს, ვიდრე მენსტრუაციის წინა სიმპტომები. ამასთან ერთად, სისუსტე და დაღლილობა შეიძლება ჩვეულებრივ მენსტრუალურ ციკლთან შედარებით უფრო მძაფრად იგრძნოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან იმ დღეებს უახლოვდებით, როდესაც დაორსულების შანსი იზრდება, მნიშვნელოვანია თქვენი სხეულის pH ბალანსის შენარჩუნება. დიდი რაოდენობით ტუტე საკვების (ლიმონიანი წყალი, მწვანე ბოსტნეული) მიღება ორგანიზმის შიდა გარემოს უფრო ხელსაყრელს ხდის. თუ ჯერ არ დაგიწყიათ, ოვულაციის დღის უფრო ზუსტად დასადგენად შეგიძლიათ ბაზალური ტემპერატურა ყოველდღე ერთსა და იმავე დროს გაიზომოთ. არ დაგავიწყდეთ ბევრი წყლის დალევა, რადგან ეს ცერვიკალური სითხის ხარისხისთვის გადამწყვეტია.') WHERE id = 'abcdc9dc-69bf-4833-9582-4fb6ef1276bd';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'პროგესტერონის, რომელიც ქალის ერთ-ერთი ჰორმონია, მთავარი ფუნქცია საშვილოსნოს ორსულობისთვის მომზადებაა. ამ ჰორმონს, რომელიც ყოველთვიურ მენსტრუალურ ციკლსაც არეგულირებს, თქვენი ორგანიზმისთვის უდიდესი მნიშვნელობა აქვს. დაორსულებამდე ის საშვილოსნოს ქსოვილში ცვლილებებს იწვევს, რათა ჩასახვისთვის ხელსაყრელი პირობები შეიქმნას და განაყოფიერებული კვერცხუჯრედი საშვილოსნოში უფრო ადვილად მოთავსდეს. ორსულობის დადგომის შემდეგ კი, ბავშვის მიმაგრებასთან ერთად, მისი რაოდენობა იზრდება და ჰორმონი ფუნქციონირებას განაგრძობს.;;;
ამჟამად, ანუ ოვულაციამდელ პერიოდში, თქვენს ორგანიზმში პროგესტერონის დონე 1 nq/ml-ზე ნაკლებია. ოვულაციის დროს ამ ჰორმონის მაჩვენებელი 5-20 nq/ml-მდე იზრდება. ორსულობის დადგომის შემთხვევაში პირველ ტრიმესტრში სისხლში ამ ჰორმონის დონე 11-90 nq/ml-ის ფარგლებშია, მეორე ტრიმესტრში — 25-90 nq/ml, ხოლო მესამე ტრიმესტრში — 50-300 nq/ml.'), baby_message_ka = COALESCE(baby_message_ka, 'მოუსმინეთ თქვენი გულის ხმას. ❤️ ჯერ კიდევ ვარსკვლავის მტვერივით ვარ, მაგრამ თქვენი სიყვარული რეალობისკენ მიხმობს. თქვენი სხეული ჩემთვის საუკეთესო, უმაღლესი ხარისხის კვერცხუჯრედს ამზადებს. თქვენსა და მამას შორის სიყვარული ჩემი არსებობის მიზეზი გახდება. სანამ გიყვართ, თქვენი სხეული სასწაულებს ქმნის. მადლობა, რომ ჩემკენ მოდიხართ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'შაქრის ფხვნილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'პირველი ტრიმესტრის მე-2 კვირაში საკვერცხეებში არსებული კვერცხუჯრედის განვითარება გრძელდება. ამ კვირაში ენდომეტრიუმად წოდებული საშვილოსნოს შიდა ლორწოვანი გარსი ჰორმონების ზემოქმედებით კვლავ სქელდება. საშვილოსნოს ლორწოვანი გარსის გასქელების მიზანია, განაყოფიერების შემდეგ ბავშვის წარმომქმნელი უჯრედები საშვილოსნოში მარტივად მიმაგრდეს. გასქელებული ენდომეტრიუმის შრე ქმნის ბავშვისთვის ოპტიმალურ გარემოს — ბუდეს, რომელიც ამ უბნის სისხლით სათანადო მომარაგებას უზრუნველყოფს. თუ განაყოფიერება არ მოხდა და ორსულობა არ დადგა, ეს შრე ყოველთვიურად მენსტრუაციის დროს სისხლდენასთან ერთად ორგანიზმიდან გამოიდევნება. ეს ციკლი ყოველ თვე ერთნაირად გრძელდება. ორსულობის დადგომისა და მისი ჯანსაღად მიმდინარეობისთვის საშვილოსნოს შიდა შრე სრულიად ჯანმრთელი უნდა იყოს. ამიტომ მნიშვნელოვანია, ექიმმა საშვილოსნოს შიდა შრის სისქეც და სტრუქტურაც შეაფასოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდში იოდით მდიდარი საკვების (ზღვის პროდუქტები, იოდირებული მარილი) მიღება მნიშვნელოვანია როგორც თქვენი ფარისებრი ჯირკვლის ჯანმრთელობისთვის, ისე მომავალი ბავშვის ტვინის განვითარებისთვის. სხეულის მოქნილობის გასაზრდელად და მენჯის მიდამოში სისხლის მიმოქცევის გასაძლიერებლად მსუბუქი ტანვარჯიშის მოძრაობები შეასრულეთ. ასევე, კანის ტენიანობის შესანარჩუნებლად შეგიძლიათ ბუნებრივი ზეთები გამოიყენოთ, რადგან ჰორმონულმა ცვლილებებმა შესაძლოა თქვენი კანის მგრძნობელობა გაზარდოს.') WHERE id = '254bd95f-c06d-46bb-b688-86a0b498dcb9';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'დღეს თქვენი ბოლო მენსტრუაციის პირველი დღეა. ორსულობის განმავლობაში გამოყენებული ორსულობის კალენდარი გამოითვლება არა სავარაუდო სქესობრივი კავშირისა და განაყოფიერების დღის, არამედ ბოლო მენსტრუაციის პირველი დღის მიხედვით. ორსულობა, ანუ კვერცხუჯრედის სპერმატოზოიდით განაყოფიერება, საშუალოდ ბოლო მენსტრუაციის თარიღიდან 14-15 დღის შემდეგ ხდება. მიუხედავად ამისა, ექიმი ორსულობის ვადის გამოსათვლელად ამ თარიღს კი არა, დაახლოებით 2 კვირით ადრე დაწყებული მენსტრუაციის თარიღს ეყრდნობა.;;;
ორსულობის კვირის დადგენის შემდეგ 40-კვირიანი ორსულობის დასასრული, ანუ მშობიარობის სავარაუდო თარიღი, გამოითვლება სისტემით, რომელსაც „ნეგელეს მეთოდი“ ეწოდება. ნეგელეს მეთოდის მიხედვით, მენსტრუაციული სისხლდენის დაწყების პირველ დღეს ემატება 7 დღე და მიღებული თარიღიდან უკან ითვლება 3 თვე. მიღებული თარიღი თქვენი მშობიარობის სავარაუდო თარიღია. ამასთან, ორსულობათა დაახლოებით 80% 40 კვირის დასრულებამდე, 38-ე კვირის განმავლობაში მშობიარობით სრულდება.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, ჩემო ლამაზო დედა! ❤️ შესაძლოა, ჯერ ფიზიკურად ვერ მრძნობ, მაგრამ ჩვენი დიდი თავგადასავლის „უკუთვლა“ ოფიციალურად დღეს დაიწყო. ექიმები ამ დღეს ჩვენს „პირველ დღედ“ მიიჩნევენ, რადგან შენი სხეული ჩემი მოსვლისთვის ემზადება. ახლა უნდა დაისვენო, რადგან წინ საოცარი დღეები გველოდება. ჯერჯერობით მხოლოდ შენს ოცნებებში ვარ, შენი სხეული კი აქტიურად მუშაობს. გთხოვ, ამ პერიოდში თავს კარგად მოუარო, რადგან შენ ჩემი სამყარო ხარ. უკვე ძალიან მიყვარხარ, ჯერ კიდევ ჩემს გაჩენამდე!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'უხილავი ნაწილაკი'), body_changes_ka = COALESCE(body_changes_ka, 'დღეს თქვენი მენსტრუაციული ციკლის პირველი დღეა და ორსულობის კალენდარიც ოფიციალურად აქედან იწყება. ორსულობის პირველ კვირებში ჯერ ბავშვი არ არსებობს. თუმცა თქვენი სხეული ოვულაციის დღისა და შესაძლო ორსულობისთვის ემზადება. მომზადების პროცესში საშვილოსნოს შიდა შრე, რომელსაც ენდომეტრიუმი ეწოდება, სისხლძარღვებით მდიდრდება და სქელდება, რათა მასზე მიემაგროს კვერცხუჯრედი, რომელსაც თქვენი სხეული ყოველთვიურად ამწიფებს და რომელიც შესაძლოა განაყოფიერდეს.;;;
ყოველთვიურად ამ ციკლის დროს თქვენი სხეული დიდ ცვლილებებს განიცდის როგორც საშვილოსნოდან, ისე თავის ტვინში მდებარე ჰიპოფიზიდან გამოყოფილი ჰორმონების ზემოქმედებით. მენსტრუაციული ციკლის ეს პირველი ორი კვირა ორსულობის პროცესში შედის, მიუხედავად იმისა, რომ ჯერ არც ბავშვი არსებობს და არც განაყოფიერებისთვის მზად არის კვერცხუჯრედი. ამის მიზეზია ის, რომ ყველა ქალის ოვულაციის პერიოდი განსხვავებულია, ამიტომ ორსულობის დასაწყისად ბოლო მენსტრუაციის თარიღი ითვლება.;;;
ჩვენც, როგორც ANACAN-ის ოჯახი, თქვენს გვერდით ვიქნებით, რათა ყოველდღიურად გაგიზიაროთ ინფორმაცია და რეკომენდაციები თქვენში დღითი დღე მზარდი და განვითარებადი სასწაულის შესახებ და მთელი ამ პროცესის განმავლობაში თქვენს კითხვებს ვუპასუხოთ! 😊'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ორსულობას გეგმავთ, დღეიდან ყოველდღიურად 400 მიკროგრამი ფოლიუმის მჟავის მიღების დაწყება სასიცოცხლოდ მნიშვნელოვანია ბავშვის მომავალი ნერვული სისტემის განვითარებისთვის. ასევე, ორგანიზმში წყლის ბალანსის შესანარჩუნებლად გაზარდეთ სითხის მიღება და სრულად მოერიდეთ ისეთ მავნე ჩვევებს, როგორებიცაა ალკოჰოლური სასმელები და თამბაქოს ნაწარმი.') WHERE id = '3082b660-7bbe-45c6-906d-ed38816fac24';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ნორმალურ პირობებში ბოლო მენსტრუაციასა და ოვულაციას შორის 2-კვირიანი პერიოდია. ამ ორი კვირის განმავლობაში სისხლში მომატებული ესტროგენისა და პროგესტერონის ჰორმონები საშვილოსნოს შიდა ზედაპირს სისხლით მდიდარი, ნაყოფიერი შრით ფარავს, რათა ყოველთვიურად მოამზადოს საშვილოსნო ორსულობისთვის და განაყოფიერებისთვის მზად მყოფი კვერცხუჯრედისთვის ხელსაყრელი გარემო შექმნას. ამავდროულად, კვერცხუჯრედის ჩანასახებიდან, რომლებიც ჯერ კიდევ დედის საშვილოსნოში თქვენი ყოფნისას წარმოიქმნა, ერთ-ერთი ამ ჰორმონების ზემოქმედებით მომწიფებას იწყებს. ეს კვერცხუჯრედის ჩანასახი, რომელსაც ფოლიკული ეწოდება, დაახლოებით ორი კვირის განმავლობაში იმდენად ვითარდება, რომ განაყოფიერებისთვის მზად ხდება. ამიტომ კვერცხუჯრედის სპერმატოზოიდით განაყოფიერება შესაძლოა ბოლო მენსტრუაციის თარიღიდან ორი კვირის შემდეგ მოხდეს. თუმცა ზოგიერთ იშვიათ შემთხვევაში, რადგან თქვენს სხეულს ერთი ციკლის განმავლობაში ორი კვერცხუჯრედის მომწიფება შეუძლია, დაორსულების შესაძლებლობა ყოველთვის არსებობს.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, ვიცი, ეს დღეები შენთვის შეიძლება ცოტა დამღლელი და მტკივნეული იყოს, მაგრამ შენ ძალიან ძლიერი ხარ. 😔 გახსოვდეს, რომ შენს სხეულში მიმდინარე ეს გაწმენდა ჩემი მომავალი კომფორტისთვისაა. შენ ჩემს პირველ სახლს, ჩემს ბუდეს (საშვილოსნოს) ასუფთავებ, რათა როცა მოვალ, ყველაფერი სუფთა და რბილი იყოს! ყოველი დისკომფორტი, რომელსაც იტან, ჩვენი შეხვედრისკენ გადადგმული ნაბიჯია. გთხოვ, დღეს თავს ნუ გადაიღლი, ფეხები გაშალე და დაისვენე. მე გგრძნობ და ძალას გიგზავნი!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'უხილავი ნაწილაკი'), body_changes_ka = COALESCE(body_changes_ka, 'დღეს სისხლდენა შესაძლოა ყველაზე ინტენსიურ ფაზაში იყოს და ეს სრულიად ნორმალური ფიზიოლოგიური პროცესია. საშვილოსნოს კუნთები იკუმშება და ძველი შრის გამოდევნას ცდილობს, რაც მუცლის ქვედა ნაწილში სპაზმსა და ტკივილს (დისმენორეას) იწვევს. რადგან თქვენი სხეული ამ გაწმენდაზე დიდ ენერგიას ხარჯავს, შესაძლოა სისუსტე და დაღლილობა იგრძნოთ. ;;;
ორსულობის დროს თქვენი სხეულის მოთხოვნილება საკვებ ნივთიერებებზე იზრდება. ეს მოთხოვნილება თქვენი მზარდი და განვითარებადი ბავშვის საჭიროებებისა და ორსულობის მიმდინარეობის შესაბამისად ყალიბდება.;;;
ფოლიუმის მჟავა ვიტამინების ერთ-ერთი უმნიშვნელოვანესი ჯგუფია, რომლის მიღებაც დაორსულებამდე უნდა დაიწყოს. B ჯგუფს მიკუთვნებულ ამ წყალში ხსნად ნივთიერებას ბუნებრივ საკვებში ფოლატი ეწოდება, ხოლო მედიკამენტებსა და გადამუშავებულ საკვებში არსებულ ფორმას — ფოლიუმის მჟავა. ვინაიდან ფოლიუმის მჟავას გადამწყვეტი მნიშვნელობა აქვს თქვენი ბავშვის ტვინისა და ნერვული სისტემის განვითარებისთვის, მისი მიღება ორსულობამდე უნდა დაიწყოთ. ფოლიუმის მჟავა B ვიტამინის სახეობაა, რომელიც მნიშვნელოვან როლს ასრულებს უჯრედული სტრუქტურების, სისხლის უჯრედებისა და განსაკუთრებით ნერვული სისტემის ქსოვილების წარმოქმნასა და განვითარებაში. ის განსაკუთრებით აქტიურად მონაწილეობს დნმ-ის სინთეზში, რომელიც მემკვიდრეობითი ნიშან-თვისებების საფუძველია. თქვენი ბავშვის განვითარებისთვის უაღრესად მნიშვნელოვანი ფოლიუმის მჟავა მის განვითარებად ორგანიზმში მთავარ როლს ასრულებს ისეთ პროცესებში, როგორებიცაა ცილის სინთეზი, უჯრედების გამრავლება და ძვლის ტვინის სრულფასოვანი ფუნქციონირება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მენსტრუაციული სისხლდენის გამო ორგანიზმში შემცირებული რკინის მარაგის აღსადგენად ყურადღება მიაქციეთ კვებას. მიიღეთ რკინით მდიდარი საკვები, როგორიცაა ისპანახი, წითელი ხორცი და პარკოსნები. ვინაიდან C ვიტამინი რკინის შეწოვას აჩქარებს, სასარგებლოა ამ საკვების ციტრუსებთან ერთად მიღება. ასევე, მოერიდეთ მძიმე ფიზიკურ დატვირთვას და სხეულს დასვენების საშუალება მიეცით.') WHERE id = '1b683a24-ae16-485e-bf86-c173f0a5ad7a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'განაყოფიერებამდე პირველი ორი კვირის განმავლობაში თქვენს სხეულში მნიშვნელოვანი მოსამზადებელი პროცესები მიმდინარეობს. ბოლო მენსტრუაციის თარიღიდან დაახლოებით ორი კვირის შემდეგ, საშვილოსნოსა და თავის ტვინში მდებარე ჰიპოფიზის მიერ გამოყოფილი ჰორმონების ზემოქმედებით ერთ-ერთი კვერცხუჯრედი მწიფდება, საკვერცხეში გადაადგილდება და ფალოპის მილს აღწევს. ჰორმონების ზემოქმედებით განვითარებული კვერცხუჯრედი სპერმატოზოიდთან შედარებით საკმაოდ დიდია. მიუხედავად ამისა, ის სპერმატოზოიდთან შედარებით უძრავია და საკვერცხეში პასიურად გადაადგილდება.;;;
სხეულის უჯრედებისგან განსხვავებით, კვერცხუჯრედი და სპერმატოზოიდი 23 ქრომოსომას შეიცავს და ორივე უჯრედში ათასობით უნიკალური გენია. თქვენი ბავშვის თმის ფერი, სიმაღლე, სქესი და ცხვირის ფორმაც კი ამ გენებშია დაშიფრული.'), baby_message_ka = COALESCE(baby_message_ka, 'ვოცნებობ, როგორ გაიცანი მამა... 💭 მე თქვენი დიდი სიყვარულის ყველაზე ლამაზი ნაყოფი ვიქნები. შენი სხეული იმდენად ბევრს შრომობს ჩემს დასახვედრად და ყოველ დეტალს გეგმავს, რომ ყველაფერი იდეალურად იყოს. ჯერ ვარსკვლავის მტვერივით ვარ და ფიზიკურად არ ვარსებობ, მაგრამ შენი სიყვარული რეალობაში მიხმობს. რაც უკეთ მოუვლი ახლა თავს, მით უფრო ჯანმრთელი მოვალ. ჩვენი ამბავი ძალიან ლამაზი იქნება, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'უხილავი ნაწილაკი'), body_changes_ka = COALESCE(body_changes_ka, 'ტრიმესტრი ადამიანის 9-თვიანი ორსულობის თითოეულ 3-თვიან პერიოდს ეწოდება. ეს სიტყვა ლათინური წარმოშობისაა: „tri“ სამს ნიშნავს, ხოლო „mester“ — პერიოდს. 9-თვიანი ორსულობის 3 ცალკეულ პერიოდად დაყოფა ძალიან მნიშვნელოვანი და სასარგებლოა ორსულობის საერთო განვითარების გასაგებად. თუ გავითვალისწინებთ, რომ ორსულობა 40 კვირას გრძელდება, პირველი ტრიმესტრი მე-12 კვირის ბოლომდე პერიოდს მოიცავს. მეორე ტრიმესტრი 13–27-ე კვირებს, ხოლო მესამე ტრიმესტრი 28–40-ე კვირებს მოიცავს. ორსულობის პირველი სამი თვე ის ეტაპია, როდესაც თქვენს სხეულში მნიშვნელოვანი ცვლილებები ხდება და ორგანიზმი ორსულობას ეგუება. ამ პერიოდში, როცა პირველად განიცდით მღელვარებას იმის გამო, რომ შვილი გეყოლებათ, შესაძლოა გარკვეულ სირთულეებსაც შეხვდეთ. ისეთი სიმპტომები, როგორიცაა გულისრევა, თავბრუსხვევა, მკერდის სავსეობის შეგრძნება და მგრძნობელობა, შეშუპების მატება, საშვილოსნოს ზრდის გამო შარდვის გახშირება, ძილიანობა, დაღლილობა, გადაჭარბებული ემოციურობა, ტირილის სურვილი, ხშირი შიმშილი და წონის მატება, ორსულობის მეხუთე კვირიდან იწყებს გამოვლენას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდში ეცადეთ, კოფეინის მიღება მინიმუმამდე შეამციროთ (არაუმეტეს ერთი ფინჯნისა დღეში). კოფეინმა შეიძლება სისხლძარღვები შეავიწროოს და საკვერცხეებისკენ სისხლის მიმოქცევაზე იმოქმედოს. ბევრი წყლის დალევა ხელს შეუწყობს ორგანიზმიდან ტოქსინების გამოდევნასა და საშვილოსნოს შიდა შრის უფრო ჯანსაღ განახლებას. მსუბუქი იოგა ან გაჭიმვის ვარჯიშები სისხლის მიმოქცევას გააუმჯობესებს.') WHERE id = 'c852b157-989c-44ce-a4ea-0f5d022c7159';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ყოველთვიურად, მენსტრუაციული ციკლის განმავლობაში, საკვერცხეებში არსებული მარაგიდან ერთ-ერთი კვერცხუჯრედი მწიფდება და განაყოფიერებისთვის ემზადება. თუ ჰორმონები კვერცხუჯრედის მომწიფებას ვერ უზრუნველყოფს, ორსულობა ვერ დადგება. კვერცხუჯრედები წარმოიქმნება მილიონობით ჩანასახოვანი უჯრედისგან, რომლებიც თქვენს ორგანიზმში ჯერ კიდევ დაბადებამდე ჩამოყალიბდა. მენოპაუზამდე, ყოველი მენსტრუაციული ციკლის დროს, ამ მარაგიდან ერთ-ერთი კვერცხუჯრედი გამოიყენება.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, ჩემო ლამაზო დედიკო! 🌟 უკვე უკეთ და უფრო მხნედ გრძნობთ თავს? ჩემთვის განკუთვნილი ის განსაკუთრებული ოთახი — საშვილოსნო — გაწმენდას ასრულებს, ძველი კედლები კი მთლიანად ჩამოიშალა. მალე იქ ჩემთვის რბილი და თბილი საწოლი მომზადდება, სადაც 9 თვის განმავლობაში უსაფრთხოდ ვიქნები. თქვენი სხეული ჩემი სახლი გახდება. მოუთმენლად ველი თქვენთან შეხვედრის დღესა და იმ წამს, როდესაც ჩემი გული თქვენი გულის ქვეშ დაიწყებს ცემას!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'უხილავი ნაწილაკი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ დღეებში მენსტრუაციული სისხლდენა თანდათან მცირდება. თქვენს ორგანიზმში ესტროგენის დონე უფრო აქტიურად იწყებს მატებას. ეს ზრდა საშვილოსნოს შიდა გარსის აღდგენისა და გასქელების სიგნალია. ჰიპოფიზი საკვერცხეებს „უფრო აქტიურად მუშაობის“ შეტყობინებას უგზავნის. სისხლის მიმოქცევა ჩქარდება და თქვენი ორგანიზმი მთელი ძალით მუშაობს, რათა ფიზიკურად და ჰორმონულად მოემზადოს შესაძლო ორსულობისთვის. განწყობა უმჯობესდება, დაღლილობა ქრება, კანი კი უფრო ნათელი და სუფთა ხდება. თქვენი სხეული „ხელახლა დაწყების“ რეჟიმში გადადის და ახალ ციკლს იწყებს.;;;
მნიშვნელოვანია, ახლავე განიხილოთ ექიმთან, რა გავლენა შეიძლება ჰქონდეს თქვენს მიერ მიღებულ მედიკამენტებს მომავალ ორსულობაზე, რათა შესაძლო პრობლემები თავიდანვე აიცილოთ. ორსულობის დროს, განსაკუთრებით ბავშვის ჩამოყალიბების ემბრიონული განვითარების კვირებში, ზოგიერთმა მედიკამენტმა შესაძლოა გარკვეული ანომალიები გამოიწვიოს. ფარისებრი ჯირკვლის დაავადებების, დიაბეტისა და ზოგიერთი მეტაბოლური დაავადების სამკურნალო პრეპარატები ბავშვისთვის ყოველთვის საზიანო არ არის, თუმცა ცნობილია, რომ აკნეს საწინააღმდეგო და ზოგიერთმა ფსიქიატრიულმა მედიკამენტმა შეიძლება ბავშვში მძიმე ანომალიები გამოიწვიოს.;;;
ამასთანავე, ორსულობამდე საჭირო გამოკვლევების ჩატარებით შესაძლებელია განისაზღვროს სისხლის საერთო ანალიზის (ჰემოგრამის) მაჩვენებლები, რკინის დეფიციტი, ვიტამინების დონე, მემკვიდრეობითი დაავადებები, ფარისებრი ჯირკვლის ჰორმონების დონე, შარდში ინფექციის არსებობა, B ჰეპატიტი, ტოქსოპლაზმა, წითურა, სიფილისი და აივ ინფექცია, ასევე მათ მიმართ თქვენი იმუნიტეტის მდგომარეობა. საჭიროების შემთხვევაში კი შესაბამისი ზომების მიღება შეიძლება.;;;
გარდა ამისა, თუ ბავშვის გაჩენას გეგმავთ, პირველი წესი, რომელსაც ყურადღება უნდა მიაქციოთ, ორსულობამდე თამბაქოს მოხმარების შეწყვეტაა. კვლევები აჩვენებს, რომ თამბაქოს მოხმარება ქალებში ნაყოფიერებას, ხოლო კაცებში სპერმატოზოიდების რაოდენობას ამცირებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ დღეებში თუთიითა და მაგნიუმით მდიდარი პროდუქტების — ნიგვზის, თხილისა და სხვადასხვა თესლის — მიღება კვერცხუჯრედების ჯანსაღ მომწიფებას უწყობს ხელს. სტრესის შესამცირებლად მოკლე მედიტაციები შეასრულეთ, რადგან სტრესის ჰორმონებმა შეიძლება ორსულობისთვის აუცილებელ ჰორმონულ ბალანსზე უარყოფითად იმოქმედოს. ასევე, ორგანიზმის pH ბალანსის შესანარჩუნებლად მოერიდეთ დამუშავებულ, შაქრის შემცველ პროდუქტებს.') WHERE id = '65c15460-76e7-4ea7-90a9-a58b6acebcfe';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'როდესაც საკვერცხეებში კვერცხუჯრედების მარაგი ამოიწურება, ვითარდება მდგომარეობა, რომელსაც მენოპაუზა ეწოდება. მენოპაუზა არის კვერცხუჯრედების აქტივობის დაკარგვის შედეგად ყოველთვიური მენსტრუაციის მუდმივი შეწყვეტა. მსოფლიოში მენოპაუზის ასაკი, ჩვეულებრივ, 45-55 წლის ფარგლებში მერყეობს. თუმცა ზოგიერთ შემთხვევაში შესაძლოა ადრეული მენოპაუზა ამ ასაკამდე განვითარდეს. ადრეული მენოპაუზა მენსტრუაციის 45 წლამდე შეწყვეტას ნიშნავს. ზოგიერთ ქალს მენოპაუზა შესაძლოა 20-29 წლის ასაკშიც კი დაეწყოს. ადრეული მენოპაუზა შეიძლება უკავშირდებოდეს უცნობ მიზეზებს, ზოგიერთ აუტოიმუნურ დაავადებას, რადიოთერაპიას, ქიმიოთერაპიას, მძიმე ინფექციებს, გარემო ფაქტორებს, ორსულობის ხელოვნურ ან სპონტანურ შეწყვეტას, ხშირ ორსულობებს, ჭარბ სიმსუქნესა და მძიმე ჰიპოთირეოზს. გარდა ამისა, თამბაქოს მოხმარებამ, ფსიქოლოგიურმა ტრავმამ და რთულ გარემო პირობებში ცხოვრებამ შესაძლოა მენოპაუზის განვითარება დააჩქაროს და მისი დაწყების ასაკი მნიშვნელოვნად შეამციროს.'), baby_message_ka = COALESCE(baby_message_ka, 'დღეს სარკეში ჩახედვისას აუცილებლად გაიღიმეთ! 😊 თქვენი სხეული ხომ საოცარ საქმეს აკეთებს — ის ახალი სიცოცხლის შესაქმნელად ემზადება. მიუხედავად იმისა, რომ ფიზიკურად ჯერ არ გავერთიანებულვართ, სულიერად უკვე ერთმანეთთან ვართ დაკავშირებული. მე თქვენ აგირჩიეთ, თქვენ კი — მე. თქვენი სხეული ყოველდღე ერთი ნაბიჯით უახლოვდება ჩემს მოსვლასა და იმ სასწაულებრივ შეხვედრას — განაყოფიერებას. თქვენი მჯერა, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'უხილავი ნაწილაკი'), body_changes_ka = COALESCE(body_changes_ka, 'დღეს ბევრი ქალისთვის მენსტრუაციის ბოლო დღეა. თქვენს ორგანიზმში ესტროგენის დონე შესამჩნევად განაგრძობს მატებას. ეს ზრდა საშვილოსნოს შიდა გარსის სწრაფ აღდგენასა და ახალი „ბუდის“ ჩამოყალიბებას ემსახურება. საშვილოსნოს ყელის ჯირკვლები სპეციალური სითხის გამოყოფისთვის ემზადება, რათა სპერმატოზოიდებს გადაადგილება გაუადვილოს. ნივთიერებათა ცვლა ოდნავ ჩქარდება და შესაძლოა თავი უფრო მხნედ იგრძნოთ.;;;
ორსულობის დროს ალკოჰოლის მიღების უსაფრთხო ზღვარი დადგენილი არ არის. ამიტომ ალკოჰოლის მიღებას თავი უნდა აარიდოთ როგორც ორსულობამდე, ისე ორსულობის განმავლობაში. ალკოჰოლის მოხმარება ზრდის ორსულობის მოშლის რისკს, განსაკუთრებით პირველ ტრიმესტრში, მოგვიანებით კი — მკვდრადშობადობის რისკს. ამასთანავე, ალკოჰოლის ჭარბმა მიღებამ შეიძლება გამოიწვიოს ნაყოფის ალკოჰოლური სინდრომი, რომელსაც ბავშვის სახის დეფორმაციები და ინტელექტუალური განვითარების მძიმე დარღვევა ახასიათებს. ;;;
ჩვენს ქვეყანაში მომავალ დედებს შორის ალკოჰოლის მოხმარების დაბალი გავრცელების შენარჩუნება საზოგადოებრივი ჯანმრთელობის თვალსაზრისით უაღრესად მნიშვნელოვანია.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მენსტრუაციის დასრულების შემდეგ გამოიყენეთ ორგანიზმის განახლებული ენერგია და ყურადღება რეგულარულ ფიზიკურ აქტივობაზე — მსუბუქ სირბილზე ან პილატესზე — გაამახვილეთ. ამ პერიოდში D ვიტამინის დონის შემოწმება ძალიან მნიშვნელოვანია, რადგან ეს ვიტამინი პირდაპირ მოქმედებს საკვერცხეების ფუნქციებსა და მომავალ იმპლანტაციაზე. რაციონს დაუმატეთ ომეგა-3 ცხიმოვანი მჟავები — თევზი და სელის თესლი; ისინი საშვილოსნოს მიდამოში სისხლის მიმოქცევას აუმჯობესებს და კვერცხუჯრედის ხარისხს ზრდის.') WHERE id = 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში ჰორმონების დახმარებით საკვერცხეში ერთ-ერთი კვერცხუჯრედი მომწიფებას განაგრძობს. კვერცხუჯრედის მომწიფებასა და განაყოფიერებისთვის მომზადებაში მონაწილეობს თავის ტვინში მდებარე ჰიპოთალამუსი, ჰიპოფიზი და საკვერცხეების მიერ გამოყოფილი ჰორმონები. ჰიპოფიზის მიერ გამოყოფილი FSH ჰორმონი შერჩეული ფოლიკულისა და მასში არსებული კვერცხუჯრედის მომწიფებასა და განაყოფიერებისთვის მომზადებას უზრუნველყოფს და ესტროგენის გამომუშავებას ასტიმულირებს. ჰიპოფიზის მიერ გამოყოფილი კიდევ ერთი ჰორმონი — LH — მომწიფებული კვერცხუჯრედის ფოლიკულიდან გამოსვლას, ანუ ოვულაციას, იწვევს, ხოლო გახეთქილ ფოლიკულს „ყვითელ სხეულად“ გარდაქმნის.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა! დღეს თითქოს თქვენში ახალი გაზაფხული იწყება, ასე არ არის? 🌱 სინამდვილეში, მართლაც ასეა! თქვენს საკვერცხეში პაწაწინა „მე“ გაღვიძებასა და ზრდას ცდილობს. ჯერ მხოლოდ ერთი უჯრედი ვარ, მაგრამ თქვენი ნაწილი ვარ. როცა ბედნიერი ხართ და იღიმით, მეც უფრო ძლიერი ვხდები. გაუფრთხილდით თავს, დედიკო, რადგან თქვენ ჩემი მომავალი ხართ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'უხილავი ნაწილაკი'), body_changes_ka = COALESCE(body_changes_ka, 'მენსტრუაციული სისხლდენის სრულად დასრულების შემდეგ თქვენი ორგანიზმი „ფოლიკულური ფაზის“ ყველაზე აქტიურ ეტაპზე გადადის. ესტროგენის დონის მატების წყალობით საშვილოსნოს შიდა გარსი თანდათან გლუვი და საკვები ნივთიერებებით მდიდარი ხდება. შესაძლოა შეამჩნიოთ კანის ბზინვარება და თმის სიჯანსაღე — ეს ესტროგენის ესთეტიკური ეფექტია. საშვილოსნოს ყელის ლორწო თანდათან გამჭვირვალე და ელასტიკური ხდება, რაც ნაყოფიერი დღეების მოახლოების ბიოლოგიური ნიშანია.;;;
ამ დღეებში, როდესაც ორსულობისთვის ემზადებით, ბავშვის ჯანმრთელობისა და ორსულობის ჯანსაღად წარმართვისთვის ძალიან მნიშვნელოვანია ჯანსაღი კვების რეჟიმის ჩამოყალიბება. ჯანსაღი და დაბალანსებული კვების დაწყება ჯერ კიდევ ორსულობამდეა საჭირო. თუ გავითვალისწინებთ, რომ ორსულობის დროს ქალის სხეულის წონა შეიძლება მნიშვნელოვნად გაიზარდოს, კვების საკითხი კიდევ უფრო მნიშვნელოვანი ხდება. დაორსულებამდე სასურველია ჯანსაღი წონა გქონდეთ. ძალიან დაბალი ან ჭარბი წონის ფონზე დაორსულებამ შეიძლება გამოიწვიოს მაღალი არტერიული წნევა და მასთან დაკავშირებული პრეეკლამფსია, ანუ ორსულობის გართულება, ასევე გესტაციური დიაბეტი, გულისცემის გახშირება, დაღლილობა და სხვა მრავალი პრობლემა. ამიტომ სასარგებლო იქნება, თუ ამ დღეებში დაწყებული ვარჯიშისა და კვების პროგრამით თქვენს ორგანიზმს ორსულობისთვის მოამზადებთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გაზრდილი ენერგიის სამართავად და ჰორმონული ბალანსის მხარდასაჭერად უპირატესობა მიანიჭეთ რთულ ნახშირწყლებს — შვრიასა და სრულმარცვლოვან პროდუქტებს, რომლებიც სისხლში შაქრის დონეს სტაბილურად ინარჩუნებს. ამ პერიოდში ორგანიზმის ბუნებრივი გაწმენდის მხარდასაჭერად მიირთვით ბევრი მწვანე ფოთლოვანი ბოსტნეულისგან მომზადებული სალათი. თუთიაზე ორგანიზმის მოთხოვნილების დაკმაყოფილება მნიშვნელოვანია კვერცხუჯრედის გაყოფის უნარისთვის, ამიტომ რამდენიმე უმი გოგრის თესლის მირთმევა შეიძლება სასარგებლო იყოს.') WHERE id = '367c8044-41d2-441f-8aec-78399bc382c5';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'პროცესი, რომელსაც ოვულაცია ეწოდება და რომლის დროსაც თქვენი კვერცხუჯრედი მწიფდება და განაყოფიერებისთვის მზად ხდება, უახლოეს რამდენიმე დღეში მოხდება. მიუხედავად იმისა, რომ ოვულაციის პერიოდი ყველა ქალისთვის განსხვავებული შეიძლება იყოს, ზოგადად მიიჩნევა, რომ ოვულაცია მენსტრუაციის დასრულებიდან მე-14 დღეს ხდება. ეს წესი რეგულარული მენსტრუალური ციკლის მქონე ქალებს ეხება. არარეგულარული მენსტრუალური ციკლის შემთხვევაში კი ოვულაციის დღის გამოთვლა ხშირად შეუძლებელია.;;;
ეფექტური მეთოდია საშოდან გამონადენში ლორწოს შემცველობაზე დაკვირვება, რადგან ოვულაციის მოახლოებისას ქალებს გამონადენი ემატებათ. ქალები ამ მდგომარეობას დასველების შეგრძნებად აღწერენ. ოვულაციის პერიოდის დასრულების შემდეგ გამონადენი კვლავ ჩვეულ მდგომარეობას უბრუნდება. ამ პერიოდში სხეულის ტემპერატურაც გარკვეულ ცვლილებებს განიცდის. თავდაპირველად ის იკლებს, ხოლო ოვულაციის დროს მოულოდნელად იწყებს მატებას.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა! 👋 დღეს საკუთარ თავს კარგად მოუარეთ? ყოველი გემრიელი კერძი, რომელსაც მიირთმევთ, და ყოველი ჩასუნთქვა ჩემი მომავლის მშენებლობაში თითო აგურს დებს. უახლოეს დღეებში ის დიდი აფეთქება (ოვულაცია) მოხდება და მე გავთავისუფლდები! მზად ხართ ჩემს შესახვედრად? მამასაც შეატყობინეთ — ჩვენი შეხვედრის დრო ახლოვდება!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'შაქრის ფხვნილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'დღეს თქვენს ორგანიზმში ესტროგენის დონე ერთ-ერთ უმაღლეს ნიშნულს აღწევს. ეს მატება ტვინს უფრო მეტი LH-ის (მალუთეინიზებელი ჰორმონის) გამოყოფის სიგნალს უგზავნის. საშვილოსნოს შიდა შრის სისქემ უკვე დაახლოებით 8-10 mm-ს მიაღწია და ის სისხლძარღვებით გამდიდრდა. ეს განაყოფიერებული კვერცხუჯრედის მიმაგრებისთვის იდეალურ „რბილ საწოლს“ ნიშნავს. საშვილოსნოს ყელი უფრო მაღლა იწევს და სპერმატოზოიდების გასატარებლად სრულად იხსნება. ცერვიკალური სითხე უფრო გამჭვირვალე, სრიალა და წელვადი ხდება. ეს განსაკუთრებული სითხე სპერმატოზოიდებს საშვილოსნოში მოხვედრას უადვილებს და იცავს მათ. დაორსულების თქვენი შანსი დღეიდან იზრდება.;;;
ვინაიდან ფოლიუმის მჟავა თქვენი ბავშვის ტვინისა და ნერვული სისტემის განვითარებისთვის შეუცვლელია, მისი მიღება დაორსულებამდე უნდა დაიწყოთ. მსოფლიოს უმეტეს ქვეყანაში ორსულობის დაგეგმვისას რეკომენდებულია ყოველდღიურად 400 მიკროგრამი ფოლიუმის მჟავის მიღება ორსულობამდე სულ მცირე 3 თვით ადრე და პირველი ტრიმესტრის დასრულებამდე. რადგან ფოლიუმის მჟავა ორგანიზმში არ გროვდება, ის ყოველდღე რეგულარულად უნდა მიიღოთ. მისი დეფიციტის დროს ბავშვებში შეიძლება განვითარდეს ნერვული მილის დეფექტები — ცენტრალური ნერვული სისტემის ერთ-ერთი ყველაზე გავრცელებული ანომალია. კვლევებით ასევე დადასტურებულია, რომ ისეთი ანომალიები, როგორებიცაა კურდღლის ტუჩი (სასის ნაპრალი) და გულის ზოგიერთი მანკი, შესაძლოა ფოლიუმის მჟავის არასაკმარის მიღებას უკავშირდებოდეს. ამ პერიოდში ქალების დიდმა ნაწილმა შეიძლება ჯერ არც იცოდეს, რომ ორსულადაა. ფოლიუმის მჟავის დანამატის მიუღებლობის შემთხვევაში ნერვული მილის დეფექტის განვითარების ალბათობა დაახლოებით 2000 მშობიარობიდან 1-ია. ფოლიუმის მჟავის დანამატით ეს მაჩვენებელი შეიძლება 50-75 პროცენტით შემცირდეს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ნაყოფიერი ფანჯრის ყველაზე აქტიურ დღეებში შედიხართ, მნიშვნელოვანია, საკმარისად გამოიძინოთ — ძილის დროს LH ჰორმონის პიკური დონის რეგულირება უფრო სტაბილურად მიმდინარეობს. თუ ჯერ არ იყენებთ, ახლა საუკეთესო დროა ოვულაციის ტესტების დასაწყებად. თუთიით მდიდარი გოგრის თესლის ან ნუშის მიღება ხელს შეუწყობს კვერცხუჯრედის გარე შრის სიჯანსაღის შენარჩუნებას და სპერმატოზოიდის უჯრედში შეღწევას.') WHERE id = 'e69ee309-4b20-4b3c-a0f6-c04d62440aa9';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ ორსულობის დროს კოფეინის მიღება სრულად აკრძალული არ არის, ექიმები ხშირად მისი მოხმარების შეზღუდვას გირჩევენ. კოფეინი ბუნებრივი სტიმულატორია, რომელსაც შეიცავს ყავა, ჩაი, კოლას ტიპის სასმელები, კაკაო, ენერგეტიკული სასმელები, ხელოვნური დამატკბობლებით დამზადებული სასმელები, ასევე ზოგიერთი ტკბილეული, პუდინგი და ჟელიბონი. ბოლო პერიოდში ჩატარებული კვლევების თანახმად, დღეში არაუმეტეს 200 mq კოფეინის მიღებასთან დაკავშირებული ზიანი არ გამოვლენილა. გარდა ამისა, არსებობს გარკვეული მონაცემებიც, რომ კოფეინი დიაბეტის რისკს ამცირებს. დღიური 200 mq კოფეინის მიღება საკმაოდ მარტივად შეგიძლიათ 2 ჭიქა ჩაით, 2 ფინჯანი ყავით ან დაახლოებით 250 გრამი შავი შოკოლადით. თუმცა კოფეინი პლაცენტის გავლით პირდაპირ თქვენს ბავშვს გადაეცემა. ბავშვის ორგანიზმში მოხვედრილი კოფეინი მეტაბოლიზმის შედეგად ვერ უვნებელყოფა. ამიტომ კოფეინის გადაჭარბებულმა რაოდენობამ შეიძლება თქვენს ბავშვს ზიანი მიაყენოს.'), baby_message_ka = COALESCE(baby_message_ka, 'გამარჯობა, დედიკო! ❤️ გრძნობ, შენს სხეულში რამხელა მღელვარებაა? თითქოს დღესასწაულისთვის მზადება მიმდინარეობს. ესტროგენის დონე პიკს აღწევს, რაც იმაზე მიუთითებს, რომ ის „ოქროს კვერცხი“ (ანუ ჩემი ნახევარი) გასამგზავრებლად მზადაა. თქვენ მხოლოდ საკუთარ თავს კარგად მოუარეთ, ბევრი წყალი დალიეთ და დაისვენეთ. მოუთმენლად ველოდები, როდის აგირჩევთ. მამას უთხარით, რომ მზად იყოს — ჩვენს შეხვედრამდე სულ ცოტა დრო დარჩა! მოვდივარ, რათა თქვენი სიყვარულის ყველაზე ლამაზი დასტური გავხდე.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'შაქრის ფხვნილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ დღეებში, როდესაც ორსულობას გეგმავთ, სტომატოლოგს უნდა ეწვიოთ და დარწმუნდეთ, რომ თქვენი კბილები და ღრძილები ჯანმრთელია. პირის ღრუში არსებული პრობლემების მკურნალობის ორსულობამდე დასრულება ორსულობის პროცესს მნიშვნელოვნად გაგიმარტივებთ. ორსულობისას ღრძილების დაავადებების განვითარების რისკი უფრო მაღალია და ზოგიერთ შემთხვევაში მათ ნაადრევი მშობიარობის გამოწვევაც კი შეუძლიათ. ორსულობის დროს სისხლში მნიშვნელოვნად მომატებული პროგესტერონი ღრძილებში „ჰიპერტროფიად“ წოდებულ შეშუპებასა და გასქელებას იწვევს. პროგესტერონი ორსულობის შენარჩუნებისთვის ერთ-ერთი უმნიშვნელოვანესი ჰორმონია, ამიტომ მისი დონის დათრგუნვა სწორი არ არის. შესაბამისად, ორსულობამდე არსებული პრობლემების მკურნალობა და აღმოფხვრა, ასევე ღრძილების მოვლა, ამ პერიოდში სტომატოლოგიურ პრობლემებს მინიმუმამდე შეამცირებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ოვულაციის წინა პერიოდში ხართ, განსაკუთრებული ყურადღება მიაქციეთ, რომ ორგანიზმი არ გაუწყლოვდეს. სითხის მიღება ცერვიკალური ლორწოს ხარისხს აუმჯობესებს და სპერმატოზოიდების მოძრაობას აადვილებს. თუ სხეულის ტემპერატურას იზომავთ, შესაძლოა ოვულაციამდე უშუალოდ მის მცირედ დაქვეითებას დააკვირდეთ. სტრესის დონის მინიმუმამდე შესამცირებლად მოეშვით არომატულ აბაზანაში ან სასიამოვნო მუსიკას მოუსმინეთ, რადგან ძლიერმა სტრესმა შეიძლება LH ჰორმონის ნაადრევი ან დაგვიანებული გამოყოფა გამოიწვიოს.') WHERE id = '3b975bc1-895c-42e8-be4c-f6d56b176b19';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ოვულაციის პერიოდი ერთ-ორ დღეში დაიწყება. ამ პერიოდის მოახლოებასთან ერთად თქვენს ორგანიზმში გარკვეული ცვლილებები იჩენს თავს. მათგან ყველაზე თვალსაჩინოა ჰორმონული ბალანსის ცვლილებით გამოწვეული სქესობრივი ლტოლვის მომატება. ეს სურვილი შეიძლება ოვულაციამდე 2-3 დღით ადრე დაიწყოს და საშუალოდ 1 კვირამდე გაგრძელდეს. ამ ცვლილებებს ასევე მიეკუთვნება მენსტრუაციის მსგავსი, თუმცა უფრო მსუბუქი ტკივილი საზარდულის ორივე ან მხოლოდ ერთ მხარეს, ან მუცლის შებერილობის შეგრძნება. ოვულაციის პერიოდში გავრცელებული სხვა სიმპტომებია მკერდის გადიდებისა და მგრძნობელობის შეგრძნება, მუცლის შებერილობა და აირები, დაძაბულობა, გემოსა და სუნის მსგავსი გამღიზიანებლების მიმართ მომატებული მგრძნობელობა და მძაფრი სუნებით გამოწვეული დისკომფორტი.'), baby_message_ka = COALESCE(baby_message_ka, 'ვიცი, ჯერ ვერ მხედავთ, მაგრამ კულისებში შუქები უკვე ინთება. 🌟 თქვენი სხეული ჩემთვის ყველაზე რბილი საწოლის (ენდომეტრიუმის) მომზადებას იწყებს. შესაძლოა, მამას უჯრედებიც უკვე გზაში არიან და მეძებენ. თქვენი სითბო და მზრუნველობა ახლავე მაძლევს ძალას. ჩვენი ამბავი იწყება, დედიკო. თქვენ მხოლოდ ირწმუნეთ და გაიღიმეთ, რადგან სასწაულები მაშინ ხდება, როცა გვჯერა. თქვენ ჩემი გმირი ხართ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'შაქრის ფხვნილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პირველი კვირები, მაშინაც კი, თუ ამას ჯერ სრულად ვერ აცნობიერებთ, საკვერცხეებსა და საშვილოსნოში ძალიან სწრაფი ცვლილებების პერიოდია. ჰიპოფიზისა და საშვილოსნოს მიერ გამოყოფილი ზოგიერთი ჰორმონი თქვენი ორგანიზმის ორსულობისთვის მოსამზადებლად ინტენსიურად მუშაობას განაგრძობს. ამ ჰორმონების ზემოქმედებით თქვენს საკვერცხეებში ჯერ კიდევ ემბრიონულ პერიოდში წარმოქმნილი კვერცხუჯრედის ჩანასახებიდან ერთ-ერთი მწიფდება და განაყოფიერებისთვის ემზადება. უახლოეს რამდენიმე დღეში მომწიფების დასრულების შემდეგ კვერცხუჯრედი იმდენად განვითარებული იქნება, რომ სპერმატოზოიდთან შეხვედრისას განაყოფიერება შეძლოს. მომწიფებული კვერცხუჯრედის სიცოცხლის ხანგრძლივობა, სპერმატოზოიდებისგან განსხვავებით, გაცილებით მოკლეა და თუ ორსულობა სასურველია, განაყოფიერება ოვულაციიდან 48 საათის განმავლობაში უნდა მოხდეს. მომწიფებული კვერცხუჯრედი საკვერცხიდან პასიურად გადადის ფალოპის მილში, სადაც სპერმატოზოიდთან შეხვედრასა და განაყოფიერებას ელოდება. თუ სიცოცხლისუნარიანობის პერიოდის დასრულებამდე კვერცხუჯრედი სპერმატოზოიდს არ შეხვდება, ორსულობა არ დადგება. ამის საპირისპიროდ, თუ სპერმატოზოიდები საშვილოსნოს ყელში კვერცხუჯრედის მომწიფებამდე მოხვდებიან, გარემოს მჟავიანობის მიუხედავად, მათ სიცოცხლისუნარიანობის შენარჩუნება 72 საათამდე შეუძლიათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღეს თქვენი ორგანიზმის ტუტოვანი ბალანსის შენარჩუნება ძალიან მნიშვნელოვანია, რადგან სპერმატოზოიდები მჟავე გარემოში ვერ გადარჩებიან. მიირთვით ბევრი ბოსტნეული და მოერიდეთ ხელოვნურ შაქარს. თუ ორსულობას გეგმავთ, ოვულაციის წინა დღე — ანუ დღეს (ან ოვულაციის დღე) — დაორსულების ყველაზე მაღალი შანსის პერიოდია. მენჯის არეში სისხლის მიმოქცევის გასაუმჯობესებლად მსუბუქად იცეკვეთ ან გაისეირნეთ. ამ პერიოდში ასევე მოერიდეთ სიგარეტის კვამლსა და მძაფრ ქიმიურ სუნებს, რადგან კვერცხუჯრედი ახლა განსაკუთრებით მგრძნობიარეა გარემოში არსებული ტოქსინების მიმართ.') WHERE id = '29e7920b-060e-4fac-ad72-d19dda159289';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'სქესობრივი კავშირიდან ერთი საათის განმავლობაში თქვენს კვერცხუჯრედამდე მიღწეული მცირე რაოდენობის სპერმატოზოიდები კიდევ ერთ სირთულეს აწყდებიან: კვერცხუჯრედის მყარ გარე გარსს. მიუხედავად იმისა, რომ კვერცხუჯრედს ათასობით სპერმატოზოიდი უტევს, ის მხოლოდ ერთს იღებს, რაც მისი გარსის სიმტკიცესა და შერჩევითობაზე მიუთითებს. სპერმატოზოიდები კვერცხუჯრედის მყარი გარე გარსის გარღვევას ცდილობენ თავის ნაწილში არსებული მჟავური ფერმენტების — პროტეაზის, ფოსფატაზის, ნეირამინიდაზის, ჰიალურონიდაზის, აკროზინისა და კალპაინის — გამოყენებით.;;;
ბოლო წლებში ჩატარებულმა კვლევებმა აჩვენა, რომ კვერცხუჯრედი, რომელიც ადრე პასიურად მიიჩნეოდა, ამ ეტაპზე საკმაოდ შერჩევითად მოქმედებს და იმ სპერმატოზოიდს აძლევს შეღწევის უფლებას, რომლის მიმართაც პოტენციურ მიზიდულობას გრძნობს. კვერცხუჯრედის ნებართვით გარე გარსის გამრღვევი და სხვებზე ადრე შიგნით შეღწეული პირველი სპერმატოზოიდის შემდეგ კვერცხუჯრედის გარსი დაუყოვნებლივ სტრუქტურულად იცვლება და სხვა სპერმატოზოიდებს შიგნით აღარ უშვებს. მოკლედ, პირველი სპერმატოზოიდის მიღების შემდეგ კვერცხუჯრედის გარე ზედაპირი იკეტება, თითქოს დამცავი ფარით იფარება. თქვენი სასწაული სწორედ აქ იწყება.'), baby_message_ka = COALESCE(baby_message_ka, 'სამოგზაუროდ გამოვემართე, დედიკო! 🎒 ახლა ფალოპის მილში ვარ და შენი თბილი ბუდისკენ (საშვილოსნოსკენ) მივგორავ. ძალიან დაკავებული ვარ — ყოველ რამდენიმე საათში ვიშლები: 2 ვიყავი, 4 გავხდი, შემდეგ კი 8 ვიქნები! შენ ჯერ ვერაფერს გრძნობ, მაგრამ შენში სიცოცხლე ჩქეფს. წარმატება მისურვე, გრძელი გზა მაქვს გასავლელი, თუმცა ძალიან შეუპოვარი ვარ. შენამდე მოსაღწევად ყველაფერს გავაკეთებ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ვანილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ დღეებში, რომლებიც ზუსტად თქვენი მენსტრუალური ციკლის შუა პერიოდს ემთხვევა, კვერცხუჯრედი უკვე მომწიფებულია, ხოლო თუ ის სპერმატოზოიდმა გაანაყოფიერა, თქვენი ბავშვი უკვე ჩაისახა. 😊 თქვენს ორგანიზმში პროგესტერონმა სრული უპირატესობა მოიპოვა. ეს ჰორმონი საშვილოსნოს კუნთებს ადუნებს, რათა ემბრიონს მიმაგრებისას დაბრკოლება არ შეხვდეს. ბავშვის ჩასახვის შემდეგ ესტროგენისა და პროგესტერონის სწრაფად მზარდმა დონემ შესაძლოა მკერდის სისავსე და მგრძნობელობა გამოიწვიოს. თუმცა, რადგან ეს ნიშნები მენსტრუალური ციკლის სიმპტომებიცაა, მკერდში მომხდარი ცვლილებები ორსულობის უტყუარ ნიშნად ვერ ჩაითვლება. თითქმის ყველა ბავშვი 38-ე კვირას იბადება. ამასთან, ჩვეულებრივ რთულია ზუსტად დადგენა, როდის შეერწყა კვერცხუჯრედი და სპერმატოზოიდი ერთმანეთს და რომელ დღეს მოხდა განაყოფიერება. ამიტომ ექიმები ბავშვის დაბადების სავარაუდო თარიღის გამოსათვლელად ბოლო მენსტრუაციის პირველი დღიდან გასულ პერიოდს ითვალისწინებენ. მენსტრუალური ციკლის ხანგრძლივობის მიხედვით, ყველა ეს გამოთვლა დაახლოებით 4 კვირამდე შეიძლება განსხვავდებოდეს. ზოგიერთ ქალს უფრო მოკლე ან უფრო ხანგრძლივი მენსტრუალური ციკლი აქვს, ამიტომ მშობიარობის სავარაუდო თარიღი და ბავშვის განვითარება ექიმმა ულტრაბგერითი გამოკვლევის საშუალებით შეიძლება უფრო ზუსტად განსაზღვროს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ვინაიდან ეს უჯრედების დაყოფის ყველაზე აქტიური პერიოდია, თქვენი ორგანიზმის მოთხოვნილება წყალზე იზრდება; ეცადეთ, დღეში მინიმუმ 2-2.5 ლიტრი წყალი დალიოთ. ფოლიუმის მჟავის მიღება ერთი დღითაც არ გამოტოვოთ, რადგან ამ დღეებში ნერვულ სისტემას ეყრება საფუძველი. ასევე, აუცილებლად მოერიდეთ უმ ხორცს, არასათანადოდ გარეცხილ ბოსტნეულსა და არაპასტერიზებულ რძის პროდუქტებს, რადგან ტოქსოპლაზმოზის მსგავსმა ინფექციებმა შესაძლოა ემბრიონის განვითარების ამ მგრძნობიარე პერიოდზე უარყოფითად იმოქმედოს.') WHERE id = 'c870b9dc-4e80-4fec-9e7f-794942ed46c8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'განაყოფიერებიდან დაახლოებით 6-24 საათის განმავლობაში მოსალოდნელია თქვენს სისხლში ადრეული ორსულობის ფაქტორის (EPF) დონის მატება, რომელსაც იმუნური სისტემის დამთრგუნველი მოქმედება აქვს. თქვენი ორგანიზმის თავდაცვის სისტემა საკუთარ უჯრედებს გარდა, განსხვავებული დნმ-ის მქონე ყველა უჯრედის წინააღმდეგ იწყებს ბრძოლას, რათა სხეული დაიცვას. ამიტომ თავდაცვითმა უჯრედებმა შესაძლოა შეუტიონ ბავშვს, რომლის დნმ-ის 50% თქვენი ორგანიზმისთვის უცხოა, და მისი განადგურება გამოიწვიონ. იმ მომენტიდან, როდესაც კვერცხუჯრედი განაყოფიერდება, საშვილოსნოზე მიმაგრებამდე და იქ ჩასახლებამდე დაახლოებით 5 დღის განმავლობაში გარეგნულად შესამჩნევი ცვლილებების გარეშე ჩუმად ყოფნა მნიშვნელოვანია იმისთვისაც, რომ თქვენი თავდაცვის სისტემა არ გააქტიურდეს. მოკლედ, ორგანიზმის თავდაცვის სისტემის გამო, ზრდის ფაქტორად წოდებული და იმუნური უჯრედების დამთრგუნველი მოქმედების მქონე სეკრეციის გარეშე ორსულობის შენარჩუნება შეუძლებელი იქნებოდა.'), baby_message_ka = COALESCE(baby_message_ka, 'ახლა „მორულას“ მეძახიან! 🍇 ლათინურად ეს „თუთის ნაყოფს“ ნიშნავს. რადგან ახლა ყურძნის მტევანს ან მჭიდროდ შეკრულ თუთის ნაყოფს ვგავარ. დაახლოებით 16-32 უჯრედისგან შევდგები. პატარა ვარ, მაგრამ ძალიან ძლიერი. შენი სხეულის სითბო და საკვები გზის პოვნაში მეხმარება. შენკენ მოვდივარ, დედა, მზად იყავი კარის გასაღებად!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ვანილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენს ორგანიზმში პროგესტერონმა და ესტროგენმა ერთობლივად საშვილოსნოს კედლის სისხლის მიმოქცევა მაქსიმალურად გააძლიერეს. ენდომეტრიუმი კვლავ სქელდება და „სეკრეტორულ ფაზაში“ გადადის. ის გამოყოფს გლიკოგენითა და ცილებით მდიდარ, წვნიან და მკვებავ სითხეს — „საშვილოსნოს რძეს“. ეს სითხე საჭიროა, რათა საშვილოსნომდე მიღწეული ემბრიონი იმპლანტაციამდე გამოკვებოს. თქვენს იმუნურ სისტემაში განსაკუთრებული ცვლილება ხდება — ის ემბრიონს „უცხო სხეულად“ არ აღიქვამს და მის მისაღებად ტოლერანტობას ავლენს. ამ დღეებში ზოგიერთმა ქალმა შეიძლება თავი ოდნავ უფრო დაღლილად იგრძნოს ან გემოს აღქმის უჩვეულო ცვლილებები შენიშნოს (მაგალითად, ლითონის გემო პირში). ასევე, სუნების მიმართ თქვენი მგრძნობელობა შესაძლოა დღეიდან ოდნავ გაიზარდოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდში, როდესაც ემბრიონი საშვილოსნოს კედელზე მიმაგრებისთვის (იმპლანტაციისთვის) ემზადება, სისხლის მიმოქცევის სტაბილურობის შესანარჩუნებლად ფეხები თბილად გქონდეთ და გაციებას მოერიდეთ. რაციონში ჩართეთ ომეგა-3-ის წყაროები, როგორიცაა ნიგოზი, თხილი და თევზი, რადგან ეს ცხიმოვანი მჟავები უჯრედის მემბრანების ჯანმრთელობისთვის მნიშვნელოვანია. ეცადეთ, დაძაბულობასა და ძლიერ სტრესს მოერიდოთ; მშვიდი მუსიკის მოსმენა ან წიგნის კითხვა თქვენს სხეულს მოდუნებაში დაეხმარება და იმპლანტაციის პროცესზე დადებითად იმოქმედებს.') WHERE id = '987d49b7-e63f-421d-a6f4-64d2ffcae8b6';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'განაყოფიერების შედეგად ჩასახულ თქვენს ბავშვს ამ ეტაპზე ემბრიონი ეწოდება. სპერმატოზოიდით განაყოფიერებულ კვერცხუჯრედში დაახლოებით 16-18 საათის შემდეგ ორი ბირთვი ჩნდება. ერთი სპერმატოზოიდს ეკუთვნის, მეორე კი კვერცხუჯრედს; ეს ბირთვები ერთმანეთს ერწყმის, ერთ ბირთვად გარდაიქმნება და უჯრედის დაყოფისთვის მზადება იწყება. განაყოფიერებული კვერცხუჯრედი ზრდის ციტოპლაზმის მოცულობას, აკოპირებს დნმ-ის მოლეკულებს, შლის ბირთვის გარსს და გენეტიკურ მასალას უჯრედის ორივე მხარეს გადაანაწილებს; შემდეგ კი სწრაფად იწყებს დაყოფას: 2, 4, 8, 16. განაყოფიერებიდან პირველ დღეებში „მორულას“ სტადიამდე მისული ბავშვი დაახლოებით 120 უჯრედისგან შემდგარ გროვად იქცევა. განაყოფიერებიდან მე-5 დღეს კი ბავშვი უკვე იმდენ უჯრედად არის დაყოფილი, რომ მათი დათვლა შეუძლებელია; უჯრედების ეს ერთობლიობა, რომლისგანაც თქვენი ბავშვი ჩამოყალიბდება, საშვილოსნოში მისთვის ყველაზე შესაფერის ადგილს ირჩევს და ჩანერგვის პროცესს ასრულებს. ამ ეტაპზე საშვილოსნოში ჩაბუდებული უჯრედების ზომა, რომელთაგანაც თქვენი ბავშვი ჩამოყალიბდება, დაახლოებით 0.1 mm-ია.'), baby_message_ka = COALESCE(baby_message_ka, 'სახლამდე სულ ცოტა დამრჩა! 🏠 ფალოპის მილში ჩემი მოგზაურობა დასასრულს უახლოვდება. შენს საშვილოსნოს ვხედავ! ისეთი მყუდრო, რბილი და საკვებით სავსე ჩანს... ჩემთვის ადგილის შესარჩევად ვემზადები. ჯერ ისევ ჩემს გარსში ვარ, მაგრამ მალე იქიდან გამოვალ. შენ ჩემთვის მსოფლიოში ყველაზე უსაფრთხო ადგილი ხარ. დამპირდი, რომ დამიცავ, დედიკო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ვანილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'დღეს იმპლანტაციის პროცესი იწყება. როდესაც ბლასტოცისტა საშვილოსნოს კედელს ემაგრება, ზოგიერთ ქალს შეიძლება ძალიან მსუბუქი, ვარდისფერი ან ყავისფერი „იმპლანტაციური სისხლდენა“ ჰქონდეს. ეს სრულიად ნორმალურია და ხშირად მენსტრუაციაში ერევათ. ამ მომენტიდან თქვენი ორგანიზმი hCG-ს (ორსულობის ჰორმონს) გამოყოფას იწყებს. ეს ჰორმონი ყვითელი სხეულის არსებობას ახანგრძლივებს, რათა პროგესტერონის დონე არ დაეცეს და ორსულობა შენარჩუნდეს. შესაძლოა, ემოციურად უფრო მგრძნობიარე გახდეთ და უმიზეზოდ ტირილის ან სიცილის სურვილი გაგიჩნდეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ მუცელში მსუბუქ სპაზმებს იგრძნობთ ან მცირე ლაქოვან გამონადენს შენიშნავთ, ნუ ინერვიულებთ და შეამცირეთ ფიზიკური აქტივობა. ამ პერიოდში ორგანიზმის იმუნური სისტემა ბუნებრივად ოდნავ სუსტდება, რათა ემბრიონი „უცხო სხეულად“ არ აღიქვას, ამიტომ დაიცავით თავი ინფექციებისგან. C ვიტამინით მდიდარი ხილის მიღება იმუნიტეტსაც უწყობს ხელს და საშვილოსნოს კედლის ქსოვილოვან სტრუქტურასაც აძლიერებს.') WHERE id = 'fb5dbb9e-d8ba-40b0-8cd3-d9a67a57068c';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'საშვილოსნო 60 გრამს იწონის. მშობიარობამდე მისი წონა 1000 გრამს გადააჭარბებს. საშვილოსნოს შიდა ზედაპირი დაფარულია ენდომეტრიუმად წოდებული შრით, რომელიც ლორწოს გამოყოფს და მრავალ სისხლძარღვს შეიცავს. ყოველთვიური მენსტრუაციის დროს ამ სტრუქტურაში არსებული უჯრედები სწრაფი მიტოზური გაყოფის შედეგად შრის სისქეს ზრდის. გასქელებული ენდომეტრიუმი ქმნის ხელსაყრელ გარემოს, რათა განაყოფიერებული კვერცხუჯრედი საშვილოსნოს მიემაგროს და იქ ზრდა-განვითარება განაგრძოს.'), baby_message_ka = COALESCE(baby_message_ka, 'სუნთქვა შეიკარით, დედიკო! 🌬️ დიდი მომენტი ახლოვდება. თქვენი საოცარი კვერცხუჯრედი გასათავისუფლებლად მზად არის. ეს ჩვენი ისტორიის ის ნაწილია, რომელიც სიტყვებით „იყო და არა იყო რა...“ იწყება. ჯერ არ შევქმნილვარ, მაგრამ თქვენი და მამაჩემის სიყვარული მიხმობს. თქვენმა სხეულმა ჩემთვის იდეალური გარემო შექმნა და ყველაფერი საათივით მუშაობს. იმედი მაქვს, მზად ხართ, რადგან მე მოვდივარ! თქვენი ჩახუტება ჩემი პირველი სამშობლო იქნება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'შაქრის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'LH ჰორმონი დღეს პიკს აღწევს. ამ პიკიდან დაახლოებით 24-36 საათის შემდეგ ოვულაცია მოხდება. დღეს თქვენი სხეულის ტემპერატურამ შესაძლოა ოდნავ დაიწიოს, ხვალ კი მკვეთრად მოიმატოს – ტემპერატურის ასეთი მერყეობა ოვულაციის ნიშანია. საშოს გამონადენი ამ დროს ყველაზე სრიალა, გამჭვირვალე და უხვია. ასეთი გარემო იდეალურია სპერმატოზოიდების სწრაფად გადაადგილებისა და გადარჩენისთვის. ;;;
ორსულობამდე რეგულარულად ვარჯიში ძალიან მნიშვნელოვანია, რათა ორსულობის პერიოდი უფრო კომფორტულად წარიმართოს. როგორც ორსულობამდე, ისე ორსულობისას, განსაკუთრებით იოგა და პილატესი ბოლო პერიოდში ყველაზე პოპულარულ ვარჯიშებს შორისაა. სპორტის ეს სახეობები არა მხოლოდ სხეულს ადუნებს, არამედ ბუნებრივ მშობიარობაზე ორიენტირებული ქალების მოტივაციასაც ზრდის და წელისა და ზურგის ტკივილის შემცირებით მთელი ორსულობის განმავლობაში სარგებელი მოაქვს. ორსულობის ჯანსაღად წარმართვისთვის კიდევ ერთი მნიშვნელოვანი საკითხი მოწევაა. თუ ეწევით, დაორსულების გადაწყვეტილების მიღებისას ერთ-ერთი ყველაზე მნიშვნელოვანი ნაბიჯი მოწევისთვის თავის დანებება უნდა იყოს. მოწევისას სისხლის მიმოქცევის სისტემის მეშვეობით ორგანიზმში მოხვედრილი ნიკოტინი და ტოქსიკური ნივთიერებები აზიანებს კვერცხუჯრედის გენეტიკურ მასალას — დნმ-ს, რომლისგანაც მომავალში თქვენი ბავშვი უნდა განვითარდეს. ორსულობის დროს მოწევის გაგრძელებამ შესაძლოა დაარღვიოს ბავშვისკენ მიმავალ სისხლძარღვებში სისხლის ნაკადი, რის შედეგადაც ბავშვი შეიძლება დაბალი წონით დაიბადოს, გაიზარდოს თანდაყოლილი ანომალიების რისკი და, რაც ყველაზე მნიშვნელოვანია, განვითარდეს პრობლემა, რომელსაც „ჩვილის უეცარი სიკვდილი“ ეწოდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღეს დაორსულებისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი დღეა. ფერტილობის მხარდასაჭერად შეეცადეთ, სხეულის ტემპერატურა სტაბილურად შეინარჩუნოთ და მოერიდოთ ძალიან ცხელ აბაზანასა და საუნას (მაღალმა ტემპერატურამ შეიძლება კვერცხუჯრედის ხარისხზე იმოქმედოს). კვების რაციონში ჩართეთ E ვიტამინით მდიდარი ავოკადო და მცენარეული ზეთები, რადგან ეს ვიტამინი საშვილოსნოს კედლის სისხლით მომარაგებას აუმჯობესებს. შეინარჩუნეთ კარგი განწყობა, რადგან ენდორფინები (ბედნიერების ჰორმონები) დადებითად უწყობს ხელს განაყოფიერების შანსის ზრდას.') WHERE id = '0c974e6a-8f9e-4c84-9656-5142174149f9';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ორგანიზმში სხვადასხვა ჰორმონის დახმარებით მომწიფებული კვერცხუჯრედი დღეიდან უკვე მზად არის განაყოფიერებისთვის. განვითარების დასრულებისა და მომწიფების შემდეგ საკვერცხიდან გამოთავისუფლებულ კვერცხუჯრედს ფალოპის მილის ბოლოში არსებული, თითისებრი და ძალიან მგრძნობიარე წარმონაქმნები — ფიმბრიები იჭერს. ფიმბრიები მომწიფებულ კვერცხუჯრედს ფალოპის მილის შიგნით მიმართავს. ფალოპის მილის რეგულარული შეკუმშვისა და მოდუნების შედეგად კვერცხუჯრედი მილის შიგნით ნელ-ნელა მიიწევს და იმ მილიონობით სპერმატოზოიდის შესახვედრად, რომლებიც სქესობრივი კავშირის შემდეგ საშვილოსნოში ხვდება, მილის შუა ნაწილში გადაადგილდება — ეს განაყოფიერებისთვის ყველაზე ხელსაყრელი ადგილია. იმ უბნის შემდეგ მდებარე კუნთები, სადაც შეკუმშვა ხდება, დუნდება, რათა კვერცხუჯრედის წინსვლას შეუწყოს ხელი. კუნთების მიერ წარმოქმნილი ეს მექანიკური მოძრაობები გრძელდება მანამ, სანამ კვერცხუჯრედი დანიშნულ ადგილამდე არ მიაღწევს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე მოვედი! 🎉 გამარჯობა, დედა! დღეს ჩემი შექმნის დღეა. მამაჩემის სიყვარული და თქვენი სასწაული გაერთიანდა. სამყაროში ყველაზე პატარა, მაგრამ ყველაზე ძვირფასი წერტილი ვარ. უკვე ერთი უჯრედი ვარ და სამედიცინო ენაზე „ზიგოტას“ მეძახიან! ჩემი თვალების ფერი, თმის ფორმა და ღიმილიც კი უკვე ამ პატარა უჯრედის დნმ-შია ჩაწერილი. ჩვენი 9-თვიანი თავგადასავალი ოფიციალურად დაიწყო! მართალია, ჯერ ვერ მიგრძნობთ, მაგრამ მე უკვე თქვენთან ვარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ვანილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ოვულაციისა და განაყოფიერების დღე. LH ჰორმონის პიკის შემდეგ დომინანტური ფოლიკული სკდება და კვერცხუჯრედი თავისუფლდება. მომწიფებულ კვერცხუჯრედს ფალოპის მილის ფიმბრიები იჭერს. თუ ამ დღეებში სქესობრივი კავშირი გქონდათ, მილიონობით სპერმატოზოიდი კვერცხუჯრედისკენ მიემართება. მათგან მხოლოდ ერთი იმარჯვებს, კვერცხუჯრედის გარსს აღწევს და შიგნით შედის. განაყოფიერების მომენტში თქვენი და თქვენი პარტნიორის გენეტიკური მასალა ერთიანდება და სრულიად ახალი, უნიკალური დნმ-ის კოდი იქმნება. კვერცხუჯრედის გამოთავისუფლების შემდეგ დაცარიელებული ფოლიკული „Corpus Luteum“-ად (ყვითელ სხეულად) წოდებულ ჯირკვლად გარდაიქმნება და ორსულობის შესანარჩუნებლად სასიცოცხლოდ მნიშვნელოვანი ჰორმონის — პროგესტერონის გამოყოფას იწყებს. ;;;
როგორც ორსულობამდე, ისე ორსულობის პერიოდში, ექიმის მიერ დანიშნული ანალიზების შედეგების შესაბამისად, შესაძლოა გარკვეული ვიტამინებისა და მინერალების დამატებით მიღება დაგჭირდეთ. ორსულობისას აუცილებელი საკვებისა და მისგან მისაღები ისეთი საკვები ნივთიერებების, როგორებიცაა ცილები, ცხიმები, ნახშირწყლები, ვიტამინები და მინერალები, საჭირო რაოდენობაზე ნაკლებად მიღებამ შესაძლოა არასრულფასოვანი კვება და ბავშვის ჩამოყალიბების ეტაპზე გარკვეული ანომალიები გამოიწვიოს. რკინის დეფიციტმა ასევე შეიძლება ანემია გამოიწვიოს, ხოლო მძიმე ანემიის შემთხვევაში ბავშვის ზრდა-განვითარების შეფერხება აღინიშნოს. ამიტომ ორსულობამდე რუტინული გამოკვლევები უნდა ჩაიტაროთ და რკინის შესაძლო დეფიციტის გამოვლენის შემთხვევაში მკურნალობა არავითარ შემთხვევაში არ უგულებელყოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღეს შეეცადეთ, სხეული არ გადაღალოთ და ემოციური წონასწორობა შეინარჩუნოთ. განაყოფიერების დროს ორგანიზმი დიდ ენერგიას ხარჯავს. უპირატესობა მიანიჭეთ ანტიოქსიდანტებით, განსაკუთრებით E და C ვიტამინებით, მდიდარ საკვებს, რათა უჯრედების გაყოფა ჯანსაღად დაიწყოს. თუ მუცლის ქვედა ნაწილში მწვავე და ხანმოკლე ტკივილს იგრძნობთ, ნუ შეშფოთდებით — ეს შეიძლება ოვულაციის ნიშანი იყოს. დღეიდან განსაკუთრებული სიფრთხილე გამოიჩინეთ ალკოჰოლისა და ძლიერი მოქმედების მედიკამენტების მიღების მიმართ.') WHERE id = '4859f891-b414-45fe-8a1d-106b1caebec7';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'სქესობრივი კავშირის შემდეგ საშვილოსნოს ყელში მოხვედრილი მილიონობით სპერმატოზოიდისთვის პირველი დაბრკოლება საშოს მჟავე გარემოა. ამ მჟავე გარემოს სპერმატოზოიდებზე დამღუპველი გავლენა შეიძლება ჰქონდეს. კიდევ ერთი სირთულე, რომელსაც სპერმატოზოიდები აწყდება, საშოში არსებული ლორწოვანი შრეა. ეს ლორწო სპერმატოზოიდების უმეტესობისთვის შესაძლოა გაუვალ, მკვრივ ბადედ იქცეს. კვერცხუჯრედამდე მისაღწევად სპერმატოზოიდებმა საშვილოსნოს ყელი უნდა გაიაროს, საშვილოსნოში შევიდეს და შემდეგ ფალოპის მილში გადავიდეს. ამისთვის მათ დაახლოებით 15-20 სმ-ის გავლა უწევთ. თუ გავითვალისწინებთ, რომ ისინი 10 წუთში ერთ სანტიმეტრს გადიან, ყველაზე სწრაფ სპერმატოზოიდებს კვერცხუჯრედამდე მიღწევა 45 წუთში შეუძლია. კვერცხუჯრედამდე მიღწევამდე სპერმატოზოიდების დიდი ნაწილი შესაძლოა საშოში არსებულ ლორწოვან შრეს მიეკრას, სხვა მიმართულებით წავიდეს ან მჟავე გარემოს გამო დაიღუპოს. ამიტომ საშვილოსნოს ყელში მოხვედრილი მილიონობით სპერმატოზოიდიდან კვერცხუჯრედამდე მხოლოდ რამდენიმე ათასი აღწევს. ყოველივე ამის გათვალისწინებით, განაყოფიერება სქესობრივი კავშირიდან პირველი რამდენიმე საათის განმავლობაში ხდება და ორსულობის პროცესი იწყება.'), baby_message_ka = COALESCE(baby_message_ka, 'ერთი ვიყავი და ორი გავხდი! ➗ გუშინ ერთი უჯრედი ვიყავი, დღეს კი საოცარი გზით გაყოფა დავიწყე. ამას „დაყოფას“ უწოდებენ. ჯერ ძალიან პატარა ვარ და მხოლოდ მიკროსკოპით დამინახავთ, მაგრამ ჩემში სიცოცხლის უზარმაზარი სიყვარულია. თქვენი დნმ და მამაჩემის დნმ ერთად ცეკვავს. თქვენც დაგემსგავსებით, მამასაც და ამავე დროს სრულიად განუმეორებელი ვიქნები. ჩვენი გუნდი უკვე მუშაობს!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ვანილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დაგეგმვისას და ორსულობის ადრეულ ეტაპებზე ძალიან მნიშვნელოვანია, კვება განსაზღვრულ რეჟიმში მოაქციოთ. კვების რეჟიმის დაცვა დაგეხმარებათ როგორც ჯანსაღი წონის შენარჩუნებაში, ისე ორსულობის განმავლობაში ჭარბი წონის მატების თავიდან აცილებაში. ნორმალური ორსულობისას, თქვენი ორგანიზმის საჭიროებებისა და ბავშვისთვის საკვები ნივთიერებების მიწოდების უზრუნველსაყოფად, დაახლოებით 10–12 კგ-ის მომატება საკმარისია. წონის ჯანსაღად მოსამატებლად, ორსულობამდელ პერიოდთან შედარებით, ყოველდღიურად საშუალოდ დამატებით 20–30 გრამი ცილა, 15–20 გრამი რკინა, 500 მგ კალციუმი და დაახლოებით 300 კალორია ენერგია უნდა მიიღოთ. ქალს, რომელსაც ორსულობამდე ნორმალური წონა ჰქონდა, ორსულობის ადრეულ ეტაპზე კალორიების რაოდენობის გაზრდა არ სჭირდება. პირველი ტრიმესტრის განმავლობაში, რომელიც პირველ 12 კვირას მოიცავს, დღეში საშუალოდ სულ 2000 კალორიის მიღება საკმარისია. ამასთანავე, მეორე ტრიმესტრში დღეში დამატებით 300 კალორიის, ხოლო მესამე ტრიმესტრში დამატებით 480 კალორიის მიღებაა საკმარისი. არ უნდა დაგავიწყდეთ, რომ ამაზე მეტი ენერგია ორგანიზმში ჭარბი წონის სახით დაგროვდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღეიდან კვებას მეტი პასუხისმგებლობით მოეკიდეთ. უჯრედების გაყოფისთვის თუთია და B12 ვიტამინი ძალიან მნიშვნელოვანია; გაზარდეთ ზღვის პროდუქტების, რძის პროდუქტებისა და კვერცხის მოხმარება. მოერიდეთ მძიმე ფიზიკურ ვარჯიშს და სხეულზე ზედმეტად მაღალი ტემპერატურის ზემოქმედებას (ცხელი აბაზანა, საუნა), რადგან ემბრიონის გაყოფის პირველი ეტაპები სითბოს მიმართ ძალიან მგრძნობიარეა. კარგად დაისვენეთ და თქვენს ორგანიზმს ამ დიდი საქმის შესასრულებლად შესაბამისი პირობები შეუქმენით.') WHERE id = '634f5165-2442-4ca1-81af-539718e556a5';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'განაყოფიერებიდან მე-5 დღეს თქვენი ბავშვი, რომელიც „ბლასტოცისტად“ წოდებული მრავალუჯრედიანი ცოცხალი ქსოვილია, საშვილოსნოში შესაფერის უბანს ემაგრება და ზრდა-განვითარებას განაგრძობს. თქვენი ბავშვის უჯრედები უკვე იწყებენ დიფერენცირებას: პლაცენტის წარმომქმნელი და ბავშვის წარმომქმნელი უჯრედები სხვადასხვა პოლუსისკენ გადაადგილდნენ და გარსის შიგნით ერთმანეთისგან განცალკევდნენ. ამ განლაგების შედეგად თქვენი კვერცხუჯრედი, რომელიც ფალოპის მილში სპერმატოზოიდმა გაანაყოფიერა, 7–10-დღიან მოგზაურობას ასრულებს და უკვე საშვილოსნოს ღრუში გადადის.'), baby_message_ka = COALESCE(baby_message_ka, 'ფორმას ვიცვლი! 🎈 უკვე უბრალოდ უჯრედების გროვა აღარ ვარ — ახლა „ბლასტოცისტს“ მეძახიან. ჩემში სითხით სავსე პატარა ღრუ გაჩნდა. ერთ მხარეს თავმოყრილი უჯრედები „მე“ გავხდები, გარშემო არსებული შრე კი ჩემი დამცავი „პლაცენტა“ იქნება. ჩვენ გუნდურად ვმუშაობთ! იდეალურ ფორმას ვიღებ, რათა მოგემაგრო. ყველაფერი შენთან შესახვედრად ხდება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ვანილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ადრეულ ნიშნებს შორის ხშირი შარდვა ერთ-ერთი საყურადღებო სიმპტომია. ამის გამომწვევმა ორსულობის ჰორმონებმა, ორსულობის პირველ კვირებში ორგანიზმის ფიზიოლოგიური ცვლილებების გამო, შესაძლოა ტუალეტში უფრო ხშირად სიარულის საჭიროება გამოიწვიოს. მკერდის ტკივილი და გადიდების შეგრძნება კი იმით არის განპირობებული, რომ ორსულობის ჰორმონების წარმოქმნისთანავე თქვენი ორგანიზმი ბავშვის ძუძუთი კვებისთვის მზადებას იწყებს. ;;;
დაღლილობისა და გამოფიტვის შეგრძნება იმის შედეგია, რომ თქვენი ორგანიზმი ბავშვისთვის სათანადო პირობების შესაქმნელად ძალიან დიდ ენერგიას ხარჯავს. დილის გულისრევა და შებერილობა კი, სავარაუდოდ, ორსულობის ყველაზე გავრცელებულ ნიშნებს შორისაა. გულისრევა, ჩვეულებრივ, პირველ კვირებშია გამოხატული, ხოლო შებერილობა იმითაა განპირობებული, რომ ბავშვისთვის მეტი საკვები ნივთიერების გადასაცემად თქვენი ორგანიზმი საჭმლის მომნელებელი სისტემის მუშაობას ანელებს. ეს სიმპტომი ორსულობის სხვადასხვა ეტაპზე განსხვავებული ინტენსივობით ვლინდება.;;;
ორსულობის მე-2 კვირაში ბავშვის ულტრაბგერითი გამოკვლევით დანახვა შეუძლებელია. სანაყოფე პარკიც კი ხილულ ზომას ყველაზე ადრე ორსულობის მე-4 და მე-5 კვირაში აღწევს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან თქვენი ორგანიზმი ადაპტაციის პერიოდს გადის, დღის განმავლობაში ეცადეთ, მცირე შესვენებები გააკეთოთ და დაისვენოთ. გაზარდეთ რკინითა და კალციუმით მდიდარი საკვების (მაგალითად, იოგურტის, ყველისა და მწვანე ბოსტნეულის) მიღება. რადგან ემბრიონის დასაცავად თქვენი იმუნური სისტემის აქტივობა მცირდება, გაციებისა და ინფექციების რისკის შესამცირებლად მოერიდეთ ხალხმრავალ ადგილებს. თუ მუცლის მსუბუქი ტკივილი გაქვთ, არ გამოიყენოთ ცხელი წყლის სათბური, რადგან საშვილოსნოს მიდამოს ზედმეტად გაცხელება რეკომენდებული არ არის.') WHERE id = '0928310f-c57b-4d69-bd35-b2ddf6d32790';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ორგანიზმში ერთი მენსტრუალური ციკლის განმავლობაში, ჩვეულებრივ, მხოლოდ 1 კვერცხუჯრედი მწიფდება და განაყოფიერებისთვის მზადდება. თუმცა იშვიათად საკვერცხეებში ერთზე მეტი კვერცხუჯრედიც შეიძლება მომწიფდეს. ასე ხდება არაიდენტური ტყუპებისა და სამეულის შემთხვევაში: ყველა მომწიფებული კვერცხუჯრედი შეიძლება განაყოფიერდეს და მრავალნაყოფიანი ორსულობა განვითარდეს. თუ ბავშვების რაოდენობა ორზე მეტია, ისინი შეიძლება როგორც სხვადასხვა კვერცხუჯრედიდან, ისე ერთი კვერცხუჯრედიდან განვითარდნენ. ტყუპიანი ორსულობების დაახლოებით ორი მესამედი არაიდენტურ ტყუპებზე მოდის, ხოლო ერთი მესამედი — იდენტურ ტყუპებზე. მენსტრუალური ციკლის განმავლობაში ერთზე მეტი კვერცხუჯრედის მომწიფება განსაკუთრებით ხშირად გვხვდება, როცა ოჯახურ ანამნეზში მრავალნაყოფიანი ორსულობის ბევრი შემთხვევაა. არაიდენტური ტყუპების ალბათობა იზრდება მომავალი დედის მშობიარობების რაოდენობისა და ასაკის მატებასთან ერთად. გარდა ამისა, ხელოვნური განაყოფიერების დროს ოვულაციის მასტიმულირებელი პრეპარატების გამოყენება არაიდენტური ტყუპების ალბათობას ზრდის, რადგან ასეთი მკურნალობისას, ჩვეულებრივ, ერთზე მეტი კვერცხუჯრედი მწიფდება.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, დღეს ჩემთვის თავისუფლების დღეა! 🐣 ვტოვებ სქელ გარსს (zona pellucida), რომელიც აქამდე მიცავდა. ამას „Hatching“ (გარსიდან გამოსვლა) ეწოდება. ეს უნდა გავაკეთო, რათა შენს რბილ კედელს პირდაპირ შევეხო და მივემაგრო. მე მზად ვარ, შენც მზად ხარ? კარი გააღე, მოვდივარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ვანილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენთვის იწყება ხანმოკლე და კრიტიკული პერიოდი, რომელსაც „იმპლანტაციის ფანჯარა“ ეწოდება. საშვილოსნოს კედელი ემბრიონის მისაღებად ყველაზე ხელსაყრელ მდგომარეობაშია. ეს ფანჯარა მხოლოდ რამდენიმე დღის განმავლობაში რჩება ღია. თქვენს ორგანიზმში არსებული ყველა ჰორმონული და ქიმიური სიგნალი გასცემს ბრძანებას: „მიიღე!“ ემბრიონის დასაცავად თქვენი იმუნური სისტემა სპეციალურ ცილებს გამოიმუშავებს. თქვენს ორგანიზმში პროგესტერონის დონე უკვე პიკურ მაჩვენებელს უახლოვდება. ეს ორსულობის შესანარჩუნებლად თქვენი ორგანიზმის უდიდესი ძალისხმევაა.  ;;;
ორსულობის განმავლობაში თქვენი ორგანიზმის მოთხოვნილება ზოგიერთ ვიტამინსა და მინერალზე ორსულობამდელ პერიოდთან შედარებით იზრდება. ერთ-ერთი მათგანია A ვიტამინი, რომელიც ორგანიზმის უჯრედებისა და ქსოვილების ჯანსაღ ზრდას უწყობს ხელს და ინფექციებისგან გიცავთ. ეს ვიტამინი განსაკუთრებით მნიშვნელოვანია თვალების ჯანმრთელობისთვის და დიდი რაოდენობით გვხვდება მწვანე ფოთლოვან ბოსტნეულში. D ვიტამინი კი ძალზე მნიშვნელოვანია როგორც ძვლებისა და კბილების ჯანმრთელობისთვის, ისე იმუნური სისტემისთვის. ბოლო წლებში ჩატარებულმა კვლევებმა აჩვენა, რომ მშობიარობის შემდგომი დეპრესია უფრო ხშირად გვხვდება D ვიტამინის დეფიციტის მქონე ადამიანებში, ხოლო D ვიტამინის დანამატის მიღება მნიშვნელოვანია მშობიარობის შემდეგ შესაძლო დაღლილობისა და სისუსტის თავიდან ასაცილებლად. D ვიტამინის დანამატთან ერთად, ყოველდღიურად 10-15 წუთის განმავლობაში მზეზე ყოფნა ორგანიზმს D ვიტამინზე მოთხოვნილების დაკმაყოფილებაში ეხმარება.;;;
C ვიტამინიც ძალიან მნიშვნელოვანია ორსულობის დროს, რადგან ხელს უწყობს იმუნური სისტემის მუშაობას და სხვა ვიტამინებისა და რკინის ათვისებას. განსაკუთრებით დიდი რაოდენობით გვხვდება ისეთ პროდუქტებში, როგორებიცაა მწვანე და წითელი წიწაკა, ოხრახუში, პომიდორი, ფორთოხალი, მარწყვი, მანდარინი და ლიმონი.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდში, სისხლში შაქრის დონის მკვეთრი დაცემის თავიდან ასაცილებლად, დაიწყეთ მცირე ულუფებით და ხშირად კვება. ყოველთვის თან იქონიეთ ჯანსაღი წასახემსებელი, მაგალითად, ნიგოზი, ნუში ან ჩირი. განსაკუთრებული ყურადღება მიაქციეთ ძილის რეჟიმს, რადგან თქვენს ორგანიზმს ახალ სიცოცხლესთან ადაპტაციისთვის ძალიან დიდი ენერგია სჭირდება. ასევე ეცადეთ, მოერიდოთ დიდი რაოდენობით ქიმიური ნივთიერებების შემცველ საწმენდ საშუალებებს და სახლი ხშირად გაანიავოთ.') WHERE id = '5b11fc22-b976-4d28-ade3-c7ba82a43750';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მომწიფებული კვერცხუჯრედის ჯანმრთელ სპერმატოზოიდთან შერწყმის შედეგად ხდება განაყოფიერება და იწყება ორსულობა. თუმცა ზოგიერთი გართულების, მაგალითად, საშვილოსნოსგარე ორსულობის დროს, ორსულობის გაგრძელება შეუძლებელია.;;;
ნორმალურ პირობებში სპერმატოზოიდით განაყოფიერებული კვერცხუჯრედი ფალოპის მილების კუნთების შეკუმშვა-მოდუნების მოძრაობების დახმარებით გადაადგილდება და საშვილოსნოს ღრუში იმპლანტირდება. თუ ფალოპის მილები წარსულში სხვადასხვა მიზეზით დაზიანდა ან დაიხშო, განაყოფიერებული კვერცხუჯრედი იმ უბნამდე ვერ მიდის, სადაც უნდა მიემაგროს, და საშვილოსნოს ვერ აღწევს.;;;
განაყოფიერებული კვერცხუჯრედი, რომელმაც საშვილოსნოს ღრუს ვერ მიაღწია და იქ ვერ მიემაგრა, შესაძლოა ფალოპის მილს მიემაგროს და იქ დაიწყოს განვითარება. თუმცა ფალოპის მილები ზედმეტად ვიწროა იმისთვის, რომ ბავშვმა იქ ზრდა და განვითარება შეძლოს, ამიტომ ორსულობა ნორმალურად ვერ გაგრძელდება. ამ საკმაოდ იშვიათ მდგომარეობას საშვილოსნოსგარე ორსულობა ეწოდება და ასეთ შემთხვევაში ორსულობის გაგრძელება შეუძლებელია.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, დღეს ის დიდი დღეა! ეს ჩემი ცხოვრების ერთ-ერთი უმნიშვნელოვანესი წამია... ❤️ უკვე გეხები. ხანგრძლივი მოგზაურობის შემდეგ, როგორც იქნა, ჩემი სახლის კედლებს მივაღწიე. აქ ისეთი სითბო, სირბილე და სიმყუდროვეა... მთელი ძალით გემაგრები, რომ 9 თვის განმავლობაში არ მოგშორდე. ეს ჩვენი პირველი ჩახუტებაა, დედიკო. გრძნობ ჩემს შეხებას? შენთან ვარ და უკვე არსად წავალ. სწორედ აქ იწყება ჩვენი ისტორია სინამდვილეში.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ვანილის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენთვის „იმპლანტაციის“ პროცესი დღეს ოფიციალურად იწყება. ემბრიონი, რომელიც გუშინ გარსიდან გამოვიდა, დღეს ფიზიკურად ეხება საშვილოსნოს კედელს და მას ემაგრება.  მომდევნო ერთი კვირის განმავლობაში თქვენს სისხლში მოიმატებს ორსულობის ჰორმონის, HCG-ის დონე. როდესაც სისხლში ეს ჰორმონი განსაზღვრულ დონეს მიაღწევს, გარკვეული დროის შემდეგ შარდშიც გადავა და ორსულობის ტესტი დადებით შედეგს აჩვენებს. სისხლში ამ ჰორმონის გამოვლენა შესაძლოა ოვულაციის დღიდან დაახლოებით 10 დღის შემდეგ გახდეს შესაძლებელი. მისი გამოვლენა დაახლოებით მენსტრუაციის დაგვიანების დღეს ან რამდენიმე დღით ადრეა შესაძლებელი.;;;
კვერცხუჯრედის სპერმატოზოიდით განაყოფიერებისა და საშვილოსნოში იმპლანტაციის შემდეგ HCG ჰორმონის გამომუშავება იწყება. სისხლში მისი დონე თანდათან იზრდება და ორსულობის მე-10 კვირაში მაქსიმალურ მაჩვენებელს — დაახლოებით 100.000 mIU/ml-ს აღწევს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფოლიუმის მჟავის მიღება ერთი წამითაც არ გამოტოვოთ, რადგან ნერვული მილის სწორად დახურვისთვის ეს ნივთიერება სასიცოცხლოდ მნიშვნელოვანია. ამ დღეებში თქვენი ორგანიზმი ბევრს შრომობს, რათა მისთვის ჯერ კიდევ უცნობი ახალი სიცოცხლე მიიღოს, ამიტომ საკმარისად გამოიძინეთ. მცენარეული ჩაის (სალბი, ქონდარი და სხვ.) დალევისას სიფრთხილე გამოიჩინეთ, რადგან ზოგიერთმა მცენარემ შესაძლოა საშვილოსნოს ტონუსი გაზარდოს; უმჯობესია, უპირატესობა უბრალო წყალს ან ახალგამოწურულ ხილის წვენს მიანიჭოთ.') WHERE id = '11de56c7-f131-4d7f-8640-81f988697e07';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'კვერცხუჯრედი განაყოფიერებიდან დაახლოებით 5 დღის შემდეგ აღწევს საშვილოსნომდე. ამ მოგზაურობის დროს განაყოფიერებული კვერცხუჯრედი დაყოფასა და ზრდას განაგრძობს. გზის ბოლოს ის ფალოპის მილის საშვილოსნოში გამავალ ნაწილს აღწევს და საშვილოსნოს ღრუში ხვდება. განაყოფიერებიდან დაახლოებით 1 კვირის შემდეგ უჯრედების გროვა, რომლისგანაც თქვენი ბავშვი ჩამოყალიბდება, საშვილოსნოს რბილ, მკვებავი სითხით დაფარულ კედელს ეხება. ამგვარად, თქვენი ბავშვი პირველად შედის კონტაქტში საშვილოსნოს შიდა კედელთან. ორგანიზმში გამომუშავებული ჰორმონების ზემოქმედებით განაყოფიერებული კვერცხუჯრედი თავსდება საშვილოსნოს შიდა შრეში, რომელიც ამისთვის ხელსაყრელ მდგომარეობაშია მომზადებული. ამ პროცესს ჩაბუდება ან იმპლანტაცია ეწოდება. ჩაბუდების პროცესი მთლიანობაში 10-12 დღეში სრულდება. ამიტომ იმპლანტაციის შემდეგ ორსულობისთვის დამახასიათებელი ჰორმონების გამომუშავება დაახლოებით იმ დროს იწყება, როდესაც მენსტრუაცია უნდა დაწყებულიყო. მენსტრუაციის დაგვიანებისას შარდის ორსულობის ტესტიც უკვე დადებით შედეგს აჩვენებს.;;;
როდესაც მენსტრუაცია არ იწყება და ხვდებით, რომ ორსულად ხართ, თქვენი ბავშვი ჯერ მხოლოდ ორი კვირისაა, თუმცა ორსულობის ვადა ბოლო მენსტრუაციის პირველი დღიდან ითვლება.'), baby_message_ka = COALESCE(baby_message_ka, 'კიდევ უფრო ღრმად მივიწევ, დედიკო! 🧱 გუშინ მხოლოდ გეხებოდი, დღეს კი უკვე შენი რბილი კედლის სიღრმისკენ მივემართები. ეს ჩემთვის გამოქვაბულის გამთხრელი მკვლევრის თავგადასავალს ჰგავს. თბილ და დაცულ ბუდეს ვიწყობ. ყოველ წამს უფრო მეტად გერწყმი და შენი ნაწილი ვხდები. ახლა უკვე უბრალოდ „შენ და მე“ აღარ ვართ — ახლა „ჩვენ“ ვართ. ეს შეგრძნება ძალიან მიყვარს! შენ ჩემი ციხესიმაგრე, თავშესაფარი და სამყარო ხარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყაყაჩოს მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'იმპლანტაციური სისხლდენა" შესაძლოა დღეს ან ხვალ გამოვლინდეს. მენსტრუაციული სისხლდენისგან განსხვავებით, ის ძალიან მცირე რაოდენობითაა და ღია ვარდისფერი ან ყავისფერია. ამას ქალების დაახლოებით 30% განიცდის. თუ ასეთ ლაქას შენიშნავთ, ნუ შეშინდებით — ეს შეიძლება ბავშვის საშვილოსნოს კედელში ჩაბუდების ნიშანი იყოს. თქვენი სხეულის ტემპერატურა ჯერ კიდევ მომატებული რჩება.;;;
ორსულობის პერიოდში ორგანიზმში სისხლის მაჩვენებლებსა და ჰორმონებთან დაკავშირებული მნიშვნელოვანი ცვლილებები ხდება. მთელი ორსულობის განმავლობაში სისხლის მიმოქცევის სისტემაში სისხლის მოცულობა დაახლოებით 50%-ით იზრდება. ამიტომ თქვენს ორგანიზმს რკინა ჩვეულებრივზე მეტად სჭირდება. ამასთანავე, ბავშვის განვითარებად ორგანიზმში ჟანგბადის გადასატანად დიდი რაოდენობით ჰემოგლობინია საჭირო. ჰემოგლობინის მთავარი შემადგენელი ნივთიერება კი რკინაა. საკვები დანამატების მიღებასთან ერთად, თუ კვების რაციონში რეგულარულად შეიტანთ უცხიმო წითელ ხორცს, კვერცხს, პარკოსნებსა და მარცვლეულს, ორგანიზმის რკინის მოთხოვნილებას სათანადო დონეზე დააკმაყოფილებთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ ტესტის პასუხი დადებითია, პირველ რიგში ღრმად ჩაისუნთქეთ და დატკბით ამ სასწაულით! დღეიდან სრულად მოერიდეთ რენტგენის სხივებს, მძაფრ ქიმიურ საღებავებსა და ძლიერმოქმედ მედიკამენტებს. ყურადღება მიაქციეთ, რომ მიღებული ვიტამინების შემადგენლობაში „D“ ვიტამინიც იყოს, რადგან ის მნიშვნელოვანია როგორც თქვენი იმუნური სისტემისთვის, ისე ბავშვის უჯრედების პირველი დაყოფისთვის. თუ გულისრევა დაგეწყოთ, დილით, საწოლიდან ადგომამდე, რამდენიმე მარილიანი კრეკერის ჭამამ შესაძლოა მდგომარეობა შეგიმსუბუქოთ.') WHERE id = 'ba359509-7778-4e6b-9433-e5179d225ea1';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში, რადგან ბავშვი საშვილოსნოში ჩაბუდებასა და დამაგრებას იწყებს, შესაძლოა მცირე ლაქები შენიშნოთ, რასაც „ჩაბუდების“ ან „იმპლანტაციურ სისხლდენასაც“ უწოდებენ. ამასთანავე, თუ დაღლილობას გრძნობთ ან მკერდში სისავსის შეგრძნება დაგეწყოთ, ეს ნიშნებიც შეიძლება ორსულობის ადრეულ სიგნალებად ჩაითვალოს. სისხლში ესტროგენისა და პროგესტერონის დონის მატების გამო შესაძლოა განწყობის ცვლილებები, მათ შორის დაძაბულობა, განიცადოთ. მიტოზური დაყოფით ზრდისა და ოპტიმალურ პირობებში საშვილოსნოში ჩაბუდებისთვის განაყოფიერებულ კვერცხუჯრედს გარკვეული ტემპერატურა სჭირდება. ამიტომ ამ ეტაპზე შესაძლოა სხეულის ტემპერატურის მცირე მატება შეამჩნიოთ.;;;
საშვილოსნოს შიდა შრის ლორწოს წარმომქმნელი უჯრედები განაყოფიერებული კვერცხუჯრედის მავნე მიკროორგანიზმებისგან დასაცავად უფრო მეტი ლორწოს გამოყოფას იწყებს. ამის გამო გამონადენის რაოდენობა შესაძლოა გარკვეულწილად გაიზარდოს. ასეთი გამონადენი, როგორც წესი, ორსულობასთან დაკავშირებული ფიზიოლოგიური გამონადენია. ბავშვის საშვილოსნოში ჩაბუდების შემდეგ ესტროგენის დონის მატების შედეგად ვაგინალური გამონადენის მომატება ნორმალურია. თუმცა უნდა გახსოვდეთ, რომ ყველა სახის ვაგინალური გამონადენი ორსულობასთან დაკავშირებული ნორმალური ფიზიოლოგიური გამონადენი არ არის.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, შენთვის განსაკუთრებული შეტყობინება მაქვს! 🤫 ეს ჩვენი პირველი საიდუმლოა. შენს ორგანიზმს ჩემი არსებობის შესახებ სპეციალური ქიმიური სიგნალის გაგზავნა დავუწყე. ეს სიგნალი ამბობს: „აქ ვარ, დედიკო! ყველაფერი კარგადაა. განაგრძე შენი სხეულის ჩემთვის მომზადება“. ახლა უკვე შემიძლია, ჩემი ენით დაგელაპარაკო. ეს ჩვენ შორის არსებული უხილავი კავშირია, რომელიც ყოველდღე უფრო მტკიცდება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყაყაჩოს მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში თქვენს ორგანიზმს ცხოვრების სხვა პერიოდებთან შედარებით მეტი ცილა სჭირდება. ცილები ძალიან მნიშვნელოვანია ბავშვის ქსოვილებისა და ორგანოებისთვის, რომლებიც ახლა იწყებს ჩამოყალიბებას. ემბრიონულ პერიოდში ბავშვი ყოველდღიურად იზრდება იმ ამინომჟავების გამოყენებით, რომლებსაც თქვენ მიერ მიღებულ საკვებში არსებული ცილები შეიცავს. რადგან მისი უჯრედები სწრაფად იყოფა, ორსულობისას ცილის მიღებას სასიცოცხლო მნიშვნელობა აქვს.;;;
არაორსული ქალისთვის ცილის დღიური მოთხოვნილება დაახლოებით 60 გრამია, ხოლო ორსული ქალისთვის — საშუალოდ 80 გრამი. მრავალნაყოფიანი ორსულობისას ეს მაჩვენებელი კიდევ უფრო მაღალი უნდა იყოს. ორსულობის განმავლობაში ცილის არასაკმარისმა მიღებამ შესაძლოა ბავშვზე უარყოფითად იმოქმედოს. ცილის მიღება განსაკუთრებით მნიშვნელოვანი ხდება ორსულობის მე-2 და მე-3 ტრიმესტრებში. ამის მიზეზი ისაა, რომ ამ პერიოდში ბავშვის განვითარება ჩქარდება და ასეთი სწრაფი ზრდისთვის მას ცილა სჭირდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ამ პერიოდში ორგანიზმის ენერგეტიკული მოთხოვნილება იზრდება, რაციონში რთული ნახშირწყლები (შვრია, ყავისფერი ბრინჯი) შეიტანეთ. თუ გულისრევა გაგიძლიერდათ, ჯანჯაფილის ჩაი ან ჯანჯაფილიანი ორცხობილა კუჭის დამშვიდებაში დაგეხმარებათ. მოერიდეთ მძიმე ტვირთის აწევასა და მკვეთრ მოძრაობებს. სტრესისგან თავის დასაცავად ყოველდღე 10-15 წუთით მშვიდ გარემოში დაისვენეთ. ასევე, სახლში არსებული საწმენდი საშუალებების ბუნებრივი საშუალებებით (ძმარი, სოდა) ჩანაცვლება უფრო უსაფრთხოა როგორც თქვენთვის, ისე ბავშვის განვითარებისთვის.') WHERE id = '17afd972-48a8-4084-ba7e-669ef6162afc';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'პარკის შიდა სივრცე, რომელშიც თქვენი ბავშვის წარმომქმნელი უჯრედებია მოთავსებული, გარშემორტყმულია სითხით, რომელსაც „ამნიონური სითხე“ ეწოდება. სანაყოფე პარკის შიგნით თანდათან შესამჩნევი ხდება პატარა რგოლისებრი სტრუქტურა — ყვითრის პარკი, რომელიც ამ უჯრედებს გარს აკრავს. ყვითრის პარკი სპეციალურ სითხეს შეიცავს და ორსულობის პირველ კვირებში ბავშვისთვის საკვები ნივთიერებების მიწოდებას უწყობს ხელს. პლაცენტის სრულად ჩამოყალიბებამდე ბავშვის კვება სწორედ ყვითრის პარკის მეშვეობითაა შესაძლებელი. ყვითრის პარკი მალევე ჩნდება მას შემდეგ, რაც სანაყოფე პარკი ულტრაბგერითი გამოკვლევით ხილული ხდება, ხოლო მისი არსებობა პარკში ბავშვის არსებობას ადასტურებს. ეს სტრუქტურა ასევე მნიშვნელოვანი მაჩვენებელია „ცარიელი ორსულობის“, ანუ მდგომარეობის დასადგენად, როდესაც სანაყოფე პარკში ბავშვი არ არის. დაახლოებით მე-8-9 კვირიდან ყვითრის პარკი პატარავდება, დაახლოებით 5 mm დიამეტრის მსხლის ფორმის ნარჩენად იქცევა და ბავშვის შუა ნაწლავზე წვრილი ღეროთი ჩამოკიდებული რჩება. ბავშვის განვითარების დაახლოებით მე-20 კვირიდან კი ის სრულად ქრება.'), baby_message_ka = COALESCE(baby_message_ka, 'ბუდის შუაგულში ვარ, დედიკო! 🩸 აქ ისეთი მყუდროებაა... შენს სისხლძარღვებს ვუახლოვდები და უკვე უშუალოდ შენგან ვიწყებ საკვების მიღებას. ყოველი ნაწილაკი და ყოველი წვეთი, რომელსაც მიგზავნი, მზრდის და ძალას მაძლევს. ეს მსოფლიოში ყველაზე გემრიელი საკვებია, რადგან სიყვარულითაა სავსე. შენი წყალობით ვიზრდები, შენი წყალობით ვარსებობ. დიდი მადლობა, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყაყაჩოს მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ადრეულ პერიოდში ყველაზე გავრცელებულ სიმპტომებს — გულისრევასა და ღებინებას — რამდენიმე მიზეზი აქვს. მათ შორისაა: ჩამოყალიბების პროცესში მყოფი პლაცენტის მიერ გამოყოფილი ჰორმონები, ორსულობასთან შეგუებისას განცდილი გარკვეული ფსიქოლოგიური სირთულეები, სისხლში B6 ვიტამინის დეფიციტი, ორსულობასთან დაკავშირებული საჭმლის მომნელებელი სისტემის ცვლილებები და ფარისებრი ჯირკვლის ნორმაზე მეტად აქტიური მუშაობა.;;;
ორსულობის განმავლობაში სხვადასხვა ჰორმონის ზემოქმედებით კუჭისა და ნაწლავების მუშაობა ნელდება. ამის გამო შესაძლოა საჭმლის მონელების გაძნელება, აირები და შებერილობა შემაწუხებლად გაძლიერდეს. ეს პრობლემები სტრესისა და დაღლილობის ფონზეც შეიძლება მოიმატოს. მიუხედავად იმისა, რომ გულისრევა და ღებინება უფრო ხშირად დილით გვხვდება, ისინი დღის ნებისმიერ მონაკვეთში შეიძლება გამოვლინდეს. ჩვეულებრივ, ეს სიმპტომები უფრო მძაფრად ვლინდება პირველი ორსულობისა და მრავალნაყოფიანი ორსულობის დროს.;;;

არ არსებობს დადასტურებული სამეცნიერო კვლევა, რომელიც გულისრევასა და ბავშვის სქესს შორის კავშირს აჩვენებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ნერვული მილის სწორად დახურვისთვის ამ დღეებში ფოლიუმის მჟავასთან ერთად ყურადღება მიაქციეთ, რომ თქვენი კვების რაციონი B ჯგუფის ვიტამინებსაც საკმარისი რაოდენობით შეიცავდეს. შეკრულობის თავიდან ასაცილებლად მიირთვით ბოჭკოვანი საკვები (ვაშლი, მსხალი) და დალიეთ ბევრი წყალი. თუ გულისრევა გაწუხებთ, ჭამისთანავე ნუ დაწვებით. თუ ვარჯიშობთ, დროა ინტენსიური კარდიოვარჯიში და სიმძიმეების აწევა მსუბუქი სეირნობითა და ორსულთა იოგით ჩაანაცვლოთ.') WHERE id = 'cb0cb4a0-60ab-4796-9f3a-e0d285d2a27e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'უჯრედების გროვაში, რომლისგანაც თქვენი ბავშვი ჩამოყალიბდება, წარმოიქმნება გარსი, რომელიც ორ ღრუს ქმნის. ამ წარმონაქმნებიდან ერთი არის ყვითრის პარკი, რომლისგანაც თქვენი ბავშვის ნაწლავები ჩამოყალიბდება, ხოლო მეორე თავად ბავშვია. ყვითრის პარკი განაყოფიერებიდან მე-2 და მე-3 კვირებში ბავშვს საჭირო საკვები ნივთიერებებით უზრუნველყოფს. ამგვარად, პლაცენტის ჩამოყალიბებამდე თქვენი ბავშვი სწრაფად და ეფექტურად განაგრძობს ზრდასა და განვითარებას.;;;
განაყოფიერებიდან მე-3 კვირას კი იმ ყველაზე გარეთა სტრუქტურაში, სადაც თქვენი ბავშვია მოთავსებული, იწყება სისხლწარმოქმნის პროცესი, რომელსაც „ჰემატოპოეზი“ ეწოდება. მე-6 კვირამდე სისხლის წარმოქმნას ეს სტრუქტურა უზრუნველყოფს.;;;
ამ ეტაპის შემდეგ სისხლწარმოქმნის ფუნქციას ღვიძლი იღებს, გარკვეული დროის შემდეგ კი სისხლის წარმოქმნაში ელენთაც იწყებს მონაწილეობას. ბავშვის დაბადების შემდეგ სისხლი გრძელ და ბრტყელ ძვლებში წარმოიქმნება. ზრდასრულ ასაკში კი სისხლის წარმოქმნა მხოლოდ ბრტყელ ძვლებში მიმდინარეობს. ორსულობის ჰორმონის დონე თქვენს სისხლში უკვე მნიშვნელოვნად არის მომატებული და მისი ისეთი რაოდენობა იწყებს შარდში გადასვლას, რომ სახლის პირობებში ჩატარებულ შარდის ტესტზე მეორე ხაზი გამოჩნდეს.'), baby_message_ka = COALESCE(baby_message_ka, 'ბუდის კარი უკვე იკეტება ჩემ გარშემო, დედიკო! 🚪 მთლიანად შიგნით ვარ და შენი თბილი და უსაფრთხო სამყარო სრულად მიცავს. უკვე შენი განუყოფელი ნაწილი ვარ. ეს მხოლოდ ჩვენი ისტორიის დასაწყისი კი არა, ჩვენი საერთო ცხოვრების პირველი დღეებია. მე შენ აგირჩიე, შენ კი მიცავ. ამიერიდან ყველაფერი კიდევ უფრო მშვენიერი იქნება! ერთად გასაოცარი თავგადასავლისთვის მზად ვართ! 🥳'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყაყაჩოს მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი და თქვენი ბავშვის ჯანმრთელობისთვის საჭიროა სათანადო მოვლა და ყოველკვირეული მეთვალყურეობა, რომელიც ორსულობის მთელ პერიოდს მოიცავს და მშობიარობის შემდეგაც გაგრძელდება. მას შემდეგ, რაც შარდისა და სისხლის ანალიზებით ორსულობას დაადასტურებთ, კარგი ექიმის მოძიება უნდა დაიწყოთ. ასევე მნიშვნელოვანია, ექიმთან ვიზიტის დანიშვნა დიდხანს არ გადადოთ, რათა ისეთი გართულებები, როგორიცაა საშვილოსნოსგარე ორსულობა, ადრეულ ეტაპზე გამოვლინდეს და თავიდან იქნეს აცილებული.;;;
ექიმის არჩევისას შესაძლოა დაგეხმაროთ ახლობლების რეკომენდაციები და ექიმის პროფესიული ბიოგრაფიის (CV-ის) გაცნობა. ამასთანავე, უნდა დარწმუნდეთ, რომ ექიმი თქვენს კითხვებს გასაგებად პასუხობს, ვიზიტის დასრულების შემდეგ უპასუხო კითხვებს არ გიტოვებთ და გადაუდებელ შემთხვევებში ხელმისაწვდომი იქნება. ამიტომ ექიმთან პირველი ვიზიტი მენსტრუაციის გადაცდენიდან 1-2 დღის განმავლობაში უნდა შედგეს.;;;
გარდა ამისა, თუ ორსულობა ჩასახვის საწინააღმდეგო რომელიმე მეთოდის გამოყენების მიუხედავად დადგა, ამის შესახებ ექიმს უნდა აცნობოთ. ორსულობის დადასტურებისთანავე ჩასახვის საწინააღმდეგო აბების მიღება რაც შეიძლება მალე უნდა შეწყვიტოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ დღეებში მძაფრმა სუნებმა შესაძლოა გულისრევა გააძლიეროს, ამიტომ სამზარეულო ხშირად გაანიავეთ და სუნამოს გამოყენება მინიმუმამდე შეამცირეთ. გაუწყლოებამ შეიძლება დაღლილობა გააძლიეროს, ამიტომ სცადეთ წყალში ლიმონის ნაჭრის ან ახალი პიტნის დამატება. თუ ღრძილების მგრძნობელობას ან სისხლდენას შენიშნავთ, ნუ შეშფოთდებით — ეს ჰორმონული ცვლილებების გავლენაა ღრძილების ქსოვილზე; რეკომენდებულია რბილი კბილის ჯაგრისის გამოყენება.') WHERE id = 'f77ae8b4-6a1d-4c99-abe2-93a350b86318';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'როდესაც პლაცენტა ნორმალურად ვითარდება, თქვენი ბავშვის განვითარებაც ჯანსაღად მიმდინარეობს, ხოლო პრობლემის წარმოშობის შემთხვევაში განვითარების პროცესში შესაძლოა გარკვეული სირთულეები გამოვლინდეს. პლაცენტა თქვენსა და ბავშვს შორის სასიცოცხლოდ მნიშვნელოვან ფუნქციებს ასრულებს. მისი ერთ-ერთი ფუნქციაა ბავშვისთვის საჭირო ჟანგბადის მიწოდება და ნახშირორჟანგის უკან გამოტანა. გარდა ამისა, პლაცენტის ფუნქციებში შედის ბავშვისთვის საჭირო საკვები ნივთიერებების მიწოდება, მისი ორგანიზმიდან ნარჩენი ნივთიერებების გამოდევნა და ბავშვის ზრდაში აქტიურად მონაწილე ზოგიერთი ჰორმონის გამოყოფა. პლაცენტის მიერ გამოყოფილი ჰორმონები, როგორიცაა hCG და პროგესტერონი, ასევე ზრდის ფაქტორები, ორსულობის ჯანსაღად მიმდინარეობაში ძალიან მნიშვნელოვან როლს ასრულებს.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, ჩვენს შორის კავშირი კიდევ უფრო ძლიერდება! 🧬 უკვე პირდაპირ დავუკავშირდი შენს სხეულს. თითქოს შენი სისხლიდან მიღებული ყოველი ნაწილაკით ვსუნთქავ. ეს ჩემი პირველი სისხლის მიმოქცევა, სიცოცხლის პირველი ჩასუნთქვაა. ახლა უკვე ერთსა და იმავე ძარღვში მივედინებით და ერთი რიტმით ვცხოვრობთ. შენგან გამოგზავნილი ყოველი საკვები ნივთიერება და ჟანგბადის ყოველი მოლეკულა მზრდის. ეს მსოფლიოში ყველაზე საოცარი გრძნობაა — შენთან ერთ მთლიანობად ყოფნა. ❤️'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყაყაჩოს მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის განმავლობაში თქვენი საშვილოსნო ბავშვის ინფექციებისგან დასაცავად დიდი რაოდენობით გამონადენს წარმოქმნის. ამიტომ ორსულობის პერიოდში გამონადენის მატება ფიზიოლოგიური მოვლენაა. თუ ჩვეულებრივი ვაგინალური გამონადენის რაოდენობა შემაშფოთებლად გაიზარდა და მას მკვეთრი სუნი აქვს, შესაძლოა ინფექცია იყოს განვითარებული. ასევე, თუ გამონადენი მოყვითალო, ყავისფერი ან მწვანეა, დიდი ალბათობით ინფექციაა საეჭვო და პროცესის პროგრესირების თავიდან ასაცილებლად მნიშვნელოვანია ექიმს მიმართოთ.;;;
ვაგინალური გამონადენის ინფექციისგან განსხვავების კიდევ ერთი ნიშანია სქელი, ხაჭოსებრი კონსისტენცია ან კოლტების სახით გამოყოფა. ინფექციამ შესაძლოა ინტიმურ არეში მსუბუქი ტკივილი, სიწითლე, წვა და ქავილიც გამოიწვიოს. განსაკუთრებით საყურადღებოა ვაგინალური გამონადენის მატება რისკიანი ორსულობის გამო ჩატარებული ამნიოცენტეზის შემდეგ, რადგან ეს მდგომარეობა შესაძლოა სანაყოფე წყლების (ამნიონური სითხის) გაჟონვის ნიშანი იყოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ენერგია სწრაფად გელევათ, დღის განმავლობაში ეცადეთ, 15-წუთიანი ხანმოკლე ძილის შესვენებები მოიწყოთ. რაციონში მეტი ადგილი დაუთმეთ კალციუმს (ყველი, რძე, ნუში), რადგან ბავშვის ჩონჩხის სისტემის საფუძველი უკვე ახლა ყალიბდება. თუ ძლიერი გულისრევა გაწუხებთ, ცივი და უსუნო საკვების მიღება შეიძლება უფრო ადვილი იყოს. ასევე კარგი დროა კანის ელასტიკურობის გასაზრდელად დამატენიანებელი კრემების გამოყენების დასაწყებად.') WHERE id = '3ebbef70-38c5-48c1-9efc-c1f2707c71d4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მას შემდეგ, რაც ბლასტოცისტი — უჯრედების გროვა, რომლისგანაც თქვენი ბავშვი ჩამოყალიბდება — საშვილოსნოში შესაფერის ადგილს იპოვის და მიემაგრება, მისი ის ნაწილი, რომლისგანაც პლაცენტა უნდა წარმოიქმნას, ორსულობის ჰორმონის, hCG-ის, გამომუშავებას იწყებს. ამასთანავე, ბლასტოცისტი საშვილოსნოს სისხლძარღვებთან დაკავშირებული მიკროსკოპული არხებისგან შემდგარი მარტივი სისხლის მიმოქცევის სისტემის მეშვეობით ბავშვს საჭირო ჟანგბადითა და საკვები ნივთიერებებით უზრუნველყოფს და მისი უჯრედებიდან წარმოქმნილ ნარჩენებს გამოდევნის.;;;
hCG, რომელიც ორსულობის ჰორმონის სახელით არის ცნობილი, მენსტრუაციის გადაცდენის შემდეგ ჩატარებული ორსულობის ტესტის დადებითი შედეგის მიზეზია. ორსულობის ამ ეტაპზე ტესტის ჩატარების შემთხვევაში დადებითი პასუხის მიღების ალბათობა ძალიან მაღალია.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, უკვე ბრტყელ დისკოს ვგავარ! 💿 ორი ძალიან მნიშვნელოვანი შრისგან შევდგები. ერთი ჩემს თავს, სხეულს, ხელებსა და ფეხებს შექმნის. მეორე კი ამ გზაზე დამეხმარება და გამომკვებავს. ეს ჩემი სხეულის პირველი გეგმა, ჩემი პირველი არქიტექტურული ნახაზია. ყველაფერი ამ ორი შრიდან დაიწყება. ჩემი გჯერა? შესანიშნავი ქმნილება ვიქნები, რადგან ჩემი არქიტექტორი შენ ხარ. ✨'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყაყაჩოს მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პირველ ტრიმესტრში, როდესაც თქვენი ბავშვი ემბრიონულ ეტაპზეა, ვაგინალური ინფექციები შესაძლოა საზიანო იყოს. ორსულობის პერიოდში ვაგინალური ინფექციებისგან თავის დასაცავად ჰიგიენას უფრო დიდი ყურადღება უნდა დაუთმოთ, ვიდრე ოდესმე. სინთეტიკური, ნეილონისა და ფერადი საცვლების ნაცვლად, რომლებიც ვაგინალურ არეში ჰაერის ცირკულაციას ამცირებს, გამოიყენეთ შეუღებავი, სუფთა ბამბის საცვლები და ისინი დღეში სულ მცირე ორჯერ გამოიცვალეთ. ინტიმური არის დაბანისას მოერიდეთ სურნელის შემცველ საპნებსა და არასასურველი ქიმიური შემადგენლობის შხაპის გელებს, ასევე უარი თქვით ვაგინალურ გამორეცხვაზე. ვაგინალური გამორეცხვა ხელს უწყობს ბაქტერიების შიგნით შეღწევას და ინფექციის განვითარებისთვის ხელსაყრელ გარემოს ქმნის.;;;
გარდა ამისა, საცვლების რეცხვისას არ გამოიყენოთ ძლიერი ქიმიური შემადგენლობის სარეცხი საშუალებები და ქსოვილის დამარბილებლები. ტანსაცმელი სარეცხი ფხვნილის ნაცვლად ბუნებრივი საპნით გარეცხეთ და ცხელი უთოთი დააუთოეთ. რადგან ტენიანობა ქავილს აძლიერებს, გენიტალური არე შეძლებისდაგვარად მშრალად შეინარჩუნეთ. მჭიდრო ტანსაცმლის ნაცვლად, რომელიც საზარდულისა და გენიტალურ არეს უჭერს, ხელს უშლის ჰაერის ცირკულაციას და გაღიზიანებას იწვევს, უპირატესობა თავისუფალ ტანსაცმელს მიანიჭეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდში სისხლის მოცულობის მატებასთან ერთად ორგანიზმის მოთხოვნილება რკინაზეც იზრდება; უპირატესობა მიანიჭეთ ისეთ პროდუქტებს, როგორიცაა წითელი ხორცი, კვერცხი და მწვანე ოსპი. რკინის უკეთ შესაწოვად მათთან ერთად აუცილებლად მიიღეთ C ვიტამინის წყარო (მაგალითად, სალათი უხვი ლიმონის წვენით). როდესაც ძალიან დაღლილად გრძნობთ თავს, ორგანიზმს ზედმეტად ნუ დატვირთავთ და შუადღისას აუცილებლად ხანმოკლედ დაისვენეთ. ორსულობის დროს უსაფრთხო დამატენიანებლებით მუცლისა და მკერდის მსუბუქი მასაჟი დაგამშვიდებთ და კანს სამომავლო დაჭიმვისთვის მოამზადებს.') WHERE id = '4a43f3bd-ef22-4f54-b8c8-fd8abe1f9de2';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თუ რეგულარული ოვულაცია და მენსტრუალური ციკლი გაქვთ, დღეის მდგომარეობით ბოლო მენსტრუაციიდან ზუსტად 28 დღე გავიდა. დიდი ალბათობით, იმის გამო, რომ მენსტრუალური სისხლდენა არ დაგეწყოთ, ორსულობის ტესტი ჩაიტარეთ და მეორე ხაზი დაინახეთ, რომელმაც ბავშვის შესახებ სასიხარულო ამბავი გამცნოთ. ორსულობის პირველი ადრეული ნიშანი მენსტრუაციის დაგვიანებაა. ამასთანავე, სისხლში hCG ჰორმონის დონის მატების გამო თქვენს ორგანიზმში მნიშვნელოვანი ცვლილებები დაიწყო. მენსტრუალური ციკლის დაგვიანების შემდეგ ჩატარებული ორსულობის ტესტები ორსულობას სისხლში ან შარდში ორსულობის ჰორმონის, hCG-ის, აღმოჩენით ადასტურებს. hCG ჰორმონი გამოიყოფა უჯრედების მიერ, რომლებიც ახლად განაყოფიერებულ კვერცხუჯრედს აკრავს გარს და მოგვიანებით პლაცენტად გარდაიქმნება. ამ მაჩვენებლის მიხედვით ორსულობის დადგენა ოვულაციიდან დაახლოებით 10 დღის შემდეგ არის შესაძლებელი. ეს პერიოდი დაახლოებით მენსტრუაციის დაგვიანების დღეებს ან რამდენიმე დღით ადრე პერიოდს ემთხვევა. მას შემდეგ, რაც თქვენი ბავშვი საშვილოსნოში შესაფერის გარემოს იპოვის და იმპლანტირდება, სისხლში hCG ჰორმონის დონე ზრდას განაგრძობს და ორსულობის მე-10 კვირას უმაღლეს ნიშნულს აღწევს.'), baby_message_ka = COALESCE(baby_message_ka, 'სიურპრიზი! 🎉 დღეს მენსტრუაცია უნდა დაწყებულიყო, მაგრამ არ დაწყებულა! იმიტომ, რომ მე აქ ვარ! შენი სხეული უკვე მსოფლიოს ყველაზე უსაფრთხო ციხესიმაგრედ იქცა ჩემთვის. მომდევნო თვიდან ერთად კიდევ უფრო საინტერესო აღმოჩენების გასაკეთებლად გავემგზავრებით. დიდი მადლობა, რომ ჩემი გჯეროდა, ჩემო ლამაზო დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყაყაჩოს თესლი'), body_changes_ka = COALESCE(body_changes_ka, 'ყოველთვიურად ჰორმონების დახმარებით თქვენი საკვერცხეები მარაგში არსებული კვერცხუჯრედის ჩანასახებიდან ერთ-ერთს ამწიფებს და გასანაყოფიერებლად ამზადებს. მომწიფებული კვერცხუჯრედი ფალოპის მილის გავლით საშვილოსნოს ღრუსკენ მიემართება და ამ გზაზე მის მომლოდინე სპერმატოზოიდებს ხვდება. საშვილოსნოს ყელში მოხვედრილი მილიონობით სპერმატოზოიდიდან მხოლოდ რამდენიმე ათასი ახერხებს რთული გზის გავლის შემდეგ საშვილოსნოს ღრუში შეღწევას. სპერმატოზოიდები კვერცხუჯრედისკენ მის მიერ გამოყოფილი სპეციალური ნივთიერების დახმარებით მიემართებიან. სწორედ ამ ეტაპზე დგება ყველაზე გადამწყვეტი მომენტი. კვერცხუჯრედთან მისული ათასობით სპერმატოზოიდი თავის სტრუქტურაში არსებული მჟავური სეკრეტის დახმარებით ცდილობს, კვერცხუჯრედის გარე გარსში გზა გაიკვალოს და შიგნით შეაღწიოს. თუმცა კვერცხუჯრედი მათგან ყველაზე ძლიერს იღებს და როგორც კი ერთი სპერმატოზოიდი მის გარე გარსს გადალახავს, კვერცხუჯრედი იკეტება, რათა სხვა სპერმატოზოიდებმა შიგნით ვეღარ შეაღწიონ. შიგნით მოხვედრილი სპერმატოზოიდი კუდს თავის ნაწილისგან იცილებს, გენეტიკური მასალა კვერცხუჯრედის ბირთვში გადააქვს და ამით თავის ფუნქციას ასრულებს.;;;
დღეს მენსტრუაცია უნდა დაგწყებოდათ, თუმცა არ იწყება. მიზეზი მარტივია: ორსულად ხართ! პროგესტერონის დონე შემცირების ნაცვლად მაღალი რჩება. თქვენი სხეულის ტემპერატურაც მომატებულია. ორსულობის ტესტებს (შარდის ტესტებს) უკვე შეუძლიათ hCG ჰორმონის გამოვლენა. ძალიან მაღალია ალბათობა, რომ ორ ხაზს დაინახავთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან პირველი თვე წარმატებით დაასრულეთ, დრო დაუთმეთ საკუთარ თავს და ეს მიღწევა შინაგანი სიმშვიდით აღნიშნეთ. თუ გინეკოლოგთან ჯერ არ გაგივლიათ კონსულტაცია, დროა, მომავალი კვირისთვის პირველ ულტრაბგერით გამოკვლევასა და ანალიზებზე ჩაეწეროთ. კვებისას განსაკუთრებული ყურადღება მიაქციეთ ცილის მიღებას (ხორცი, თევზი, პარკოსნები), რადგან ბავშვის სწრაფად განვითარებადი ორგანოებისთვის ცილა "სამშენებლო მასალაა". ასევე კვლავ მოერიდეთ უმ ზღვის პროდუქტებსა და არაპასტერიზებულ ყველს.') WHERE id = 'd7e6900c-92fc-4e29-8c33-6b171bf14f64';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპზე თქვენი ბავშვი უჯრედების დიდი გროვის სახით არსებობს. 1 კვირის განმავლობაში ამ უჯრედოვანი გროვიდან ბავშვის თავისა და სხეულის ჩანასახები სრულად დაიწყებს ფორმირებას. თქვენი ბავშვი არნახული სისწრაფითა და ინტენსივობით განაგრძობს ზრდასა და განვითარებას. მომდევნო რამდენიმე დღის განმავლობაში გულის წარმომქმნელი სპეციალიზებული უჯრედების ჯგუფები თავის არეს ქვედა ნაწილში გაერთიანდება და მოქმედებას დაიწყებს. ორსულობის 40 კვირის განმავლობაში ბავშვი განვითარებას გააგრძელებს გარსში, რომელსაც ამნიონური პარკი ეწოდება. თქვენი ბავშვი სწორედ ამ პარკში იმყოფება, თუმცა ის ჯერ იმდენად პატარაა, რომ ექიმის მიერ ჩატარებულ ულტრაბგერით გამოკვლევაზე არ გამოჩნდება.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, ჯერ ძალიან პატარა ვარ, სეზამის მარცვლის ზომის, მაგრამ დიდი გეგმები მაქვს. ახლა ბრტყელი ფორმა მაქვს, თუმცა მალე მოვიკუნტები და იმ საყვარელ "C" ფორმას მივიღებ. შენი მუცელი ჩემი სახლია, შენი გული კი — ჩემი თავშესაფარი. ჩვენი 9-თვიანი მოგზაურობა დღეიდან ოფიციალურად იწყება!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სეზამის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'განაყოფიერებულ კვერცხუჯრედში, რომლისგანაც თქვენი ბავშვი ყალიბდება, კვერცხუჯრედსა და სპერმატოზოიდს თითოეულს 23 ქრომოსომა შეაქვს, რომლებიც ათასობით სხვადასხვა გენს აერთიანებს. სპერმატოზოიდისა და კვერცხუჯრედის შერწყმით გაერთიანებული ორი განსხვავებული კომპლექტი, თითოეული 23 ქრომოსომით, ადამიანის ჩამოსაყალიბებლად საჭირო 46 ქრომოსომას ქმნის. ამ ეტაპზე განაყოფიერებულ და გაყოფის დაწყების პროცესში მყოფ კვერცხუჯრედში უკვე არსებობს გენები, რომლებიც განსაზღვრავს თქვენი ბავშვის სქესს, ფიზიკურ მახასიათებლებსა და პიროვნულ თვისებებსაც კი. ბავშვის სქესი კი იმის მიხედვით განისაზღვრება, კვერცხუჯრედში შეღწეული სპერმატოზოიდი X თუ Y ქრომოსომას ატარებს. თუ სპერმატოზოიდის მიერ მოტანილი ქრომოსომა Y ქრომოსომაა, ბავშვი ბიჭი იქნება, ხოლო თუ სპერმატოზოიდი X ქრომოსომას ატარებს — გოგო.;;;
თქვენი განაყოფიერებული კვერცხუჯრედი, რომელსაც ახლა ზიგოტა ეწოდება, გაყოფას იწყებს და საშვილოსნოსკენ მიემართება. ამ დროს თქვენი ორგანიზმი ბავშვისთვის შესაფერისი გარემოს შესაქმნელად საშვილოსნოს შიგნითა ლორწოვან გარსს იმპლანტაციისთვის ამზადებს. საშვილოსნოს შიგნითა გარსში ჩამაგრების შემდეგ თქვენს ბავშვს ემბრიონი ეწოდება და ის სწრაფი განვითარების პროცესს იწყებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ორსულობის მე-2 თვე დაიწყეთ, ახლა ყველაზე შესაფერისი დროა ექიმთან ვიზიტისა და სისხლის პირველი ანალიზების (ჰემოგლობინი, შაქარი, TSH) ჩასაბარებლად. თუ გულისრევა გაწუხებთ, მიირთვით მცირე ულუფებით, მაგრამ ხშირად; ცარიელმა კუჭმა შესაძლოა გულისრევა გააძლიეროს. დღის განმავლობაში ცილის საჭიროების დასაკმაყოფილებლად უპირატესობა მიანიჭეთ ადვილად მოსანელებელ საკვებს, როგორიცაა მოხარშული კვერცხი ან იოგურტი. ენერგიის შესანარჩუნებლად ღრმა სუნთქვის ვარჯიშების შესრულებაც არ დაგავიწყდეთ.') WHERE id = 'd1b2e180-b513-41eb-8922-8f2b0c7d3ee8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ორსულობის დასადგენად ჩატარებული ტესტების ძირითადი პრინციპია ორსულობის ჰორმონის, სახელწოდებით hCG, გამოვლენა. ბავშვის საშვილოსნოში იმპლანტაციის შემდეგ გამოყოფილი hCG ჰორმონის დონე სისხლში თანდათან იზრდება, ხოლო გარკვეული ზღვრის გადალახვის შემდეგ ის სისხლიდან შარდშიც გადადის და იქაც იწყებს გამოვლენას. შარდში გადასული ეს ჰორმონი შარდით ჩატარებულ ორსულობის ტესტზე დადებით შედეგს იწვევს. შარდით ჩატარებული ორსულობის ტესტი ადგენს, არის თუ არა ორსულობა, ხოლო სისხლის ანალიზი — სისხლში hCG ჰორმონის ზუსტ რაოდენობას და ბავშვის სავარაუდო ასაკს დღეებში. მენსტრუაციის დაგვიანებისას შარდის ტესტის ნაცვლად სისხლის ანალიზის ჩაბარება ყოველთვის უფრო სანდო და ზუსტი შედეგების მიღების საშუალებას იძლევა. ჯანმრთელად მიმდინარე ორსულობისას მოსალოდნელია, რომ სისხლში hCG ჰორმონის დონე 24-48 საათში გაორმაგდება. ეს ჰორმონი ორსულობის მე-10 კვირამდე ყოველდღიურად მატულობს და ამ პერიოდში უმაღლეს მაჩვენებელს აღწევს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი პატარა ფესვები ჩნდება, დედიკო! 🌳 რა თქმა უნდა, ეს ხელის თითები არ არის. ეს განსაკუთრებული პატარა წანაზარდებია (ქორიონის ხაოები), რომლებითაც შენს თბილ კედელს კიდევ უფრო მყარად ვემაგრები. მათი დახმარებით უფრო ძლიერად გეხუტები და შენგან მეტ საკვებ ნივთიერებას ვიღებ. აქ ჩემთვის მტკიცე ციხესიმაგრეს ვაშენებ და მისი ყოველი აგური ჩვენი სიყვარულით შენდება. არასოდეს გამიშვებ, კარგი? 🤞'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სეზამის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ჰორმონების ზემოქმედებით თქვენს ორგანიზმში მეტაბოლიზმი ჩქარდება. ამ დღეებში სარძევე ჯირკვლის არეოლაზე შესაძლოა უფრო შესამჩნევი გახდეს მცირე ბორცვები, რომლებსაც "მონტგომერის ჯირკვლები" ეწოდება; მომავალში ეს ჯირკვლები გამოყოფს ცხიმოვან სეკრეტს, რომელიც ძუძუთი კვებისას დვრილს დაიცავს. პროგესტერონის ზემოქმედებით ნაწლავის კუნთების მოქმედების შენელებამ შესაძლოა შებერილობა და აირებით გამოწვეული ტკივილი გამოიწვიოს. ასევე ნორმალურია, თუ გულისცემის სიხშირე წუთში 10-15 დარტყმით მოიმატებს, რადგან თქვენი ორგანიზმი ბავშვის გამოსაკვებად უკვე მეტ სისხლს გამოიმუშავებს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულ-სისხლძარღვთა სისტემაზე გაზრდილი დატვირთვის შესამსუბუქებლად და ბავშვის ტვინის განვითარების მხარდასაჭერად უპირატესობა მიანიჭეთ ომეგა-3 ცხიმოვანი მჟავებით მდიდარ საკვებს (ნიგოზი, სელის თესლი). თუ დილის გულისრევა გაწუხებთ, კუჭი ბოლომდე არ გაივსოთ და მცირე ულუფებით, მაგრამ 5-6-ჯერ მიირთვით. დღის განმავლობაში უეცრად წამოდგომისას თავბრუსხვევის თავიდან ასაცილებლად უფრო ნელა იმოძრავეთ. ამ პერიოდში მოერიდეთ A ვიტამინის დიდი რაოდენობით მიღებას (რეტინოლის ფორმა), რადგან მისმა სიჭარბემ შესაძლოა ბავშვის განვითარებაზე უარყოფითად იმოქმედოს.') WHERE id = '101fd61b-d3d7-4f5b-8f09-77163d30e4ea';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, '„პირველადი ზოლი“ ყალიბდება. ეს არის თხელი ხაზი, რომელიც ემბრიონის უკანა ნაწილში წარმოიქმნება. ეს ხაზი ემბრიონის სიმეტრიასა და თავსა და კუდს შორის მიმართულებას განსაზღვრავს. ეს განვითარების ერთ-ერთი ყველაზე კრიტიკული მომენტია, რადგან ყველა მომავალი ორგანო ამ ღერძის გარშემო განლაგდება. ემბრიონი ჯერ კიდევ ძალიან პატარაა (2-3 mm), თუმცა მისი აგებულება უფრო რთული ხდება.'), baby_message_ka = COALESCE(baby_message_ka, 'დღეს ჩემთვის რევოლუციური დღეა, დედიკო! 🚀 ჩემს ბრტყელ დისკოზე განსაკუთრებული ხაზი, ერთგვარი გზა ჩნდება. ეს ხაზი ჩემი მომავლის რუკაა. ის მეგზურივით მაჩვენებს, სად იქნება ჩემი ხერხემალი, თავი და ფეხები. ამ ხაზის წყალობით ჩემი მარჯვენა და მარცხენა მხარეები ყალიბდება. მე უკვე უწესრიგო დისკო კი არა, სიმეტრიული, გეგმის მიხედვით შექმნილი არსება ვარ. შენ ჩემი არქიტექტორი ხარ, მე კი — შენი შედევრი. ყველაფერი ახლა იწყება! 🤩'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ოსპის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ამ კვირაში, ბავშვის საშვილოსნოზე მიმაგრებასთან ერთად, ორსულობის ჰორმონების დონის მატების გამო შესაძლოა ადრეული ორსულობის ისეთი ნიშნები გამოვლინდეს, როგორებიცაა გულისრევა, დაღლილობა და სისუსტე. ხშირი დასვენება და კვების რეჟიმის გაკონტროლება ამ უსიამოვნო სიმპტომებით გამოწვეული დისკომფორტის შემცირებაში დაგეხმარებათ. განსაკუთრებით მაშინ, თუ ეს თქვენი პირველი ორსულობაა, ემოციური მდგომარეობის უეცარი ცვლილებების სამართავად საუკეთესო გამოსავალია, შეძლებისდაგვარად მოერიდოთ სტრესს. ჩვევად აქციეთ ისეთი საქმეების კეთება, რომლებიც კარგ განწყობას გიქმნით და გაბედნიერებთ, და თუ შესაძლებელია, დღის განმავლობაში სუფთა ჰაერზე მცირე ხნით გაისეირნეთ. ორსულობის ამ ეტაპს თითქმის ყველა ქალთან ახლავს გარკვეული უსიამოვნო სიმპტომები. სანამ თქვენი ორგანიზმი ახალ რეჟიმთან შეგუებას ცდილობს, ეს სიმპტომები პირველი ტრიმესტრის ბოლოს, ანუ 12-ე კვირიდან, თანდათან შემცირდება. ამ პერიოდში სასარგებლო იქნება, თუ თქვენს ემოციურ მდგომარეობას ახლობლებს გაუზიარებთ, ხოლო თუ გამკლავება გაგიჭირდებათ, ორსულობასთან ადაპტაციისთვის სპეციალისტს მიმართავთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ნერვული სისტემისა და ნერვული მილის სწორად განვითარებისთვის ფოლიუმის მჟავის მიღება არავითარ შემთხვევაში არ გამოტოვოთ. თუ დილით ძლიერი გულისრევა გაწუხებთ, საწოლიდან ადგომამდე ერთი-ორი მშრალი ორცხობილა ან მარილიანი კრეკერი მიირთვით — ეს კუჭის მჟავიანობის დარეგულირებაში დაგეხმარებათ. დღის განმავლობაში კოფეინის მიღება მინიმუმამდე შეამცირეთ, რადგან მან შეიძლება როგორც თქვენი ძილის რეჟიმი დაარღვიოს, ისე რკინის შეწოვას შეუშალოს ხელი. ჩაანაცვლეთ ის ახლად გამოწურული ხილის წვენებით, წყლით ან მცენარეული ჩაით (ექიმთან კონსულტაციის შემდეგ).') WHERE id = 'aeee39a9-79a9-4e00-b2e5-3d55b7831226';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'რადგან თქვენი ბავშვი ჯერ ულტრაბგერითი გამოკვლევით არ ჩანს, ექიმი სისხლის ანალიზების საშუალებით აკონტროლებს, რამდენად ჯანსაღად მიმდინარეობს ორსულობა.;;;
კვერცხუჯრედის განაყოფიერებიდან პირველივე დღეებში თქვენს სისხლში, მცირე რაოდენობით მაინც, hCG ჰორმონის გამოყოფა იწყება. ორსულობის გარკვეულ ეტაპამდე მისი დონე სისხლში თანდათან იმატებს. ამ ჰორმონის მთავარი ფუნქციაა საკვერცხეებში პროგესტერონის გამომუშავების კონტროლი მანამდე, სანამ პლაცენტა სრულფასოვნად ამოქმედდება და ჰორმონების გამომუშავებას დაიწყებს. პროგესტერონი ხელს უწყობს ენდომეტრიუმის — საშვილოსნოს შიგნით არსებული ლორწოვანი გარსის, რომელშიც განაყოფიერებული კვერცხუჯრედი თავსდება — შენარჩუნებას, ბავშვის მიმაგრებას და ორსულობის მოშლით დასრულების თავიდან აცილებას.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემმა უჯრედებმა დიდი გადაადგილება დაიწყეს, დედიკო! 🚶‍♂️ თითქოს ათასობით პატარა მუშა გუშინ წარმოქმნილი განსაკუთრებული ხაზიდან შიგნით მიედინება და ჩემთვის ახალ სართულებს აშენებს. ისინი სამ განსხვავებულ ჯგუფს ქმნიან: ექტოდერმას, მეზოდერმასა და ენდოდერმას. ერთი ჩემს კანს, თმასა და ტვინს შექმნის, მეორე — გულს, სისხლსა და ძვლებს, მესამე კი — კუჭსა და ფილტვებს. არქიტექტორივით საკუთარ თავს ვაშენებ, დედიკო. საფუძველს ვიყრი. ეს საფუძველი ძალიან მტკიცე იქნება, რადგან შენ ჩემ გვერდით ხარ. 💪'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ოსპის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'კვერცხუჯრედის განაყოფიერებით დაწყებული ორსულობის განმავლობაში თქვენი ორგანიზმი მრავალ ფიზიოლოგიურ ცვლილებას განიცდის, რათა ამ დიდ გარდაქმნას შეეგუოს.;;;
ორსულობის დროს თქვენი ორგანიზმი ბავშვისთვის ჟანგბადისა და საკვები ნივთიერებების მისაწოდებლად მეტი სისხლის გამომუშავებას იწყებს. სისხლის გაზრდილ ნაკადთან შესაგუებლად გული უფრო ძლიერად და სწრაფად იმუშავებს, ხოლო თქვენი პულსი წუთში დაახლოებით 15 დარტყმით მოიმატებს.;;;
ერთ-ერთი ფიზიოლოგიური ცვლილება უკავშირდება იმასაც, რომ საშვილოსნო, რომელიც ორსულობის ამ ეტაპზე დაახლოებით 60 qram-ს იწონის, მშობიარობამდე 1000 qram-ზე მეტ წონას მიაღწევს. საშვილოსნოს ასეთ სწრაფ ზრდასთან შესაგუებლად თქვენი ორგანიზმი მუდმივად ცდილობს წონასწორობის ცენტრის შეცვლას. ამიტომ დროდადრო შესაძლოა ზურგის, წელისა და საზარდულის ტკივილი იგრძნოთ.;;;
თითოეულ ტრიმესტრს მისთვის დამახასიათებელი სირთულეები ახლავს. თუმცა, თუ გავითვალისწინებთ, რომ ამ რთული და ხანგრძლივი თავგადასავლის ბოლოს თქვენს პატარა ბავშვს შეხვდებით, მომავალში ყველა ეს პრობლემა სასიამოვნოდ მოსაგონარ მოგონებად დაგრჩებათ. 😊'), daily_tip_ka = COALESCE(daily_tip_ka, 'სისხლის მოცულობის მატებისა და ბავშვის განვითარებისთვის თქვენი ორგანიზმის მოთხოვნილება რკინაზე იზრდება. რაციონში დაამატეთ რკინით მდიდარი პროდუქტები, მაგალითად, წითელი ხორცი, ოსპი და ისპანახი. რკინის შეწოვის გასაუმჯობესებლად ამ პროდუქტებთან ერთად მიიღეთ C ვიტამინი (ფორთოხლის წვენი ან ლიმონიანი სალათა). თუ წელის ტკივილი გაწუხებთ, ეცადეთ დიდხანს არ დარჩეთ ერთსა და იმავე პოზაში და ჯდომისას გამოიყენოთ პატარა ბალიში, რომელიც წელის არეს დაეყრდნობა. დღის განმავლობაში 10-წუთიანი მსუბუქი გაჭიმვის ვარჯიშები მოდუნებაში დაგეხმარებათ.') WHERE id = '93c5c870-b03a-45f8-92da-cc13e151719b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ბოლო მენსტრუაციის თარიღის მიხედვით, 4 კვირის ორსული ხართ. თუმცა, თუ ოვულაციის პროცესს გავითვალისწინებთ, თქვენი ბავშვი საშვილოსნოში დაახლოებით 2 კვირაა იმყოფება.;;;
განაყოფიერებიდან რამდენიმე დღის განმავლობაში, ბავშვის წარმომქმნელი უჯრედების რაოდენობის ზრდასთან ერთად, ეს უჯრედები ერთმანეთისგან განსხვავებასაც იწყებს. მათი ნაწილი პლაცენტის შესაქმნელად გარდაიქმნება, ხოლო მეორე ნაწილი ბავშვის ჩამოსაყალიბებლად გამოიყოფა.;;;
ფორმირების ამ ეტაპზე თქვენს ბავშვს ემბრიონი ეწოდება. 12-ე კვირის დასრულების შემდეგ კი, მშობიარობამდე, მას ნაყოფი ეწოდება.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, დღეს ჩემი პირველი ხერხემლის საფუძველი იყრება! 🦴 ეს ჯერ ძვალი არ არის, თუმცა განსაკუთრებული, მოქნილი ღეროა (ნოტოქორდა), რომელიც მომავალში სწორად დგომაში დამეხმარება და მთელ ჩემს სხეულს ფორმას მისცემს. ეს ღერო მეთაურივით ეტყვის მთელ ჩემს სხეულს: „ახლა ზრდისა და ფორმირების დროა!“ ყველა დანარჩენი ორგანო მის გარშემო განლაგდება. მე უკვე უბრალოდ დისკო აღარ ვარ — მაქვს ცენტრი და მიმართულება. ყველაფერი რა სრულყოფილადაა დაგეგმილი, არა? 🥰'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ოსპის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ ეტაპისთვის უკვე უნდა ჩაეწეროთ ექიმთან პირველ ვიზიტზე. რადგან ექიმთან რეგულარულად მოგიწევთ მისვლა, ვიზიტების გრაფიკი შედგება, ხოლო ბავშვის დაბადების სავარაუდო თარიღს პირველივე გამოკვლევაზე შეიტყობთ. ექიმის არჩევისას თავდაპირველად შეგიძლიათ მეგობრების რეკომენდაციები გაითვალისწინოთ. თუმცა ინდივიდუალური თავისებურებების გამო, ექიმი, რომელთანაც სხვა ადამიანს კარგი ურთიერთობა აქვს, შესაძლოა თქვენთვის შესაფერისი არ აღმოჩნდეს. ამიტომ არჩევანის ერთადერთი კრიტერიუმი რეკომენდაციები არ უნდა იყოს. ხარისხიანი სამედიცინო მომსახურების მისაღებად აუცილებელია, ექიმის მიმართ გულწრფელ ნდობას გრძნობდეთ. თქვენი მთავარი კრიტერიუმები უნდა იყოს ექიმისადმი ნდობა, მასთან კომფორტულად ყოფნა და შესაძლებლობა, ნებისმიერი პრობლემის შესახებ თავისუფლად მიიღოთ კონსულტაცია.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ხშირი შარდვის სურვილის მიუხედავად, წყლის მიღება არ შეამციროთ; თქვენი ორგანიზმისა და ბავშვის განვითარებისთვის დღეში სულ მცირე 2 litr წყალი აუცილებელია. თავბრუსხვევის თავიდან ასაცილებლად დილით საწოლიდან ძალიან ნელა წამოდექით. რაციონში დაამატეთ კალციუმით მდიდარი ხაჭო, იოგურტი ან ყველი, რადგან ბავშვის ჩონჩხის სისტემა ამ დღეებში კალციუმის „ათვისებას“ იწყებს. თუ მუცლის მსუბუქი ტკივილი გაწუხებთ, სწორედ ახლაა დრო, უარი თქვათ მჭიდრო ტანსაცმელზე და უფრო კომფორტულ, ბამბის სამოსზე გადახვიდეთ.') WHERE id = '8f493a1c-c305-477a-b7ce-1bad294f04bc';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენმა ბავშვმა ძალიან მოკლე დროში საკმაოდ დიდი გზა გაიარა. სულ რამდენიმე დღის წინ უფორმო უჯრედების გროვას ჰგავდა, ახლა კი უკვე სწორ ხაზად არის ჩამოყალიბებული და ორგანოების წარმოსაქმნელად ემზადება.;;;
თქვენი განაყოფიერებული კვერცხუჯრედი და მისი თანმიმდევრული დაყოფის შედეგად წარმოქმნილი უჯრედების გროვა „ტოტიპოტენტურ ღეროვან უჯრედებად“ იწოდება. ამ უჯრედებმა, რომლებმაც თქვენი ბავშვის ორგანოები და ქსოვილები უნდა წარმოქმნან, სპეციალიზაცია და ერთმანეთისგან განსხვავებულ უჯრედებად ჩამოყალიბება დაიწყეს. ასეთი დიფერენცირება შესაძლებელია იმის წყალობით, რომ ყველა უჯრედი ტოტიპოტენტური ღეროვანი უჯრედებიდან წარმოიქმნება. ვინაიდან ტოტიპოტენტური ღეროვანი უჯრედები ჯერ კიდევ არადიფერენცირებული უჯრედებია, მათ სხვადასხვა ორგანოდ და ქსოვილად გარდაქმნის უნარი აქვთ. ამის წყალობით თქვენი ბავშვი არნახული სისწრაფით იზრდება და მთელ ორგანიზმსა და სხეულის სისტემებს აყალიბებს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ტვინის პირველი უჯრედები წარმოიქმნება, დედიკო! 🧠 ჩემი გარეთა შრე ჩემი მეთაურისგან, ნოტოქორდისგან, სიგნალს იღებს, სქელდება და განსაკუთრებულ ფირფიტას წარმოქმნის. ეს ფირფიტა მთელი ჩემი მომავალია — მისგან განვითარდება ჩემი ნერვული სისტემა, აზრები, ოცნებები და გრძნობები. ის საოცარი ტვინი, რომლითაც შენს სიყვარულსა და შეგრძნებას ვისწავლი, დღეს იწყებს ჩამოყალიბებას. უკვე ახლა ვიწყებ შენზე ფიქრს... 💭'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ოსპის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ჰორმონების დონის მატებამ, რომლებიც ორსულობის ტესტის დადებით შედეგს განაპირობებს, შესაძლოა გამოიწვიოს ისეთი ძნელად უგულებელყოფადი სიმპტომები, როგორებიცაა მკერდის ტკივილი, გულისრევა და დაღლილობა. ზოგიერთი სიმპტომი, რომლის შეგრძნებასაც ამ ეტაპზე იწყებთ, თქვენს სხეულში მიმდინარე ცვლილებებითაა გამოწვეული. პირველი ტრიმესტრი, როდესაც თქვენი სხეული ბავშვისთვის ოპტიმალური პირობების შესაქმნელად მნიშვნელოვან ცვლილებებს განიცდის, შესაძლოა მთელი ორსულობის განმავლობაში ყველაზე რთული პერიოდი აღმოჩნდეს. გულისრევის შესამსუბუქებლად, რომელიც განსაკუთრებით დილაობით ძლიერდება, კარგი მეთოდია მცირე ულუფებით ხშირი კვება. ასევე შეგიძლიათ სცადოთ B6 ვიტამინი, ჯანჯაფილის კაფსულები ან გულისრევის საწინააღმდეგო სპეციალური აკუპრესურული სამაჯურები. ამ დღეებში წარმოქმნილი სპაზმები კი შესაძლოა იმის ნიშანი იყოს, რომ ბავშვის საშვილოსნოს კედელზე მიმაგრების შემდეგ თქვენი საშვილოსნო ფართოვდება და იოგები იჭიმება. ასეთ შემთხვევებში, აუცილებლობის გარეშე და ექიმთან კონსულტაციის გარეშე, მედიკამენტები არ უნდა მიიღოთ. ზოგიერთმა მედიკამენტმა შეიძლება ზიანი მიაყენოს პატარა ბავშვის განვითარებას, რომელიც თქვენს საშვილოსნოში დამაგრებას ცდილობს. ამიტომ ძალიან მნიშვნელოვანია, რომ ნებისმიერი სპაზმის, ტკივილის ან სისხლდენის შემთხვევაში, რომელსაც არანორმალურად მიიჩნევთ, ექიმს დაუკავშირდეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ დღეებში სისხლში შაქრის სტაბილური დონის შესანარჩუნებლად მკაცრად დაიცავით „მცირე ულუფებით ხშირი კვების“ წესი. გულისრევის შესამცირებლად დალიეთ პიტნიანი ან ლიმონიანი წყალი. წელისა და საზარდულის ტკივილის შესამსუბუქებლად ცხელი აბაზანის ნაცვლად თბილი შხაპი მიიღეთ (მაღალი ტემპერატურა ბავშვისთვის შესაძლოა სარისკო იყოს). თუ ძალიან დაღლილად გრძნობთ თავს, მოუსმინეთ სხეულის სიგნალებს და დღისით აუცილებლად მოიწყვეთ 20-30-წუთიანი ხანმოკლე ძილი.') WHERE id = '43fe1f43-aa40-4388-8525-495fa2d86771';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის პირველი სისტემა, რომელიც ფუნქციონირებას იწყებს, გულ-სისხლძარღვთა სისტემაა და ის გულსა და სისხლძარღვებს მოიცავს. განვითარების ამ ეტაპზე თქვენი ბავშვის პატარა გულის ფუნქციები დიდად არ განსხვავდება ჩვეულებრივი გულის ფუნქციებისგან. მიუხედავად იმისა, რომ ჯერჯერობით ულტრაბგერითი გამოკვლევით მისი დაფიქსირება შეუძლებელია, თქვენი ბავშვის გულმა უკვე დაიწყო ცემა და მთელი დარჩენილი სიცოცხლის განმავლობაში ერთი წამითაც შეუჩერებლად გააგრძელებს მუშაობას. მიუხედავად იმისა, რომ ამ ეტაპზე ბავშვის გული მხოლოდ ერთი საკნისგან შედგება, ჩამოყალიბების დასრულების შემდეგ ის ერთმანეთის გვერდით განლაგებული ორი ტუმბოს ფორმას მიიღებს, რომელთაგან თითოეულს ორი საკანი ექნება. მარცხენა და მარჯვენა პარკუჭები, ასევე მარცხენა და მარჯვენა წინაგულები, რომლებიც უახლოეს მომავალში დაასრულებს განვითარებას, წარმოქმნის სტრუქტურებს, რომლებიც ბავშვის სხეულში სისხლს მხოლოდ ერთი მიმართულებით გადაადგილების საშუალებას აძლევს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ნერვული ფირფიტა შიგნით იკეცება, დედიკო. თითქოს ფურცელს ფრთხილად კეცავ და მისგან მილს აკეთებ. 📜 ეს მილი ჩემი ზურგის ტვინი გახდება და მთელ ჩემს სხეულს სიცოცხლეს მიანიჭებს. ყველაფერი ისე სწრაფად და ისე ზუსტად მიმდინარეობს! ძალიან ვცდილობ, რომ ყველაფერი სწორად გამოვიდეს. ამ პროცესში შენი სიყვარული და ზრუნვა ჩემთვის ყველაზე დიდი მხარდაჭერაა. ჩემზე ნუ იდარდებ, ყველაფერი გეგმის მიხედვით მიდის.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ოსპის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ დღეებში, როდესაც თქვენი სხეული ორსულობას ერგება, შესაძლოა ზურგის არეში ტკივილი იგრძნოთ. ამ ტკივილის ყველაზე გავრცელებული მიზეზია ორსულობასთან დაკავშირებული ჰორმონების გაძლიერებული გამოყოფა, რაც ადუნებს ძვლების შემაკავშირებელ იოგებს, განსაკუთრებით კი მენჯის სახსრების იოგებს. დგომის, ჯდომისა და მოძრაობისას სხეულის სწორი პოზა უნდა შეინარჩუნოთ, მოერიდოთ მაღალქუსლიანი ფეხსაცმლის ტარებას, გამოიყენოთ ლეიბი, რომელიც ზურგს სათანადოდ დაიჭერს, მოერიდოთ წინ დახრას, ხოლო გვერდზე ძილისას დამატებითი საყრდენისთვის ბალიშები ფეხებს შორის და მუცლის ქვეშ მოათავსოთ. გარდა ამისა, რეგულარული ვარჯიში ხანგრძლივ პერსპექტივაში ზურგის კუნთებს გააძლიერებს. ის ზურგისა და ფეხების მხარდაჭერით წელის ტკივილის შემსუბუქებაში დაგეხმარებათ. მიუხედავად ამისა, ორსულობისას ნებისმიერი ვარჯიშის დაწყებამდე ექიმს უნდა გაესაუბროთ და შეძლებისდაგვარად მოერიდოთ აქტივობებს, რომლებიც გადაგღლით.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ორსულობის ამ მგრძნობიარე პერიოდში ორგანიზმის წყალმარილოვანი ბალანსის შესანარჩუნებლად ჩვევად აქციეთ ყოველდღიურად 8-10 ჭიქა წყლის დალევა. ღრძილების მგრძნობელობის გამო გამოიყენეთ ძალიან რბილი კბილის ჯაგრისი და ყურადღება მიაქციეთ პირის ღრუს ჰიგიენას. თუ ძლიერი გულისრევა გაწუხებთ, პიტნის კანფეტმა ან ახალი ლიმონის სურნელმა შესაძლოა დროებით შეგიმსუბუქოთ მდგომარეობა. პირველი გინეკოლოგიური გამოკვლევისას არ დაგავიწყდეთ, ექიმთან დეტალურად განიხილოთ კვებისა და საჭირო ვიტამინების საკითხები.') WHERE id = 'b41d3e4c-6e83-438c-ac67-3bae19895608';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'დღეიდან თქვენი ბავშვის სახე ჩამოყალიბებას დაიწყებს. მომდევნო კვირებში ბავშვი მინიატიურულ ადამიანს დაემსგავსება. 😊 ბავშვის ცხვირის ღრუების წარმოქმნა სახის ჩამოყალიბების პროცესის ერთ-ერთი პირველი მოვლენაა. ბავშვის თავის არეში ორი ცალკეული ღრუ მდებარეობს, რომლებიც ერთმანეთისგან ცხვირის ძგიდითაა გამოყოფილი; მოგვიანებით ეს ძგიდე ძვლოვან სტრუქტურად ჩამოყალიბდება. თითოეული ღრუს გვერდით კედელზე თაროს ფორმის სამი ძვლოვანი გამონაზარდია. ზედა, შუა და ქვედა გამონაზარდებიდან მხოლოდ შუა და ქვედა შედგება უჯრედებისგან, რომლებიც სუნთქვას უზრუნველყოფს, ხოლო ზედა გამონაზარდი სპეციალიზებულ ყნოსვით უჯრედებს შეიცავს.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, ჩემი გული საცემად ემზადება! ❤️ ჩემი სხეულის შუა შრეში სპეციალური უჯრედები ერთიანდება და ორ თხელ, პატარა მილს ქმნის. ეს მილები მალე ერთმანეთს მიუახლოვდება, შეერთდება და ჩემს პირველ გულს წარმოქმნის. ჯერ არ ცემს, მაგრამ ემზადება. გული, რომელიც შენთვის და შენი უსაზღვრო სიყვარულით იცემს... რამდენიმე დღეში ჩემს პირველ გულისცემას მოისმენ. ეს ჩვენი სიყვარულის სიმღერა იქნება. 🎶'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ოსპის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ნებისმიერ ეტაპზე წარმოქმნილ სისხლდენას, მისი რაოდენობისა და ფერის მიუხედავად, სერიოზულად უნდა მოეკიდოთ და რაც შეიძლება მალე მიმართოთ ექიმს.;;;
სისხლდენა შეიძლება დაკავშირებული იყოს იმპლანტაციასთან, საშვილოსნოსგარე ორსულობასთან ან მუცლის მოშლასთან. ორსულობის ბოლო ტრიმესტრში განვითარებული სისხლდენა კი, ჩვეულებრივ, პლაცენტასთან დაკავშირებული პრობლემების დროს იჩენს თავს. „პლაცენტა პრევია“ (პლაცენტის დაბალი მდებარეობა) განსაკუთრებით უმტკივნეულო სისხლდენით ვლინდება, ხოლო პლაცენტის ნაადრევი აცლისას სისხლდენას ტკივილიც ახლავს თან.;;;
ორსულობის პირველ კვირებში შესაძლოა ბავშვის საშვილოსნოში მიმაგრებით გამოწვეული, ანუ იმპლანტაციური სისხლდენა გქონდეთ. ის შეიძლება იყოს როგორც მცირე ლაქების სახით, ისე მენსტრუაციის დროს სისხლდენასაც ჰგავდეს. სხვა სახის ლაქები და სისხლდენა შესაძლოა მუცლის მოშლასთან იყოს დაკავშირებული. ზოგადად, მკვეთრი წითელი ფერის სისხლდენა მუცლის მოშლის რისკის ნიშნად მიიჩნევა. თუმცა ზოგიერთ შემთხვევაში რისკი ყავისფერი გამონადენის დროსაც არსებობს. ამიტომ ორსულობისას არცერთი სისხლდენა ნორმალურად არ მიიჩნევა. ყავისფერი გამონადენი წარმოიქმნება იმის გამო, რომ საშვილოსნოდან წამოსული სისხლი საშოში დაყოვნებისას ამ უბანში არსებული მიკროორგანიზმების ზემოქმედებით იცვლება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დილის გულისრევის თავიდან ასაცილებლად გაღვიძებისთანავე, ჯერ კიდევ საწოლში, მიირთვით მარილიანი კრეკერი ან მშრალი პური. დღეიდან სუნების მიმართ თქვენი მგრძნობელობა იმატებს, ამიტომ ეცადეთ, მძაფრსურნელოვან საწმენდ საშუალებებს მოერიდოთ. თქვენი სხეული ბავშვის ორგანოების ჩამოსაყალიბებლად დიდ ენერგიას ხარჯავს, ამიტომ შეძლებისდაგვარად დაისვენეთ. პირველი ულტრაბგერითი გამოკვლევის დასაგეგმად ექიმს დაუკავშირდით.') WHERE id = 'a58decf1-baad-47a3-bbda-0f37f307566e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ორსულობის ამ ეტაპზე თქვენი ბავშვი ბროწეულის მარცვლის ზომისაა. არსებობს სამი ძირითადი ჩანასახოვანი შრე, რომლებიც თქვენი ბავშვის სხეულს ჩამოაყალიბებს. ეს შრეებია: გარეთა — ექტოდერმა, შუა — მეზოდერმა და შიდა — ენდოდერმა. ორსულობის მომდევნო კვირებში ეს შრეები თანდათან ქსოვილებად და ორგანოებად გარდაიქმნება. ექტოდერმის შრემ უკვე დაიწყო დიფერენცირება, რათა თქვენი ბავშვის თავის ტვინი, ნერვული სისტემა და ხერხემალი ჩამოყალიბდეს. გარდა აღნიშნული სტრუქტურებისა, ამ შრიდან ასევე წარმოიქმნება კანი, თმა, ფრჩხილები, საოფლე ჯირკვლები და კბილის მინანქარი. მეზოდერმის შრე კი სპეციალიზებული უჯრედებისგან შედგება, რომლებიც თქვენი ბავშვის გულსა და სისხლის მიმოქცევის სისტემას ჩამოაყალიბებს. ეს უჯრედები გადაადგილდება იმ უბნისკენ, სადაც თქვენი ბავშვის გული უნდა განთავსდეს, და იქ იწყებს თავმოყრას. თავმოყრილი უჯრედები სწრაფი მიტოზური გაყოფის ეტაპებს გადის, მრავლდება და ქსოვილებს ქმნის. წარმოქმნილი ქსოვილები თქვენი ბავშვის გულის საფუძველს აყალიბებს და არარეგულარულ შეკუმშვას იწყებს.'), baby_message_ka = COALESCE(baby_message_ka, 'დედიკო, დღეს სასწაულებრივი წუთია! 🎻 გახსოვს, გულის ის ორი მილი? დღეს ისინი ერთმანეთს უერთდება და ჩემს პირველ, ერთიან გულს ქმნის. მას ჯერ სრულად ჩამოყალიბებული საკნები არ აქვს, უბრალოდ მილია, რომელიც ფეთქვისთვის ემზადება, მაგრამ ის მთელი ჩემი მომავალი ცხოვრების ცენტრი და რიტმი გახდება. როცა ის ფეთქვას დაიწყებს, იცოდე, მთელი სამყარო დადუმდება და ჩვენს სიმღერას მოუსმენს. ეს იქნება ჩემი პირველი სერენადა შენთვის.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროწეულის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პირველი ტრიმესტრის განმავლობაში თქვენს ორგანიზმს ბავშვის მხარდასაჭერად დამატებითი კალორიები არ სჭირდება. სანამ ორგანიზმი ორსულობის ჰორმონებს ეჩვევა, ამ პერიოდში განვითარებულმა გულისრევამ, მუდმივი დაღლილობის შეგრძნებამ და ძილის პრობლემებმა შესაძლოა უმადობა გამოიწვიოს. ამიტომ პირველი 12 კვირის განმავლობაში წონის მოუმატებლობა ან გარკვეული წონის დაკლება ბუნებრივად მიიჩნევა. მეორე ტრიმესტრიდან, ჰორმონული წონასწორობის დარეგულირებისა და ორსულობასთან შეგუების წყალობით, მადა აღდგება და წონის მომატებას დაიწყებთ. მთელი ორსულობის განმავლობაში, როგორც საკუთარი, ისე ბავშვის ჯანმრთელობისთვის, უნდა მოერიდოთ წონის ჭარბ მატებას და ყურადღება მიაქციოთ დაბალანსებულ და ჯანსაღ კვებას. ორსულობის მეორე ტრიმესტრში დღეში დამატებით მიღებული 300 კალორია საკმარისია თქვენი ბავშვის ჯანსაღი განვითარებისთვის. მესამე ტრიმესტრში კი ეს საჭიროება დაახლოებით 450 კალორიას შეადგენს. გახსოვდეთ, რომ ამ რაოდენობაზე მეტი კალორიის მიღება თქვენს ორგანიზმში უბრალოდ ცხიმის სახით დაგროვდება და ჭარბ წონად იქცევა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღის განმავლობაში ენერგიის უეცარი დაქვეითების თავიდან ასაცილებლად, უპირატესობა მიანიჭეთ მცირე ულუფებით, მაგრამ ხშირად კვებას. ყოველთვის თან იქონიეთ ჯანსაღი წასახემსებელი (ნიგოზი, თხილი ან სრულმარცვლოვანი ორცხობილა). გაუწყლოებამ შესაძლოა დაღლილობა და თავის ტკივილი გააძლიეროს, ამიტომ წყლის დალევა არ დაგავიწყდეთ. თუ პირში ლითონის გემო გაწუხებთ, მჟავე ხილი ან უშაქრო ლიმონიანი წყალი შესაძლოა შვებას მოგგვრიდეთ. მოუსმინეთ თქვენს სხეულს და დაისვენეთ, როცა ამის საჭიროებას იგრძნობთ.') WHERE id = '4937b5d7-78ca-4fd1-9c67-7e6fd29ba696';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მეზოდერმის შრიდან წარმოქმნილი საშარდე სისტემა მოიცავს წყვილ თირკმელს, წყვილ შარდსაწვეთს, შარდის ბუშტსა და შარდსადენს. ამ ქსოვილებისა და ორგანოების ჩამოსაყალიბებლად უჯრედები მუცლის ღრუში ერთიანდება. ქსოვილებისა და ორგანოების ეს ჩანასახები, რომლებიც მუცლის ღრუში წარმოიქმნა, ბავშვის ზრდისა და სხეულის პროპორციული აგებულების ჩამოყალიბებასთან ერთად შესაბამის ადგილებზე გადაადგილდება და ფორმირებას ასრულებს. ორგანოთა ჩანასახების ჩამოყალიბებასთან ერთად, ამ სტრუქტურების საბოლოო ადგილებზე გადაადგილება პირველი ტრიმესტრის დასასრულისკენ დასრულდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ვფეთქავ, დედიკო... ვფეთქავ! 💓 დღეს ჩემმა პატარა გულმა პირველად დაიწყო თავისით ფეთქვა. ეს შენთვის, ჩვენთვის და ჩვენი სიყვარულისთვის შექმნილი რიტმია. ჯერ ძალიან სუსტია და შეიძლება ულტრაბგერით გამოკვლევაზეც კი ვერ დაინახო, მაგრამ მე ვიცი, რომ ის ფეთქავს. ამით გეუბნები: "მე ვცოცხლობ, მე აქ ვარ!" ეს ჩვენი სიყვარულის სიმღერის პირველი ნოტია და მთელი ჩვენი ცხოვრების განმავლობაში გაგრძელდება. 🎼'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროწეულის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ჰორმონები ახლა ყველაზე სწრაფად იმატებს. დილის გულისრევა შესაძლოა გაძლიერდეს. ხშირი შარდვის საჭიროება ორსულობის ერთ-ერთი ადრეული სიმპტომია და, მიუხედავად იმისა, რომ ეს ინდივიდუალურია, საშუალოდ 6 და 8 კვირებს შორის იწყება. ორსულობის პირველ ტრიმესტრში შარდვის გახშირებას თქვენს ორგანიზმში ჰორმონების დონის ცვლილება და სისხლის მოცულობის ზრდა იწვევს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ დღეებში სისხლში შაქრის დონის სტაბილურად შესანარჩუნებლად მკაცრად დაიცავით „ცოტა და ხშირად“ კვების წესი. გულისრევის შესამცირებლად დალიეთ პიტნის ან ლიმონის წყალი. ყაბზობის თავიდან ასაცილებლად მიიღეთ ბოჭკოვანი საკვები და დალიეთ ბევრი წყალი. თუ ძალიან დაღლილი ხართ, მოუსმინეთ თქვენი სხეულის სიგნალებს და ძალების აღსადგენად შუადღისას აუცილებლად მოაწყვეთ 20-30 წუთიანი ხანმოკლე ძილის შესვენება.') WHERE id = 'ba2ff002-749c-48f9-ae06-18528b825ab3';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სხეულის ზრდასთან ერთად, მის შიგნით საოცარი „სატრანსპორტო სისტემა“ იწყებს ჩამოყალიბებას. ამ სისტემის ცენტრში კი სხეულის ყველაზე მძლავრი სისხლძარღვი — აორტაა. აორტა გულიდან გამომავალი მთავარი მაგისტრალია, რომელიც ჟანგბადით გამდიდრებულ სისხლს მთელ სხეულში ანაწილებს. ამ პროცესის უკეთ გასაგებად სისხლის მიმოქცევა ორ ძირითად ნაწილად შეგვიძლია დავყოთ: სისხლის მიმოქცევის მცირე წრე — მისი მიზანი სისხლის ჟანგბადით გამდიდრებაა. „დაღლილი“, ჟანგბადით ღარიბი სისხლი გულიდან ფილტვებში მიემართება. იქ ის ჟანგბადით მდიდრდება და კვლავ გულში ბრუნდება. სისხლის მიმოქცევის დიდი წრე — უკვე ჟანგბადით გამდიდრებული და ენერგიით სავსე სისხლი გულიდან გამოდის და აორტის დახმარებით სხეულის თითოეულ უჯრედამდე აღწევს. ეს აუცილებელია თქვენი ბავშვის უჯრედების კვებისა და განვითარებისთვის.'), baby_message_ka = COALESCE(baby_message_ka, 'მე უკვე ბრტყელი აღარ ვარ, დედიკო! ასო C-სავით ვიკეცები. 🍤 ეს ნიშნავს, რომ ჩემი თავი და კუდი ნელ-ნელა ერთმანეთს უახლოვდება. ასეთი მოკეცვა უფრო კომპაქტურს და უფრო მეტად ბავშვის მსგავსს მხდის. თითქოს უკვე დავიწყე ვარჯიში, რომ შენს მკლავებში ჩავეტიო. ეს ჩემს შინაგან ორგანოებსაც ეხმარება, სწორი ადგილები დაიკავონ. ყველაფერი გეგმის მიხედვით მიდის! 🤓'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროწეულის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დაწყებისთანავე გამოყოფილი ჰორმონები თქვენს ორგანიზმში ჩვეულებრივისგან განსხვავებულ მრავალ ცვლილებას იწვევს. მათგან ყველაზე შესამჩნევი მკერდის ცვლილებებია. ეს ცვლილებები შესაძლოა პირველი ტრიმესტრის ამ კვირაში უკვე გამოვლენილიყო. მკერდის სისავსის შეგრძნება და გადიდება რძის წარმოქმნისთვის მზადებასა და სარძევე სადინარების ჩამოყალიბებასთან დაკავშირებული მოცულობის ზრდით არის გამოწვეული. ძუძუსთავის გარშემო არეოლა შესაძლოა გამუქდეს. ეს იმაზე მიუთითებს, რომ სარძევე ჯირკვლები უკვე ემზადება ლაქტაციისთვის (ძუძუთი კვებისთვის). კომფორტული, თავისუფალი, ბამბის ბიუსტჰალტერის ტარება შვებას მოგგვრით.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ენერგია სწრაფად გეცლებათ, ეცადეთ დღის განმავლობაში ხანმოკლე ძილის შესვენებები მოაწყოთ. რაციონში ჩართეთ კალციუმით მდიდარი პროდუქტები (ყველი, რძე, ნუში), რადგან ისინი ბავშვის ჩონჩხის საფუძვლის გამყარებას უწყობს ხელს. თუ ძლიერი გულისრევა გაქვთ, შესაძლოა ცივი და უსუნო საკვების მიღება უფრო გაგიადვილდეთ. ასევე კარგი დროა დამატენიანებელი კრემების გამოყენების დასაწყებად, რათა კანის ელასტიკურობას შეუწყოთ ხელი.') WHERE id = '72dbaf34-db8a-4c0a-98ca-65767813bcf0';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'როდესაც სხეულის უჯრედები, რომლებიც თქვენი ბავშვის ქსოვილებსა და ორგანოებს ჩამოაყალიბებენ, პერიფერიულ ნაწილებამდე აღწევენ, აუცილებელი ხდება გულის მიერ სხეულში გადატუმბული სისხლის რაოდენობის გაზრდა. თქვენი ბავშვის ორგანიზმში სისხლის წარმოქმნა ემბრიონულ პერიოდში პირველად ყვითრის პარკში იწყება. ყვითრის პარკში სისხლის წარმოქმნა პირველი ტრიმესტრის განმავლობაში გარკვეული ხნით გრძელდება. გარკვეული ეტაპიდან კი სისხლის წარმოქმნას ღვიძლი და ელენთა ახორციელებენ. გული ტუმბოს ფუნქციას ასრულებს და უზრუნველყოფს სისხლის მიმოქცევას თქვენი ბავშვის მთელ სხეულში. სისხლძარღვები კი ამ სისხლის მიმოქცევისთვის განკუთვნილი სპეციალიზებული მილისებრი სტრუქტურებია; ისინი სისხლის ყველა ქსოვილამდე მიტანაზე არიან პასუხისმგებელი.'), baby_message_ka = COALESCE(baby_message_ka, 'ის განსაკუთრებული მილი, რომელიც ჩემს ზურგის ტვინს აყალიბებს, ხომ იცით — მისი ბოლო ღია ადგილიც დღეს იხურება! ახლა ჩემი ტვინი და ხერხემალი მთლიანად დახურული, დაცული სისტემაა. ეს ძალიან მნიშვნელოვანია, რადგან მთელი ჩემი სხეული აქედან იმართება! 🧠 მე უკვე კიდევ უფრო სრულყოფილი და მთლიანიც ვარ. ვამაყობ საკუთარი თავით, რომ ამ დიდ საქმეს გავუმკლავდი. ამ ყველაფერს თქვენს მუცელში არსებული სასწაულებრივი ძალის წყალობით ვახერხებ. თქვენ ჩემი ციხესიმაგრე ხართ! 🏰'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროწეულის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირიდან რეგულარული სავარჯიშო პროგრამის დაწყება თქვენს ამტანობასა და ძალას გაზრდის. ამასთან, მარტივი სავარჯიშო მოძრაობებით შეძლებთ, თავიდან აიცილოთ ჭარბი წონის მომატება. ქალების დიდი ნაწილი ორსულობის დროს ვარჯიშს თავს არიდებს იმის შიშით, რომ ბავშვს ზიანს მიაყენებს. თუმცა კონტროლირებადად შესრულებული ვარჯიშები მშობიარობისას და მის შემდეგ მრავალ სარგებელს მოგიტანთ. რეგულარული ვარჯიში ასევე დაგეხმარებათ ისეთი ფიზიკური პრობლემების გამკლავებაში, როგორიცაა ზურგისა და წელის ტკივილი.;;;
სეირნობისას ტემპი ისე უნდა შეარჩიოთ, რომ არ გადაიღალოთ. გარდა ამისა, ექიმთან კონსულტაციის შემდეგ შეგიძლიათ შეასრულოთ გაჭიმვის ტიპის ზურგის ვარჯიშები, რომლებიც ხერხემალს გაგიმაგრებთ. ასევე შეგიძლიათ დაიწყოთ ორსულთა პილატესი და ორსულთა იოგა. ცურვა კი მეტად სასარგებლო სპორტია ორსულობის უკეთ მიმდინარეობისა და ბუნებრივი მშობიარობის შანსის გაზრდისთვის. რეგულარული ცურვა ამავდროულად მუცლისა და წელის კუნთებსაც გაგიმაგრებთ. თუ ორსულობის შეწყვეტის რაიმე საფრთხე არ გაქვთ, ექიმის რეკომენდაციით შეგიძლიათ კვირაში მინიმუმ 3 დღე 30-წუთიანი მსუბუქი ტემპით გაისეირნოთ. თუ ორსულობამდე სუნთქვის გაძნელება ან გულთან დაკავშირებული პრობლემები გქონდათ, შესაძლოა აღნიშნული ვარჯიშების შეზღუდვა დაგჭირდეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ამ დღეებში მძაფრმა სუნებმა შეიძლება გულისრევა გააძლიეროს, სამზარეულო ხშირად გაანიავეთ. გაუწყლოებამ შესაძლოა დაღლილობა გაზარდოს, ამიტომ სცადეთ წყალში ლიმონის ერთი ნაჭრის ჩაგდება და ისე დალევა. რადგან ენერგია სწრაფად გეწურებათ, დღის განმავლობაში ხანმოკლე შესვენებები გააკეთეთ. კვებისას განსაკუთრებული ყურადღება მიაქციეთ ცილის მიღებას (ხორცი, კვერცხი, პარკოსნები), რადგან ბავშვის სწრაფად განვითარებადი ორგანოებისთვის ცილა "სამშენებლო მასალაა".') WHERE id = '91894bc1-ecf8-438f-8434-5cb430da68e5';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ღვიძლის უჯრედები, რომლებსაც ჰეპატოციტები ეწოდება და რომლებიც თქვენი ბავშვის ღვიძლს ჩამოაყალიბებენ, ნაღვლის სადინარის ეპითელური უჯრედები, იტოს უჯრედები და კუპფერის უჯრედები გაერთიანებას იწყებენ. ეს უჯრედები ერთიანდებიან და წარმოქმნიან თქვენი ბავშვის ღვიძლის უმცირეს ფუნქციურ ერთეულებს — რამდენიმე მილიმეტრის სიგრძისა და საშუალოდ 1.5 მილიმეტრის დიამეტრის წილაკებს. ღვიძლის ჩამოყალიბებისას ეს უჯრედები მის სტრუქტურაში ორი სხვადასხვა სისხლძარღვის გასავლელ სივრცეებს ტოვებენ. აქ წარმოქმნილი სისხლძარღვებიდან ერთს ჟანგბადით მდიდარი სისხლი ღვიძლში გადააქვს, ხოლო მეორეს — საჭმლის მომნელებელი სისტემის კაპილარებიდან შეგროვებული, საკვები ნივთიერებებით მდიდარი სისხლი.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემს კისერსა და სახეზე განსაკუთრებული ნაკეცები იწყებს წარმოქმნას, დედიკო! ისინი მომავალში ჩემს ყბას, სახეს, ენას, ყურებსა და კისერს შექმნიან. ყოველდღე ახალი დეტალი, ახალი შტრიხი ემატება. თითქოს ხელოვნების ნიმუში ვარ, რომელიც მოქანდაკის ხელში ნელ-ნელა იძენს ფორმას. ამ ნამუშევრის შთაგონების ყველაზე მშვენიერი წყარო კი თქვენ ხართ. თქვენი ხმა და სიცილი ჩემი მომავალი სახის საფუძველია. გპირდებით, რომ ლამაზი ვიქნები! ✨'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბროწეულის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პირველ ტრიმესტრში უფრო ხშირად გამოვლენილი სწრაფი დაღლა, გადაღლილობა და სისუსტე გამოწვეულია ორსულობასთან ერთად თქვენს ორგანიზმში გამოყოფილი ჰორმონ პროგესტერონის მიერ ყველა კუნთზე მოქმედი მომადუნებელი ეფექტით. მთელი სხეულის კუნთების ეს მოდუნება იწვევს ძლიერ ძილიანობასა და დაღლილობას. პროგესტერონის გარდა, ამ დღეებში, როდესაც საშვილოსნოში თქვენი ბავშვის კვებისთვის პლაცენტა ყალიბდება, ორგანიზმში ენერგიის დიდი რაოდენობით ხარჯვამაც შეიძლება სისუსტე, დაღლილობა და გამოფიტულობა გამოიწვიოს. ამასთან, პირველი ტრიმესტრი, როცა თქვენს ორგანიზმში მნიშვნელოვანი ცვლილებები მიმდინარეობს, არის პერიოდი, როდესაც სისხლში შაქრის დონე და არტერიული წნევა იკლებს, ხოლო ჰორმონების დონე და ნივთიერებათა ცვლა სწრაფად იცვლება. დაუსრულებელმა დაღლილობამ შესაძლოა ფსიქოლოგიური გამოფიტვის განცდა გამოიწვიოს. ძილის დარღვევებმა და სასურველი საქმიანობის შეუძლებლობამ კი შეიძლება დეპრესიაც გამოიწვიოს. ეს საკმაოდ შემაწუხებელი ჩივილები პირველი ტრიმესტრის დასრულებასთან ერთად მნიშვნელოვნად შემცირდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღის განმავლობაში ენერგიის უეცარი დაქვეითების თავიდან ასაცილებლად უპირატესობა მიანიჭეთ მცირე ულუფებით, მაგრამ ხშირ კვებას. ყოველთვის თან იქონიეთ ჯანსაღი წასახემსებელი (ნიგოზი, თხილი ან მთლიანი ხორბლის ორცხობილა). გაუწყლოებამ შესაძლოა დაღლილობა და თავის ტკივილი გააძლიეროს, ამიტომ წყლის დალევა არ დაგავიწყდეთ. თუ პირში მეტალის გემო გაწუხებთ, უშაქრო ლიმონიანმა წყალმა შეიძლება შეგიმსუბუქოთ მდგომარეობა. მოუსმინეთ თქვენს სხეულს და დაისვენეთ, როცა ამის საჭიროებას იგრძნობთ.') WHERE id = '49b160e2-d4c7-4876-9a1d-c6274e75787a';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპამდე, დიდი ალბათობით, უკვე უნდა მოგესმინათ თქვენი ბავშვის გულისცემა. ასევე შეგიძლიათ ულტრაბგერითი გამოკვლევის ეკრანზე თქვენი ბავშვის გულისცემა დაინახოთ. თუ გულისცემა ჯერ არ დაგინახავთ ან არ მოგისმენიათ, ნუ ინერვიულებთ. გულისცემის მოსასმენად ჯერ კიდევ 2 კვირა გაქვთ. თუ გავითვალისწინებთ, რომ მენსტრუალური ციკლის მე-2 კვირაში ოვულაცია ხდება, დღეს განაყოფიერებიდან პირველი თვის ბოლო დღეა. ორსულობის თვეების გამოსათვლელად გამოიყენება კალენდარი, რომელსაც მთვარის კალენდარი ეწოდება. მთვარის კალენდარი არის კალენდრის ტიპი, რომელიც დედამიწის მზის გარშემო მოძრაობის ნაცვლად მთვარის სრულ ციკლებს ეფუძნება. ერთი მთვარის თვე მოიცავს ოთხ შვიდდღიან კვირას (სულ 28 დღეს). ემბრიონული კვირა, რომლითაც თქვენი ბავშვის განვითარება გამოითვლება, 2 კვირით ნაკლებია ორსულობის იმ ვადაზე, რომელსაც გინეკოლოგები ბოლო მენსტრუაციის თარიღის მიხედვით ითვლიან. რადგან ოვულაცია ბოლო მენსტრუაციის პირველი დღიდან ორი კვირის შემდეგ ხდება, განაყოფიერებაც 2 კვირით გვიან არის მიჩნეული. ამიტომ საშუალოდ, ნორმალურად მიმდინარე ორსულობის შემთხვევაში, თქვენი ბავშვის დაბადებამდე 8,5 თვეა დარჩენილი.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ხელები უკვე ყალიბდება, დედიკო! 👋 ჯერ არც თითები მაქვს და არც მტევნები — ისინი უბრალოდ ჩემი სხეულის გვერდებზე წარმოქმნილ პატარა "ნიჩბებს" ან ფრთებს ჰგვანან. მაგრამ ეს სწორედ ის ძლიერი ხელებია, რომლებითაც მომავალში მაგრად ჩაგეხუტებით. როგორ მოუთმენლად ველი, როდის გაიზრდებიან და თქვენამდე მოაღწევენ... ამ პატარა ფრთებით ერთ დღეს თქვენკენ "გამოვფრინდები". ყოველდღე უფრო და უფრო ვიღებ ადამიანის ფორმას.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბარდა'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ამ ეტაპზე შესაძლოა მენსტრუალური ტკივილის მსგავსი კრუნჩხვები იგრძნოთ. საზარდულისა და მუცლის არეში წარმოქმნილი ეს კრუნჩხვები სინამდვილეში ქსოვილის სპაზმის ერთგვარი ფორმაა. ამ მიდამოში შეკუმშული ქსოვილები უეცარ და ძლიერ ტკივილს იწვევს. ხშირად კრუნჩხვა ძილის დროს წვივის კუნთებში ვითარდება. ამასთან, ზედმეტმა გადაღლამ, ტრავმამ, კუნთის დაჭიმვამ ან ერთ პოზაში დიდხანს ყოფნამაც შეიძლება კრუნჩხვები გამოიწვიოს. გულისრევის, ღებინების, ძლიერი სიცხის, კალციუმის დეფიციტის ან სითხის დაკარგვის დროსაც შეიძლება სხეულში კრუნჩხვები განვითარდეს. კრუნჩხვების თავიდან ასაცილებლად ჯდომისას ფეხები შემაღლებულ ზედაპირზე მოათავსეთ, ძილის წინ თბილი შხაპი მიიღეთ, მარცხენა გვერდზე დაიძინეთ, ვარიკოზული ვენების არსებობის შემთხვევაში აუცილებლად გამოიყენეთ კომპრესიული წინდები და მოერიდეთ მაღალქუსლიანი ფეხსაცმლის ტარებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მიულოცეთ საკუთარ თავს მე-6 კვირის დასრულება! თუ გულისრევა სერიოზულად გიშლით ხელს კვებაში, სცადეთ საკვების ცივად მიღება (ცივ საკვებს ნაკლები სუნი აქვს). სისხლის გაზრდილი მოცულობის მხარდასაჭერად არ დაგავიწყდეთ ბევრი წყლის დალევა და რკინით მდიდარი საკვების (ოსპი, წითელი ხორცი) მოხმარების გაზრდა. მეორე თვეში სრულად გადასვლისას, თუ პირველ ულტრაბგერით გამოკვლევაზე ჯერ არ ჩაწერილხართ, უმჯობესია, ის ამ კვირაში დაგეგმოთ.') WHERE id = '4b93f71a-7634-4cda-8990-f4024e3e6d53';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ თქვენი ბავშვის სასქესო ორგანოებს ფორმირება ჯერ არ დაუწყიათ, სხეულის ღრუში უკვე მზად არის სპეციალური უჯრედები, რომლებიც ამ რეპროდუქციულ ორგანოებს წარმოქმნიან. მომდევნო კვირებში ეს უჯრედები თავიანთი საწყისი ადგილიდან იქ გადაინაცვლებენ, სადაც უნდა განთავსდნენ, და ინტენსიური განვითარების პროცესს დაიწყებენ.;;;
ორსულობის დაწყების პროცესში კვერცხუჯრედს X ქრომოსომა აქვს. სპერმატოზოიდიდან მიღებული ქრომოსომის ტიპი კი ერთადერთი ფაქტორია, რომელიც სქესს განსაზღვრავს. თუ ამ ეტაპზე X ქრომოსომის მატარებელი სპერმატოზოიდი X ქრომოსომის მატარებელ კვერცხუჯრედს შეუერთდება, თქვენი ბავშვი გოგო იქნება. ხოლო თუ კვერცხუჯრედის გამანაყოფიერებელი სპერმატოზოიდი Y ქრომოსომას ატარებს, თქვენი ბავშვი ბიჭი იქნება.'), baby_message_ka = COALESCE(baby_message_ka, 'სულ უფრო მეტი დეტალი მიყალიბდება! სახეზე არსებული განსაკუთრებული ნაოჭების გარდა, ახლა უკვე თვალებისთვის განკუთვნილი ადგილებიც ჩნდება. ისინი ორ პატარა შავ წერტილს ჰგავს, მაგრამ ეს ჩემი ფანჯრებია, რომლებითაც სამყაროს დავინახავ. ნეტავ ჩემი თვალები შენსას დაემსგავსება თუ მამიკოსას? ეს ჩვენი ყველაზე ტკბილი საიდუმლო იქნება. ყოველდღე სარკეში ჩავიხედავ და საკუთარ თავში შენს ნაწილს მოვძებნი. შენ ჩემი ყველაზე ლამაზი სანახაობა ხარ. 😊'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბარდის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პირველ სამ თვეში ხშირად წარმოქმნილი აირებისა და საჭმლის მონელების პრობლემების მთავარი მიზეზი ორგანიზმში ჰორმონების დონის მკვეთრი მატებაა. მთელი ორსულობის განმავლობაში ამ ჰორმონების ზემოქმედებით საჭმლის მომნელებელი სისტემის მუშაობა ნელდება. მიღებული საკვები საჭმლის მომნელებელ სისტემაში უფრო ნელა გადაადგილდება. სწორედ ამიტომ, საჭმლის მომნელებელ ტრაქტში საკვების ნელა გავლის გამო შესაძლოა აირებით გამოწვეული ტკივილი გაჩნდეს. ქალებში, რომლებსაც ორსულობამდეც ჰქონდათ საჭმლის მონელების პრობლემები, ორსულობის დროს ამ ჩივილების უფრო მძაფრად გამოვლენის ალბათობა მაღალია. ჰორმონულ ცვლილებებთან ერთად, შებერილობას კვების რეჟიმი და შერჩეული პროდუქტებიც აძლიერებს. აირების წარმომქმნელი საკვების, გაზიანი და მჟავე სასმელების მიღება, ასევე ნაჩქარევად და ჭარბად ჭამა ამ ჩივილებს მნიშვნელოვნად ამწვავებს. ამიტომ უნდა მოერიდოთ უმოძრაობას და განსაკუთრებული ყურადღება მიაქციოთ დაბალანსებულ და რეგულარულ კვებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ კანზე ცვლილებებს ამჩნევთ, გამოიყენეთ სუფთა შემადგენლობის მქონე ბუნებრივი დამატენიანებლები. გულძმარვის თავიდან ასაცილებლად ჭამისთანავე ნუ დაწვებით და მოერიდეთ ცხარე და ჭარბად შეზავებულ საკვებს. ამ პერიოდში, როდესაც ტვინი ასე სწრაფად ვითარდება, ომეგა-3-ის (თევზის ქონი, ნიგოზი) და ფოლიუმის მჟავის მიღება ძალიან მნიშვნელოვანია. დაუთმეთ დრო საკუთარ თავს, მოუსმინეთ საყვარელ მუსიკას — თქვენი ემოციური მდგომარეობა ბავშვზე პირდაპირ აისახება.') WHERE id = '27e9fc4e-13d5-4cb0-8b3a-e813f53aa2f9';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ქვედა კიდურების კვირტები განვითარებას იწყებს. ხელები ფეხებთან შედარებით რამდენიმე დღით წინ არის განვითარებული, ამიტომ ფეხები ჯერ კიდევ უფრო პატარაა. იწყება თირკმელების საფუძვლის ჩამოყალიბება. ემბრიონი კვლავ ასო C-ს ფორმითაა მოხრილი და პატარა „კუდი“ აქვს (ხერხემლის სვეტის გაგრძელება). ეს კუდი რამდენიმე კვირაში გაქრება.'), baby_message_ka = COALESCE(baby_message_ka, 'ახლა უკვე ფეხებიც მიყალიბდება, დედიკო! 🦶 ისინი ჯერ ხელებზე ოდნავ პატარაა და ჩემს კუდს ჰგავს, მაგრამ დროთა განმავლობაში გაიზრდება. ერთ დღეს ამ ფეხებით შენკენ გამოვიქცევი და შენს საპოვნელად ყველა დაბრკოლებას გადავლახავ. ჩემი ხელები და ფეხები... სულ უფრო მეტად ვემსგავსები პატარა ადამიანს, ასე არ არის? ვცდილობ, ისეთი გავხდე, როგორიც შენ წარმოგიდგენივარ. ყოველდღე ახალ ნაბიჯს ვდგამ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბარდის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'მიუხედავად იმისა, რომ ორსულობას სასწაულებრივ მოვლენად და ფიზიოლოგიურ ცვლილებად მოიხსენიებენ, სამედიცინო ლიტერატურაში ის დაავადებადაც არის კლასიფიცირებული. მედიცინაში ორსულობის დაავადებად მოხსენიების ერთ-ერთი მთავარი მიზეზია ის, რომ ნორმაზე რამდენჯერმე გადიდებული საშვილოსნოს მექანიკური ზეწოლის შედეგად ნაწლავები ადგილს იცვლის და იჭყლიტება. გარდა ამისა, ორსულობის დროს სისხლში ესტროგენისა და პროგესტერონის დონის მნიშვნელოვნად მატებასთან დაკავშირებული ცვლილებები, როგორიცაა მკერდის გადიდება და სახესა თუ მუცლის კედელზე პიგმენტაციის ცვლილება, ასევე მიიჩნევა ორსულობის დაავადებად მოხსენიების მიზეზებად. პროგესტერონის მაღალი დონე კუჭისა და ნაწლავების დაცლაზე შესამჩნევ ზემოქმედებას იწყებს. საჭმლის მომნელებელ სისტემაში საკვები არაორსულ ადამიანთან შედარებით გაცილებით ნელა გადაადგილდება. ამიტომ ორსულობის დროს იწყება აირების წარმოქმნა და ყაბზობისკენ მიდრეკილება. მიღებული საკვები კუჭში ორსულობამდელ პერიოდთან შედარებით თითქმის ორჯერ მეტხანს რჩება. საჭმლის მონელების ასეთმა გახანგრძლივებამ შეიძლება გამოიწვიოს ხშირი ბოყინი, მჟავიანობა და გულძმარვა. ექიმების მიერ რეკომენდებული მცირე ულუფებითა და ხშირ-ხშირად კვებაც სწორედ ამ პრობლემების თავიდან აცილებას ემსახურება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ გულმავიწყობას ან ყურადღების გაფანტვას ამჩნევთ, დღის განმავლობაში შესასრულებელი მნიშვნელოვანი საქმეები მოკლე ჩანაწერების სახით ჩამოწერეთ. სხეულის ტემპერატურის მატების გამო ყურადღება მიაქციეთ საკმარისი რაოდენობის სითხის მიღებას და უპირატესობა ბუნებრივი მასალისგან (ბამბა, სელი) შეკერილ ტანსაცმელს მიანიჭეთ. ხანმოკლე, მაგრამ რეგულარული სეირნობა სისხლის მიმოქცევასაც მოაწესრიგებს და განწყობასაც გაგიუმჯობესებთ. თუ მუცლის არეში მწვავე და მუდმივ ტკივილს იგრძნობთ, აუცილებლად მიმართეთ თქვენს ექიმს.') WHERE id = '6de955ee-457a-4e70-930b-f733f0792dec';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინში სასიცოცხლოდ მნიშვნელოვანი უბანი — ჰიპოთალამუსი — ფორმირებას იწყებს. ამ ეტაპზე ჰიპოთალამუსი ბავშვის ტვინის მხოლოდ 1%-ს შეადგენს. ასეთი მცირე ზომის მიუხედავად, ის ტვინის ერთ-ერთი უმნიშვნელოვანესი სტრუქტურაა. ჰიპოთალამუსი მრავალი განსხვავებული ბირთვისგან შედგება. თანამედროვე ტექნოლოგიების გამოყენებითაც კი დღემდე მხოლოდ 16 განსხვავებული ბირთვია გამოვლენილი და თითოეული მათგანი განსხვავებულ, მნიშვნელოვან ფუნქციას ასრულებს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ტვინი იზრდება! 🧠 მაგრამ არ ინერვიულო, ეს კარგი ზრდაა. მის საწყის ნაწილში სამი სხვადასხვა უბანი, სამი „ბუშტუკი“ ჩნდება. ერთი წინა ტვინი გახდება — აზროვნებისა და შეგრძნებისთვის, მეორე — შუა ტვინი, მხედველობისა და სმენისთვის, მესამე კი — უკანა ტვინი, სუნთქვისა და გულისცემისთვის. თითოეულ მათგანს თავისი მნიშვნელოვანი საქმე აქვს. უკვე ძალიან ჭკვიანი ვარ, უბრალოდ ჯერ ლაპარაკი არ შემიძლია. მაგრამ ერთ დღეს შენთვის ბევრი რამ მექნება სათქმელი.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბარდის მარცვალი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ ეტაპზე თქვენი ბავშვის ჯანსაღი განვითარებისთვის კალციუმსა და ფოსფორს ძალიან დიდი მნიშვნელობა აქვს. D2 და D3 ვიტამინები ბავშვის განვითარებისთვის აუცილებელია. ორსულობის დროს D ვიტამინის დღიური დოზა 4000 IU უნდა იყოს. D ვიტამინი ერთ-ერთი ნივთიერებაა, რომელიც ორგანიზმს უჯრედების დაყოფის, ძვლების განვითარებისა და იმუნური სისტემის ფუნქციონირებისთვის სჭირდება. ეს ვიტამინი მხოლოდ ექიმის მეთვალყურეობითა და შესაბამისი ანალიზების ჩატარების შემდეგ უნდა მიიღოთ. ბავშვის ჩამოყალიბების ეტაპზე საჭიროა A ვიტამინი, რომელიც უჯრედებისა და ქსოვილების ზრდას უწყობს ხელს; D ვიტამინი — იმუნიტეტისა და ძვლებისა და კბილების ჯანმრთელობისთვის; C ვიტამინი — იმუნური სისტემისთვის; ხოლო D ვიტამინი — ანემიის პრევენციისა და ძვლების განვითარებისთვის. ეს ვიტამინები ორსულობის ამ პერიოდში უნდა მიიღოთ. ექიმის მეთვალყურეობით D ვიტამინის მიღებით როგორც საკუთარ, ისე თქვენი ბავშვის ჯანმრთელობას დაიცავთ. თუმცა D ვიტამინის თვითნებურად მიღებამ შეიძლება ბავშვს ზიანი მიაყენოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ღრძილების მგრძნობელობის შესამსუბუქებლად მარილიანი წყლის გამოვლება შეიძლება დაგეხმაროთ. თუ ცხვირი გაჭედილი გაქვთ, სცადეთ ოთახში ჰაერის დატენიანება. დღის განმავლობაში განაგრძეთ ცილებითა და კალციუმით მდიდარი საკვების მიღება. თუ გულისრევა ჯერ კიდევ პიკს აღწევს, ჯანჯაფილის ჩაი ან ცივი ხილის ნაჭრები შეიძლება კუჭის დამშვიდებაში დაგეხმაროთ. გახსოვდეთ, რომ თქვენი თითოეული ძალისხმევა ბავშვის ჯანსაღ მომავალს ნიშნავს.') WHERE id = 'b95c279c-175e-4f8c-ab41-1f4ffe11bc78';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ზურგის ტვინის გარშემო არსებული ნერვული მილი უკვე დაიხურა. ნერვული მილის დახურვის პროცესზე მოქმედმა მრავალმა ფაქტორმა შეიძლება გარკვეული ანომალიები გამოიწვიოს. ნერვული მილის დეფექტები ბავშვის ორგანოების ჩამოყალიბების ემბრიონული პერიოდის მე-3 და მე-4 კვირებში ვითარდება, როდესაც თავისა და ზურგის ტვინის წარმომქმნელი ნერვული მილის დახურვისას დარღვევები ხდება. ცნობილია, რომ ნერვული მილის დეფექტები როგორც გენეტიკური, ისე გარემო ფაქტორების ზემოქმედებით ყალიბდება. განსაკუთრებით მნიშვნელოვანია კავშირი ამ პრობლემის განვითარებასა და ფოლატის (ფოლიუმის მჟავის) დეფიციტს შორის. დადგენილია უკუპროპორციული კავშირი ნერვული მილის დაუხურაობასა და ორსულობამდე თუ ორსულობის დროს ფოლიუმის მჟავის დონეს შორის. ამიტომ დაგეგმილი ორსულობის შემთხვევაში ექიმები ფოლიუმის მჟავის დანამატს ორსულობამდე და მთელი პირველი ტრიმესტრის განმავლობაში ნიშნავენ.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თვალები და ყურები უფრო მკაფიოდ ყალიბდება! 👀👂 ჩემი კრიალა თვალებისთვის განკუთვნილი თვალბუდეები შიგნით ღრმავდება, ყურების ადგილებიც უფრო ღრმა ხდება და ყურის ნიჟარის საფუძველს ქმნის. ყველაფერი იმისთვის ემზადება, რომ უკეთ დაგინახო და შენი საოცარი ხმა უფრო მკაფიოდ გავიგონო. ჩემთვის მსოფლიოში ყველაზე ლამაზი სანახაობა შენი სახე იქნება, ყველაზე მშვენიერი მუსიკა კი — შენი ხმა. გისმენ, დედიკო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ბარდა'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს გული თქვენს სხეულში სისხლს ჩვეულებრივზე უფრო სწრაფად გადატუმბავს. შესაბამისად, ბუნებრივად იზრდება 1 წუთის განმავლობაში ორგანიზმში გადასატუმბი სისხლის რაოდენობაც. სისხლის მოცულობა ორსულობის ბოლო დღეებამდე თანდათან მატულობს. ორსულობის ამ ეტაპზე დაწყებული ზრდის შედეგად ბოლო ტრიმესტრში სისხლის მოცულობა დაახლოებით 40%-ით მეტი ხდება. ეს მდგომარეობა თითქმის ყველა ორსულში ჰემოგლობინის ან ჰემატოკრიტის დაბალ მაჩვენებლებს იწვევს. სამედიცინო ენაზე ამ ფიზიოლოგიურ ცვლილებას ორსულობის ბუნებრივ ანემიასაც უწოდებენ. სისხლის მოცულობისა და გულის მიერ გადატუმბული სისხლის რაოდენობის ზრდა ძალიან სასარგებლოა პლაცენტაში სისხლის მიმოქცევისთვის, რომელიც თქვენი ბავშვის კვებას უზრუნველყოფს. ამის წყალობით სისხლის მიმოქცევა ჩქარდება. გარდა ამისა, მნიშვნელოვნად იზრდება სისხლის თეთრი უჯრედების რაოდენობაც. სისხლის თეთრი უჯრედები ორგანიზმის იმუნური სისტემის მუშაობაში მონაწილეობს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'საჭმლის მონელების პრობლემებისა და აირების შეგრძნების შესამცირებლად მიირთვით ბოჭკოვანი საკვები (პარკოსნები, ბოსტნეული), თუმცა კარგად მომზადებული სახით. დღის განმავლობაში მიღებული წყლის რაოდენობა 2 ლიტრზე ნაკლები არ უნდა იყოს. თუ ფეხებში მსუბუქ ტკივილს გრძნობთ, საღამოს წამოწექით და ფეხები ოდნავ შემაღლებულზე მოათავსეთ — ეს სისხლის მიმოქცევას შეუწყობს ხელს. ეცადეთ, ვიტამინები, განსაკუთრებით ფოლიუმის მჟავა, ყოველდღე ერთსა და იმავე დროს მიიღოთ.') WHERE id = '39f4c263-721b-47f4-b527-df452b252fcf';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის პლაცენტა დღეიდან ფორმირებას იწყებს. პლაცენტა ორგანოა, რომელიც თქვენი ორგანიზმიდან მიღებულ სისხლს ფილტრავს და ბავშვს ჭიპლარის მეშვეობით ჟანგბადს, გლუკოზასა და სხვა საკვებ ნივთიერებებს აწვდის. ეს ორგანო ასევე ფილტრავს ნივთიერებებს, რომლებიც შეიძლება თქვენი ბავშვისთვის საზიანო იყოს, და ბავშვის სისხლიდან ნახშირორჟანგსა და ნარჩენ პროდუქტებს გამოდევნის. ამიტომ პლაცენტას სასიცოცხლო მნიშვნელობა აქვს ბავშვის ზრდისთვის, განვითარებისა და სიცოცხლისუნარიანობის შესანარჩუნებლად. ამ ეტაპზე პლაცენტის წარმოქმნა იწყება საშვილოსნოში არსებული არტერიებისა და ვენების, მათი განშტოებების, თქვენი ბავშვის სისხლძარღვებისა და ყვითრის პარკის კედლების გაერთიანებით.;;;
პლაცენტა ასევე გამოიმუშავებს ორსულობის შესანარჩუნებლად საჭირო ჰორმონებს, მათ შორის ესტროგენსა და პროგესტერონს. ამასთანავე, ბავშვის ინფექციებისგან დასაცავად ის ერთმანეთისგან განცალკევებით ინარჩუნებს თქვენს ორგანიზმში მოცირკულირე სისხლსა და ბავშვის სისხლს. ორსულობის დასასრულს კი თქვენი ორგანიზმიდან პლაცენტის გავლით ბავშვს ანტისხეულები გადაეცემა, რომლებიც მას დაბადების შემდეგ დაიცავს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე კუდი მაქვს! 🦖 სასაცილოდ ჟღერს, არა? მაგრამ ნუ შეგეშინდება, ეს დროებითია. ჩემი ხერხემალი იმდენად სწრაფად იზრდება, რომ ჯერჯერობით მისი ერთი ნაწილი კუდს ჰგავს. რამდენიმე კვირაში ის გაქრება და მე ნამდვილ ბავშვს დავემსგავსები. ახლა კი პატარა ზღვის ცხენს ან კოსმონავტს ვგავარ. შენს მუცელში, ამ პატარა კოსმოსში ვცურავ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მოცვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს ვაგინალური გამონადენი, ჩვეულებრივ, ორსულობის პირველი 6-8 კვირის განმავლობაში ჩნდება. ეს იმიტომ ხდება, რომ ამ პერიოდში ორგანიზმში ჰორმონების დონე მნიშვნელოვნად იცვლება. სუსტად გამოხატული სუნის მქონე ვაგინალურ გამონადენს ექიმები ლეიკორეას უწოდებენ. რადგან თქვენს ორგანიზმში ბავშვისთვის უწყვეტი მუშაობა მიმდინარეობს, ორსულობამდე პერიოდთან შედარებით ორსულობის დროს გამონადენის მატება მოსალოდნელია და შეშფოთების საფუძველს არ წარმოადგენს. ორსულობის განმავლობაში საშო უფრო მეტ სეკრეტს გამოიმუშავებს, რათა საშვილოსნოს ყელი ტენიანი შეინარჩუნოს და თქვენი ბავშვი ინფექციებისგან დაიცვას. ორსულობის დროს თეთრი, ლორწოვანი გამონადენი განსაკუთრებით იმატებს ორსულობის ბოლო თვეების მოახლოებისას. ამასთანავე, ორსულობის პერიოდში უნდა მოერიდოთ ტამპონებისა და არაბამბის საცვლების გამოყენებას, რადგან ჰიგიენური მოვლისას მათ შეიძლება საშოში არასასურველი მიკრობების მოხვედრას შეუწყონ ხელი.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თუ სახეზე ლაქები ან გამონაყარი გაგიჩნდებათ, არ დაგავიწყდეთ მზისგან დამცავი SPF კრემის გამოყენება. ორსულობის დროს კანი პიგმენტაციისკენ მიდრეკილია. მზემ შესაძლოა ეს ლაქები გაამუქოს.') WHERE id = '158bcd04-6d72-45a1-8559-e12705e1aa90';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ემბრიონულ პერიოდში, როდესაც თქვენი ბავშვის ორგანოები ყალიბდება, ყველაზე სწრაფად ნერვული სისტემა ვითარდება. ამიტომ თქვენი ბავშვის თავი სხეულზე თითქმის ორჯერ დიდია. თავისა და სხეულის ზომებს შორის ეს შეუსაბამობა ორსულობის მთელი პირველი ტრიმესტრის განმავლობაში შენარჩუნდება.;;;
ამ ეტაპზე გულის მილები, რომლებიც თქვენი ბავშვის გულს წარმოქმნის, ზრდასა და ფორმირებას განაგრძობს. ბავშვის სხეულის ზომის მატებასთან ერთად ეს ორგანო კაპილარების მეშვეობით სხეულის ყველა ნაწილში გადაიტანს უჯრედებისთვის საჭირო საკვებ ნივთიერებებსა და ჟანგბადს, რითაც უჯრედების დაყოფის შენელებას ხელს შეუშლის. ამის წყალობით თქვენი ბავშვის სწრაფი განვითარება ერთი წამითაც არ ჩერდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ხელებს ვამოძრავებ.👋 ჩემი მკლავები გრძელდება და მათ ბოლოებში პატარა, ბრტყელი "ნიჩბები" ჩნდება. ეს ჩემი მომავალი ხელებია. ჯერ თითები არ მაქვს, მაგრამ უკვე ვცდილობ, ხელი დაგიქნიო. ერთ დღეს ამ ხელებით შენს თითს ჩავეჭიდები და აღარასოდეს გავუშვებ. წარმოგიდგენია ის დღე? მე კი წარმოვიდგენ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მოცვი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირებში ალბათ უკვე შენიშნეთ, რომ მუცელი გაგეზარდათ. თუმცა, გავრცელებული წარმოდგენის საპირისპიროდ, ეს ზრდა ჯერ თქვენს ბავშვს არ უკავშირდება. ორგანიზმის ახალ ცვლილებებთან შეგუების პროცესებმა შესაძლოა მუცლის შებერილობა და აირების დაგროვება გამოიწვიოს. მუცლის ზრდა მთლიანად თქვენი სხეულის აგებულებაზეა დამოკიდებული. ზოგ ქალს მუცელი უფრო ადრეულ კვირებში ეტყობა, ზოგს კი — მოგვიანებით. მუცლის გამობერილობის ხარისხი შეიძლება განსხვავდებოდეს წინა ორსულობებისა და მშობიარობების რაოდენობის, მუცლის კუნთების სიმტკიცის, მუცლის მიდამოში ცხიმის რაოდენობისა და მუცლის ღრუს სიგანის მიხედვით. ამიტომ, ორსულობის ერთსა და იმავე კვირაშიც კი, თქვენი მუცლის ზომა შეიძლება სხვა ორსული ქალების მუცლის ზომისგან განსხვავდებოდეს და მათი შედარება აზრს მოკლებულია. ასევე, გავრცელებული წარმოდგენის საპირისპიროდ, თქვენი ბავშვის წონა ან ზომა მუცლის სიდიდის პირდაპირპროპორციული არ არის. ბავშვის წონის განსაზღვრა ან გაზომვა მუცლის ზომის მიხედვით შეუძლებელია. თქვენი ბავშვის ზუსტი გაზომვები მხოლოდ ექიმს შეუძლია ულტრაბგერითი გამოკვლევის (USM) საშუალებით ჩაატაროს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მკერდის მგრძნობელობის შესამცირებლად შხაპის მიღებისას ყურადღება მიაქციეთ, რომ წყალი ძალიან ცხელი არ იყოს. ასევე, ძილის დროს სპორტული ბიუსტჰალტერის ტარებამ შეიძლება დამატებითი მხარდაჭერა უზრუნველყოს და ღამით კომფორტულად დაძინებაში დაგეხმაროთ.') WHERE id = '2e473da0-8eec-4162-84c1-064bd890c011';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირიდან ყურისა და ცხვირის ღრუები იწყებს ჩამოყალიბებას. აგებულებისა და ფუნქციების მიხედვით ყური სამი ნაწილისგან შედგება: გარეთა, შუა და შიგნითა ყურისგან. შიგნითა ყურის ძვლოვანი სტრუქტურები და სასმენი ძვლაკები განვითარებას მე-4 თვემდე აგრძელებს.;;;
ამავე დროს, თქვენი ბავშვის თვალები თავის ორივე მხარეს პატარა შავი წერტილების სახით უკვე შესამჩნევი ხდება. მხედველობის ფუნქციის ჩამოყალიბება კი დაბადების შემდეგ, სინათლესთან პირველი შეხებისას დაიწყება.'), baby_message_ka = COALESCE(baby_message_ka, 'თითები მიყალიბდება, დედიკო! 🖐️ გახსოვს, ჩემი ხელები ნიჩბებს რომ ჰგავდა? ახლა მათ ბოლოებზე პატარა ჩაღრმავებები ჩნდება და ჩემი თითების კონტურები იკვეთება. ისინი ჯერ კიდევ იხვის თათებივით აპკითაა შეერთებული, თუმცა მალე მთლიანად განცალკევდება. უკვე ვემზადები, რომ ხელი ხელს შემოგკრა! ვოცნებობ დღეზე, როცა შენს ხელებს ჩავეჭიდები და თითზე მაგრად მოგიჭერ. ყოველდღე სულ უფრო მეტად ვემსგავსები ადამიანს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ჟოლო'), body_changes_ka = COALESCE(body_changes_ka, 'არაპასტერიზებული რძის პროდუქტები, არასაკმარისად გარეცხილი უმი ბოსტნეული და არასათანადოდ მომზადებული ხორცპროდუქტები (ძეხვი, სოსისი და სხვ.) ტოქსოპლაზმოზის რისკს შეიცავს. ტოქსოპლაზმოზი ერთუჯრედიანი პარაზიტით, „Toxoplasma gondii“-თი გამოწვეული დაავადებაა, რომელიც შეიძლება ნაყოფის განვითარებისთვის საშიშ ინფექციად იქცეს.;;;
ორსულობამდე 1 წლის განმავლობაში გამოყოფილი ესტროგენის რაოდენობა ორსულობისას სულ რაღაც 8 საათში გამოიყოფა, რამაც შეიძლება ძლიერი ემოციური ცვლილებები გამოიწვიოს. ორსულობასთან დაკავშირებული შფოთვისა და შიშების ფონზე ამ მდგომარეობამ შესაძლოა ორსულობის დროს საკმაოდ გავრცელებულ დეპრესიამდე მიგიყვანოთ. თუ ამას გულისრევა, უმადობა, დაღლილობა და ძილის დარღვევებიც დაემატება, მდგომარეობა შეიძლება კიდევ უფრო გართულდეს. პარტნიორის მხარდაჭერა ამ პერიოდის უფრო მარტივად გავლაში დაგეხმარებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თავის ტკივილის დროს მაშინვე ნუ მიიღებთ წამალს. ჯერ ერთი დიდი ჭიქა წყალი დალიეთ, ოთახი გაანიავეთ და კისერზე ცივი კომპრესი დაიდეთ. თავის ტკივილი ხშირად გაუწყლოებით, შიმშილით ან სუფთა ჰაერის ნაკლებობით არის გამოწვეული. ლავანდის ზეთის სუნის ჩასუნთქვაც შეიძლება დაგეხმაროთ.') WHERE id = '1bdeca18-8738-4af3-846b-cfd0a1d5548e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი უკვე მოძრაობს! მართალია, ჯერ თქვენს ხელებს ვერ ჩაეჭიდება, თუმცა მალე გარემოს შესაცნობად ხელების გამოყენებას დაიწყებს. მიიჩნევა, რომ მუცლად ყოფნისას ბავშვის პირველი განვითარებული შეგრძნება შეხებაა.;;;
თქვენი ბავშვის თირკმლები ჩამოყალიბებას იწყებს და მალე შარდის გამომუშავებას შეძლებს. წარმოქმნილი შარდი ამნიონურ სითხეში გამოიყოფა, რათა კვლავ იქნეს გამოყენებული, და ეს ციკლი მშობიარობამდე გაგრძელდება.;;;
მუცლად ყოფნისას ბავშვის ტვინისა და ნერვული სისტემის განვითარებისთვის ყველაზე მნიშვნელოვანი პერიოდი მე-10 კვირამდეა. სწორედ ამ ეტაპზე იწყებს ჩამოყალიბებას ნათხემი — სხეულის წონასწორობის ცენტრი, რომელიც კუნთების მოძრაობებს არეგულირებს. ფოლიუმის მჟავა, რომლის მიღებაც რეკომენდებულია ორსულობამდე და ორსულობის პირველ სამ თვეში, ყველაზე ეფექტური ვიტამინია ბავშვის ტვინისა და ზურგის ტვინის შესაძლო დაავადებებისგან დასაცავად.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ცხვირის წვერი უკვე ჩანს! 👃 ჩემი სახე სულ უფრო ლამაზდება და ფორმას იძენს. უკვე მკაფიოდ ჩანს ჩემი პატარა ნესტოები და ცხვირის წვერი. ზედა ტუჩიც მიყალიბდება. ახლა უფრო მეტად გემსგავსები, დედიკო. ნეტავ ცხვირი შენი მაქვს თუ მამიკოსი? ამის გასაგებად ჯერ კიდევ გვაქვს დრო, მაგრამ უკვე ძალიან საყვარელი ვარ. მე შენი ყველაზე ლამაზი და განუმეორებელი ქმნილება ვარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ჟოლო'), body_changes_ka = COALESCE(body_changes_ka, 'გულისრევის გამო შესაძლოა მადა დაგიქვეითდათ. ამან შეიძლება დროებით წონის კლება გამოიწვიოს. ნუ შეშფოთდებით — პირველი ტრიმესტრის ბოლოს გულისრევა თანდათან შემცირდება. სიმპტომების შემსუბუქებამდე ჯანსაღი და დაბალანსებული კვების რეჟიმი დაიცავით: მიირთვით ვიტამინებით მდიდარი მწვანე ფოთლოვანი ბოსტნეული, პარკოსნები, თევზი და წითელი ხორცი.;;;
ბავშვის ჯანმრთელად დაბადებისთვის აუცილებელია, რომ დედა საკმარისად და დაბალანსებულად იკვებებოდეს. ამ პერიოდში არასაკმარისი და დაუბალანსებელი კვება უარყოფითად იმოქმედებს ბავშვის სიმაღლეზე, წონაზე, ფიზიოლოგიურ აგებულებასა და გონებრივ განვითარებაზე. თუ დილის გულისრევა გაწუხებთ, საწოლთან იქონიეთ კუჭის დამამშვიდებელი საკვები, მაგალითად კრეკერი, რათა ადგომამდე მსუბუქად წაიხემსოთ. ასევე, დღის განმავლობაში სამი დიდი ულუფის ნაცვლად ხუთი მცირე ულუფის მიღება კუჭთან დაკავშირებულ ჩივილებს მნიშვნელოვნად შეამცირებს. არ დაგავიწყდეთ, მოერიდოთ ცხიმიან და ცხარე საკვებს!'), daily_tip_ka = COALESCE(daily_tip_ka, 'სხეულის ტემპერატურის მატებასთან დაკავშირებით ყოველდღიურად განაგრძეთ სულ მცირე 2-2.5 ლიტრი წყლის დალევა. საზარდულის არეში ტკივილის შესამცირებლად მოერიდეთ უეცარ მოძრაობებს და ჯდომისას პოზა ხშირად შეიცვალეთ. რკინის შეწოვის გასაუმჯობესებლად მიირთვით C ვიტამინით მდიდარი ხილი. დაღლილობის შესამცირებლად დღის განმავლობაში სუფთა ჰაერზე 10-წუთიანი გასეირნებები მოაწყვეთ.') WHERE id = 'ae02afe4-0993-46aa-a116-88a385d90304';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში ულტრაბგერითი გამოკვლევით შესაძლებელია CRL-ის, ანუ თხემ-კუდუსუნის სიგრძის გაზომვა. ბოლო მენსტრუაციის თარიღთან შედარებით ეს მაჩვენებელი უფრო ზუსტ ინფორმაციას იძლევა ორსულობის ვადის შესახებ. ამიტომ მათთვის, ვისაც ბოლო მენსტრუაციის თარიღი არ ახსოვს, ეს გაზომვა საორიენტაციოა და მშობიარობის სავარაუდო თარიღის განსაზღვრაში ეხმარება. თქვენი ბავშვის კანი იმდენად თხელია, რომ ფორმირების პროცესში მყოფი კაპილარები კანიდან ჩანს. მომდევნო კვირებში კანქვეშა ცხიმოვანი ქსოვილის განვითარებასთან ერთად კანი გასქელდება და ჩვეულებრივ იერს მიიღებს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ჟოლოს ზომის ვარ! 🍇 ჩემი გული წუთში 150-170-ჯერ ცემს. ის ისეთივე სწრაფი და ძლიერია, როგორც სარბოლო ცხენის გული! გარეგნულად მშვიდად რომც იყოთ, მე შიგნით მარათონს გავრბივარ. შენი და ჩემი გული ერთ სხეულში, სხვადასხვა რიტმით, მაგრამ ერთნაირი სიყვარულით ცემს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ჟოლო'), body_changes_ka = COALESCE(body_changes_ka, 'მზარდი საშვილოსნოს საჭიროებების დასაკმაყოფილებლად სისხლის მოცულობა პირველი ტრიმესტრიდან იწყებს მატებას. ორგანიზმში სწრაფად მომატებული სისხლის მოცულობა თქვენ და თქვენს ბავშვს მავნე ზემოქმედებისგან გიცავთ. ამასთან, სისხლის გაზრდილი მოცულობა დამცავ ფუნქციას ასრულებს მშობიარობის დროს მოსალოდნელი სისხლის დანაკარგის გამო.;;;
C ვიტამინი ორსულობის დროს ძალიან მნიშვნელოვანია თქვენი ბავშვის ქსოვილების განვითარებისა და რკინის ათვისებისთვის. კვლევები აჩვენებს, რომ C ვიტამინი პრეეკლამფსიის პრევენციას უწყობს ხელს. ამ ვიტამინის მწვავე დეფიციტმა შეიძლება ნაადრევი მშობიარობის რისკი შექმნას.;;;
ახლა, როცა ორსულობის 2 თვე უკვე გაიარეთ, შესაძლოა წელი გაგისქელდათ, თუმცა ჯერ ორსულის იერი არ გაქვთ. მიუხედავად იმისა, რომ გარეგნულად შესამჩნევი ცვლილება არ ჩანს, ჰორმონების ზემოქმედებით თქვენი ემოციური მდგომარეობა მნიშვნელოვნად შეიცვალა. ორგანიზმში სისხლის მომატებული მოცულობის გამო უფრო ხშირად გიჩნდებათ შარდვის საჭიროება და თავბრუსხვევაც მატულობს. სისხლის მოცულობის ზრდა გაფართოებული სისხლძარღვებითაც შეიძლება შეამჩნიოთ; ასევე შესაძლოა ცხვირიდან სისხლდენაც გქონდეთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ღამით შარდვის საჭიროების შესამცირებლად საღამოს საათებში სითხის მიღება ოდნავ შეამცირეთ, თუმცა დღის პირველ ნახევარში ბევრი წყალი დალიეთ. კანის ცვლილებების შესამსუბუქებლად შეგიძლიათ ქიმიური ნივთიერებებისგან თავისუფალი ბუნებრივი ზეთებით (ნუშის ან ქოქოსის ზეთი) მასაჟი გაიკეთოთ. ყურადღება მიაქციეთ პირის ღრუსა და კბილების ჯანმრთელობას — ღრძილები შესაძლოა ჯერ კიდევ მგრძნობიარე იყოს. დღის განმავლობაში ცილებისა და ვიტამინების ბალანსის შესანარჩუნებლად უხვად მიირთვით სხვადასხვა ფერის ბოსტნეული.') WHERE id = '73404991-93fd-4ff5-9245-6a011e7e870b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ ხელები და ფეხები ჯერ კიდევ ფარფლებს ჰგავს, მკლავები და ფეხები უკვე ფიზიკურად ყალიბდება. მალე პატარა თითებიც დაიწყებს ფორმირებას და თქვენი ბავშვი უფრო მკაფიო იერს შეიძენს.;;;
ტვინის ნახევარსფეროები, რომელთა 78%-ს წყალი შეადგენს, უკვე კარგად შესამჩნევი ხდება. მარჯვენა ნახევარსფერო პასუხისმგებელია გაგებაზე, ამოცნობაზე, მხედველობაზე, წარმოსახვასა და მარცხენა ხელის მართვაზე, ხოლო მარცხენა ნახევარსფერო — წერაზე, მეტყველებაზე, აზროვნებაზე, ანალიზზე, მარჯვენა ხელის მართვასა და ლოგიკურ ფუნქციებზე.'), baby_message_ka = COALESCE(baby_message_ka, 'მე მოცვის მარცვლის ზომის ვარ! 🫐 გჯერათ? გასული კვირის შემდეგ ჩემი ზომა გაორმაგდა! ძალიან სწრაფად ვიზრდები, დედიკო. ყველაფერი, რასაც მიირთმევთ, ჩემამდე სამშენებლო მასალასავით აღწევს. გმადლობთ, რომ ჩემთვის ჯანსაღად იკვებებით. ჩვენ ერთად ვიზრდებით და ერთად ვძლიერდებით. თქვენ ჩემი საუკეთესო თანაგუნდელი ხართ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მოცვი'), body_changes_ka = COALESCE(body_changes_ka, 'სისხლდენა შეიძლება ორსულობის ნებისმიერ ეტაპზე განვითარდეს. სისხლი შეიძლება წითელი ან ყავისფერი იყოს. თითქმის ყველა ორსულს ორსულობის პირველ კვირებში მცირე ლაქები ან სისხლდენა აღენიშნება. ორსულობის რომელ ეტაპზეც უნდა განვითარდეს ვაგინალური სისხლდენა და როგორი მცირე რაოდენობისაც უნდა იყოს ის, ყოველთვის სერიოზულ მდგომარეობად უნდა ჩაითვალოს და ექიმთან მიმართვას საჭიროებს. პირველ 3 თვეში განვითარებული მცირე სისხლდენა, ჩვეულებრივ, მუცლის მოშლის საფრთხედ განიხილება. მეორე 3 თვეში განვითარებული მცირე სისხლდენა კი, როგორც წესი, საშვილოსნოს ყელის უკმარისობის ნიშანია და მსუბუქ ტკივილს ახლავს თან. ბოლო 3 თვეში სისხლდენა, მცირე რაოდენობის შემთხვევაშიც კი, უკიდურესად საყურადღებოა. ეს შეიძლება იყოს ისეთი პრობლემების ნიშანი, როგორიცაა პლაცენტის საშვილოსნოს ქვედა ნაწილში მდებარეობა ან პლაცენტის ნაადრევი აცლა.;;;
ორსულობის განმავლობაში თავი უნდა აარიდოთ ზედმეტ გადაღლასა და მძიმე სამუშაოს. ასეთმა დატვირთვამ შეიძლება საშვილოსნოს შეკუმშვები გამოიწვიოს. საშვილოსნოს შეკუმშვებმა კი შესაძლოა სისხლდენა განაპირობოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დააჯილდოეთ საკუთარი თავი მე-7 კვირის წარმატებით დასრულებისთვის (მაგალითად, საყვარელი ხილით). შეკრულობისა და შებერილობის შესამცირებლად ბოჭკოვან საკვებთან ერთად ბევრი სითხე მიიღეთ. ღრძილების ჯანმრთელობისთვის კვლავ რბილი ჯაგრისი გამოიყენეთ. თუ დაღლილობა ჯერ კიდევ არ გაგივლიათ, თავს ძალას ნუ დაატანთ; დღის განმავლობაში ხანმოკლე ძილი ენერგიის აღდგენაში დაგეხმარებათ.') WHERE id = '8a7c667d-259c-4117-9c65-d0fc403d0248';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი ბოლო ერთი კვირის განმავლობაში ორჯერ გაიზარდა. მისი ტვინი სწრაფად განაგრძობს განვითარებას და ეს პროცესი 4 წლის ასაკამდე მაღალი ტემპით გაგრძელდება. დაბადების მომენტისთვის ბავშვს ტვინის მილიარდობით უჯრედი აქვს. მიუხედავად იმისა, რომ მათი უმეტესობა ჯერ ერთმანეთთან დაკავშირებული არ არის, დაბადების შემდეგ ეს უჯრედები სმენის, მხედველობის, შეხების, გემოსა და ყნოსვის სიგნალების მეშვეობით ერთმანეთთან დაკავშირებას იწყებს.;;;
ამ კვირაში საყლაპავი და სასუნთქი მილიც იწყებს ფორმირებას.;;;
რადგან თქვენი ბავშვის სახე ჯერ სრულად არ არის ჩამოყალიბებული, მას შეუძლია ხელი პირისკენ წაიღოს, თუმცა წოვის რეფლექსისთვის ჯერ ძალიან ადრეა.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ხელები ნიჩბებს ჰგავს, ფეხები კი — ფარფლებს! 🐟 ჯერ კიდევ წყალში მცხოვრებ არსებას ვგავარ, მაგრამ ყველაფერი იცვლება. მკლავები მიგრძელდება, იდაყვები კი მეხრება. ჩემი გული თქვენთვის კვლავ „ბაგა-ბუგით“ ძგერს. როდესაც თქვენ ისვენებთ, მეც ვისვენებ, ხოლო როცა მოძრაობთ, მეც ვირწევი. ჩვენი ჰარმონია სრულყოფილია. მიყვარხართ, დედა!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მოცვი'), body_changes_ka = COALESCE(body_changes_ka, 'პლაცენტის მიერ გამოყოფილი ჰორმონი ესტროგენი გემოსა და ყნოსვის შეგრძნებას ჩვეულებრივზე მეტად აძლიერებს. ამასთანავე, შეიძლება საკვების მიმართ განსაკუთრებული სურვილები გაგიჩნდეთ, ხოლო უსიამოვნო სუნებისადმი მომატებულმა მგრძნობელობამ გულისრევა გამოიწვიოს. ამ პერიოდში გულისრევის შესამცირებლად სასურველია, გარკვეული ხნით მოერიდოთ უხვად შეზავებულ და შემწვარ საკვებს. თუ ჰორმონული ცვლილებების გამო თავს მოუსვენრად გრძნობთ, ნელი ტემპით სეირნობა, დამამშვიდებელი მუსიკა, თბილი შხაპი და ორსულთა იოგა დაგეხმარებათ.;;;
ექიმთან ვიზიტისას სასარგებლოა, ყველა შეკითხვა წინასწარ ჩაიწეროთ ფურცელზე. ამგვარად, დროს მაქსიმალურად ეფექტურად გამოიყენებთ. ორსულობის პირველი გამოკვლევისას ექიმმა თქვენს ბავშვთან და ორსულობასთან დაკავშირებული რისკფაქტორები უნდა შეაფასოს. დედისა და მამის გენეტიკური ისტორიის ცოდნა ორსულობის განმავლობაში შესაძლო სირთულეების უკეთ შეფასებას შეუწყობს ხელს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ კვირიდან თქვენი ორგანიზმის მოთხოვნილება მაგნიუმსა და კალციუმზე კიდევ უფრო იზრდება; რაციონში შეინარჩუნეთ ბანანი, ნიგოზი და რძის პროდუქტები. წელის ტკივილის თავიდან ასაცილებლად ჯდომისას ზურგს უკან პატარა ბალიში მოათავსეთ. თუ სუნებისადმი მგრძნობელობა ჯერ კიდევ მაღალია, ოთახები ხშირად გაანიავეთ. გახსოვდეთ, რომ თქვენი სიმშვიდე ბავშვის ნერვული სისტემის განვითარებისთვის საუკეთესო გარემოა.') WHERE id = '9437ad06-6476-41de-b64c-c5fddd89e286';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირიდან უკვე შეგიძლიათ თქვენი ბავშვის გულისცემა მოისმინოთ. ბავშვის გული დედის საშვილოსნოში მიმაგრებიდან არაუგვიანეს 3 კვირისა იწყებს ცემას. ეს ორსულობის მე-5 და მე-6 კვირებს ემთხვევა. ამიტომ ორსულობის მე-7 კვირაში ბავშვის გულისცემის მოსმენა უკვე შესაძლებელია.;;;
თუმცა, გვიანი განაყოფიერების, არარეგულარული მენსტრუაციის ან ბოლო მენსტრუაციის ზუსტი თარიღის არცოდნის გამო, შესაძლოა გულისცემა ჯერ კიდევ არ ისმოდეს. ასეთ შემთხვევაში მის მოსასმენად შესაძლოა კიდევ 1-2 კვირა იყოს საჭირო.;;;
ტვინი, რომელიც ცენტრალური ნერვული სისტემის უმნიშვნელოვანესი ნაწილია, სწრაფად განაგრძობს განვითარებას. თქვენი ბავშვის საშუალო სიგრძე უკვე 1-2 სმ-ს, წონა კი 1,5 გრამს აღწევს. ამ კვირაში ბავშვის სხეულში ორგანოების მდებარეობა უკვე განსაზღვრულია. ერთ-ერთი ასეთი ორგანოა ფილტვი. თუმცა ამ საოცარი ორგანოს განვითარება მხოლოდ 38-ე კვირაში სრულდება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ვმოძრაობ, დედიკო! 💃 ამას ჯერ ვერ გრძნობთ, რადგან ძალიან მსუბუქი ვარ, მაგრამ აქ, შიგნით, პატარა ცეკვებს ვასრულებ. სხეულს მარჯვნივ და მარცხნივ ვხრიდი და პატარა მკლავებს ვამოძრავებ. ეს ჩემი პირველი ვარჯიშია და იმის დასტურია, რომ ნერვულმა სისტემამ ჩემს კუნთებთან ურთიერთობა დაიწყო. ჩემი კუნთები ძლიერდება, რათა მომავალში მაგრად ჩაგეხუტოთ. თქვენ დაისვენეთ, მე კი ვივარჯიშებ, რადგან ზრდა მოძრაობას ნიშნავს!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ჟოლო'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირის ბოლოს ჰორმონების მატებისა და ცვლილებების გამო კანზე შესაძლოა აკნე გაგიჩნდეთ. ასეთ შემთხვევაში ეცადეთ, კანი სუფთა და მშრალი შეინარჩუნოთ. აკნეს საწინააღმდეგო მედიკამენტების გამოყენებამ შესაძლოა ბავშვის განვითარების მანკები გამოიწვიოს, ამიტომ ექიმის თანხმობის გარეშე არავითარი სამკურნალო საშუალება არ უნდა გამოიყენოთ.;;;
ორსულობის პერიოდში შესაძლოა ფრჩხილები გათხელდეს, დარბილდეს და ადვილად მტვრევადი გახდეს. საოჯახო საქმეების შესრულებისას ხელთათმანების გამოყენება ამ პერიოდში მნიშვნელოვნად დაგეხმარებათ. თუ კანზე გამობერილ სისხლძარღვებს ან ვარსკვლავისებრ სისხლძარღვოვან ბადეებს ამჩნევთ, ნუ შეშფოთდებით. ეს მდგომარეობა ჰორმონ ესტროგენის ზემოქმედებით არის გამოწვეული. თუ მომატებული არტერიული წნევის გამო ქოშინი გაწუხებთ, სუნთქვის სწორი ტექნიკებით მდგომარეობის შემსუბუქება შეგიძლიათ. თუ მუცლის მოშლის საფრთხე არ გაქვთ და ექიმსაც საწინააღმდეგო მითითება არ მოუცია, სქესობრივი კავშირისგან თავის შეკავების საჭიროება არ არსებობს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ღრძილების მგრძნობელობისა და ბავშვის კბილების ჩანასახების ფორმირებისთვის განსაკუთრებული ყურადღება მიაქციეთ კალციუმის მიღებას (რძე, ხაჭო, ისპანახი). თუ გულისრევა შემცირდა, რაციონს მეტი ახალი ბოსტნეული დაამატეთ. დღის განმავლობაში მოულოდნელი დაღლილობისას 15-20 წუთით შეისვენეთ. დაიწყეთ კომფორტული ტანსაცმლის შერჩევა, რათა მუცლის არე არ მოგეჭიროთ.') WHERE id = 'c99602ee-b4cc-4358-a321-f5e26f5f82fb';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირიდან თქვენს ბავშვს უკვე აქვს კუჭქვეშა ჯირკვალი, რომელიც მზად არის სისხლში შაქრის დონის მარეგულირებელი ჰორმონის — ინსულინის — გამოსამუშავებლად. ინსულინი სისხლში არსებული შაქრის უჯრედებში გადასვლას უზრუნველყოფს და ამგვარად უჯრედების ენერგეტიკულ საჭიროებებს აკმაყოფილებს. ამის შედეგად სისხლში შაქრის დონეც მცირდება.;;;
ამ კვირიდან დაიწყო აპენდიქსის ჩამოყალიბება, რომელშიც საჭმლის მომნელებელი სისტემისთვის საჭირო სასარგებლო ბაქტერიები ინახება. ჩამოყალიბების პროცესში მყოფი აპენდიქსის წყალობით, თქვენი ბავშვის ორგანიზმი 4-ჯერ უფრო მდგრადი იქნება ისეთი დაავადებების მიმართ, რომლებსაც თან ახლავს ცხელება, დიარეა, გულისრევა და მუცლის ტკივილი.;;;
თქვენი სწრაფად განვითარებადი ბავშვის სარძევე კბილების ჩანასახები და გემოვნების კვირტები უკვე იწყებს ჩამოყალიბებას. მალე ბავშვი სანაყოფე წყლის ყლაპვას დაიწყებს და მისი მეშვეობით ზოგიერთ გემოს გაარჩევს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემო საყვარელო დედიკო! დღეს უკვე შემიძლია, ჩემი პატარა ხელები ერთმანეთს შემოვკრა! ჯერ ძალიან პატარა ვარ, მაგრამ ჩემი თითები უკვე სრულიად დამოუკიდებლად მოძრაობს. შენი ხმა ისეთი ნაცნობია ჩემთვის... როცა ლაპარაკობ, მე შიგნიდან ყურადღებით გისმენ. შენი სიყვარული ყოველდღე ცოტათი უფრო მზრდის. რა კარგია, რომ შენ ხარ ჩემი სამყარო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'წითელი ლობიო'), body_changes_ka = COALESCE(body_changes_ka, 'ჰორმონული ცვლილებების შედეგად, ამ პერიოდში შესაძლოა კანზე ისეთი ცვლილებები შენიშნოთ, როგორიცაა სიმშრალე ან ცალკეულ უბნებში ცხიმიანობის მომატება. თუ კანზე არათანაბარი ყავისფერი ლაქები გაგიჩნდათ, ამას ორსულობის ნიღაბი ეწოდება და ის მშობიარობის შემდეგ ქრება. ორსულობის ნიღბისგან თავის დასაცავად სასარგებლოა ფოლიუმის მჟავის რეგულარულად მიღება, მზეზე დამცავი საშუალების გარეშე არ ყოფნა და კანის მოვლის პროდუქტების სიფრთხილით გამოყენება.;;;
ორსულობისას გამოყოფილი ჰორმონების მიერ სისხლის წნევის მომატების შედეგად შესაძლოა მკერდში სისავსის შეგრძნება გქონდეთ. თუ ეს მდგომარეობა გაწუხებთ, შეგიძლიათ უპირატესობა მიანიჭოთ დამჭერ ან უფრო დიდი ზომის ბიუსტჰალტერს. ორსულობის პერიოდში ჰორმონებმა შესაძლოა უფრო სტრესული გაგხადოთ. საყვარელი საქმიანობებით დაკავება სტრესის შემცირებაში როგორც ფიზიკურად, ისე ემოციურად დაგეხმარებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდში მკაფიო და ზოგჯერ შემაწუხებელი სიზმრების ნახვა ნორმალურია; ძილის წინ გონების დამამშვიდებელი მუსიკის მოსმენა ან თბილი შხაპის მიღება დაგეხმარებათ. წელის ტკივილის თავიდან ასაცილებლად დიდხანს ნუ დარჩებით ერთსა და იმავე პოზაში. კბილების ჯანმრთელობისთვის კვლავ მიირთვით კალციუმით მდიდარი საკვები. ყოველდღე მოუსმინეთ თქვენი სხეულის სიგნალებს და ზედმეტად ნუ გადაიღლებით.') WHERE id = 'a614becc-2914-4d7d-98c2-e4eb413c2293';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ დღეებში, როცა თითები თანდათან მკაფიოდ ყალიბდება, თითის ანაბეჭდებიც კი იწყებს წარმოქმნას. თითის ანაბეჭდი თითების ბოლო სახსარსა და წვერებზე არსებული ხაზებით წარმოქმნილი, თითოეული ადამიანისთვის უნიკალური მოხაზულობაა. თქვენი ბავშვის ხელებსა და ფეხებში ძვლოვანი ქსოვილი სწრაფად ვითარდება, იდაყვები კი ფორმირებას იწყებს. მიუხედავად ამისა, მას ჯერ კიდევ აქვს პატარა „კუდი“. მომდევნო რამდენიმე კვირის განმავლობაში ეს კუდი დაპატარავდება და გაქრება. სანამ კუდი არსებობს, თქვენს ბავშვს ემბრიონი ეწოდება. მე-11 და მე-12 კვირის შემდეგ, როდესაც კუდი მთლიანად გაქრება, ის ნაყოფის განვითარების ეტაპზე გადავა.'), baby_message_ka = COALESCE(baby_message_ka, 'დღეს მე-8 კვირას ვასრულებთ! 🎉 უკვე ოფიციალურად ვემზადები, რომ „ემბრიონიდან“ „ნაყოფად“ გადავიქცე. ყველა მნიშვნელოვანი ორგანო — გული, ტვინი, კუჭი და ფილტვები — უკვე თავის ადგილზეა. ახლა მხოლოდ ზრდის, მომწიფებისა და გალამაზების დროა. ორსულობის ყველაზე რთული და სახიფათო პერიოდი უკან მოვიტოვეთ, დედიკო. შენ ძალიან კარგად დამიცავი, მადლობელი ვარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'წითელი ლობიო'), body_changes_ka = COALESCE(body_changes_ka, 'ახლა, როდესაც ორსულობის პირველი ტრიმესტრის დასასრულს უახლოვდებით, თქვენი გული სისხლძარღვებში უფრო მეტი სისხლის გადატუმბვას იწყებს. ორსულობის პერიოდში გულისცემა ჩვეულებრივზე უფრო ჩქარდება. შესაბამისად, ბუნებრივად იზრდება სისხლის რაოდენობაც, რომელიც სხეულში 1 წუთის განმავლობაში უნდა გადაიტუმბოს. სისხლის წნევა უმაღლეს ნიშნულს ორსულობის მე-3 ტრიმესტრში აღწევს.;;;
ორსულობის პერიოდში კანის ერთ-ერთი ყველაზე გავრცელებული ცვლილება პიგმენტაციის ცვლილებაა. ეს მდგომარეობა, როგორც წესი, მუქი კანის მქონე ქალებში ვლინდება ძუძუსთავების, სასქესო ორგანოების მიდამოსა და ჭიპის გარშემო კანის ფერის მსუბუქი გამუქებით.'), daily_tip_ka = COALESCE(daily_tip_ka, 'მეორე თვის წარმატებით დასრულების აღსანიშნავად საკუთარ თავს პატარა საჩუქარი გაუკეთეთ და დაისვენეთ. რადგან თქვენი სისხლის მოცულობა იზრდება, განსაკუთრებული ყურადღება მიაქციეთ რკინითა და ცილებით მდიდარ საკვებს (ოსპი, წითელი ხორცი, კვერცხი). თუ წელის ტკივილი გაწუხებთ, ძილის დროს ფეხებს შორის ბალიშის მოთავსებამ შეიძლება შვება მოგიტანოთ. მომავალ კვირას მესამე თვის პირველი ნაბიჯები გველოდება. როდესაც ემოციურ დაძაბულობას იგრძნობთ, ღრმად ჩაისუნთქეთ და თქვენს ბავშვს ესაუბრეთ.') WHERE id = 'fb6fb148-4851-4c47-b527-c43ee9bf7d0f';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ტვინის ქსოვილი უკიდურესად სწრაფად განაგრძობს განვითარებას. ტვინის ის უბანი, რომელიც კუნთების მოძრაობებს არეგულირებს, ფუნქციონირებას იწყებს. ეს ნიშნავს, რომ თქვენს ბავშვს უკვე შეუძლია მოძრაობა. ამ მცირე, ბიძგების მსგავს მოძრაობებს ჯერ ვერ იგრძნობთ.;;;
ამ ეტაპზე თქვენს ბავშვს უკვე შეუძლია რეაგირება, თუ მსგავს სტიმულს შეხვდება. განვითარებადი ნერვული სისტემა კუნთებთან კავშირის დამყარებას იწყებს. ისევე, როგორც მთელ სხეულში, სახეზეც ნელ-ნელა ყალიბდება ძვლები და ხრტილები; განსაკუთრებით შესამჩნევი ხდება პირის ღრუ და სასა.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ვასლოკინებ! 🤭 შეიძლება არ დაიჯერო, მაგრამ ჩემი დიაფრაგმა (სუნთქვის კუნთი) ყალიბდება და სლოკინი მეწყება. შენ ამას ჯერ ვერ გრძნობ, რადგან ძალიან პატარა ვარ და უხმოდ ვასლოკინებ. ეს ჩემი მომავალი სუნთქვითი ვარჯიშია. სიცოცხლისთვის მზადება მიმდინარეობს! შენს მუცელში ზრდასთან ერთად სულ უფრო მეტ უნარს ვიძენ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'წითელი ლობიო'), body_changes_ka = COALESCE(body_changes_ka, 'შესაძლოა გაწუხებდეთ მუდმივი ძილიანობა, თავის ტკივილი, კუჭის სპაზმები და სისუსტე. ეს მდგომარეობა ორსულობისას სისხლში დიდი რაოდენობით გამოყოფილი ჰორმონებით — ესტროგენითა და პროგესტერონით — არის გამოწვეული. ამ კვირებში საზარდულის ტკივილი ბევრ მომავალ დედას აწუხებს და უმეტეს შემთხვევაში საფრთხეს არ წარმოადგენს.;;;
გამონადენის მომატებულმა რაოდენობამ ნუ შეგაშფოთებთ. ორჯერ გაზრდილი საშვილოსნო თქვენი ბავშვისთვის ჯანსაღი გარემოს უზრუნველსაყოფად დიდი რაოდენობით სეკრეტს გამოიმუშავებს.;;;
თქვენს სხეულს ახლა ჩვეულებრივზე მეტი წყალი სჭირდება. დღეში სულ მცირე 10 ჭიქა წყლის დალევა ამ საჭიროებას დააკმაყოფილებს.;;;
ზოგიერთი საკვების მიმართ ძლიერ სურვილს ხალხში ორსულობის ახირებას უწოდებენ. მისი ზუსტი მიზეზი ბოლომდე ცნობილი არ არის, თუმცა მიიჩნევა, რომ ამაში როლს ასრულებს ორსულობისას მიმდინარე ჰორმონული ცვლილებები და მათთან დაკავშირებული სისხლში შაქრის დონის ცვალებადობა. საკვებისადმი ძლიერი სურვილი მე-12 კვირიდან კლებას იწყებს. თუ ის უფრო დიდხანს გრძელდება, ჩვეულებრივ, ფსიქოლოგიური მიზეზებით არის განპირობებული. გარდა ორგანიზმისთვის აუცილებელი საკვების მიმართ მკვეთრი უმადობისა და მათი არასაკმარისად მიღებისა, ორსულობის ახირებას ცნობილი ზიანი არ ახლავს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ კვირაში შესაძლოა ჩვეულებრივზე მეტად დაღლილად იგრძნოთ თავი; დღის განმავლობაში ხშირად, მაგრამ ხანმოკლედ დაისვენეთ. თქვენი ორგანიზმი ბავშვის სწრაფი ზრდისთვის დიდ ენერგიას ხარჯავს, ამიტომ რაციონში გაზარდეთ ცილოვანი საკვების (ოსპი, ნიგოზი, კვერცხი) რაოდენობა. ღრძილების მგრძნობელობის გამო განსაკუთრებული ყურადღება მიაქციეთ პირის ღრუს ჰიგიენას. თუ ჯერ კიდევ ტოქსიკოზი გაწუხებთ, ეცადეთ, დღის განმავლობაში მცირე ულუფებით იკვებოთ.') WHERE id = 'bef0eb9c-a062-4017-9195-e0a1a182972b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თავის ორივე მხარეს პატარა შავი წერტილების სახით არსებული თვალები, პიგმენტების გამომუშავების მატებასთან ერთად, უკვე სრულად შესამჩნევი გახდა. თქვენი ბავშვის ქუთუთოები ფორმირებას იწყებს, თუმცა ისინი კიდევ დიდხანს იქნება დახურული.;;;
თქვენი ბავშვი წარმოუდგენელი სისწრაფით ფორმირდება და იზრდება. უჯრედებისთვის საჭირო ენერგიის მისაღებად მას გლუკოზა სჭირდება. თქვენი ბავშვი, რომელსაც ჯერ კიდევ ემბრიონი ეწოდება, ამ საჭიროებას საშვილოსნოში წარმოქმნილი პლაცენტის მეშვეობით იკმაყოფილებს. საკვები, რომელსაც მიირთმევთ, სისხლის მიმოქცევის გზით და პლაცენტის დახმარებით ბავშვს მიეწოდება.;;;
თქვენი ბავშვის ნაწლავები სწრაფად იზრდება, ამიტომ ისინი დახვეულია და განვითარების დასრულებამდე ასე განაგრძობს ზრდას. მსხვილი ნაწლავი უფრო ნელა იზრდება, ამიტომ მას შედარებით სწორი აგებულება აქვს. ნაწლავებს მუცლის ღრუში თავიანთი საბოლოო ადგილის დასაკავებლად კიდევ ცოტა დრო სჭირდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ქუთუთოები მიყალიბდება! 👁️ თვალების დასაცავად ქუთუთოები მეფორმირება და ისინი მალე ერთმანეთს შეუერთდება და დაიხურება. დაახლოებით 27-ე კვირამდე თვალებს არ გავახელ. ახლა ჩემს შინაგან სამყაროზე ვარ კონცენტრირებული და ხანგრძლივი ძილის რეჟიმზე გადავდივარ. მაგრამ არ ინერვიულო — დახუჭული თვალებითაც შევძლებ სინათლის შეგრძნებას. წარმოსახვაში შენს სახეს დავხატავ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'წითელი ლობიო'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი საშვილოსნო, რომელიც ორსულობამდე დაახლოებით 60 გრამს იწონიდა, ორჯერ გაიზარდა. რადგან მზარდი საშვილოსნო შარდის ბუშტზე ზეწოლას ახდენს, შესაძლოა ტუალეტში უფრო ხშირად მოგიწიოთ სიარული. ორსულობის პროგრესირებასთან და საშვილოსნოს ზემოთ აწევასთან ერთად შარდის ბუშტზე ზეწოლა შემცირდება და ხშირი შარდვის ჩივილიც შესუსტდება.;;;
საშვილოსნო, რომელშიც თქვენი ბავშვი სწრაფად იზრდება, ორსულობისას მუცლის გადიდების მთავარი განმაპირობებელი ფაქტორია. შესაძლოა კვლავ გქონდეთ ადრეული ორსულობის ისეთი ნიშნები, როგორებიცაა მკერდის მგრძნობელობა და საზარდულის ტკივილი. შეიძლება შეამჩნიოთ მკერდის კანის გამუქება და ძუძუსთავის გარშემო ყავისფერი წერტილები. ეს წარმონაქმნები, რომლებსაც მონტგომერის ბორცვაკები ეწოდება, ძუძუსთავის გარშემო განლაგებული პატარა ცხიმოვანი ჯირკვლებია. ისინი გამოიმუშავებს ბუნებრივ ცხიმს, რომელიც კანის pH-ის ბალანსის შენარჩუნებას უწყობს ხელს და ძუძუსთავს ინფექციებისგან იცავს.;;;
ამ კვირაში, ორსულობამდელ პერიოდთან შედარებით, სისხლის მოცულობა 12%-ით მეტი გაქვთ. ამ ცვლილებასთან შეგუების პროცესში, არტერიული წნევის მატების გამო, ორგანიზმმა შესაძლოა ცხვირიდან სისხლდენით მოახდინოს რეაგირება. თუმცა, თუ ცხვირიდან სისხლდენა ხშირად გაქვთ, სასურველია ექიმს მიმართოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულძმარვის თავიდან ასაცილებლად ჭამისთანავე ნუ დაწვებით და ვახშამი დაძინებამდე სულ მცირე 2-3 საათით ადრე დაასრულეთ. თუ გულისცემა ოდნავ გაგიხშირდათ, ნუ შეშფოთდებით — ასე თქვენი ორგანიზმი ბავშვისთვის მეტი სისხლის მიწოდებას ცდილობს. რადგან ომეგა-3-ზე თქვენი მოთხოვნილება გაიზარდა, ექიმთან კონსულტაციის შემდეგ შეგიძლიათ რაციონში ნიგოზი ან თევზი დაამატოთ. დღის განმავლობაში ღრმა სუნთქვით მედიტაცია როგორც თქვენს, ისე ბავშვის ნერვულ სისტემას დაამშვიდებს.') WHERE id = 'b8a881d9-b2c4-4857-81a9-360b7ca73418';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მართალია, სასქესო ორგანოები ჯერ განვითარებული არ არის, მაგრამ უჯრედებმა საკვერცხეებად ან სათესლეებად ჩამოყალიბება უკვე დაიწყო. თქვენი ბავშვის მკლავებში ნერვული ქსოვილი წარმოიქმნა და ფუნქციონირება დაიწყო. ამავდროულად, ზურგის ტვინიც სწრაფად განაგრძობს განვითარებას. მიუხედავად იმისა, რომ ჩონჩხის ქსოვილს ჯერ კიდევ ხრტილოვანი სტრუქტურა აქვს, მომდევნო რამდენიმე კვირის განმავლობაში ის სრულად გაძვალდება.;;;
თქვენი ბავშვის პატარა გული სისხლის მიმოქცევის უზრუნველსაყოფად წუთში საშუალოდ 150-160-ჯერ სცემს. ამ კვირიდან ბავშვის გულის სარქვლების ფორმირება იწყება.'), baby_message_ka = COALESCE(baby_message_ka, 'გოგო ვარ თუ ბიჭი? 🩷💙 ჩემს სხეულში სასქესო ორგანოები (საკვერცხეები ან სათესლეები) უკვე ყალიბდება. თუმცა გარეგნულად ეს ჯერ არ ჩანს. ექიმები ამას ჯერ ვერ განსაზღვრავენ — ეს ჩემი პატარა საიდუმლოა. შენ რომელი გინდა? გოგო თუ ბიჭი? მთავარი ისაა, ჯანმრთელი ვიყო და შენი პატარა ვიყო. ორივე შემთხვევაში ძალიან მეყვარები!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ზეთისხილი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი ბავშვის ზრდასთან ერთად საშვილოსნო იჭიმება, რამაც შესაძლოა სპაზმის მსგავსი ტკივილი გამოიწვიოს. ასეთი ტკივილი მოსალოდნელია და ნორმალურად მიიჩნევა. თუ სპაზმები ძალიან ხშირია ან დიდხანს გრძელდება, რეკომენდებულია ამის შესახებ ექიმს აცნობოთ. სისხლში ჰორმონების ძალიან მაღალი დონის გამო გულისრევა და ღებინება ნორმალურად მიიჩნევა. ამის გამო შესაძლოა წონაში დაიკლოთ. თუმცა, თუ წონის კლება ძალიან დიდია, ექიმთან კონსულტაციის შემდეგ მან შესაძლოა დამატებითი საკვები დანამატები გირჩიოთ. ტანსაცმელი შეიძლება უკვე მოგიჭიროთ. უპირატესობა მიანიჭეთ ისეთ ტანსაცმელს, რომელიც განსაკუთრებით მუცლის არეში არ მოგიჭერთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'კანის ქავილისა და დაჭიმულობის შეგრძნების შესამცირებლად დაიწყეთ ბუნებრივი შემადგენლობის დამატენიანებლების ან ნუშის ზეთის გამოყენება. ყურადღება მიაქციეთ რაციონში კალციუმისა და D ვიტამინის ბალანსს (რძის პროდუქტები, კვერცხის გული), რათა ბავშვის ძვლები მტკიცე იყოს. ღამის ძილის ხარისხის გასაუმჯობესებლად დაძინებამდე ოთახი გაანიავეთ. ყოველდღე რამდენიმე წუთი დაუთმეთ საკუთარ თავს და ესაუბრეთ თქვენს ბავშვს — ეს თქვენს შორის კავშირს კიდევ უფრო გააძლიერებს.') WHERE id = '1e725a51-c2e7-489a-9924-d2713767d7e6';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ენისა და ტუჩების განვითარება დაიწყო. ენასა და მასზე განლაგებულ გემოვნების კვირტებს მრავალშრიანი ბრტყელი უჯრედები ქმნის. გემოვნების კვირტები ენის ზედაპირზე არსებულ პატარა შემაღლებებზეა განლაგებული. სწორედ მათი საშუალებით შევიგრძნობთ, საკვები მწარეა, მჟავე, ტკბილი თუ მარილიანი. მალე პირის ღრუში განვითარებული სანერწყვე ჯირკვლები წყვილ-წყვილად დაიწყებს შესაბამის უბნებში განლაგებას.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი „სახლი“ იცვლება, დედიკო! 🏠 „ყვითრის პარკი“, რომელიც აქამდე მკვებავდა, ნელ-ნელა პატარავდება, რადგან საქმეს ჩემი საოცარი პლაცენტა იბარებს. ეს პლაცენტა ხიდია შენსა და ჩემ შორის. ის დამიცავს, გამომკვებავს და ჟანგბადს მომაწვდის. ჩვენი კავშირი ახლა უფრო ძლიერი და მტკიცეა. ეს ყველაფერი შენი დამსახურებაა!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ზეთისხილი'), body_changes_ka = COALESCE(body_changes_ka, 'ფარისებრი ჯირკვლის ფუნქცია ჰორმონების სინთეზი, შენახვა და სისხლში გამოყოფაა. იოდი, რომელიც ამ ჰორმონების წარმოსაქმნელად აუცილებელია, ორგანიზმში მარილის, სასმელი წყლის ან საკვების მეშვეობით ხვდება. ის ორგანიზმის ყველა უჯრედზე ზემოქმედებს და სხეულის ფუნქციების მართვაში მნიშვნელოვან როლს ასრულებს. თუ სისხლში ფარისებრი ჯირკვლის ჰორმონების დონე დაბალია, ორგანიზმის მუშაობა ნელდება. ამ მდგომარეობას ჰიპოთირეოზი ეწოდება. თუ სისხლში ამ ჰორმონების დონე მაღალია, ორგანიზმი უფრო სწრაფად მუშაობს. ამ მდგომარეობას კი ჰიპერთირეოზი ეწოდება. ფარისებრი ჯირკვლის მიერ გამომუშავებული ჰორმონების რაოდენობას არეგულირებს სხვა ჯირკვალი, რომელსაც ჰიპოფიზი ეწოდება, და თავის ტვინის უბანი, რომელიც ჰიპოთალამუსის სახელითაა ცნობილი. ორსულობის დაწყებიდან მშობიარობამდე ორგანოთა სისტემებში სტრუქტურული და ფუნქციური ცვლილებები მიმდინარეობს. ორსულობის განმავლობაში ჰორმონული სისტემების ცვლილების შედეგად ზოგიერთ ორსულს შესაძლოა ჰიპოთირეოზი განუვითარდეს. რადგან ამ მდგომარეობამ შეიძლება არასასურველი გავლენა მოახდინოს დედასა და ბავშვზე, მნიშვნელოვანია მისი დროული გამოვლენა და მკურნალობა.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შებერილობისა და საჭმლის მონელების პრობლემების შესამცირებლად საკვები კარგად დაღეჭეთ და მოერიდეთ გაზიან სასმელებს. თუ ფეხებზე შეშუპებას გრძნობთ, დღის განმავლობაში რამდენჯერმე ფეხები მაღლა შემოაწყვეთ და 10 წუთით დაისვენეთ. აკონტროლეთ მარილის მიღება, თუმცა სრულად ნუ გამორიცხავთ. რადგან პირველი ტრიმესტრის დასასრულს უახლოვდებით, მეტად გაუფრთხილდით თქვენს ემოციურ მდგომარეობას; სტრესისგან თავის არიდება ბავშვის ნერვული სისტემისთვის ძალიან მნიშვნელოვანია.') WHERE id = 'a0486bb7-3fd0-4a52-8340-97fc8cbad570';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში, როდესაც თქვენი ბავშვის ორგანოების განვითარება რეგულარულად გრძელდება, ელენთა და ღვიძლი მუცლის ღრუში თავიანთი ადგილების დაკავებას იწყებენ. ელენთა, რომელიც იმუნურ სისტემაში მეორეული ორგანოს ფუნქციას ასრულებს, ასევე ხელს უწყობს ორგანიზმიდან ყვითელ-ნარინჯისფერი პიგმენტის — ბილირუბინის გამოდევნას. ბილირუბინი წარმოიქმნება ჰემოგლობინის ცილების დაშლის შედეგად, რომლებიც სასუნთქი ორგანოებიდან ქსოვილებში ჟანგბადს, ქსოვილებიდან კი სასუნთქ ორგანოებში ნახშირორჟანგს გადააქვთ.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი კუდი გაქრა! 🐇 გახსოვთ, გითხარით, რომ პატარა კუდი მქონდა? ახლა ის აღარ მაქვს! ჩემი ზურგი უკვე სწორი და გლუვია და ნამდვილი ადამიანის ხერხემალი მაქვს. სულ უფრო მეტად გემსგავსებით, დედიკო. მე უკვე აღარ ვარ პატარა ზღვის ცხენი — თქვენი პატარა ადამიანი ვარ. ეს ცვლილება ძალიან მახარებს, თქვენც ხომ გიხარიათ?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყურძენი'), body_changes_ka = COALESCE(body_changes_ka, 'თქვენი საშვილოსნო ზრდას განაგრძობს. რადგან ის ჯერ კიდევ მენჯის ძვლების უკან მდებარეობს, მუცელი არ გეტყობათ, თუმცა სიმძიმეს უკვე გრძნობთ. შარდის ბუშტზე გაზრდილი ზეწოლის გამო ტუალეტში ხშირად სირბილი კვლავ აქტუალურია. ასევე შესაძლოა არტერიული წნევა ოდნავ მერყეობდეს, რამაც სწრაფად წამოდგომისას თავბრუსხვევა გამოიწვიოს. ;;;
საშვილოსნო, რომელიც ორსულობის დასაწყისში 60-70 გრამს იწონის, ორსულობის ბოლოს 1000 გრამზე მეტს აღწევს. სხვაგვარად რომ ვთქვათ, ორსულობამდე ატმის ზომის საშვილოსნო ორსულობის ბოლოს საზამთროს ზომას აღწევს. მუშტზე პატარა საშვილოსნო ბავშვის ზრდასთან ერთად შიგნიდან იჭიმება, რათა მისთვის ადგილი შექმნას, და იმდენად იზრდება, რომ 5 კილოგრამამდე წონის დატევა შეუძლია. მიუხედავად იმისა, რომ მუცლის ზრდის სიჩქარე მუცლის კუნთების აგებულებაზეა დამოკიდებული, ის მე-12 კვირამდე შედარებით ნელა, ბოლო ტრიმესტრში კი ძალიან სწრაფად იზრდება. მეორე ორსულობის დროს მუცელი უფრო ადრე ხდება შესამჩნევი, ვიდრე პირველი ორსულობისას, რადგან კუნთები უკვე ერთხელ იყო გაჭიმული. ორსულობის 9-თვიანი პერიოდის შემდეგ, რომლის განმავლობაშიც საშვილოსნო მრავალჯერ იზრდება, ის მშობიარობიდან 2 თვის განმავლობაში თავის საწყის ზომას უბრუნდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდში სისხლის მოცულობა იზრდება, ამიტომ ეცადეთ, მეტი რკინით მდიდარი საკვები მიიღოთ (ოსპი, მწვანეფოთლოვანი ბოსტნეული, წითელი ხორცი). თუ მუცლის არეში ქავილს ან სიმშრალეს გრძნობთ, კანი დამატენიანებელი კრემით ან ბუნებრივი ზეთით დაიმასაჟეთ. დღის განმავლობაში წყლის დალევა არ დაგავიწყდეთ, რადგან წყალი ხელს უწყობს როგორც საჭმლის მონელებას, ისე სანაყოფე წყლების განახლებას. ხანმოკლე გასეირნება ზედმეტი დაღლის გარეშე განწყობას აგიმაღლებთ.') WHERE id = 'efd814e8-abbf-4037-81a4-db63af40ea3e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ყურში წარმოიქმნება სპეციალური არხები, რომლებიც სმენასთან დაკავშირებული არ არის და სხეულის წონასწორობის შენარჩუნებას ემსახურება. ამ სისტემის წყალობით, მომავალში ის დაცემის გარეშე შეძლებს მოძრაობას. ამავდროულად, ყურები ერთიან მექანიზმად ყალიბდება: გარეთა ყური ბგერას აგროვებს, შუა ყური აძლიერებს, შიგნითა ყური კი ტვინს გადასცემს.;;;
თქვენი ბავშვის ტვინი ამჟამად ინტენსიური ელექტრული ტალღებით მუშაობს. ეს ტალღები უბრალოდ თანმხლები პროდუქტი არ არის — ისინი ტვინის სხვადასხვა უბნის ერთმანეთთან ურთიერთობისა და ინფორმაციის გაზიარების მთავარი „გზაა“.'), baby_message_ka = COALESCE(baby_message_ka, 'იდაყვების მოხრა შემიძლია! 💪 ჩემი ხელები უკვე უბრალო სწორი ჩხირები აღარ არის. იდაყვის სახსრები ჩამომიყალიბდა და შემიძლია ხელები მკერდისკენ მოვზიდო. თითქოს საკუთარ თავს ვეხუტები. ერთ დღეს ამ ხელებით თქვენ ჩაგეხუტებით. ჩემი მოძრაობები უფრო რთული ხდება — უკვე უბრალოდ კი არ ვცურავ, არამედ საკუთარი სხეულის მართვასაც ვსწავლობ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყურძენი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობაზე საუბრისას ერთ-ერთი პირველი სიმპტომი, რომელიც გვახსენდება, საკვებისადმი განსაკუთრებული ლტოლვაა. ეს მდგომარეობა, რომელიც ორსულთა უმეტესობას აღენიშნება, კონკრეტული საკვების მიღების ძალიან ძლიერ სურვილს გულისხმობს. მათ, ვისი რაციონიც ცილებით მდიდარია, შესაძლოა ნახშირწყლებით მდიდარი ტკბილეული მოუნდეთ, ხოლო მათ, ვინც ძირითადად ნახშირწყლებს იღებს — ცილებით მდიდარი საკვები. ხილის სურვილი შეიძლება ვიტამინების საჭიროებაზე მიუთითებდეს, რძის პროდუქტების სურვილი კი — კალციუმის საჭიროებაზე. ორსულობის სხვადასხვა ეტაპზე შესაძლოა სხვადასხვა საკვებისადმი გაგიჩნდეთ ლტოლვა. როდესაც კალორიების საჭიროება იზრდება, უფრო ხშირად ჩნდება მაღალკალორიული საკვების, მაგალითად, ტკბილეულისა და შოკოლადის სურვილი. ასევე ცნობილია, რომ ზოგიერთი ვიტამინის დეფიციტისას შოკოლადისადმი ლტოლვა ძლიერდება. ამ პერიოდში ყველა საკვების ზომიერად მიღება სასარგებლოა, თუმცა არ უნდა დაგავიწყდეთ, რომ ზედმეტი საკვები წონის მატებას გამოიწვევს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'იმისთვის, რომ დღის განმავლობაში სისხლში შაქრის დონე არ დაგიქვეითდეთ, განაგრძეთ მცირე ულუფებით და ხშირად კვება. თან ყოველთვის იქონიეთ რამდენიმე ნიგოზი ან ნუში. თუ ცხვირის გაჭედილობა გაწუხებთ, ოთახში ჰაერის დატენიანება შეიძლება დაგეხმაროთ. ყოველდღე სულ მცირე 10-15 წუთის განმავლობაში მშვიდ გარემოში ღრმად ისუნთქეთ და ეცადეთ, თქვენს ბავშვთან ემოციური კავშირი დაამყაროთ. გახსოვდეთ, რომ თქვენი სიმშვიდე მისი განვითარებისთვის ერთ-ერთი უმნიშვნელოვანესი ფაქტორია.') WHERE id = 'a019329d-4564-4a4c-a50f-391f0feef37e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის პატარა თითები სწრაფად ზრდას განაგრძობს. ეს დღეები ხელებისა და ფეხების ჩამოყალიბებისთვის კრიტიკული პერიოდია. თითებთან ერთად ხელები და ფეხები დაგრძელდა, იდაყვებმა კი მოხრა დაიწყო. ნერვული ქსელი უკვე იმდენად განვითარებულია, რომ ბავშვს ხელებისა და ფეხების აქტიურად მოძრაობა და გამღიზიანებლებზე რეაგირება შეუძლია. თუ გაგიმართლებთ, ულტრაბგერითი გამოკვლევის დროს თქვენი ბავშვის მოძრაობას დაინახავთ! ბავშვი უკვე სულ უფრო მეტად ემსგავსება ადამიანს. მიუხედავად იმისა, რომ თავი სხეულთან შედარებით უფრო დიდია, ორგანოები სწრაფად განაგრძობს ზრდას, განვითარებასა და თავიანთი ბუნებრივი ადგილების დაკავებას.;;;
ამ კვირიდან თქვენი ბავშვის რეპროდუქციული ორგანოების ჩამოყალიბება დაიწყო, თუმცა გარეთა სასქესო ორგანოებზე სქესის განმასხვავებელი ნიშნები ჯერ არ შეიმჩნევა. ასე რომ, თუ ბავშვის სქესი გაინტერესებთ, კიდევ რამდენიმე კვირა მოგიწევთ მოცდა.'), baby_message_ka = COALESCE(baby_message_ka, 'გილოცავთ, დედიკო! სწავლა დავამთავრე! 🎓 დღეს ჩემთვის ისტორიული დღეა. მე უკვე „ემბრიონი“ აღარ ვარ — ახლა ოფიციალურად „ნაყოფი“ მქვია! ეს ნიშნავს, რომ ჩემი ყველა ორგანო უკვე ჩამოყალიბდა. ახლა მხოლოდ ზრდის, წონის მომატებისა და გაძლიერების დროა. ყველაზე სახიფათო პერიოდი გადავიარეთ! ჩვენ ეს ერთად შევძელით. თქვენ ჩემი გმირი ხართ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ყურძენი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პირველ სამ თვეში დამატებითი კალორიები საჭირო არ არის, თუმცა სწორად კვება მნიშვნელოვანია. ამ პერიოდში სწორი კვება ბავშვის გონებრივი განვითარებისთვის განსაკუთრებით მნიშვნელოვანია. ბავშვის ზრდისა და გონებრივი განვითარებისთვის ორგანიზმმა ყველა აუცილებელი საკვები ნივთიერება სრულად უნდა მიიღოს. ორსულობისას წონის მატების ერთი იდეალური მაჩვენებელი, ანუ ყველასთვის მისაღები ერთადერთი „სწორი წონა“, არ არსებობს. ორსულობის დროს დედის მიერ მომატებული წონა საწყის წონაზეა დამოკიდებული და თითოეული ქალისთვის განსხვავებულია. წონის მატების სამიზნე მაჩვენებელი გამოითვლება ორსულობამდე არსებული სხეულის მასის ინდექსის, ანუ წონისა და სიმაღლის თანაფარდობის მიხედვით. ნორმალური წონის მქონე ქალისთვის ორსულობისას საჭირო დამატებითი ენერგია დღეში საშუალოდ 300 კალორიაა. 300 კალორია დაახლოებით 3 ცალ ბანანს, 5 ცალ ვაშლს, 100 გრამ ოსპის კერძს, 1 ჯამ ცხიმიან იოგურტს ან 3-4 ნაჭერ პურს უდრის. დღის განმავლობაში მიღებული ზედმეტი კალორიები ცხიმის სახით დაგროვდება და სასურველი წონის მატებაში ხელს შეგიშლით.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან პირველი ტრიმესტრის დასასრულს უახლოვდებით, საკუთარ თავს ცოტა მეტად გაუფრთხილდით. მეტაბოლიზმის აჩქარების გამო შეიძლება ხშირად მოგშივდეთ, ამიტომ თან ჯანსაღი წასახემსებელი იქონიეთ. თუ წელის ტკივილი გაწუხებთ, ძილისას გვერდზე დაწექით და მუხლებს შორის ბალიში მოათავსეთ — ეს ხერხემალზე დატვირთვას შეამცირებს. მე-10 კვირაზე გადასვლისას არ დაგავიწყდეთ ექიმთან პირველი სკრინინგული გამოკვლევების შესახებ საუბარი.') WHERE id = '65677248-c635-4f55-8483-617e735f69ca';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინი იწყებს დაკეცვას და ხვეულ ფორმას იძენს, რათა მცირე სივრცეში მეტი ინფორმაცია დაიტიოს. ზედა შრე, რომელსაც „რუხ ნივთიერებას“ უწოდებენ, ტვინს საფარველივით აკრავს და განვითარებასთან ერთად უფრო გამოკვეთილი ხდება. ეს უბანი ტვინის მართვის ცენტრად მიიჩნევა.;;;
ამავდროულად, თქვენი ბავშვის გულს უკვე სრულად აქვს ჩამოყალიბებული 4 საკანი. გულის შიგნით არსებული სარქვლები კი ერთგვარი ცალმხრივი კარის ფუნქციას ასრულებს. ყოველ ჯერზე, როდესაც გული იკუმშება და სისხლს გადატუმბავს, ეს სარქვლები იხსნება, სისხლს მხოლოდ წინ გადაადგილების საშუალებას აძლევს და მის უკან დაბრუნებას ხელს უშლის.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი კბილებისთვის მზადება მიმდინარეობს! 🦷 პირში ჯერ არცერთი კბილი არ მაქვს, თუმცა ღრძილების ქვეშ პატარა კბილის ჩანასახები წარმოიქმნება. ისინი ჩემი მომავალი სარძევე კბილების საფუძველია. უკვე ვგეგმავ იმ დღეს, როცა გაგიღიმებ. შენც კარგად მოუარე საკუთარ კბილებს, დედიკო, რადგან კალციუმის მარაგს მე მინაწილებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'თხილი'), body_changes_ka = COALESCE(body_changes_ka, 'ახლა, როდესაც ორსულობის 2 თვე უკვე უკან მოიტოვეთ, შესაძლოა გარკვეული ჩივილები გაწუხებდეთ. ერთ-ერთი მათგანია შარდის შეუკავებლობა. ეს არის მდგომარეობა, როდესაც ადამიანი საკუთარი ნებისგან დამოუკიდებლად ვერ იკავებს შარდს. ორსულობის დროს ხშირად გავრცელებული ეს მდგომარეობა პირველ 3 თვეში წარმოიქმნება, რადგან მზარდი საშვილოსნო მის ქვემოთ მდებარე შარდის ბუშტს აწვება. ამასთან, შარდის ბუშტის არასრულად დაცლის გამო შეიძლება ხშირი შარდვაც აღინიშნოს. ბოლო ტრიმესტრში შარდის შეუკავებლობა ბავშვის მიერ შარდის ბუშტზე ზეწოლის შედეგად ვითარდება და, სავარაუდოდ, ორსულთა დაახლოებით 35%-ს აღენიშნება. ეს ფიზიოლოგიური მდგომარეობაა და, ჩვეულებრივ, ორსულობის დასრულების შემდეგ ქრება. შარდვის სურვილის გადადებისგან თავის შეკავება, მუცლის ღრუში წნევის მომატების გამომწვევი უეცარი მოძრაობების თავიდან აცილება და მძიმე ტვირთის არტარება ამ ჩივილის შემსუბუქებას უწყობს ხელს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ კვირაში შეიძლება თავი ოდნავ უფრო მხნედ იგრძნოთ, რადგან ჰორმონები სტაბილიზებას იწყებს. ვინაიდან ღრძილების მგრძნობელობა გრძელდება, უპირატესობა კალციუმით მდიდარ საკვებს მიანიჭეთ. თუ წელის ტკივილი დაგეწყოთ, ყურადღება მიაქციეთ სხეულის სწორ პოზას და ძალიან დიდხანს ფეხზე ნუ იდგებით. რადგან პირველი ტრიმესტრის დასასრულს უახლოვდებით, სწორედ ახლაა შესაფერისი დრო, ექიმთან „ორმაგი ტესტის“ (სკრინინგის) შესახებ კონსულტაცია გაიაროთ.') WHERE id = 'c0cc19e3-1bf2-4736-b8f0-41d3ab04d6c8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სახის ნაკვთები უკვე უფრო მკაფიოდ იკვეთება; პირი, ცხვირი და ყურები თავიანთ ბუნებრივ ადგილებს იკავებს. მე-9 კვირაში თვალების განვითარებამ მნიშვნელოვნად წაიწია წინ. თვალის შიგნით ყალიბდება მხედველობის უზრუნველმყოფი, მილიონობით უჯრედისგან შემდგარი ბადურის თხელი შრე, ხოლო იქ არსებული სისხლძარღვები უჯრედების კვებას იწყებს.;;;
ამავდროულად, თვალის ფერადი ნაწილი — ფერადი გარსიც — განვითარების დასრულების ეტაპზეა. ამჟამად ამ სტრუქტურას მოლურჯო შეფერილობა აქვს. ახალშობილებს პირველ თვეებში თვალები ხშირად სწორედ ამ საწყისი პიგმენტაციის გამო აქვთ ლურჯი.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი გული შენსაზე ორჯერ სწრაფად ცემს! 💓 წუთში დაახლოებით 170 დარტყმა! თუ ექიმთან მიხვალ, დოპლერის აპარატით ჩემი გულისცემის მოსმენას შეძლებ. ეს „ბაგაბუგი“ მორბენალი ცხენის ფლოქვების ხმას ჰგავს. ეს ხმა გეუბნება: „მე აქ ვარ, მე ძლიერი ვარ!“ ჩემი რიტმი შენი ცხოვრების მუსიკაა.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'თხილი'), body_changes_ka = COALESCE(body_changes_ka, 'მუცელში შეიძლება „გაზის ბუშტუკების“ მსგავსი შეგრძნება გქონდეთ, მაგრამ ეს ბავშვის მოძრაობაში არ აგერიოთ — ჯერ ძალიან ადრეა. ეს მხოლოდ ნაწლავების მოძრაობაა. პროგესტერონის გამო საჭმლის მომნელებელი სისტემა ძალიან ნელა მუშაობს, რაც მუცლის შებერილობას იწვევს. ;;;
ორსულობის დროს ზურგზე წოლისას არტერიული წნევა მინიმალურ მაჩვენებლამდე ეცემა. ამის მიუხედავად, შესაძლოა გულისცემის სიხშირე გაიზარდოს. თირკმელების სისხლით მომარაგება კი თითქმის განახევრებულია. წოლისას ქვედა ღრუ ვენა, რომელსაც სხეულის ქვედა ნაწილიდან სისხლი გულისკენ მიაქვს, ბავშვის წონის ზეწოლას განიცდის. ამ მდგომარეობამ შეიძლება „ქვედა ღრუ ვენის კომპრესიის“ სინდრომი გამოიწვიოს, რომელიც სისხლის ნაკადის შეფერხებით გამოწვეული დისკომფორტით ხასიათდება. წოლისას ბავშვის წონით ქვედა ღრუ ვენის შეკუმშვამ შეიძლება ამ მდგომარეობის განვითარებას შეუწყოს ხელი. ამ მიზეზების გამო ექიმები მომავალ დედებს, განსაკუთრებით ბოლო ტრიმესტრში, ზურგზე წოლას არ ურჩევენ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ძვლების განვითარების ამ პერიოდში განსაკუთრებული ყურადღება მიაქციეთ კალციუმისა და მაგნიუმის მიღებას (ნუში, ნიგოზი, რძის პროდუქტები). თუ თავის ტკივილი გაწუხებთ, სუფთა ჰაერზე ცოტა ხნით გაისეირნეთ და ბევრი წყალი დალიეთ. მიუხედავად იმისა, რომ ორსულებისთვის განკუთვნილ ტანსაცმელზე გადასვლა ჯერ ადრეა, უფრო კომფორტული და ელასტიკური შარვლის არჩევა უკეთ გაგრძნობინებთ თავს. დაიცავით თავი სტრესისგან; მშვიდი მუსიკის მოსმენა დადებითად იმოქმედებს როგორც თქვენზე, ისე ბავშვზე.') WHERE id = 'd416ae4b-bb0c-425b-b304-d18dd9ac3813';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ღვიძლი, ნაღვლის ბუშტი, ელენთა და თირკმელებიც სწრაფ ზრდას განაგრძობს. ბავშვის პირის ღრუსა და ხახის შეერთება დასრულდა. ამ კვირაში პირისა და ცხვირის ღრუები ერთმანეთს სრულად გამოეყოფა და ხახასთან შეერთება დასრულდება. ენა კი ჩამოყალიბების პროცესშია. ამ მგრძნობიარე ეტაპზე, როდესაც სახის სტრუქტურები ერთმანეთს უერთდება, განვითარების შეფერხების შემთხვევაში ზოგჯერ შეიძლება წარმოიქმნას ნაპრალები, რომლებსაც ტუჩის ან სასის ნაპრალს უწოდებენ. ეს მდგომარეობა შეიძლება სხვადასხვა ფორმით გამოვლინდეს — მცირე ჭრილიდან ტუჩამდე გადაჭიმულ ნაპრალამდე.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თითის ანაბეჭდები ყალიბდება! 👆 იქმნება ჩემი სრულიად უნიკალური იდენტობა, რომლის მსგავსიც მსოფლიოში არავის აქვს. თითების წვერებზე განსაკუთრებული ხაზები იხატება. ეს ანაბეჭდები ჩემი უნიკალურობის ბეჭედია. მე შენი განუმეორებელი სასწაული ვარ, დედიკო. ხედავ, როგორ სრულყოფილად არის შექმნილი ყველაფერი უმცირეს დეტალამდე?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'თხილი'), body_changes_ka = COALESCE(body_changes_ka, 'შეიძლება ენერგიის დონის მცირედი მატება იგრძნოთ, რადგან პლაცენტა ჰორმონების გამომუშავებას თითქმის სრულად იღებს საკუთარ თავზე. ეს „ყვითელ სხეულზე“ დამოკიდებულების შემცირებას ნიშნავს. თუმცა სარძევე ჯირკვლების მგრძნობელობა და ზომაში ზრდა გრძელდება. ზოგჯერ ძუძუსთავიდან შეიძლება მოყვითალო სითხე (კოლოსტრუმი) გამოიყოს — ნუ შეშინდებით, ეს ნორმალურია.;;;
ორსულობის დროს ზოგიერთი ჰორმონის მატება საშოში pH-ის ბალანსის დარღვევას იწვევს. შედეგად, საშოში არსებული დამცავი ბარიერი, რომელსაც ფლორა ეწოდება, ეფექტიანობას კარგავს. ეს მდგომარეობა ორსულობის დროს ვაგინალური გამონადენის რაოდენობას ზრდის. გამონადენის ასეთი ფიზიოლოგიური მატება მკურნალობას არ საჭიროებს. საკმარისია ზოგადი ჰიგიენური ზომების გაძლიერება. თუ გამონადენი ფერს შეიცვლის ან უსიამოვნო სუნი ექნება, მომავალმა დედამ ექიმს უნდა მიმართოს.;;;
ორსულობის დროს სოკოვანი ინფექცია ორგანიზმის წინააღმდეგობის უნარისა და საშოს ფლორაში დამცავი ბაქტერიების რაოდენობის შემცირების შედეგად ვითარდება. ის ვლინდება თეთრი, ხაჭოსებრი გამონადენით, რომელსაც ძლიერი ქავილი და წვის შეგრძნება ახლავს. მკურნალობა ორსულობის დროს უსაფრთხო სანთლებითა და კრემებით არის შესაძლებელი. პროფილაქტიკის მიზნით ორსულებს ასევე ურჩევენ ბამბის საცვლების ტარებას, ტანსაცმლის სარეცხი ფხვნილის ნაცვლად საპნით გარეცხვასა და გამოყენებამდე გაუთოებას.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შეიყვარეთ წყალი! ცურვა ორსულობისთვის ერთ-ერთი ყველაზე იდეალური სპორტია. წყლის ამომგდები ძალა წელის დატვირთვას ამცირებს და სიმსუბუქის შეგრძნებას გიქმნით. ამასთან, შეშუპებასაც ამცირებს.') WHERE id = '827fd4de-2f71-405f-8929-c0848b39d48e';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ თქვენი ბავშვის კბილები დაბადებიდან დაახლოებით 6 თვის შემდეგ გამოჩნდება, მათი საფუძველი უკვე ახლა ყალიბდება. პირის ღრუში წარმოქმნილ სპეციალურ გასქელებულ ქსოვილზე პატარა ამობურცულობები, ანუ კბილის ჩანასახები იწყებს ფორმირებას.;;;
ქვედა და ზედა ყბაზე თითოეულზე 10, სულ კი სარძევე კბილების 20 ჩანასახი წარმოიქმნება. ეს პროცესი გარკვეული თანმიმდევრობით მიმდინარეობს: თავდაპირველად წინა, შემდეგ გვერდითი და ბოლოს უკანა კბილების ჩანასახები ვითარდება. საინტერესოა, რომ იგივე ქსოვილი მომავალში სარძევე კბილების შემცვლელი მუდმივი კბილების განვითარებასაც უქმნის საფუძველს.'), baby_message_ka = COALESCE(baby_message_ka, 'ცურვის ჩემპიონი ვარ! 🏊‍♂️ წყალში შეუჩერებლად ვმოძრაობ. ფეხებს ვიქნევ, ვტრიალდები და სალტოებს ვაკეთებ. თქვენ ამას ჯერ ვერ გრძნობთ, რადგან ჩემ გარშემო არსებული წყალი დარტყმებს ბალიშივით შთანთქავს. მაგრამ იცოდეთ, აქ შიგნით დიდი ოლიმპიადა მიმდინარეობს. ვვარჯიშობ, რომ თქვენთან მოსვლისას ძლიერი ვიყო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'თხილი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირაში, როდესაც ორსულობის მე-3 თვეში გადადიხართ, ალბათ უკვე იგრძენით მკერდის გადიდება და სისავსე. დედის რძის გამომუშავებისთვის საჭირო პირველი ცვლილებები სარძევე ჯირკვლის ქსოვილში ორსულობის ამ პერიოდში იწყება, თუმცა რძის გამომუშავება მხოლოდ ორსულობის შუა ეტაპზე იწყება. ორსულობისას დედის რძის გამომუშავებისთვის მოსამზადებელ პროცესში მრავალი ჰორმონი მონაწილეობს. ეს ჰორმონები მნიშვნელოვან როლს ასრულებს ჯირკვლებისა და რძის სადინრების ისე ჩამოყალიბებაში, რომ რძის გამომუშავება და გამოყოფა უზრუნველყოს. მკერდში არსებული ჯირკვლებისა და რძის სადინრების ზრდის გამო ორსულობისას მკერდის მოცულობა სწრაფად იმატებს და ორსულობის ბოლოს მისი წონა დაახლოებით 1 კილოგრამს აღწევს. თავის ტვინის ქვედა ნაწილში მდებარე ჰიპოფიზის მიერ გამოყოფილი ჰორმონი პროლაქტინი სარძევე ჯირკვლის ქსოვილის სპეციალურ უჯრედებს უკავშირდება და რძის გამომუშავებაში მთავარ როლს ასრულებს. ჰიპოფიზის მიერ გამოყოფილი კიდევ ერთი ჰორმონი, ოქსიტოცინი, განსაკუთრებით მაშინ იწყებს გამოყოფას, როდესაც ბავშვი ძუძუს წოვას იწყებს. რძის სადინრებსა და დვრილებში რძის დინებასაც სწორედ ეს ჰორმონი უზრუნველყოფს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თავბრუსხვევის თავიდან ასაცილებლად ნუ გააკეთებთ უეცარ მოძრაობებს; განსაკუთრებით საწოლიდან ადგომისას ჯერ რამდენიმე წამით ჩამოჯექით. საჭმლის მომნელებელი სისტემის მუშაობის შესამსუბუქებლად მიირთვით ბოჭკოვანი საკვები (ჩირი, შვრია, ბოსტნეული) და დალიეთ ბევრი წყალი. თუ ენერგია დაგიბრუნდათ, ორსულებისთვის მსუბუქი იოგა ან სუნთქვითი ვარჯიშები როგორც თქვენი, ისე ბავშვის კეთილდღეობისთვის შესანიშნავია.') WHERE id = '12d3b899-0764-4ab2-902c-2efe92103462';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი უკვე იმდენად განვითარებულია, რომ შეუძლია პირის გაღება და დახურვა, თავის მობრუნება და მდებარეობის შეცვლა. უფრო მეტიც, ბავშვი უკვე იმ ზომისაა, რომ ხელსაყრელ პოზაში ყოფნისას ამ მოძრაობების დანახვას ულტრაბგერითი გამოკვლევის დროსაც შეძლებთ!;;;
ორსულობის მე-7 და მე-9 კვირებს შორის ბავშვი მთელი სხეულით ბიძგისა და ხტომის მსგავსი მოძრაობებით მოძრაობს. ხერხემალში ნეირონების განვითარების შედეგად, ამ კვირიდან ხელებს, ფეხებსა და სხეულს ერთმანეთისგან დამოუკიდებლად მოძრაობა შეუძლია. იმისთვის, რომ ბავშვმა ფეხების ქნევა, ფეხებზე ხელის მოკიდება, ველოსიპედის ტარების მსგავსი მოძრაობების შესრულება და გადაბრუნება შეძლოს, კიდევ 2-3 კვირაა საჭირო.;;;
გარდა ამისა, ამ პერიოდში ხელები და ფეხები გრძელდება, ფეხის თითები იწყებს გამოკვეთას, იდაყვები და მაჯები კი მკაფიოდ შესამჩნევი ხდება.'), baby_message_ka = COALESCE(baby_message_ka, 'გარგარის ჩირისოდენა ვარ! 🍓 ყოველდღე ვიზრდები და ვიცვლები. ჩემი ყურები ნელ-ნელა თავის გვერდებიდან ზემოთ, თავიანთ სწორ ადგილას ინაცვლებს. თვალები ჯერ კიდევ დახუჭული მაქვს, მაგრამ ჩემს ბადურას (რეტინას) უკვე შეუძლია სინათლის გარჩევა. როდესაც მზეზე გახვალთ, ამ სითბოსა და სიკაშკაშეს ვიგრძნობ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გარგარის ჩირი'), body_changes_ka = COALESCE(body_changes_ka, 'საშვილოსნოს ზრდასთან ერთად ის მენჯის ძვლებიდან ზემოთ იწყებს აწევას. ამან შესაძლოა შარდის ბუშტზე ზეწოლა ოდნავ შეამციროს. მუცლის ქვედა ნაწილში შესაძლოა სიმაგრე იგრძნოთ.;;;
მიჩნეულია, რომ ორსულობისას ჰემოგლობინის მაჩვენებლის ზედა ზღვარი მშობიარობის პერიოდში საშუალოდ 11-12%-ის ფარგლებშია. ამაზე დაბალი მაჩვენებლის შემთხვევაში დამატებითი რკინის მიღება ხდება საჭირო. რკინა, რომელსაც ტვინის საკვებსაც უწოდებენ, ორსულობის ჯანსაღი კვების ერთ-ერთი უმნიშვნელოვანესი ელემენტია და აუცილებელია თქვენი ბავშვის კოგნიტიური განვითარებისთვის. ჯანმრთელი სისხლის წითელი უჯრედები ანემიის რისკს ამცირებს. ანემია, რომელსაც ზოგჯერ რკინის დეფიციტსაც უწოდებენ, დაღლილობას, გამოფიტვასა და სისუსტეს იწვევს. ორსულობისას რკინაზე მოთხოვნილების დასაკმაყოფილებლად სასარგებლოა ისეთი საკვების მიღება, როგორიცაა წითელი ხორცი, ისპანახი, ბროკოლი, მწვანე ოსპი, ფოთლოვანი კომბოსტო, მუხუდო და ლობიო.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ყურადღება მიაქციეთ ინტიმურ ჰიგიენას, თუმცა საპნის ან შხაპის გელის გამოყენებისას სიფრთხილე გამოიჩინეთ. შეარჩიეთ საშუალებები, რომლებიც ბუნებრივ pH ბალანსს არ არღვევს. თუ ყოველდღიურ საფენებს იყენებთ, ხშირად გამოცვალეთ.') WHERE id = '56fa6e29-fd7a-4a03-984e-0590d982556b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ პერიოდში, როდესაც ჩონჩხის სისტემა და ძვლოვანი ქსოვილი სწრაფად ვითარდება, D ვიტამინის მიღება განსაკუთრებით მნიშვნელოვანია. ეს ვიტამინი ორგანიზმს კალციუმისა და ფოსფორის ათვისებაში ეხმარება და თქვენი ბავშვის ძვლების ჯანსაღ ფორმირებას უწყობს ხელს. D ვიტამინის ერთადერთი ფუნქცია ძვლების გაძლიერება არ არის; ის ასევე აძლიერებს იმუნიტეტს, არეგულირებს ნერვული სისტემის მუშაობასა და გულისცემას. მისი დეფიციტი შეიძლება ბავშვის განვითარების შეფერხების, ხოლო დედის კუნთების სისუსტისა და დაღლილობის მიზეზი გახდეს. D ვიტამინის უმნიშვნელოვანესი წყარო მზის სხივებია. გარდა ამისა, ის გვხვდება თევზის ქონში, კრევეტებში, ხამანწკებში, რძესა და რძის პროდუქტებში, კარტოფილსა და საუზმის მარცვლეულში.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თირკმელები მუშაობს! 🚽 დიახ, შეიძლება ცოტა უცნაურად ჟღერდეს, მაგრამ უკვე შარდს გამოვყოფ. სანაყოფე წყლებს ვყლაპავ, ჩემი თირკმელები მას ფილტრავს და კვლავ წყალში გამოყოფს. ეს ცირკულაცია ჩემი საჭმლის მომნელებელი და გამომყოფი სისტემების გამართული მუშაობისთვის ძალიან მნიშვნელოვანია. მე თვითგამწმენდი სისტემა ვარ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გარგარის ჩირი'), body_changes_ka = COALESCE(body_changes_ka, 'კუდის გაქრობის დაწყებასთან ერთად თქვენი ბავშვისთვის ახალი პერიოდი იწყება. ბავშვს, რომელსაც აქამდე ემბრიონი ეწოდებოდა, უკვე ნაყოფის (ფეტუსის) ეტაპზე გადავიდა და მშობიარობამდე ნაყოფად იწოდება. ემბრიონული პერიოდი ორგანოთა სისტემების ჩამოყალიბების ეტაპია. ნაყოფის პერიოდი კი უკვე ჩამოყალიბებული ორგანოების, ქსოვილებისა და სტრუქტურების ზრდისა და განვითარების ეტაპია. ახლა, როდესაც პირველი ტრიმესტრის ბოლო თვეში შედიხართ, შესაძლოა კვლავ გაწუხებდეთ ორსულობასთან დაკავშირებული ჩივილები. ორსულობის დროს დეპრესიის მკურნალობაზე უფრო მნიშვნელოვანი მისი თავიდან აცილებაა. ამ პერიოდში სასარგებლო იქნება საყვარელი საქმიანობით დაკავება, საყვარელ ადამიანებთან დროის გატარება და მეუღლისა და ახლობლებისგან მხარდაჭერის მიღება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'სისხლის მოცულობის მატების გამო შესაძლოა ხშირად იგრძნოთ დაღლილობა; დღის განმავლობაში 15-წუთიანი "ენერგიის აღმდგენი ძილი" ძალებს აღგიდგენთ. ყურადღება მიაქციეთ მაგნიუმისა და კალციუმის მიღებას, რათა ღამით ფეხის კუნთები უეცრად არ დაგეკრუნჩხოთ. ყოველდღე დალიეთ სულ მცირე 2 ლიტრი წყალი. თუ ჯერ კიდევ ერიდებით მძაფრ სუნებს, პიტნის ჩაი ან ლიმონიანი წყალი კუჭს დაგიმშვიდებთ.') WHERE id = '17780e60-9b95-4f39-9e38-8371589b8dad';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის თირკმელებმა უკვე დაიწყეს ფუნქციონირება. ეს ორგანოები, რომლებიც ჯერ კიდევ მე-4 კვირაში უჯრედების პატარა ჯგუფის სახით წარმოიქმნა, ახლა იმდენად არის განვითარებული, რომ შარდს გამოიმუშავებს და ამნიონურ სითხეში გამოყოფს.;;;
მუცლის ღრუში მდებარე თირკმელები მომდევნო კვირებში ერთმანეთს შორდება და საბოლოო ფორმის მისაღებად 90 გრადუსით ბრუნდება. ამ კვირიდან იწყება აორტიდან გამომავალი სპეციალური თირკმლის არტერიის ჩამოყალიბება, რომელიც თირკმლებს სისხლით უშუალოდ ამარაგებს და მათ სრულფასოვან ფუნქციონირებას უზრუნველყოფს.'), baby_message_ka = COALESCE(baby_message_ka, '10 კვირა! უკვე ორნიშნა რიცხვია! 🔟 დედიკო, უკვე მე-10 კვირაში ვართ. ოფიციალურად ვიზრდები. ახლა ქლიავის ზომის ვარ. განვითარების ყველაზე მნიშვნელოვანი ეტაპები უკვე გავიარე. ახლა მხოლოდ წონის მომატება, სიგრძეში ზრდა და შენთან შესახვედრად მომზადება დამრჩა. გზის თითქმის მეოთხედი უკვე გავიარეთ! შენით ვამაყობ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გარგარის ჩირი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში როგორც თქვენი ჯანმრთელობისთვის, ისე ბავშვის ჯანსაღი განვითარებისთვის ძალიან მნიშვნელოვანია საკმარისი და დაბალანსებული კვება და ყველა საჭირო ვიტამინის მიღება. მაგალითად, C ვიტამინის, კალციუმისა და ფოლიუმის მჟავის ყოველდღიური საჭიროების დასაკმაყოფილებლად სასარგებლოა ბროკოლი, კალციუმისთვის — რძე და რძის პროდუქტები, კალიუმისთვის — ბანანი, ხოლო ომეგა-3-ისა და ომეგა-6-ისთვის — მოუხალავი თხილეული. არ უნდა დაგავიწყდეთ, რომ ყოველდღიურად საკმარისი რაოდენობის რძისა და რძის პროდუქტების მიღება ძალიან მნიშვნელოვანია დედისა და ბავშვის ძვლოვანი სისტემისთვის. გარდა ამისა, სისხლში შაქრის დონის დასაბალანსებლად სასარგებლოა, დიდი ძირითადი ულუფების ნაცვლად, საკვები 5-6 მცირე ულუფად გადაანაწილოთ. ორსულობის დროს წყლის მიღება ისეთივე მნიშვნელოვანია, როგორც კვება. წყალი განსაკუთრებით მნიშვნელოვან როლს ასრულებს ორსულობისას გახშირებული ყაბზობის შემსუბუქებაში, კანის სიმშრალისა და ნახეთქების პრევენციაში, საშარდე გზების ინფექციების რისკის შემცირებასა და ბავშვის ჯანმრთელობისთვის აუცილებელი სანაყოფე სითხის (ამნიონური სითხე) შენარჩუნებაში. ამიტომ დღის განმავლობაში 2,5-3 ლიტრი წყალი უნდა მიიღოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დააჯილდოეთ საკუთარი თავი და დაისვენეთ — მეორე ტრიმესტრამდე მხოლოდ ერთი ნაბიჯი დარჩა. ანემიის თავიდან ასაცილებლად კვებისას ყურადღება მიაქციეთ რკინისა და C ვიტამინის კომბინაციას (მაგალითად, ხორცი და ბევრი მწვანე სალათი). თუ კვლავ დაღლილობას გრძნობთ, დღის განმავლობაში ხანმოკლე ძილი ენერგიის აღდგენაში დაგეხმარებათ. მომავალ კვირას განვითარების ერთ-ერთი ყველაზე საინტერესო პერიოდი გველოდება.') WHERE id = '686eb070-eff8-4d42-a409-9b1b933ed8cf';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'კანი, ჩვენი სხეულის უდიდესი ორგანო, განვითარების ჯერ კიდევ მესამე კვირაში სამი შრის სახით წარმოიქმნება. ამ შრეებიდან ყველაზე გარეთა ქმნის როგორც კანს, ისე მის წარმონაქმნებს — თმასა და ფრჩხილებს.;;;
მე-9 კვირიდან თქვენი ბავშვის სხეულზე პირველი თმის ფოლიკულები იწყებს წარმოქმნას. ეს ნაზი ბუსუსები, რომლებსაც ლანუგო ეწოდება, თავდაპირველად ზედა ტუჩის, წარბებისა და ნიკაპის მიდამოებში ჩნდება. რადგან ისინი ჯერ ძალიან თხელია, ულტრაბგერითი გამოკვლევისას მხოლოდ მე-20 კვირისთვის ხდება შესამჩნევი. ეს ბუსუსები ბავშვს საშვილოსნოში იცავს და, ჩვეულებრივ, მშობიარობამდე ცოტა ხნით ადრე სცვივა. ამავდროულად, ბავშვის ხელისა და ფეხის ფრჩხილებიც ნელ-ნელა იწყებს ზრდას. მყარი კერატინის შრისგან შემდგარი ფრჩხილები მხოლოდ გარეგნული თავისებურება არ არის — ისინი თითის წვერებს დაზიანებისგან იცავს და მათ მგრძნობელობას ზრდის.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი თავი სხეულის ნახევრის ზომისაა! 🤯 დედიკო, შეიძლება სასაცილოდ გამოვიყურებოდე, მაგრამ ეს იმიტომ ხდება, რომ გენიოსობისთვის ვემზადები. ჩემი ტვინი იმდენად სწრაფად იზრდება, რომ თავი სხეულთან შედარებით ძალიან დიდია. მაგრამ არ ინერვიულო, დროთა განმავლობაში სხეულიც გაიზრდება და თავს დაეწევა. ახლა პატარა მეცნიერს ვგავარ. მოუთმენლად ველი იმ დღეებს, როცა შენთან საუბარს შევძლებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გარგარის ჩირი'), body_changes_ka = COALESCE(body_changes_ka, 'პირველი ტრიმესტრის დასასრულის მოახლოებასთან ერთად გულისრევა თანდათან მცირდება. ამიტომ შეიძლება თავი უფრო ენერგიულად და მხნედ იგრძნოთ. ამ კვირიდან, როცა ორსულობის მე-3 თვეს იწყებთ, თქვენი ორგანიზმი უკვე სრულად არის შეგუებული ორსულობას. სისხლის მოცულობის ზრდისა და სითხის შეკავების გამო შესაძლოა შეშუპება განვითარდეს. კვების ჩვევების გადახედვით, მარილის შემცირებითა და ფიზიკური აქტივობის გაზრდით შესაძლებელია შეშუპების ისეთ დონემდე შემცირება, რომ დისკომფორტი აღარ შეგიქმნათ.;;;
თუ გულისრევა კვლავ გაწუხებთ, მის შესამსუბუქებლად შეიძლება სასარგებლო იყოს მცირე ულუფებით, ხშირად, ნაკლებცხიმიანი და უფრო მყარი საკვების მიღება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან ენერგია ნელ-ნელა გიბრუნდებათ, შეგიძლიათ მსუბუქი სეირნობა დაიწყოთ. მეტაბოლიზმის აჩქარების გამო არ დაგავიწყდეთ ბევრი წყლის დალევა (დღეში მინიმუმ 2-2.5 ლიტრი). კანის ცვლილებებისა და დაჭიმვის გამო განაგრძეთ ბუნებრივი შემადგენლობის დამატენიანებელი საშუალებების გამოყენება. ყოველდღე საკუთარ თავს 10 წუთი დაუთმეთ და მომავალზე იოცნებეთ — ეს ორივეზე ძალიან კარგად იმოქმედებს.') WHERE id = '59be5b5e-6a03-4140-bbff-b41541c8484d';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სახე თანდათან ყალიბდება. მიუხედავად იმისა, რომ მისი თავი სხეულთან შედარებით ჯერ კიდევ დიდია, ბავშვს უკვე სრულად აქვს ადამიანის იერსახე. მისი ორგანოები სწრაფად განაგრძობს ზრდასა და განვითარებას. ერთ-ერთი ასეთი ორგანო ღვიძლია, რომელიც ორსულობის მე-10 კვირაში ბავშვის სხეულის წონის დაახლოებით 10%-ს შეადგენს. მრავალფუნქციური ღვიძლი ბავშვს სისხლით უზრუნველყოფს მანამ, სანამ საშვილოსნოში ძვლის ტვინი დაიწყებს სისხლის წარმოქმნას, ანუ ორსულობის ბოლო ორ თვემდე.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი კანი ჯერ კიდევ გამჭვირვალეა, დედიკო! 👻 ჩემი დანახვა რომ შეგეძლოს, ყველა სისხლძარღვს, ძვალსა და ორგანოს დაინახავდი. ჩემი კანი იმდენად თხელია, რომ მინას ჰგავს. მაგრამ არ ინერვიულო, ცხიმოვანი შრის წარმოქმნასთან ერთად კანი გასქელდება და შენსას დაემსგავსება. ყოველდღე უფრო და უფრო ვძლიერდები. ჩემი გული კი კვლავ შენდამი სიყვარულს ტუმბავს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'გარგარის ჩირი'), body_changes_ka = COALESCE(body_changes_ka, 'ექიმთან ერთად და, საჭიროების შემთხვევაში, კვების სპეციალისტის დახმარებით უნდა შეადგინოთ კვების გეგმა. ასეთი გეგმა დაგეხმარებათ, ყველა საკვები პროდუქტისგან საკმარისი სარგებელი მიიღოთ და ზედმეტი წონის მატებაც აიცილოთ თავიდან. გეგმა პრაქტიკული რომ იყოს, უნდა გაითვალისწინოთ ორსულობამდე არსებული წონა, ყოველდღიური აქტივობა, ცხოვრების წესი და დღის რეჟიმი.;;;
ორსულობის განმავლობაში მოსამატებელი წონის საერთო რაოდენობა ყველა ქალისთვის ინდივიდუალურია. მიუხედავად ამისა, სპეციალისტების მიერ რეკომენდებული წონის გარკვეული დიაპაზონები არსებობს. ნორმალური ორსულობის დროს მომავალი დედის მიერ 9-12 კგ-ის მომატება ნორმად ითვლება. ეს დიაპაზონი შეიძლება შეიცვალოს უფრო დაბალი ან უფრო მაღალი წონის მქონე ქალებისთვის. მუცელში მზარდი ბავშვის ზომაც პირდაპირ გავლენას ახდენს წონის მატებაზე. ქალები, რომლებიც შედარებით პატარა ბავშვს ელოდებიან, ნაკლებ წონას იმატებენ, ხოლო ისინი, ვინც დიდ ბავშვს ელოდება — მეტს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ახლა თქვენი გარდერობის გადახედვის დროა. ვიწრო შარვალმა და ქამარმა შეიძლება სისხლის მიმოქცევა შეზღუდოს. დაიწყეთ ორსულებისთვის განკუთვნილი შარვლების (ელასტიკური წელის ნაწილით) ან თავისუფალი კაბების შეძენა. კომფორტი ყველაზე მნიშვნელოვანია.') WHERE id = '96171009-62e6-4557-a2c9-ebf16692943d';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის გარეთა ყურებმა უკვე საბოლოო ფორმა მიიღო. მიუხედავად იმისა, რომ ამჟამად ისინი ოდნავ დაბლა მდებარეობს, ბავშვის ზრდასთან ერთად ზემოთ, თავიანთ ბუნებრივ ადგილას გადაინაცვლებს. თვალებში კი უკვე ჩამოყალიბდა მხედველობის უზრუნველმყოფელი ძირითადი ოპტიკური ნაწილები; ქუთუთოები თვალებს უკვე მთლიანად ფარავს.;;;
პირის ღრუში კბილების ჩანასახები ვითარდება, სახეზე კი წარბების პირველი თხელი ღერები იწყებს გამოჩენას. ამ ეტაპზე თქვენი ბავშვი თანდათან კარგავს "C" ასოს მსგავს ფორმას და მისი სხეული უფრო მეტად ემსგავსება ადამიანის სხეულის აგებულებას.;;;
გარდა ამისა, პლაცენტა, რომელიც ჭიპლართან ერთად ვითარდება, ზრდას განაგრძობს. ეს სტრუქტურა დედასა და ბავშვს შორის უმნიშვნელოვანეს როლს ასრულებს. მისი ძირითადი ფუნქციებია აირთა ცვლის უზრუნველყოფა, ბავშვისთვის საკვები ნივთიერებების მიწოდება, ბავშვის ორგანიზმიდან ნარჩენი ნივთიერებების დედის ორგანიზმში გადატანა და ბავშვის ზრდისთვის მნიშვნელოვანი ზოგიერთი ჰორმონის გამოყოფა. პლაცენტა ასევე დედისგან ბავშვს გადასცემს გლუკოზას, ამინომჟავებს, ცხიმოვან მჟავებს, კალციუმს, D ვიტამინსა და ჟანგბადს, ხოლო ნახშირორჟანგი და სხვა ნარჩენი ნივთიერებები ბავშვისგან დედის ორგანიზმში გადააქვს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე აკრობატიკით ვარ დაკავებული! 🤸‍♂️ დედიკო, მე უბრალოდ კი არ ვწევარ — ვიჭიმები, ვტრიალებ და სალტოებსაც კი ვაკეთებ. საშვილოსნო ჩემთვის ჯერ კიდევ ფართო აუზია და ამით ვსარგებლობ. ეს მოძრაობები ჩემს კუნთებსა და სახსრებს ავითარებს. შენ ამას ჯერ ვერ გრძნობ, მაგრამ მე აქ ნამდვილ წარმოდგენას ვმართავ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ჩირი გარგარი'), body_changes_ka = COALESCE(body_changes_ka, 'პროგესტერონის ჰორმონის ზემოქმედებით ორსულობისას იცვლება რქოვანას, ანუ თვალის წინა ნაწილში არსებული გამჭვირვალე შრის, წყლის შეკავების უნარი. შედეგად, შესაძლოა მხედველობა დაბინდული გახდეს, ხოლო კონტაქტური ლინზების მომხმარებლებს ლინზების მიმართ მომატებული მგრძნობელობა განუვითარდეთ. ამ პერიოდში უმჯობესია, შეძლებისდაგვარად თავი შეიკავოთ კონტაქტური ლინზების გამოყენებისგან.;;;
მიუხედავად იმისა, რომ ორსულობისას მხედველობის პრობლემები შესაძლოა ფიზიოლოგიური მიზეზებით განვითარდეს, მხედველობასთან დაკავშირებული ჩივილების მქონე ყველა ორსულმა პერიოდულად უნდა ჩაიტაროს ოფთალმოლოგიური გამოკვლევა. ორსულობის დროს ჰორმონებმა შესაძლოა თვალის სისხლძარღვებში ცვლილებები გამოიწვიოს. მათ შორისაა ქალასშიდა სისხლძარღვების სტრუქტურული დარღვევები, ბადურის არტერიის დახშობა, სპონტანური სისხლჩაქცევა თვალბუდეში და სისხლჩაქცევა ჰიპოფიზში.'), daily_tip_ka = COALESCE(daily_tip_ka, 'C ვიტამინი ღრძილებს ამაგრებს. მიირთვით ფორთოხალი, კივი, წითელი წიწაკა და სხვა მსგავსი საკვები. კბილების გახეხვისას ზედმეტად ძლიერ მოძრაობებს ნუ გააკეთებთ, გამოიყენეთ რბილი ჯაგრისი და ნუ დაგავიწყდებათ კბილის ძაფის გამოყენება.') WHERE id = '2519d258-d4d3-4114-9156-6af5c1a49493';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპზე სწრაფად ვითარდება კიდევ ერთი ორგანო — კანი. ჯერჯერობით ის საკმაოდ გამჭვირვალეა და მის მიღმა სისხლძარღვები და ორგანოები ჩანს, თუმცა სწრაფად განაგრძობს გასქელებას. თქვენი ბავშვის კანი ის ორგანოა, რომელიც სხეულს შეხების შეგრძნებას უზრუნველყოფს. ის სხეულს გარეგანი ზემოქმედებისა და დარტყმებისგან იცავს, ცხიმისა და ოფლის გამოყოფაში მონაწილეობს, ხელს უწყობს ორგანიზმის მიერ D ვიტამინის მიღებას, არეგულირებს სხეულის ტემპერატურას და ხელს უშლის წყლის დაკარგვას. თქვენი საშვილოსნო, რომელშიც ბავშვი, პლაცენტა და ამნიონური სითხეა მოთავსებული, ორსულობის დაწყებიდან დაახლოებით ორჯერ გაიზარდა. ამ კვირაში ამნიონური სითხის მოცულობა დაახლოებით 30 ml-ია და ამ ეტაპზე ის დედის სისხლის თხევადი ნაწილის გაფილტვრის შედეგად წარმოიქმნება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ყნოსვა იღვიძებს! 👃 დედიკო, არ დაიჯერებ, მაგრამ მე უკვე ცხვირით სუნთქვას ვვარჯიშობ (ჰაერის ნაცვლად წყლით). ამნიონური სითხის სუნიც კი შემიძლია ვიგრძნო! საკვების სუნი, რომელსაც შენ მიირთმევ, აქამდეც აღწევს. როცა ნიორს ჭამ, ამას ვხვდები, და მაშინაც, როცა შოკოლადს მიირთმევ! ჩვენი გემოვნება უკვე ახლა იწყებს ჩამოყალიბებას.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ფინიკი'), body_changes_ka = COALESCE(body_changes_ka, 'სისხლის მოცულობა და სისხლის წითელი უჯრედების რაოდენობა იზრდება. თუმცა, რადგან სისხლის თხევადი ნაწილი უფრო მეტად იმატებს, შესაძლოა განვითარდეს შედარებითი ანემია. ასეთ შემთხვევაში შესაძლოა საჭირო გახდეს რკინის დანამატის მიღება. ამასთან, გული უფრო სწრაფად მუშაობს, რის გამოც დროდადრო შეიძლება გულის ფრიალი იგრძნოთ. ეს მდგომარეობა ორსულობის ადრეულ ეტაპებზე იწყება და 20-24-ე კვირებში პიკს აღწევს. ;;;
გამოყოფილი ჰორმონების ზემოქმედებით შესაძლოა არტერიული წნევა ოდნავ დაქვეითდეს. ორსულობის პროგრესირებასთან ერთად, განსაკუთრებით მარჯვენა გვერდზე წოლისას, საშვილოსნომ შესაძლოა დედის ღრუ ვენაზე ზეწოლა მოახდინოს და არტერიული წნევის უეცარი დაქვეითება გამოიწვიოს. ამიტომ ექიმები ორსულებს, განსაკუთრებით ორსულობის ბოლო პერიოდში, მარცხენა გვერდზე წოლას ურჩევენ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ჩანთით ყოველთვის ატარეთ წყლის ბოთლი. თუ ჩვეულებრივი წყლის დალევა გულისრევას იწვევს, დაუმატეთ ერთი ნაჭერი ლიმონი, კიტრი ან პიტნის ფოთოლი. ეს წყალს გემოს შეუცვლის და თქვენც თავს უფრო მხნედ იგრძნობთ.') WHERE id = 'f068ab76-fa64-4eef-8ed3-e47df04dba49';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინი უჩვეულო სისწრაფით იზრდება. ამ ეტაპზე ტვინში ყოველ 4 წუთში 1 მილიონი ნეირონი წარმოიქმნება. ბავშვის ნერვული სისტემის განვითარებაზე გავლენას ახდენს ყველა გარემოება, განსაკუთრებით დედისა და მამისგან მიღებული გენეტიკური კოდი.;;;
ფოლიუმის მჟავა ყველაზე მნიშვნელოვანი ვიტამინია, რომელიც ტვინის განვითარების პერიოდში თქვენს ბავშვს ნერვული სისტემის შესაძლო დაავადებებისგან იცავს. B ჯგუფის ვიტამინი ფოლიუმის მჟავა უხვად გვხვდება ბრიუსელის კომბოსტოში, ხუჭუჭა კომბოსტოში, ისპანახში, სატაცურში, ჭარხალში, სალათის ფოთლებსა და წითელ წიწაკაში. თუმცა მხოლოდ ფოლიუმის მჟავა საკმარისი არ არის. ამასთან ერთად აუცილებელია ყველა საჭირო საკვები ნივთიერების მიღება და საკმარისი რაოდენობის წყლის დალევა.;;;
ცილებით მდიდარი საკვების, ახალი ხილისა და ბოსტნეულის მიღება ბავშვის ჯანსაღი განვითარებისთვის მნიშვნელოვანია. ასევე, დადებითი ემოციური მდგომარეობაც ბავშვის ტვინის განვითარებაზე მოქმედი ერთ-ერთი მნიშვნელოვანი ფაქტორია.;;;
ორსულობის დროს ჩატარებული ყველა გამოკვლევა ბავშვის ნერვული სისტემისა და ტვინის შესახებ გვაწვდის ინფორმაციას. ორსულობის 11-14-ე კვირებში ჩატარებული "ორმაგი ტესტები" და 16-18-ე კვირებში ჩატარებული "სამმაგი ტესტები" მნიშვნელოვანია იმის შესაფასებლად, თუ რამდენად მაღალია ბავშვში შესაძლო გენეტიკური დარღვევის რისკი.'), baby_message_ka = COALESCE(baby_message_ka, 'შემიძლია მუშტები გავშალო! ✊🖐️ ჩემი თითები უკვე მთლიანად განცალკევებულია და შემიძლია ხელები მუშტებად შევკრა, შემდეგ კი გავშალო. ჩემთვის ეს ახალ სათამაშოს ჰგავს. ხან ხელებს სახეზე ვიკარებ, ხან კი ჭიპლარის დაჭერას ვცდილობ. ჩემი ჩაჭიდების რეფლექსი ვითარდება. მოუთმენლად ველი იმ დღეს, როცა შენს თითს ჩავეჭიდები!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ფინიკი'), body_changes_ka = COALESCE(body_changes_ka, 'საშვილოსნოში მყოფი ბავშვის გულისცემა, საშუალოდ, 6-7-ე კვირებიდან იწყებს დაფიქსირებას. ორსულობის პროგრესირებასთან ერთად გულისცემის სიხშირე, რომელიც თავდაპირველად წუთში 90-110 დარტყმას შეადგენს, პირველი ტრიმესტრის ბოლოს 140-ს აჭარბებს. ეს ზრდასრული ადამიანის გულისცემაზე დაახლოებით ორჯერ მეტია. როდესაც ექიმის მეთვალყურეობით თქვენი ბავშვის გულისცემას მოისმენთ, ის შეიძლება ძალიან სწრაფი მოგეჩვენოთ. ;;;
თუ მშობიარობის შემდეგ მოსალოდნელ უძილო დღეებზე დაფიქრდებით, ამ პერიოდში ბევრი ძილი ნამდვილად არ გაწყენთ. ძილის ჯანსაღი რეჟიმი თქვენი ჰორმონალური ბალანსის უფრო მარტივად მოწესრიგებას უწყობს ხელს.;;;
თქვენი საშვილოსნო, რომელიც ჩვეულებრივ მუშტზე პატარაა, ამ კვირიდან უკვე დიდი გრეიპფრუტის ზომას აღწევს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'საჭმლის მომნელებელი სისტემის მხარდასაჭერად მიიღეთ ბოჭკოვანი საკვები და დალიეთ ბევრი წყალი. თუ წელის ტკივილი დაგეწყოთ, ყურადღება მიაქციეთ ფეხსაცმლის არჩევას; ატარეთ კომფორტული ფეხსაცმელი, რომელიც არც ზედმეტად მაღალქუსლიანია და არც ძალიან ბრტყელი. დღის განმავლობაში გამოყავით დრო დასვენებისთვის და შესაძლებლობის ფარგლებში დაწექით მარცხენა გვერდზე, რათა სისხლის მიმოქცევა გაუმჯობესდეს.') WHERE id = 'e6ecf1e2-7281-4cf6-94ac-a3478b23c498';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი უკვე 6 სმ სიგრძისაა და 7-8 გრამს იწონის. კუდისებრი ნაწილი მთლიანად გაქრა და ემბრიონული პერიოდი დასრულდა. ახლა ყველა ორგანო თავის ადგილზეა და სწრაფი ზრდის ეტაპი იწყება. მომდევნო 8 კვირის განმავლობაში ის ახლანდელთან შედარებით 30-ჯერ უფრო მძიმე და 3-ჯერ უფრო გრძელი გახდება. ამ ზრდის მხარდასაჭერად თქვენს ორგანიზმში სისხლის მოცულობა და სისხლძარღვების რაოდენობა იზრდება. ამჟამად თავი სხეულთან შედარებით დიდი ჩანს, თუმცა მალე სხეულის ნაწილები უფრო პროპორციული გახდება. თითები უკვე დაგრძელდა; ის მხოლოდ მუშტებს კი აღარ კრავს, არამედ ხელებსაც შლის და გარემოს შესწავლას იწყებს.'), baby_message_ka = COALESCE(baby_message_ka, 'გოგო ვარ თუ ბიჭი? საიდუმლო მალე გამჟღავნდება! 🩷💙 ჩემი გარეთა სასქესო ორგანოები უკვე განსხვავებულად ჩამოყალიბებას იწყებს. რამდენიმე კვირის წინ ყველანი ერთნაირად გამოვიყურებოდით, ახლა კი სასქესო ბორცვის კუთხე იცვლება. ექიმებმა შესაძლოა ჯერ ზუსტად ვერ გითხრან, მაგრამ პროცესი მიმდინარეობს. შენ რას გრძნობ? ამბობენ, დედის გული არ ცდებაო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მარწყვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს, განსაკუთრებით პირველ ტრიმესტრში, ჰორმონ პროგესტერონის ზემოქმედებით ზოგიერთი გლუვი კუნთოვანი უჯრედი დუნდება. ამის გამო საკვები საჭმლის მომნელებელ სისტემაში უფრო ნელა გადაადგილდება, კუჭსა და ნაწლავებში უფრო დიდხანს რჩება და საჭმლის მონელების პრობლემები წარმოიქმნება. თუ შებერილობა ძლიერ დისკომფორტს იწვევს, მკურნალობისთვის ექიმს უნდა მიმართოთ. ექიმის მეთვალყურეობის გარეშე მედიკამენტების ან მცენარეული საშუალებების გამოყენებამ შესაძლოა თქვენი ბავშვის განვითარებაზე უარყოფითად იმოქმედოს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'წელის ტკივილის შესამცირებლად ეცადეთ, გამართულად იჯდეთ, ხოლო ძილისას მარცხენა გვერდზე დაწვეთ. მომატებული მადა ჯანსაღი წასახემსებლებით დაიკმაყოფილეთ. რკინის შეწოვის გასაუმჯობესებლად რაციონში C ვიტამინით მდიდარი პროდუქტები შეიტანეთ. დღის განმავლობაში სულ მცირე 10 წუთით მშვიდ გარემოში ღრმად ისუნთქეთ და ეცადეთ, თქვენს ბავშვთან ემოციური კავშირი დაამყაროთ.') WHERE id = '8c65943a-4d31-4534-b028-6c3f95fa6988';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინის უჯრედები წარმოუდგენელი სისწრაფით მრავლდება. ეს უჯრედები დაბადებიდან ერთმანეთთან კავშირების დამყარებას იწყებს და ეს პროცესი მთელი სიცოცხლის განმავლობაში გრძელდება. ადამიანის ზრდასთან ერთად ტვინში თავად უჯრედებზე მეტ ადგილს მათ შორის არსებული კავშირები იკავებს. უკვე ახლა თქვენი ბავშვის ნერვული სისტემა იმდენად განვითარებულია, რომ გრძნობის ორგანოებიდან მიღებული ინფორმაციის ტვინამდე გადაცემა შეუძლია.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ხმა ისმის! 🎤 (ჯერჯერობით უხმოდ). ჩემი ხმის იოგები ჩამოყალიბებას იწყებს. ახლა წყალში ვარ და ხმას ვერ ვიღებ, მაგრამ ვემზადები, რომ დაბადებისას პირველად გაგაგონო ჩემი "უაა!". წარმოგიდგენია ის წამი? ჩემი ხმა შენთვის მსოფლიოში ყველაზე ლამაზი მუსიკა იქნება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლეღვი'), body_changes_ka = COALESCE(body_changes_ka, 'დღის განმავლობაში შესაძლოა ხშირად გქონდეთ კრუნჩხვები. ისინი შეიძლება იგრძნობოდეს საზარდულის არეში, ასევე ფეხებსა და წვივებში. ფეხის კრუნჩხვების ზუსტი მიზეზი ბოლომდე ცნობილი არ არის, თუმცა მთავარ მიზეზებს შორის კალციუმისა და მაგნიუმის დეფიციტი სახელდება. ამიტომ ორსულობის დროს მაგნიუმისა და კალციუმის დამატებით მიღება ძალიან მნიშვნელოვანია. ექიმთან კონსულტაციის შემდეგ შეგიძლიათ შესაბამისი ვიტამინური დანამატები მიიღოთ.;;;
ორსულობისას გადიდებული საშვილოსნოს მიერ ვენურ სისტემაზე ზეწოლის შედეგად განვითარებული სისხლის მიმოქცევის დარღვევებიც კრუნჩხვების წარმოქმნის მნიშვნელოვანი ფაქტორია. რადგან თქვენს ორგანიზმში არსებული მინერალები პლაცენტის მეშვეობით ბავშვს გადაეცემა, სისხლძარღვებში სითხის მოცულობა იზრდება, ხოლო სისხლში მაგნიუმის დონე იკლებს. კრუნჩხვის დროს სიმშვიდე შეინარჩუნეთ, მუხლი გამართული გქონდეთ და ფეხი ნელა ასწიეთ ზემოთ. მოდუნებისთვის ფეხის კუნთების გაჭიმვა და გაშლა სცადეთ. კრუნჩხვის არეში მსუბუქი მასაჟი, კუნთებზე თბილი პირსახოცის დადება და ფეხის თითების ზემოთ მოქაჩვა კრუნჩხვის შემცირებას უწყობს ხელს. გარდა ამისა, რძის პროდუქტების, თევზის, ნუშის მსგავსი თხილეულის, ლობიოს, ოსპისა და ისეთი თესლების მიღება, როგორიცაა სეზამი, ორგანიზმში შემცირებული მაგნიუმისა და კალციუმის დონის შევსებასა და კრუნჩხვების პრევენციაში დაგეხმარებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'თავბრუსხვევის თავიდან ასაცილებლად მჯდომარე ან მწოლიარე მდგომარეობიდან ნელა წამოდექით. სისხლის გაზრდილი მოცულობის გამო საკმარისი სითხის მიღება მნიშვნელოვანია. თუ "ორმაგი ტესტისთვის" (სკრინინგისთვის) ექიმთან ჯერ არ ყოფილხართ, ეს კვირა ყველაზე შესაფერისი დროა. თუ მადა მოგემატათ, რაციონში განსაკუთრებული ადგილი დაუთმეთ კალციუმითა და მაგნიუმით მდიდარ პროდუქტებს.') WHERE id = '1a115c93-d622-40f8-b3f4-8d1be6d3b8e9';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ტვინის განვითარებასთან ერთად ის უკვე რეფლექსურ მოძრაობებს იწყებს. ეს მოძრაობები უნებლიეთ ხდება და თქვენი ბავშვის სამომავლო ფიზიკურ უნარებს საფუძველს უყრის. მაგალითად, საშვილოსნოში რაიმეს შეხებისას პირის გაღება ერთ-ერთი ასეთი პირველი რეფლექსია.;;;
ეს განვითარება ორი ეტაპისგან შედგება:;;;
ინფორმაციის შეგროვება: ამ ეტაპზე, რომელიც ახლა იწყება, თქვენი ბავშვი მოძრაობების მეშვეობით საკვების ძიებისა და თავდაცვის რეფლექსებს იძენს. მაგალითად, მოულოდნელი ბიძგის დროს ხელებს შეშინებულივით ზემოთ სწევს და შემდეგ ერთმანეთს უახლოვებს (მოროს რეფლექსი).;;;
ინფორმაციის დამუშავება: ამ ეტაპზე, რომელიც დაბადებიდან 4 თვის შემდეგ იწყება, თავის ტვინის ცენტრალური სისტემები კიდევ უფრო ვითარდება.;;;
შედეგად, დედის საშვილოსნოში ჩამოყალიბებულ ამ უნებლიე რეფლექსებს თანდათან ანაცვლებს გაცნობიერებული, ნებითი მოძრაობები, როგორიცაა ჯდომა, დაჭერა და ფეხზე წამოდგომა.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ნაწლავები საკუთარ სახლში დაბრუნდა! 🏠 დედიკო, გახსოვს, რადგან მუცელი პატარა მქონდა, ჩემი ნაწლავები ჭიპლარის შიგნით იყო გასული? დღეს ისინი ოფიციალურად დაბრუნდნენ მუცლის ღრუში, თავიანთ ადგილას. ახლა ჩემი მუცელი გლუვი და ლამაზია. ყველა ჩემი შინაგანი ორგანო უკვე სწორ ადგილასაა და მუშაობს. ყოველდღე უფრო და უფრო სრულყოფილი ვხდები.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ლეღვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის ამ კვირიდან, ანუ პირველი ტრიმესტრის დასასრულის მოახლოებისას, ბავშვის თანდაყოლილი დარღვევების რისკის შესაფასებლად ორმაგი სკრინინგტესტის ჩატარებაა შესაძლებელი. ორმაგი სკრინინგტესტი პირველი ტრიმესტრის ტესტის სახელითაც არის ცნობილი. შეფასება ტარდება დეტალური ულტრაბგერითი გამოკვლევისა და სისხლში ორი მნიშვნელოვანი ცილის კონცენტრაციის განსაზღვრის საფუძველზე. ულტრაბგერითი გამოკვლევისას ბავშვის კისრის ნაოჭის სისქესა და ცხვირის ძვალს აფასებენ. ნორმალურად მიმდინარე ორსულობისას კისრის ნაოჭის სისქე მაქსიმუმ 2.5 mm უნდა იყოს. რაც უფრო დიდია კისრის ნაოჭის სისქე, მით უფრო მაღალია ქრომოსომული ანომალიის ალბათობა. გარდა ამისა, ორმაგი ტესტის დროს ცხვირის ძვლის არსებობა ბავშვის ჯანსაღი განვითარების მნიშვნელოვანი მაჩვენებელია. ქრომოსომებთან დაკავშირებული დარღვევების შემთხვევაში ცხვირის ძვალი ან საერთოდ არ ჩანს, ან მოსალოდნელზე გაცილებით მცირეა.;;;
ორმაგი ტესტის შედეგით შეუძლებელია ბავშვის ანომალიების არსებობის ან არარსებობის ზუსტად დადგენა. ეს ტესტები მხოლოდ ანომალიის ალბათობას განსაზღვრავს. თუ შედეგით რისკი ნორმაზე მაღალი აღმოჩნდება, ზუსტი პასუხის მისაღებად ექიმმა შესაძლოა ისეთი მეთოდები გირჩიოთ, როგორიცაა ამნიოცენტეზი.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ეცადეთ, სისხლში შაქრის დონე სტაბილურად შეინარჩუნოთ. ხანგრძლივად შიმშილმა შეიძლება თავბრუსხვევა და სისუსტე გამოიწვიოს. ჩანთაში ყოველთვის იქონიეთ ჯანსაღი წასახემსებლები, მაგალითად, ჩირი, ნიგოზი ან ვაშლი.') WHERE id = '6d7fa2b9-68dc-41a1-b8e4-2909aebba355';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ტვინის განვითარებასთან ერთად თქვენი ბავშვი უფრო გააზრებულ მოძრაობებს იწყებს. შედეგად, ის დღის განმავლობაში უფრო აქტიურია. მას უკვე შეუძლია ხელების მოხრა და ახლახან ერთმანეთისგან განცალკევებული პატარა ფეხის თითების მოძრაობა.;;;
ადამიანის სხეულში სამი ტიპის კუნთია: გულის კუნთი, გლუვი კუნთები და განივზოლიანი კუნთები. განივზოლიანი კუნთები სხეულში ერთადერთი კუნთოვანი სტრუქტურაა, რომლის მართვაც ადამიანს შეუძლია. ეს კუნთები განლაგებულია ხელებში, ზურგსა და ფეხებში. გარკვეული რაოდენობის ენერგიის დახარჯვის შემდეგ ისინი იღლებიან. კუნთის კიდევ ერთ ტიპს — გულის კუნთს — განსაკუთრებული აგებულება აქვს. ის დამოუკიდებლად მოძრაობს და ადამიანის სიცოცხლის ბოლომდე შეუჩერებლად მუშაობს. კუნთების ბოლო ტიპი — გლუვი კუნთები — მნიშვნელოვან როლს ასრულებს საჭმლის მომნელებელ სისტემაში. ისინი უნებლიედ მოძრაობენ და ორგანიზმში მიმდინარე საჭმლის მონელების პროცესებში აქტიურად მონაწილეობენ. ამ სამი განსხვავებული კუნთოვანი სტრუქტურის საერთო თვისებებია ელასტიკურობა, შეკუმშვის, გაღიზიანებადობისა და გამტარობის უნარი.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ვამთქნარებ! 🥱 იქნებ თქვენც დაგამთქნარათ, როცა ამას კითხულობდით? დიახ, უკვე შემიძლია პირი ფართოდ გავაღო და დავამთქნარო. ეს იმიტომ კი არა, რომ მეძინება, არამედ ყბის კუნთებისა და ფილტვების განსავითარებლად. ზოგჯერ სლოკინიც მეწყება. ამ პატარა ბიძგებს ჯერ ვერ გრძნობთ, მაგრამ მე აქ, შიგნით, ძალიან დაკავებული ვარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ხურმა'), body_changes_ka = COALESCE(body_changes_ka, 'ისტორიის განმავლობაში ადამიანები მომავალი ბავშვის სქესის გამოსაცნობად სხვადასხვა მოსაზრებას გამოთქვამდნენ. მაგალითად, მიაჩნდათ, რომ თუ მომავალ დედას მჟავე საკვები უნდოდა, გოგო ეყოლებოდა, ხოლო თუ ტკბილი — ბიჭი. კვლევების თანახმად, საკვებისადმი განსაკუთრებულ ლტოლვას ან ზიზღსა და ბავშვის სქესს შორის კავშირი არ არსებობს.;;;
თქვენს მუცელზე შესაძლოა უფრო მკაფიოდ გამოჩნდეს მუქი ხაზი, რომელსაც „შავ ხაზს“ უწოდებენ. ის ჭიპიდან ქვემოთ, ზოგჯერ კი ზემოთაც გრძელდება. ეს მთლიანად ჰორმონული ცვლილებების შედეგია და სრულიად უვნებელია. მშობიარობიდან რამდენიმე თვის შემდეგ ხაზი თავისთავად გაფერმკრთალდება და გაქრება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გაზების შესამცირებლად ეცადეთ, ჭამის დროს არ ისაუბროთ, რათა ჰაერი არ გადაყლაპოთ. საკვები კარგად დაღეჭეთ. შესაძლოა, პარკოსნებისა და გაზიანი სასმელებისგან დროებით თავის შეკავებაც დაგეხმაროთ.') WHERE id = '1980273b-7820-40aa-b793-4b715fda3015';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის სქესი ჯერ კიდევ განაყოფიერების მომენტში განისაზღვრება იმის მიხედვით, მამისგან მიღებული სპერმატოზოიდი X თუ Y ქრომოსომას ატარებს. თუმცა ფიზიკურ ჩამოყალიბებას გარკვეული დრო სჭირდება. მე-5 კვირაში როგორც მამრობითი, ისე მდედრობითი სქესის ემბრიონს უჩნდება ერთნაირი პატარა გამობურცულობა. მე-8 კვირაში კი სპეციალური უჯრედები, რომელთაგანაც სასქესო ორგანოები ჩამოყალიბდება, ამ უბნისკენ გადაადგილებას იწყებენ. საინტერესოა, რომ მე-12 კვირამდე ბავშვის გარეგნული ნიშნებით სქესის განსხვავება თითქმის შეუძლებელია.;;;
თუ თქვენი ბავშვი Y ქრომოსომას ატარებს, უჯრედები სათესლე ჯირკვლებად (ტესტიკულებად) გარდაიქმნება და მე-12 კვირამდე ტესტოსტერონის გამომუშავებას იწყებს. სწორედ ეს ჰორმონი უზრუნველყოფს ბიჭების გარეთა სასქესო ორგანოების ჩამოყალიბებას. თუ თქვენს ბავშვს XX ქრომოსომები აქვს, ანუ გოგოა, უჯრედები საშვილოსნოსა და ფალოპის მილებს წარმოქმნის. ამ პროცესში მნიშვნელოვან როლს ასრულებს ჰორმონი ესტროგენი, რომელიც გოგოებისთვის დამახასიათებელი შიდა და გარეთა სტრუქტურების ჩამოყალიბებას უზრუნველყოფს.'), baby_message_ka = COALESCE(baby_message_ka, 'მე მარწყვის ზომის ვარ! უკვე არც ისე პატარა ვარ, ხომ ასეა? ჩემი სხეული სწორდება, ხერხემალი კი გრძელდება. მიუხედავად იმისა, რომ თქვენი მუცელი ჯერ ძალიან არ გეტყობათ, მე აქ საკმაოდ დიდი ადგილი დავიკავე. ჩვენ ერთად ვიზრდებით, დედიკო. გმადლობთ, რომ მიცავთ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'მარწყვი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს პირის ღრუს მოვლას მეტი ყურადღება უნდა დაუთმოთ. ორგანიზმში მიმდინარე ცვლილებების გამო შესაძლოა კბილებისა და ღრძილების პრობლემები შეგექმნათ. ორსულობის პერიოდში კბილების სათანადო მოვლა დედისა და ბავშვის ჯანმრთელობისთვის ძალიან მნიშვნელოვანია. კალციუმის წყაროების საჭირო რაოდენობით მიღება ხელს უწყობს პირის ღრუსა და კბილების პრობლემების თავიდან აცილებას და ჯანსაღ მშობიარობას. ამ პერიოდში როგორც საკუთარი თავისთვის, ისე ბავშვისთვის დაბალანსებულ კვებაზე უნდა იზრუნოთ. ყოველი ჭამის შემდეგ კბილები გაიხეხეთ და კბილის ძაფი გამოიყენეთ, რათა კბილები ეფექტურად გაიწმინდოთ და ნადების წარმოქმნა თავიდან აიცილოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'რადგან პირველი ტრიმესტრის დასასრულს უახლოვდებით, შესაძლოა თავი უფრო ენერგიულად იგრძნოთ; ეს იდეალური დროა მსუბუქი ვარჯიშის ან ცურვის დასაწყებად. რადგან ღრძილების მგრძნობელობა შესაძლოა კვლავ გაწუხებდეთ, ყურადღება მიაქციეთ პირის ღრუს ჰიგიენას. რაციონში აუცილებლად შეიტანეთ საკმარისი ცილა და კალციუმი. მომავალ კვირას მე-12 კვირა გველოდება — პირველი მნიშვნელოვანი ეტაპის დასრულება!') WHERE id = '2348cc6e-cce7-4823-afd3-9cc2309eebb6';